INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88383, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "列举", "is_correct": true, "explanation": "正确答案。列举是把东西一个一个说出来。"}, {"text": "劣迹", "is_correct": false, "explanation": "jì（第四声）与 jǔ（第三声）韵母、声调都不同，劣迹指不好的行为。"}, {"text": "烈暑", "is_correct": false, "explanation": "shǔ（第三声）与 jǔ 声母不同（sh 与 j），烈暑指炎热的暑天。"}, {"text": "猎区", "is_correct": false, "explanation": "qū 与 jǔ 声母不同（q 与 j），声调也不同，猎区指打猎的地区。"}, {"text": "烈祖", "is_correct": false, "explanation": "zǔ 与 jǔ 声母不同（z 与 j），烈祖指有功业的先人，多用于书面。"}], "explanations": {"列举": "正确答案。列举是把东西一个一个说出来。", "劣迹": "jì（第四声）与 jǔ（第三声）韵母、声调都不同，劣迹指不好的行为。", "烈暑": "shǔ（第三声）与 jǔ 声母不同（sh 与 j），烈暑指炎热的暑天。", "猎区": "qū 与 jǔ 声母不同（q 与 j），声调也不同，猎区指打猎的地区。", "烈祖": "zǔ 与 jǔ 声母不同（z 与 j），烈祖指有功业的先人，多用于书面。"}, "sentence_index": null, "correct_answer": "列举"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“名字”作宾语。"}, {"text": "列举", "is_correct": true, "explanation": "正确。“列举”可以带“十个国家的名字”作宾语，表示一个一个说出来。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”针对具体的物品，不能用于“名字”。"}, {"text": "推迟", "is_correct": false, "explanation": "语义：“推迟”指延后，与“一口气”的迅速完成意思相反。"}], "explanations": {"吃": "搭配：“吃”不能以“名字”作宾语。", "列举": "正确。“列举”可以带“十个国家的名字”作宾语，表示一个一个说出来。", "拆": "搭配：“拆”针对具体的物品，不能用于“名字”。", "推迟": "语义：“推迟”指延后，与“一口气”的迅速完成意思相反。"}, "sentence_index": 6, "correct_answer": "列举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把课文列举了一遍。", "explanation": "这里应该用〈背诵〉。列举指一项项说出事项，不能用于把整篇课文背出来。"}, {"text": "摄影师列举了一组照片。", "explanation": "这里应该用〈拍摄〉。列举指说出或写出事项，不指拍照的动作。"}, {"text": "他把这篇文章列举成了英文。", "explanation": "这里应该用〈翻译〉。列举是说出或写出多个事项，不能表示把文章转换成另一种语言。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她列举得很多理由。", "corrected_sentence": "她列举了很多理由。", "error_description": "“列举得”错误：“得”不能直接接数量宾语；应为“列举了”，用体标“了”表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把要带去旅行的东西都列举来了。", "corrected_sentence": "我把要带去旅行的东西都列举出来了。", "error_description": "漏掉“出”：结果补语“出来”少了“出”，“列举”后应接“出来”，应为“列举出来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
