INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回家就是回到自己住的地方。", "primary_collocate": null, "pronunciation": "huí jiā", "ipa": "/xweɪ̯˧˥ tɕjä˥/", "syllable_count": 2, "sentences": [{"text": "下班以后，我坐地铁回家。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，孩子们该回家了。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，大家都要回家看爸妈。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天几点回家？", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天走路回家，不坐车。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得很大，我没带伞，只好等雨小了再回家。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，今晚早点回家吃饭。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想回家睡觉，太累了。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人回家的路上，一直在听歌。", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末你回家还是去朋友那儿？", "target_word": "回家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回了家", "label": "完成体"}, {"form": "回过家", "label": "经历体"}], "register": "中性", "sense_fingerprint": "回到自己住的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去单位工作，与句中的“下班以后”矛盾。"}, {"text": "回家", "is_correct": true, "explanation": "“回家”指回到自己住的地方，与“下班以后，我坐地铁”的语境相符。"}, {"text": "放学", "is_correct": false, "explanation": "搭配：“放学”只用于学生，不能用于下班的上班族。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公外出，与下班后坐地铁回去的日常情境不合。"}], "explanations": {"上班": "语义：“上班”指去单位工作，与句中的“下班以后”矛盾。", "回家": "“回家”指回到自己住的地方，与“下班以后，我坐地铁”的语境相符。", "放学": "搭配：“放学”只用于学生，不能用于下班的上班族。", "出差": "语义：“出差”指因公外出，与下班后坐地铁回去的日常情境不合。"}, "sentence_index": 0, "correct_answer": "回家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天回家饭店吃饭。", "explanation": "这里应该用〈去〉。“回家”只指回到自己住的地方，要到饭店吃饭应说“去饭店”。"}, {"text": "我下午回家图书馆看书。", "explanation": "这里应该用〈去〉。“回家”只指回到住处，到图书馆看书要说“去图书馆”。"}, {"text": "明天我要回家公司开会。", "explanation": "这里应该用〈去〉。“回家”只指回到住处，到公司开会要说“去公司”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校，与今晚在家吃饭的情境矛盾。"}, {"text": "回老家", "is_correct": false, "explanation": "地点：“老家”指故乡，今晚不可能回去吃饭，与句意不合。"}, {"text": "回家", "is_correct": true, "explanation": "“回家”指回到家里，与“今晚早点”“吃饭”相符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”指去单位工作，与“今晚早点……吃饭”的场景矛盾。"}], "explanations": {"上学": "语义：“上学”指去学校，与今晚在家吃饭的情境矛盾。", "回老家": "地点：“老家”指故乡，今晚不可能回去吃饭，与句意不合。", "回家": "“回家”指回到家里，与“今晚早点”“吃饭”相符。", "上班": "语义：“上班”指去单位工作，与“今晚早点……吃饭”的场景矛盾。"}, "sentence_index": 6, "correct_answer": "回家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明年回家留学。", "explanation": "这里应该用〈出国〉。“回家”指回到自己住的地方，去国外留学要说“出国”。"}, {"text": "他昨天回家检查身体。", "explanation": "这里应该用〈到医院〉。“回家”指回到住处，检查身体要到医院。"}, {"text": "他明天回家商场买衣服。", "explanation": "这里应该用〈去〉。“回家”只指回到自己住的地方，到商场买衣服要说“去商场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把弟弟回家了。", "corrected_sentence": "我把弟弟带回家了。", "error_description": "错误形式：“把弟弟回家”；正确形式：“把弟弟带回家”。“回家”是不及物动词，不能直接带“把”的宾语，要加“带”表示带着人回去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们晚上九点去回家了。", "corrected_sentence": "他们晚上九点回家了。", "error_description": "错误形式：“去回家”；正确形式：“回家”。“回家”本身已含“去”的意思，前面不能再加“去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
