INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88389, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发觉是慢慢知道了以前不知道的事。", "primary_collocate": null, "pronunciation": "fā jué", "ipa": "fa˥ tɕye˧˥", "syllable_count": 2, "sentences": [{"text": "过了很久，我才发觉他不在家。", "target_word": "发觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她慢慢发觉自己喜欢上了这座城市。", "target_word": "发觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没发觉天已经黑了。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发觉钱包不见了。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走到门口，我才发觉忘了带钥匙。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈发觉我最近很少说话。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你什么时候发觉他在骗你？", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师慢慢发觉这个学生很聪明。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住久了，他发觉邻居们都很热情。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她发觉自己的头发白了不少。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发觉了", "label": "体标"}, {"form": "发觉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "经过一段时间，才渐渐知道以前没注意到的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造出新的事物或方法，不能用来表示察觉某人不在家。"}, {"text": "发觉", "is_correct": true, "explanation": "“发觉”指慢慢才察觉到以前没注意的事，与“过了很久”和“不在家”的语境相符。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”的主语应是事件，不能以“我”作主语带“他不在家”这样的小句作宾语。"}, {"text": "发挥", "is_correct": false, "explanation": "语义：“发挥”指施展能力或作用，与察觉某种情况无关。"}], "explanations": {"发明": "语义：“发明”指创造出新的事物或方法，不能用来表示察觉某人不在家。", "发觉": "“发觉”指慢慢才察觉到以前没注意的事，与“过了很久”和“不在家”的语境相符。", "发生": "配价：“发生”的主语应是事件，不能以“我”作主语带“他不在家”这样的小句作宾语。", "发挥": "语义：“发挥”指施展能力或作用，与察觉某种情况无关。"}, "sentence_index": 0, "correct_answer": "发觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家发觉了一种新的元素。", "explanation": "这里应该用〈发现〉。发觉侧重逐渐察觉已存在的情况，科学上找到新元素或新规律要用〈发现〉。"}, {"text": "我突然发觉了一个好办法。", "explanation": "这里应该用〈想到〉。发觉是察觉已有的情况，不能用来表示突然想出一个办法。"}, {"text": "我终于发觉了丢失的钥匙。", "explanation": "这里应该用〈找到〉。发觉的宾语应是一种情况，要说“发觉钥匙丢了”；找回具体物品要用〈找到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”指忧虑、担心，不表示察觉对方在骗人，句中用不通。"}, {"text": "发觉", "is_correct": true, "explanation": "“发觉”指察觉到之前没注意的欺骗，句中问的是何时察觉，语义和搭配都合适。"}, {"text": "发财", "is_correct": false, "explanation": "配价：“发财”是不及物动词，不能带“他在骗你”这样的小句作宾语。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指公开宣布或刊登，不能表示察觉某人在欺骗。"}], "explanations": {"发愁": "语义：“发愁”指忧虑、担心，不表示察觉对方在骗人，句中用不通。", "发觉": "“发觉”指察觉到之前没注意的欺骗，句中问的是何时察觉，语义和搭配都合适。", "发财": "配价：“发财”是不及物动词，不能带“他在骗你”这样的小句作宾语。", "发表": "语义：“发表”指公开宣布或刊登，不能表示察觉某人在欺骗。"}, "sentence_index": 6, "correct_answer": "发觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出版社发觉了这套丛书。", "explanation": "这里应该用〈印行〉。发觉是察觉已有的情况，不能表示印刷发行书籍，要用〈印行〉。"}, {"text": "工人发觉了一座大桥。", "explanation": "这里应该用〈建造〉。发觉表示察觉已有的情况，不能用来表示建造出一座桥。"}, {"text": "设计师发觉了一件衣服。", "explanation": "这里应该用〈制作〉。发觉表示察觉已有的情况，不能表示做出一件衣服，做衣服要用〈制作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天才发觉着钱包丢了。", "corrected_sentence": "我昨天才发觉钱包丢了。", "error_description": "“发觉”后加“着”是错误的。“着”表示持续的状态，而“才发觉”表示一次性察觉到某事，应去掉“着”，说“我昨天才发觉钱包丢了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈晚上才把发觉门没锁。", "corrected_sentence": "妈妈晚上才发觉门没锁。", "error_description": "“把”后面须接名词性宾语，这里接的是动词“发觉”，把字句不成立，应去掉“把”，说“妈妈晚上才发觉门没锁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
