INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始知道或感觉到。", "primary_collocate": null, "pronunciation": "fā jué", "ipa": "fa˥ tɕye˧˥", "syllable_count": 2, "sentences": [{"text": "他发觉有人在后面跟着他。", "target_word": "发觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我发觉屋子里有点儿冷。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她发觉孩子的脸色不好。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走了一会儿，我发觉脚很疼。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他发觉大家都在看他。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王发觉自己说错话了。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我发觉桌子上多了一本书。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生发觉病人的手在发抖。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直到下车，他才发觉下雨了。", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你发觉了什么问题吗？", "target_word": "发觉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发觉了", "label": "体标"}, {"form": "发觉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "突然注意到或感觉到某种情况正在出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发表", "is_correct": false, "explanation": "语义：“发表”指公开刊登或宣布，不能表示注意到有人跟踪。"}, {"text": "发觉", "is_correct": true, "explanation": "“发觉”指突然注意到身后有人跟着，与句意相符。"}, {"text": "发财", "is_correct": false, "explanation": "配价：“发财”是不及物动词，不能带“有人在后面跟着他”这样的小句作宾语。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，与察觉身后有人跟随毫无关系。"}], "explanations": {"发表": "语义：“发表”指公开刊登或宣布，不能表示注意到有人跟踪。", "发觉": "“发觉”指突然注意到身后有人跟着，与句意相符。", "发财": "配价：“发财”是不及物动词，不能带“有人在后面跟着他”这样的小句作宾语。", "发明": "语义：“发明”指创造新事物，与察觉身后有人跟随毫无关系。"}, "sentence_index": 0, "correct_answer": "发觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我发觉明天会下雨。", "explanation": "这里应该用〈预感〉。发觉指察觉到已经出现的情况，不能用来推测将来要发生的事。"}, {"text": "他发觉了一个新方案。", "explanation": "这里应该用〈提出〉。发觉是察觉已有的情况，不能用来表示提出新的方案。"}, {"text": "摄影师发觉了一组照片。", "explanation": "这里应该用〈拍摄〉。发觉是察觉已有的情况，不能表示拍出一组照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”指忧虑，不表示察觉桌上多了一本书，句中用不通。"}, {"text": "发觉", "is_correct": true, "explanation": "“发觉”指察觉到桌上多了东西，与句意相符。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”的主语是事件，不能以“我”作主语带“桌子上多了一本书”作宾语。"}, {"text": "发挥", "is_correct": false, "explanation": "语义：“发挥”指施展能力或作用，与察觉桌上的变化无关。"}], "explanations": {"发愁": "语义：“发愁”指忧虑，不表示察觉桌上多了一本书，句中用不通。", "发觉": "“发觉”指察觉到桌上多了东西，与句意相符。", "发生": "配价：“发生”的主语是事件，不能以“我”作主语带“桌子上多了一本书”作宾语。", "发挥": "语义：“发挥”指施展能力或作用，与察觉桌上的变化无关。"}, "sentence_index": 6, "correct_answer": "发觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们发觉了任务。", "explanation": "这里应该用〈完成〉。发觉是察觉已有的情况，不能用来表示完成一项任务。"}, {"text": "学校发觉了一次郊游。", "explanation": "这里应该用〈组织〉。发觉不能表示组织活动，组织郊游要用〈组织〉。"}, {"text": "法官发觉了判决。", "explanation": "这里应该用〈作出〉。发觉表示察觉，不能表示法官作出判决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一进门就发觉着屋里很暖和。", "corrected_sentence": "我一进门就发觉屋里很暖和。", "error_description": "“发觉”后加“着”是错误的。“着”表示持续的状态，而“发觉”表示瞬间察觉到某种情况，应去掉“着”，说“我一进门就发觉屋里很暖和”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走进屋子，我很发觉灯还亮着。", "corrected_sentence": "走进屋子，我发觉灯还亮着。", "error_description": "副词“很”不能修饰“发觉”。错误形式是“很发觉”，“很”放在了动词前面；正确形式是“发觉灯还亮着”，去掉“很”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
