INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88392, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精神分析理论中，介于意识与潜意识之间、可以回忆起来的心理内容。", "primary_collocate": null, "pronunciation": "qián yì shí", "ipa": "tɕʰiɛn˧˥ i˥˩ ʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "弗洛伊德把人的心理分成意识、前意识和潜意识。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前意识介于意识和潜意识之间。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前意识中的内容，可以通过回忆进入意识。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在精神分析中，前意识是很重要的概念。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中用一个比方解释了前意识。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前意识和潜意识不同，前者容易回忆起来。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了前意识的特点。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文研究的是前意识与梦的关系。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家认为，前意识像一座桥。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的第二章专门讲前意识。", "target_word": "前意识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前意識", "label": "繁体"}], "register": "书面", "sense_fingerprint": "精神分析中介于意识与潜意识之间的心理层次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉体", "is_correct": false, "explanation": "语义：肉体不属于心理层次，不能与“意识”并列。"}, {"text": "前意识", "is_correct": true, "explanation": "正确。前意识是意识与潜意识之间的心理层次，符合“分成……”的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“分成”后接的是心理层次，“冰箱”不能这样用。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不是心理层次，与“心理”的分类相冲突。"}], "explanations": {"肉体": "语义：肉体不属于心理层次，不能与“意识”并列。", "前意识": "正确。前意识是意识与潜意识之间的心理层次，符合“分成……”的语境。", "冰箱": "搭配：“分成”后接的是心理层次，“冰箱”不能这样用。", "身高": "语义：身高不是心理层次，与“心理”的分类相冲突。"}, "sentence_index": 0, "correct_answer": "前意识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在前意识的状态下把手缩了回来。", "explanation": "这里应该用〈无意识〉。无意识指没有察觉地做某事；前意识是介于意识与潜意识之间、可以回忆起来的心理内容，不能用来描述不自觉的动作。"}, {"text": "弗洛伊德认为，人的很多冲动都隐藏在前意识中。", "explanation": "这里应该用〈潜意识〉。冲动被压抑在潜意识中；前意识的内容可以回忆起来，不能说冲动“隐藏”其中。"}, {"text": "他的前意识今天很快乐。", "explanation": "这里应该用〈心情〉。前意识是心理层次，指可以回忆起来的内容，不能用来形容情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语法：“非常”是副词，不能作“的特点”的定语中心。"}, {"text": "前意识", "is_correct": true, "explanation": "正确。前意识是心理层次，可以讲它的特点。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能放在“的特点”前。"}, {"text": "突然", "is_correct": false, "explanation": "语法：“突然”修饰动作，不能说“讲了突然的特点”指代理论内容。"}], "explanations": {"非常": "语法：“非常”是副词，不能作“的特点”的定语中心。", "前意识": "正确。前意识是心理层次，可以讲它的特点。", "已经": "语法：“已经”是副词，不能放在“的特点”前。", "突然": "语法：“突然”修饰动作，不能说“讲了突然的特点”指代理论内容。"}, "sentence_index": 6, "correct_answer": "前意识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他通过前意识感受到了温度的变化。", "explanation": "这里应该用〈知觉〉。知觉是感官对外界的感受，前意识指可以回忆起来的心理层次，不是感知的途径。"}, {"text": "老师凭前意识判断出这道题的答案。", "explanation": "这里应该用〈经验〉。经验来自实践积累，前意识是心理层次，不能用来做判断。"}, {"text": "他对这件事有很深的前意识。", "explanation": "这里应该用〈感受〉。前意识是心理层次，不是可以“很深”的感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前意识处在意识和潜意识。", "corrected_sentence": "前意识处在意识和潜意识之间。", "error_description": "漏掉“之间”：“处在”后需要方位词“之间”作补足，应为“处在意识和潜意识之间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一章专门讲在前意识。", "corrected_sentence": "这一章专门讲前意识。", "error_description": "多了“在”：“讲”后直接带宾语“前意识”，不能在“前意识”前加“在”，应为“讲前意识”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
