INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88393, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前面是脸对着的那一边。", "primary_collocate": null, "pronunciation": "qián miàn", "ipa": "tɕʰjɛn˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "前面有一家小商店。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请站在我前面，别走到后面去。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在我前面，我看不见黑板。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的路很窄，车开不过去。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子前面有一棵大树。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校前面就是公园。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在大家前面讲话。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人请往旁边走一走。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服前面有两个口袋。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往前面看，老师在那儿。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前边", "label": "口语变体"}, {"form": "前头", "label": "口语变体"}], "register": "中性", "sense_fingerprint": "脸或物体正对着的那一边，空间位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88393, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前面", "is_correct": true, "explanation": "正确答案：前面（qián miàn），指脸或物体正对着的那一边。"}, {"text": "墙面", "is_correct": false, "explanation": "qiáng（第二声）与 qián（第二声）韵母不同：ang 与 an，意思是墙的表面。"}, {"text": "前线", "is_correct": false, "explanation": "xiàn 与 miàn 声母不同：x 与 m，意思是战场上最靠前的一线。"}, {"text": "前站", "is_correct": false, "explanation": "zhàn 与 miàn 声母不同：zh 与 m，声调相同，意思是前一站。"}], "explanations": {"前面": "正确答案：前面（qián miàn），指脸或物体正对着的那一边。", "墙面": "qiáng（第二声）与 qián（第二声）韵母不同：ang 与 an，意思是墙的表面。", "前线": "xiàn 与 miàn 声母不同：x 与 m，意思是战场上最靠前的一线。", "前站": "zhàn 与 miàn 声母不同：zh 与 m，声调相同，意思是前一站。"}, "sentence_index": null, "correct_answer": "前面"}, "level_3": {"options": [{"text": "前面", "is_correct": true, "explanation": "正确：“前面有一家小商店”表示小商店在正对着的那一边。"}, {"text": "前途", "is_correct": false, "explanation": "语义：“前途”指发展的未来，不能作为有商店的处所。"}, {"text": "前额", "is_correct": false, "explanation": "体貌：“前额”指人的额头，不能成为有商店的地方。"}, {"text": "前提", "is_correct": false, "explanation": "搭配：“前提”是条件，作主语时与“有一家小商店”要求的处所不搭配。"}], "explanations": {"前面": "正确：“前面有一家小商店”表示小商店在正对着的那一边。", "前途": "语义：“前途”指发展的未来，不能作为有商店的处所。", "前额": "体貌：“前额”指人的额头，不能成为有商店的地方。", "前提": "搭配：“前提”是条件，作主语时与“有一家小商店”要求的处所不搭配。"}, "sentence_index": 0, "correct_answer": "前面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我站在他前面，所以只能看见他的后背。", "explanation": "这里应该用〈后面〉。站在一个人前面看到的是他的脸，能看见后背要站在他“后面”。"}, {"text": "电视在我前面，我要回头才能看到。", "explanation": "这里应该用〈后面〉。要回头才能看到的东西在身体“后面”，“前面”是脸对着的那一边。"}, {"text": "学习前面要先预习。", "explanation": "这里应该用〈之前〉。“前面”不能直接放在动作前表示先后，要说“学习之前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88393, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前面", "is_correct": true, "explanation": "正确答案：前面（qián miàn），指脸或物体正对着的那一边。"}, {"text": "全面", "is_correct": false, "explanation": "quán 与 qián 韵母不同：u 与 i，声调相同，意思是各方面都包括在内。"}, {"text": "前站", "is_correct": false, "explanation": "zhàn 与 miàn 声母不同：zh 与 m，声调相同，意思是前一站。"}, {"text": "见面", "is_correct": false, "explanation": "jiàn（第四声）与 qián（第二声）声母、声调都不同，意思是彼此会面。"}], "explanations": {"前面": "正确答案：前面（qián miàn），指脸或物体正对着的那一边。", "全面": "quán 与 qián 韵母不同：u 与 i，声调相同，意思是各方面都包括在内。", "前站": "zhàn 与 miàn 声母不同：zh 与 m，声调相同，意思是前一站。", "见面": "jiàn（第四声）与 qián（第二声）声母、声调都不同，意思是彼此会面。"}, "sentence_index": null, "correct_answer": "前面"}, "level_3": {"options": [{"text": "前面", "is_correct": true, "explanation": "正确：“站在大家前面”表示位置在众人正对着的那一边。"}, {"text": "前景", "is_correct": false, "explanation": "语义：“前景”指事物的发展趋势，不能作为“站在”的处所。"}, {"text": "前胸", "is_correct": false, "explanation": "体貌：“前胸”是人身体的部位，不能说“站在大家前胸讲话”。"}, {"text": "前身", "is_correct": false, "explanation": "语义：“前身”指事物先前的形态，不能作为“站在”的处所。"}], "explanations": {"前面": "正确：“站在大家前面”表示位置在众人正对着的那一边。", "前景": "语义：“前景”指事物的发展趋势，不能作为“站在”的处所。", "前胸": "体貌：“前胸”是人身体的部位，不能说“站在大家前胸讲话”。", "前身": "语义：“前身”指事物先前的形态，不能作为“站在”的处所。"}, "sentence_index": 6, "correct_answer": "前面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃完饭前面，我们去散步。", "explanation": "这里应该用〈之后〉。“前面”表示空间或次序靠前，饭后的时间要用“之后”。"}, {"text": "老师在教室前面，学生们都转过身去看她。", "explanation": "这里应该用〈后面〉。学生面对教室前方，要转过身才能看到的人在“后面”。"}, {"text": "这件事我前面再告诉你。", "explanation": "这里应该用〈以后〉。“前面”不能表示将来的时间，将来要用“以后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = E