INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间或次序上在先的部分，与“后面”相对。", "primary_collocate": null, "pronunciation": "qián miàn", "ipa": "tɕʰjɛn˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "前面我已经说过这件事了。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书前面几页我都看完了。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名字排在前面的同学先来。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面讲的内容很容易，到后来就比较难了。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你前面说的话，我都记着。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把前面的问题再做一遍。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名的人里，前面三个已经考完了。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章前面写得好，后面写得差。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名单上他的名字排在前面，最先被叫到。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面提到过的办法，我们可以试试。", "target_word": "前面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前边", "label": "口语变体"}, {"form": "前头", "label": "口语变体"}], "register": "中性", "sense_fingerprint": "时间或次序上在先的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
