INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88394, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前面", "is_correct": true, "explanation": "正确答案：前面（qián miàn），指时间或次序上在先的部分。"}, {"text": "墙面", "is_correct": false, "explanation": "qiáng（第二声）与 qián（第二声）韵母不同：ang 与 an，意思是墙的表面。"}, {"text": "前站", "is_correct": false, "explanation": "zhàn 与 miàn 声母不同：zh 与 m，声调相同，意思是前一站。"}, {"text": "千面", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是多种面貌。"}], "explanations": {"前面": "正确答案：前面（qián miàn），指时间或次序上在先的部分。", "墙面": "qiáng（第二声）与 qián（第二声）韵母不同：ang 与 an，意思是墙的表面。", "前站": "zhàn 与 miàn 声母不同：zh 与 m，声调相同，意思是前一站。", "千面": "qiān（第一声）与 qián（第二声）声调不同，意思是多种面貌。"}, "sentence_index": null, "correct_answer": "前面"}, "level_3": {"options": [{"text": "前面", "is_correct": true, "explanation": "正确：“前面三个已经考完了”表示次序在先的三个人。"}, {"text": "前景", "is_correct": false, "explanation": "语义：“前景”指发展趋势，不能表示报名人群中的先后次序。"}, {"text": "前额", "is_correct": false, "explanation": "体貌：“前额”指人的额头，与报名人群的次序无关，不能填入。"}, {"text": "前身", "is_correct": false, "explanation": "语义：“前身”指事物先前的形态，不能表示报名人群中的先后。"}], "explanations": {"前面": "正确：“前面三个已经考完了”表示次序在先的三个人。", "前景": "语义：“前景”指发展趋势，不能表示报名人群中的先后次序。", "前额": "体貌：“前额”指人的额头，与报名人群的次序无关，不能填入。", "前身": "语义：“前身”指事物先前的形态，不能表示报名人群中的先后。"}, "sentence_index": 6, "correct_answer": "前面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "等他回来前面，我们再商量。", "explanation": "这里应该用〈之前〉。“前面”不能直接接在动作后表示时间，要说“他回来之前”。"}, {"text": "吃完午饭前面要休息。", "explanation": "这里应该用〈之后〉。“前面”只能表示时间在先，不能指动作完成之后的时间，要说“吃完午饭之后”。"}, {"text": "这件事前面再说。", "explanation": "这里应该用〈以后〉。“前面”表示时间时指先前，不能指将来，将来要说“以后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他排在队伍的前面的。", "corrected_sentence": "他排在队伍的前面。", "error_description": "错误：“前面”后多加了“的”。“前面”是方位词，直接作“排在……”的宾语，不能再加“的”，应说“排在队伍的前面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在前面里已经讲过这个问题了。", "corrected_sentence": "我在前面已经讲过这个问题了。", "error_description": "错误：“前面”后多了“里”。“前面”指次序在先的部分，不能再加“里”，应说“我在前面已经讲过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
