INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88395, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "在下是很久以前的人说话时,叫自己的词。", "primary_collocate": null, "pronunciation": "zài xià", "ipa": "tsai̯˥˩ ɕia̯˥˩", "syllable_count": 2, "sentences": [{"text": "小姐莫怕，在下不是坏人。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在下今天来，是想借一本书。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板，在下身上没带钱，明天再还可以吗？", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在下愿意为您送信。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您看错人了，在下不是那位将军。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在下远道而来，想见一见县官大人。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生说得对，在下知错了。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父，在下想拜您为师。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在下记性不好，请问您贵姓？", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位姑娘，在下刚才多有冒犯。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "古旧", "sense_fingerprint": "很久以前的人说话时称呼自己的词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在下", "is_correct": true, "explanation": "“在下”是古时的自称，与“小姐莫怕”的古雅对话语境相符，且说话人是自己说明身份。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，“石头不是坏人”句意荒谬，不能作说话人的自称。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”指对方，“您不是坏人”会把说话的对象变成对方，与句意不符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”不是人，“花朵不是坏人”句意荒谬。"}], "explanations": {"在下": "“在下”是古时的自称，与“小姐莫怕”的古雅对话语境相符，且说话人是自己说明身份。", "石头": "语义：“石头”不是人，“石头不是坏人”句意荒谬，不能作说话人的自称。", "您": "语义：“您”指对方，“您不是坏人”会把说话的对象变成对方，与句意不符。", "花朵": "语义：“花朵”不是人，“花朵不是坏人”句意荒谬。"}, "sentence_index": 0, "correct_answer": "在下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个在下很狡猾，你别信他的话。", "explanation": "这里应该用〈小人〉。“在下”只能是说话人自称，不能用来指“这个”第三者。"}, {"text": "在下，您愿意送信吗？", "explanation": "这里应该用〈先生〉。“在下”是说话人自称，不能用作称呼对方。"}, {"text": "那位在下很聪明，读了很多书。", "explanation": "这里应该用〈书生〉。“在下”是说话人自称，不能用“那位在下”指第三者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在下", "is_correct": true, "explanation": "“在下”是说话人的谦称，句中说话人承认自己的错误，与句意相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”不是人，“河流知错了”句意荒谬。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是人，“房子知错了”句意荒谬。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，“石头知错了”句意荒谬。"}], "explanations": {"在下": "“在下”是说话人的谦称，句中说话人承认自己的错误，与句意相符。", "河流": "语义：“河流”不是人，“河流知错了”句意荒谬。", "房子": "语义：“房子”不是人，“房子知错了”句意荒谬。", "石头": "语义：“石头”不是人，“石头知错了”句意荒谬。"}, "sentence_index": 6, "correct_answer": "在下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位在下刚才多有冒犯。", "explanation": "这里应该用〈姑娘〉。“在下”只能是说话人自称，不能用来指“这位”对方。"}, {"text": "在下，请您原谅我刚才的冒犯。", "explanation": "这里应该用〈姑娘〉。“在下”是说话人自称，不能用来称呼对方。"}, {"text": "那个书生是在下，刚才冒犯了姑娘。", "explanation": "这里应该用〈他〉。“在下”只指说话人自己，不能指第三者“那个书生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在下们今天想进城看看。", "corrected_sentence": "在下今天想进城看看。", "error_description": "“在下”是单数自称，不能加“们”表示复数。错误形式是「在下们」，此处应保留单数「在下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在下的这就去备茶，请稍候。", "corrected_sentence": "在下这就去备茶，请稍候。", "error_description": "错误形式是「在下的这就去备茶」，正确形式是「在下这就去备茶」。“在下”是代词自称，作主语时后面不能直接加「的」表示所属，多出的「的」使句子结构不通，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
