INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88396, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "旧时谦称自己,多用于对人说话时。", "primary_collocate": null, "pronunciation": "zài xià", "ipa": "tsai̯˥˩ ɕia̯˥˩", "syllable_count": 2, "sentences": [{"text": "在下姓李，请问先生贵姓？", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位兄台，在下有礼了。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在下初来此地，还请多多关照。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多谢大侠相救，在下感激不尽。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事与你无关，在下自己来处理。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不敢当，在下只是个读书人。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公子请坐，在下给您倒茶。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在下不才，愿意和您比一比。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生，在下想向您请教一件事。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客官，在下是这家店的伙计。", "target_word": "在下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "古旧", "sense_fingerprint": "旧时对人说话时谦称自己的代词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 4 words above tier T1 (max 2): 多谢 (Zipf 3.94), 大侠 (Zipf 3.33), 相救 (Zipf 3.39), 不尽 (Zipf 3.48)']::text[], '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在下", "is_correct": true, "explanation": "“在下”是旧时对人说话时的谦称，与“请问先生贵姓”的古雅语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，没有姓氏，“石头姓李”句意不通。"}, {"text": "您", "is_correct": false, "explanation": "语义：“您”指对方，不能作说话人的自称，“您姓李”与句意不符。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“花朵”不是人，没有姓氏，“花朵姓李”句意荒谬。"}], "explanations": {"在下": "“在下”是旧时对人说话时的谦称，与“请问先生贵姓”的古雅语境相符。", "石头": "语义：“石头”不是人，没有姓氏，“石头姓李”句意不通。", "您": "语义：“您”指对方，不能作说话人的自称，“您姓李”与句意不符。", "花朵": "语义：“花朵”不是人，没有姓氏，“花朵姓李”句意荒谬。"}, "sentence_index": 0, "correct_answer": "在下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请问在下贵姓？", "explanation": "这里应该用〈您〉。“在下”是说话人的自称，不能指对方，“贵姓”是问对方的姓。"}, {"text": "这位先生是在下吗？", "explanation": "这里应该用〈他〉。“在下”是说话人自称，不能指第三者“这位先生”。"}, {"text": "客官，在下想吃点什么？", "explanation": "这里应该用〈您〉。“在下”指说话人自己，不能用来询问对方想吃什么。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在下", "is_correct": true, "explanation": "“在下”是说话人的谦称，句中说话人亲自倒茶，与句意相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”不是人，不能给人倒茶，“河流给您倒茶”句意荒谬。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是人，不能给人倒茶，句意荒谬。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，不能给人倒茶，句意荒谬。"}], "explanations": {"在下": "“在下”是说话人的谦称，句中说话人亲自倒茶，与句意相符。", "河流": "语义：“河流”不是人，不能给人倒茶，“河流给您倒茶”句意荒谬。", "房子": "语义：“房子”不是人，不能给人倒茶，句意荒谬。", "石头": "语义：“石头”不是人，不能给人倒茶，句意荒谬。"}, "sentence_index": 6, "correct_answer": "在下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在下吃过饭了吗？", "explanation": "这里应该用〈诸位〉。“在下”是说话人自称，不能用来询问对方。"}, {"text": "这位在下请坐，客官稍等。", "explanation": "这里应该用〈公子〉。“在下”是说话人自称，不能用来指“这位”对方。"}, {"text": "伙计问客人：“在下要住几天？”", "explanation": "这里应该用〈客官〉。“在下”是说话人自称，伙计不能用它称呼客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在下们初次来到此地，望多多指教。", "corrected_sentence": "在下初次来到此地，望多多指教。", "error_description": "“在下”是单数自称，不能加“们”表示复数。错误形式是「在下们」，正确形式是「在下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公子请进，我在下这就去沏茶。", "corrected_sentence": "公子请进，在下这就去沏茶。", "error_description": "“在下”本身已是自称，前面不能再加“我”。错误形式是「我在下」，正确形式是「在下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
