INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "白痴是脑子不太会想事情的人，也有人用它来骂别人。", "primary_collocate": null, "pronunciation": "bái chī", "ipa": "pai˧˥ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他脑子不好用，别人说他是白痴。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白痴是脑子不太会想事情的人。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人用白痴来骂别人。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟生气时，会骂哥哥是白痴。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个白痴把钱都弄丢了！", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是白痴，你不用说得这么慢。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“我真是个白痴！”", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的白痴总是笨手笨脚的。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说错了话，同学就叫他白痴。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白痴这个词不能随便对朋友说。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "脑子不太会想事情的人，也被人用来骂人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白痴", "is_correct": true, "explanation": "白痴指脑子不太会想事情的人。用在“别人说他是……”里，正好与“脑子不好用”相合。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是小动物，不是对人智力的评价，与“脑子不好用”的句意不合。"}, {"text": "学者", "is_correct": false, "explanation": "语义：学者指有学问的人，与“脑子不好用”的句意相反。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使指善良美好的人，与“脑子不好用”不相合。"}], "explanations": {"白痴": "白痴指脑子不太会想事情的人。用在“别人说他是……”里，正好与“脑子不好用”相合。", "小猫": "语义：小猫是小动物，不是对人智力的评价，与“脑子不好用”的句意不合。", "学者": "语义：学者指有学问的人，与“脑子不好用”的句意相反。", "天使": "语义：天使指善良美好的人，与“脑子不好用”不相合。"}, "sentence_index": 0, "correct_answer": "白痴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在课堂上表扬学生是白痴。", "explanation": "语义：这里把“白痴”用来表扬学生，而白痴是骂人的话，或指脑子不太会想事情的人，与“表扬”的语境相反。"}, {"text": "这盆花的名字叫白痴，很好看。", "explanation": "语义：这里把“白痴”当成了花的名称，白痴只指人或骂人的话，不能用作植物名。"}, {"text": "我们班的白痴都考上了大学。", "explanation": "语义：这里把“白痴”用来形容考上大学的同学，白痴是骂人的话或指脑子不太会想事情的人，与“考上大学”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白痴", "is_correct": true, "explanation": "白痴是骂人的话，这里用于自嘲，正好符合“我真是个……”的语气。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：人不是钥匙，这样说没有意义。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：人不是窗户，这样说不合常理。"}, {"text": "摇篮", "is_correct": false, "explanation": "搭配：“摇篮”指婴儿睡的床或发源地，不能用来形容自己。"}], "explanations": {"白痴": "白痴是骂人的话，这里用于自嘲，正好符合“我真是个……”的语气。", "钥匙": "语义：人不是钥匙，这样说没有意义。", "窗户": "语义：人不是窗户，这样说不合常理。", "摇篮": "搭配：“摇篮”指婴儿睡的床或发源地，不能用来形容自己。"}, "sentence_index": 6, "correct_answer": "白痴"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "这位白痴教授讲的课很精彩。", "explanation": "语义：这里把“白痴”用来修饰讲课精彩的教授，白痴指智力低下或骂人的话，与“讲课精彩”矛盾。"}, {"text": "这位白痴在科研领域获得了诺贝尔奖。", "explanation": "语义：这里把“白痴”用来指获奖的科学家，白痴是骂人的话或指智力低下，与“获得诺贝尔奖”矛盾。"}, {"text": "这首歌被评委称为白痴的经典之作，大家都很喜欢。", "explanation": "语义：这里把“白痴”当成了赞美的词，白痴是骂人的话，不能用来称赞作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只白痴，常常犯错。", "corrected_sentence": "他是一个白痴，常常犯错。", "error_description": "错误：量词用“只”，应为“个”。白痴指人，量词用“个”；“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一条白痴，真让人生气。", "corrected_sentence": "他是一个白痴，真让人生气。", "error_description": "错误：量词用“条”，应为“个”。白痴指人，量词用“个”；“条”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
