INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "智力严重低下的人；用作骂人的话。", "primary_collocate": null, "pronunciation": "bái chī", "ipa": "pai˧˥ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "医生说，这个孩子不是白痴，只是学得慢。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生下来就是白痴，需要人照顾。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前有人把智力很低的人叫白痴。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这个白痴，怎么又忘了带钥匙！", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别叫别人白痴，这样太不礼貌了。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车乱来，我气得骂他白痴。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白痴这个词很难听，别随便用。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的白痴最后救了大家。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生气地说：“你是白痴吗？”", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不让同学互相骂白痴。", "target_word": "白痴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "智力严重低下的人，也用作骂人的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白痴", "is_correct": true, "explanation": "白痴指智力严重低下的人。这里用“不是白痴”否定，说明孩子只是学得慢，并非智力有问题。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，说孩子是老虎与智力无关，句子不通。"}, {"text": "植物", "is_correct": false, "explanation": "语义：这个孩子是人，不能说成植物。"}, {"text": "学究", "is_correct": false, "explanation": "语域：学究是书面词，指迂腐的读书人，与口语句子的语气不合。"}], "explanations": {"白痴": "白痴指智力严重低下的人。这里用“不是白痴”否定，说明孩子只是学得慢，并非智力有问题。", "老虎": "语义：老虎是动物，说孩子是老虎与智力无关，句子不通。", "植物": "语义：这个孩子是人，不能说成植物。", "学究": "语域：学究是书面词，指迂腐的读书人，与口语句子的语气不合。"}, "sentence_index": 0, "correct_answer": "白痴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他聪明又能干，大家都夸他是白痴。", "explanation": "语义：这里把“白痴”当成夸奖的话，白痴指智力严重低下的人或骂人的话，与“聪明能干”“夸”矛盾。"}, {"text": "这位数学家一生解决了很多难题，被誉为白痴。", "explanation": "这里应该用〈天才〉。白痴指智力严重低下的人或骂人的话，不能用来褒奖别人；“被誉为”后面要接褒义词。"}, {"text": "这个白痴是一种植物，开花很漂亮。", "explanation": "语义：这里把“白痴”当成了植物的名称，白痴只指智力低下的人或骂人的话，不指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白痴", "is_correct": true, "explanation": "白痴指智力严重低下的人，也用作骂人的话。这里说它“很难听”，正好指这个词本身的不当之处。"}, {"text": "天才", "is_correct": false, "explanation": "语义：天才是褒义词，与“很难听”矛盾。"}, {"text": "阁下", "is_correct": false, "explanation": "语义：阁下是尊敬的称呼，并不难听，与“很难听，别随便用”不合。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“难听”说的是词语或声音，不能用来形容地点。"}], "explanations": {"白痴": "白痴指智力严重低下的人，也用作骂人的话。这里说它“很难听”，正好指这个词本身的不当之处。", "天才": "语义：天才是褒义词，与“很难听”矛盾。", "阁下": "语义：阁下是尊敬的称呼，并不难听，与“很难听，别随便用”不合。", "公园": "搭配：“难听”说的是词语或声音，不能用来形容地点。"}, "sentence_index": 6, "correct_answer": "白痴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个白痴的成绩全班第一。", "explanation": "语义：这里把“白痴”用来形容成绩全班第一的学生，而白痴指智力低下的人或骂人的话，二者自相矛盾。"}, {"text": "爷爷得了白痴，连家里人的名字都记不住。", "explanation": "这里应该用〈痴呆〉。白痴指智力低下的人，不是病名；老年人记忆衰退应说“老年痴呆”。"}, {"text": "这位画家的作品在美术馆展出，被评论家誉为白痴。", "explanation": "这里应该用〈天才〉。白痴指智力低下或骂人的话，不能用来赞扬人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是只白痴，脾气很坏。", "corrected_sentence": "他是个白痴，脾气很坏。", "error_description": "错误：量词用“只”，应为“个”。白痴指人，量词用“个”；“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一条白痴，真让人生气。", "corrected_sentence": "他是一个白痴，真让人生气。", "error_description": "错误：量词用“条”，应为“个”。白痴指人，量词用“个”；“条”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "扣分", "is_correct": true, "explanation": "正确：“扣分”与“加分”意思相反，都指分数的增减。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清理卫生，与分数增减没有反义关系。"}, {"text": "报名", "is_correct": false, "explanation": "无关：“报名”指登记参加，与分数没有关系。"}, {"text": "参观", "is_correct": false, "explanation": "无关：“参观”指去某处看看，与分数没有关系。"}], "correct_answer": "扣分", "explanations": {"扣分": "正确：“扣分”与“加分”意思相反，都指分数的增减。", "打扫": "无关：“打扫”指清理卫生，与分数增减没有反义关系。", "报名": "无关：“报名”指登记参加，与分数没有关系。", "参观": "无关：“参观”指去某处看看，与分数没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减分", "is_correct": true, "explanation": "正确：“减分”指减少分数，与“加分”意思相反。"}, {"text": "出发", "is_correct": false, "explanation": "无关：“出发”指动身，与分数增减没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”指休息入睡，与分数没有关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”指在水中运动，与分数没有关系。"}], "correct_answer": "减分", "explanations": {"减分": "正确：“减分”指减少分数，与“加分”意思相反。", "出发": "无关：“出发”指动身，与分数增减没有反义关系。", "睡觉": "无关：“睡觉”指休息入睡，与分数没有关系。", "游泳": "无关：“游泳”指在水中运动，与分数没有关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加分数；在原有得分上追加分数。", "primary_collocate": null, "pronunciation": "jiā fēn", "ipa": "tɕja˥ fən˥", "syllable_count": 2, "sentences": [{"text": "老师说，回答对问题可以加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会弹钢琴的学生，面试时会加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加志愿活动，申请学校时能加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明帮同学打扫教室，老师说要给他加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道附加题答对了会加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会说外语的人应聘时能加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长表现很好，老师决定给他加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作文写得干净整齐，也能加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前认真准备，评委会给你加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试迟到的同学，老师不会给他加分。", "target_word": "加分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加了分", "label": "体标"}, {"form": "加过分", "label": "体标"}, {"form": "加分项", "label": "复合"}], "register": "通用", "sense_fingerprint": "在原有得分上追加分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扣分", "is_correct": false, "explanation": "语义：“扣分”是减少分数，与“回答对问题”的奖励语境相反。"}, {"text": "加分", "is_correct": true, "explanation": "正确：回答对问题后，老师可以在原有分数上追加分数。"}, {"text": "罚站", "is_correct": false, "explanation": "搭配：“罚站”是一种惩罚，不能用来回应“回答对问题”。"}, {"text": "加班", "is_correct": false, "explanation": "语义：“加班”指延长工作时间，与回答问题无关。"}], "explanations": {"扣分": "语义：“扣分”是减少分数，与“回答对问题”的奖励语境相反。", "加分": "正确：回答对问题后，老师可以在原有分数上追加分数。", "罚站": "搭配：“罚站”是一种惩罚，不能用来回应“回答对问题”。", "加班": "语义：“加班”指延长工作时间，与回答问题无关。"}, "sentence_index": 0, "correct_answer": "加分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重一直在加分。", "explanation": "这里应该用〈增加〉。“加分”指分数变多，体重这类数量的增长要用〈增加〉。"}, {"text": "经过训练，他的游泳水平一直在加分。", "explanation": "这里应该用〈提高〉。“加分”指分数增加，水平、能力的上升要用〈提高〉。"}, {"text": "这几年他的工资一直在加分。", "explanation": "这里应该用〈涨〉。“加分”用于分数，工资的上涨要用〈涨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出缺点，与“表现很好”的语境相反。"}, {"text": "加分", "is_correct": true, "explanation": "正确：班长表现好，老师可以在原有分数上追加分数。"}, {"text": "处罚", "is_correct": false, "explanation": "语义：“处罚”是惩罚，与“表现很好”的奖励语境相反。"}, {"text": "罚款", "is_correct": false, "explanation": "搭配：“罚款”一般指罚钱，不能用“给他罚款”来回应表现好的情况。"}], "explanations": {"批评": "语义：“批评”是指出缺点，与“表现很好”的语境相反。", "加分": "正确：班长表现好，老师可以在原有分数上追加分数。", "处罚": "语义：“处罚”是惩罚，与“表现很好”的奖励语境相反。", "罚款": "搭配：“罚款”一般指罚钱，不能用“给他罚款”来回应表现好的情况。"}, "sentence_index": 6, "correct_answer": "加分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年这家公司的利润有很大的加分。", "explanation": "这里应该用〈增长〉。“加分”是动词，指给分数增加分值，利润变多要用〈增长〉。"}, {"text": "跑完这段路以后，我们的速度加分了。", "explanation": "这里应该用〈加快〉。“加分”用于分数，速度变快要用〈加快〉。"}, {"text": "这个园区的规模有很大的加分。", "explanation": "这里应该用〈扩大〉。“加分”是动词，只用于分数，规模变大要用〈扩大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师说，这次回答对的同学都会他们加分。", "corrected_sentence": "老师说，这次回答对的同学都会给他们加分。", "error_description": "错误：“加分”的对象（得分的人）要用“给”引出，应说“给他们加分”，漏掉“给”就不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长这次工作出色，老师他加分了。", "corrected_sentence": "班长这次工作出色，老师给他加分了。", "error_description": "错误：“加分”的对象（得分的人）要用“给”引出，应说“老师给他加分了”，不能说“老师他加分了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
