INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88403, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇室是皇帝和他的家人。", "primary_collocate": null, "pronunciation": "huáng shì", "ipa": "xwɑŋ˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "皇室里的人不能随便出宫。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的皇室很受人民喜欢。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，皇室下个月要去海边旅行。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇室的孩子也要上学读书。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是一千年前皇室的故事。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇室每天吃的饭菜都很讲究。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁入皇室已经三十年了。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇室的人住在一座大房子里，有很多人照顾他们。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国的人都想看一看皇室的样子。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷认识皇室的一些人。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "皇室成员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "皇帝和他的家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88403, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "皇室", "is_correct": true, "explanation": "皇室：皇帝和他的家人。"}, {"text": "黄石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是黄色的石头，也是地名。"}, {"text": "红事", "is_correct": false, "explanation": "hóng 与 huáng 读音相近，意思是喜事，如婚礼。"}, {"text": "环视", "is_correct": false, "explanation": "huáng 与 huán 韵母不同，意思是环顾四周。"}], "explanations": {"皇室": "皇室：皇帝和他的家人。", "黄石": "shí（第二声）与 shì（第四声）声调不同，意思是黄色的石头，也是地名。", "红事": "hóng 与 huáng 读音相近，意思是喜事，如婚礼。", "环视": "huáng 与 huán 韵母不同，意思是环顾四周。"}, "sentence_index": null, "correct_answer": "皇室"}, "level_3": {"options": [{"text": "学校", "is_correct": false, "explanation": "搭配：“出宫”只用于宫廷，学校里的人不能说出宫。"}, {"text": "皇室", "is_correct": true, "explanation": "皇室：皇帝和他的家人，此处指住在宫里的皇家成员。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司不是宫殿，里面的人不说出宫。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是宫殿，“出宫”不能用于医院。"}], "explanations": {"学校": "搭配：“出宫”只用于宫廷，学校里的人不能说出宫。", "皇室": "皇室：皇帝和他的家人，此处指住在宫里的皇家成员。", "公司": "语义：公司不是宫殿，里面的人不说出宫。", "医院": "语义：医院不是宫殿，“出宫”不能用于医院。"}, "sentence_index": 0, "correct_answer": "皇室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把皇室放进了冰箱。", "explanation": "这里应该用〈食物〉。皇室指人，不是物品，不能放进冰箱。"}, {"text": "这座皇室很有名，游客很多。", "explanation": "这里应该用〈宫殿〉。皇室指皇帝和他的家人，不指建筑，不能说“这座皇室”。"}, {"text": "我渴了，想喝一杯皇室。", "explanation": "这里应该用〈茶〉。皇室指皇帝和他的家人，不是饮品，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "搭配：“嫁入”的对象须是家族，学历不能嫁入。"}, {"text": "皇室", "is_correct": true, "explanation": "皇室：皇帝和他的家人，此处指他嫁入的皇家家族。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子不能作“嫁入”的对象，“嫁入孩子”不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能作“嫁入”的对象。"}], "explanations": {"学历": "搭配：“嫁入”的对象须是家族，学历不能嫁入。", "皇室": "皇室：皇帝和他的家人，此处指他嫁入的皇家家族。", "孩子": "语义：孩子不能作“嫁入”的对象，“嫁入孩子”不通。", "石头": "语义：石头是无生命的物体，不能作“嫁入”的对象。"}, "sentence_index": 6, "correct_answer": "皇室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的爷爷每天吃很多皇室。", "explanation": "这里应该用〈饼干〉。皇室指人群，不是食物，不能用来吃。"}, {"text": "他每天用皇室扫地。", "explanation": "这里应该用〈扫帚〉。皇室指人群，不是工具，不能用来扫地。"}, {"text": "他每天早上去皇室上课。", "explanation": "这里应该用〈学校〉。皇室指皇帝的家族，不是学习的地方，不能说“去皇室上课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是皇室地一员，很少出席公开活动。", "corrected_sentence": "他是皇室的一员，很少出席公开活动。", "error_description": "助词错误：“皇室”修饰“一员”时应用定语助词“的”，此处误用状语助词“地”。正确说法是“皇室的一员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张皇室成员很少出席公开活动。", "corrected_sentence": "那位皇室成员很少出席公开活动。", "error_description": "量词错误：“皇室成员”指人，应用量词“位”，不能用“张”（“张”用于平面的东西）。正确说法是“那位皇室成员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
