INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "皇帝的家族；皇家。", "primary_collocate": null, "pronunciation": "huáng shì", "ipa": "xwɑŋ˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这座古老的宫殿曾经是皇室的住所。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇室成员每年都会参加这个仪式。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个皇室家庭里。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件首饰是皇室留下来的宝物。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国皇室的婚礼吸引了很多游客。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇室的生活看起来很美，其实很辛苦。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多皇室用过的东西。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家专门为皇室画像。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇室的花园对游客开放了。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的祖先曾经是皇室的一员。", "target_word": "皇室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "皇室成员", "label": "复合词"}], "register": "中性", "sense_fingerprint": "皇帝的家族，皇家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88404, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "皇室", "is_correct": true, "explanation": "皇室：皇帝的家族，皇家。"}, {"text": "黄石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是黄色的石头，也是地名。"}, {"text": "红事", "is_correct": false, "explanation": "hóng 与 huáng 读音相近，意思是喜事，如婚礼。"}, {"text": "环视", "is_correct": false, "explanation": "huáng 与 huán 韵母不同，意思是环顾四周。"}], "explanations": {"皇室": "皇室：皇帝的家族，皇家。", "黄石": "shí（第二声）与 shì（第四声）声调不同，意思是黄色的石头，也是地名。", "红事": "hóng 与 huáng 读音相近，意思是喜事，如婚礼。", "环视": "huáng 与 huán 韵母不同，意思是环顾四周。"}, "sentence_index": null, "correct_answer": "皇室"}, "level_3": {"options": [{"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不住在宫殿里，所以不能说宫殿是游客的住所。"}, {"text": "皇室", "is_correct": true, "explanation": "皇室：皇帝的家族，此处指曾经住在宫殿里的皇家成员。"}, {"text": "办公室", "is_correct": false, "explanation": "搭配：“住所”指供人生活居住的地方，办公室不能作住所。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的地方，不是人居住的场所。"}], "explanations": {"游客": "语义：游客是来参观的人，不住在宫殿里，所以不能说宫殿是游客的住所。", "皇室": "皇室：皇帝的家族，此处指曾经住在宫殿里的皇家成员。", "办公室": "搭配：“住所”指供人生活居住的地方，办公室不能作住所。", "花园": "语义：花园是种植花草的地方，不是人居住的场所。"}, "sentence_index": 0, "correct_answer": "皇室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爱好是皇室。", "explanation": "这里应该用〈园艺〉〈绘画〉这类爱好活动。皇室指皇帝的家族，是一群人，不是活动，不能当作爱好。"}, {"text": "我每天喝一杯皇室。", "explanation": "这里应该用〈咖啡〉。皇室指人群，不是饮品，不能说“喝一杯皇室”。"}, {"text": "下雨了，他打开皇室挡雨。", "explanation": "这里应该用〈雨伞〉。皇室指皇帝的家族，不是物品，不能用来挡雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植物", "is_correct": false, "explanation": "配价：“用过”要求有能力使用东西的主体，植物不能使用东西。"}, {"text": "皇室", "is_correct": true, "explanation": "皇室：皇帝的家族，此处指皇家成员使用过的东西。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不会使用东西。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能使用东西的主体，“用过的东西”与天空不搭。"}], "explanations": {"植物": "配价：“用过”要求有能力使用东西的主体，植物不能使用东西。", "皇室": "皇室：皇帝的家族，此处指皇家成员使用过的东西。", "石头": "语义：石头是无生命的物体，不会使用东西。", "天空": "语义：天空不是能使用东西的主体，“用过的东西”与天空不搭。"}, "sentence_index": 6, "correct_answer": "皇室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座皇室很大，有很多房间。", "explanation": "这里应该用〈宫殿〉。皇室指皇帝的家族，不指建筑物，所以不能说“这座皇室”很大。"}, {"text": "他每天用皇室打电话。", "explanation": "这里应该用〈手机〉。皇室指人群，不是工具，不能用来打电话。"}, {"text": "妈妈每天早上去皇室买菜。", "explanation": "这里应该用〈菜市场〉。皇室指皇帝的家族，不是买东西的地方，不能说“去皇室买菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一把皇室成员昨天来到了我们学校。", "corrected_sentence": "一位皇室成员昨天来到了我们学校。", "error_description": "量词错误：“皇室成员”指人，应用量词“位”，不能用“把”（“把”多用于有柄的器具）。正确说法是“一位皇室成员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是皇室地一员，很少公开露面。", "corrected_sentence": "她是皇室的一员，很少公开露面。", "error_description": "助词错误：“皇室”修饰“一员”时应用定语助词“的”，此处误用状语助词“地”。正确说法是“皇室的一员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
