INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学中在某种条件下运动变化位置的点。", "primary_collocate": null, "pronunciation": "dòng diǎn", "ipa": "tʊŋ˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "动点P在线段AB上运动，求它的最短路线。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动点M到两个定点的距离一样。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当动点移到圆心时，它到圆上各点的距离相等。", "target_word": "动点", "complexity_tier": "T3", "furigana": "dāng dòng diǎn yí dào yuán xīn shí, tā dào yuán shàng gè diǎn de jù lí xiāng děng.", "sentence_source": "generated"}, {"text": "这个动点沿着直线运动。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动点Q的位置每秒都在变。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动点在正方形的边上走了一圈。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先找出这个动点的路线。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题让动点从A走到B。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动点到原点的距离是五。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说动点的位置会随时间变化。", "target_word": "动点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个动点", "label": "量词"}, {"form": "動點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "按条件运动变化位置的点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动点", "is_correct": true, "explanation": "正确：“动点”指按条件运动的点，可以在线段上运动并求最短路线。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“在线段上运动、求最短路线”要求几何对象作主语，桌子不能在线段上运动。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事不是几何对象，不能在线段上运动，也没有最短路线。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不能在线段上运动，也谈不上最短路线。"}], "explanations": {"动点": "正确：“动点”指按条件运动的点，可以在线段上运动并求最短路线。", "桌子": "配价：“在线段上运动、求最短路线”要求几何对象作主语，桌子不能在线段上运动。", "故事": "语义：故事不是几何对象，不能在线段上运动，也没有最短路线。", "早饭": "语义：早饭不能在线段上运动，也谈不上最短路线。"}, "sentence_index": 0, "correct_answer": "动点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "正方形的中心是一个动点，它的位置不随条件改变。", "explanation": "这里应该用〈定点〉。位置不随条件改变的点不叫动点，动点指按条件运动、位置变化的点。"}, {"text": "他的动点很快。", "explanation": "这里应该用〈动作〉。动点是数学术语，指运动的点；人做的动作要说动作。"}, {"text": "这个椭圆有两个动点，位置固定不动。", "explanation": "这里应该用〈焦点〉。椭圆的两个焦点位置固定，动点应指运动变化位置的点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动点", "is_correct": true, "explanation": "正确：“动点”可以有路线，能在题目中被找出路线。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是抽象观念，没有可以找出的“路线”。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不是可以移动的对象，没有“路线”可言。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“找出……的路线”搭配移动对象，黑板不能这样说。"}], "explanations": {"动点": "正确：“动点”可以有路线，能在题目中被找出路线。", "道理": "语义：“道理”是抽象观念，没有可以找出的“路线”。", "早饭": "语义：早饭不是可以移动的对象，没有“路线”可言。", "黑板": "搭配：“找出……的路线”搭配移动对象，黑板不能这样说。"}, "sentence_index": 6, "correct_answer": "动点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "马拉松的动点设在山脚下。", "explanation": "这里应该用〈终点〉。动点是数学中运动的点，不指路线的尽头；马拉松的终点要说终点。"}, {"text": "这把刀的动点很锋利。", "explanation": "这里应该用〈刀尖〉。“动点”专指数学中运动的点，不指物体的尖端。"}, {"text": "我们研究股价的动点，发现它一直在上涨。", "explanation": "这里应该用〈动态〉。“动点”是数学术语，指运动的点，不能用来说股价的变化趋势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条动点在线段上来回运动。", "corrected_sentence": "一个动点在线段上来回运动。", "error_description": "量词错误：“动点”是抽象概念，量词应用“个”，不能用“条”。正确说法是：一个动点在线段上来回运动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "动点们已经走过了三角形的一条边。", "corrected_sentence": "动点已经走过了三角形的一条边。", "error_description": "词缀错误：“们”一般只加在指人或拟人的名词后，“动点”是抽象的数学概念，不能说“动点们”，应说“动点”或“这些动点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
