INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "感谢就是别人帮了你,你对他说谢谢。", "primary_collocate": null, "pronunciation": "gǎn xiè", "ipa": "kan˨˩ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "谢谢你送我回家，我要好好感谢你。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮了我很多，我想当面感谢她。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借给我一把伞，我很感谢他。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我搬家，我请他吃饭来感谢他。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居照顾我的小狗，我买了水果感谢他们。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你帮了我这么大的忙，我真不知道怎么感谢你。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生治好了妈妈的病，我们全家都很感谢他。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她教我学汉语，我一直很感谢她。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他救了我的孩子，我永远感谢他。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人帮了你，你应该感谢他。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感谢了", "label": "完成体"}, {"form": "感谢过", "label": "经历体"}, {"form": "感谢信", "label": "复合词"}, {"form": "感謝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人帮了自己，自己说谢谢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感谢", "is_correct": true, "explanation": "“感谢”表示对别人的帮助表示谢意，与“谢谢你送我回家”相符。"}, {"text": "埋怨", "is_correct": false, "explanation": "语义：“埋怨”含有不满，与前面的“谢谢你送我回家”矛盾。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出对方的错误，与前面的感谢语境矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“谢谢你送我回家”的感谢语境矛盾。"}], "explanations": {"感谢": "“感谢”表示对别人的帮助表示谢意，与“谢谢你送我回家”相符。", "埋怨": "语义：“埋怨”含有不满，与前面的“谢谢你送我回家”矛盾。", "批评": "语义：“批评”指指出对方的错误，与前面的感谢语境矛盾。", "拒绝": "语义：“拒绝”与“谢谢你送我回家”的感谢语境矛盾。"}, "sentence_index": 0, "correct_answer": "感谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站起来，向我感谢。", "explanation": "这里应该用〈道谢〉。“感谢”要直接带对象，表示向某人说谢谢要说“道谢”。"}, {"text": "向大家感谢，是我最后的话。", "explanation": "这里应该用〈致谢〉。“向……致谢”是固定说法，“感谢”后面不带“向”。"}, {"text": "我们感谢你考上了大学。", "explanation": "这里应该用〈祝贺〉。别人取得成绩时用“祝贺”，“感谢”用于别人帮了你的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感谢", "is_correct": true, "explanation": "“感谢”表示对别人的帮助表示谢意，与“我们全家都很”的语境相符。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”含有指责，与医生治好了妈妈的病这一情境矛盾。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：“厌恶”表示反感，与“全家都很”的感激情绪矛盾。"}, {"text": "咒骂", "is_correct": false, "explanation": "语域：“咒骂”语气过于激烈，与感激医生的家庭语境不符。"}], "explanations": {"感谢": "“感谢”表示对别人的帮助表示谢意，与“我们全家都很”的语境相符。", "责怪": "语义：“责怪”含有指责，与医生治好了妈妈的病这一情境矛盾。", "厌恶": "语义：“厌恶”表示反感，与“全家都很”的感激情绪矛盾。", "咒骂": "语域：“咒骂”语气过于激烈，与感激医生的家庭语境不符。"}, "sentence_index": 6, "correct_answer": "感谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们感谢那个偷钱的人。", "explanation": "这里应该用〈谴责〉。“感谢”是对帮过你的人表示谢意，对偷钱的人要说“谴责”。"}, {"text": "妈妈感谢我考了一百分。", "explanation": "这里应该用〈表扬〉。成绩是自己努力得来的，不是别人帮的，要说“表扬”，不说“感谢”。"}, {"text": "我感谢那位刚刚撞到我的人。", "explanation": "这里应该用〈道歉〉。撞到别人要说“道歉”，“感谢”用于别人帮了你的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我感谢很你的帮助。", "corrected_sentence": "我感谢你的帮助。", "error_description": "错误：“感谢很你的帮助”，“很”插在“感谢”和“你”之间，应删去。正确：“我感谢你的帮助。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经感谢过我的老师过。", "corrected_sentence": "他曾经感谢过我的老师。", "error_description": "错误：句末多了一个“过”。“过”表示经历，应紧跟动词“感谢”，句末不能再加“过”。正确：“他曾经感谢过我的老师。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
