INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人的帮助或好意表示谢意。", "primary_collocate": null, "pronunciation": "gǎn xiè", "ipa": "kan˨˩ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我感谢大家对我的帮助。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我非常感谢你们的好意。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他感谢朋友在他生病时照顾他。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要感谢那些帮助过我们的人。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感谢妈妈一直支持她。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理感谢大家今年的支持。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "感谢你们来看我，我很高兴。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送了我一束花，我感谢他的好意。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人感谢路人扶了他一把。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子感谢警察叔叔帮他找到了妈妈。", "target_word": "感谢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感谢了", "label": "完成体"}, {"form": "感谢过", "label": "经历体"}, {"form": "感谢信", "label": "复合词"}, {"form": "感謝", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对别人的帮助或好意表示谢意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '670abb29-3f2a-4552-853e-5fbd6cd3bc58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感谢", "is_correct": true, "explanation": "“感谢”表示对别人的帮助表示谢意，与“对我的帮助”相符。"}, {"text": "质疑", "is_correct": false, "explanation": "语义：“质疑”针对说法或观点，不用于对别人的帮助。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”指指出对方的错误，与“对我的帮助”的语境矛盾。"}, {"text": "警惕", "is_correct": false, "explanation": "语义：“警惕”表示提防，与“我感谢大家对我的帮助”的感激语境矛盾。"}], "explanations": {"感谢": "“感谢”表示对别人的帮助表示谢意，与“对我的帮助”相符。", "质疑": "语义：“质疑”针对说法或观点，不用于对别人的帮助。", "批评": "语义：“批评”指指出对方的错误，与“对我的帮助”的语境矛盾。", "警惕": "语义：“警惕”表示提防，与“我感谢大家对我的帮助”的感激语境矛盾。"}, "sentence_index": 0, "correct_answer": "感谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到他生病，我很感谢他。", "explanation": "这里应该用〈关心〉。得知别人生病要表示关心，不说“感谢”；“感谢”用于别人帮了你。"}, {"text": "老师感谢他的好成绩。", "explanation": "这里应该用〈表扬〉。好成绩是他自己努力得来的，不是别人帮的，要说“表扬”。"}, {"text": "我感谢那个撞坏我车的人。", "explanation": "这里应该用〈道歉〉。撞坏别人的东西要说“道歉”，“感谢”用于别人帮了你。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感谢", "is_correct": true, "explanation": "“感谢”表示对别人的好意表示谢意，与“我很高兴”相符。"}, {"text": "埋怨", "is_correct": false, "explanation": "语义：“埋怨”含有不满，与“我很高兴”的语境矛盾。"}, {"text": "谴责", "is_correct": false, "explanation": "语域：“谴责”语气严厉、偏书面，与“感谢你们来看我”的温馨语境不符。"}, {"text": "怪罪", "is_correct": false, "explanation": "语义：“怪罪”是责怪对方，与“我很高兴”的语境矛盾。"}], "explanations": {"感谢": "“感谢”表示对别人的好意表示谢意，与“我很高兴”相符。", "埋怨": "语义：“埋怨”含有不满，与“我很高兴”的语境矛盾。", "谴责": "语域：“谴责”语气严厉、偏书面，与“感谢你们来看我”的温馨语境不符。", "怪罪": "语义：“怪罪”是责怪对方，与“我很高兴”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "感谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在演讲结束时向听众感谢。", "explanation": "这里应该用〈致谢〉。“向……致谢”是固定说法，“感谢”后面不带“向”。"}, {"text": "这个故事让我很感谢。", "explanation": "这里应该用〈感动〉。被故事打动要说“感动”，“感谢”用于别人帮了你的事，不指被打动的感受。"}, {"text": "我们感谢你考上了大学。", "explanation": "这里应该用〈祝贺〉。别人取得成绩时用“祝贺”，“感谢”用于别人帮了你的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我感谢很大家的帮助。", "corrected_sentence": "我感谢大家的帮助。", "error_description": "错误：“感谢很大家的帮助”，“很”插在“感谢”和“大家”之间，应删去。正确：“我感谢大家的帮助。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾经感谢过那位医生过。", "corrected_sentence": "我们曾经感谢过那位医生。", "error_description": "错误：句末多了一个“过”。“过”表示经历，应紧跟动词“感谢”，句末不能再加“过”。正确：“我们曾经感谢过那位医生。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6fa71c8-3322-42b7-bc4e-54ea8519d39d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间接选举", "is_correct": true, "explanation": "反义：间接选举由代表投票，直接选举由选民亲自投票，二者相对。"}, {"text": "天气预报", "is_correct": false, "explanation": "无关：天气预报是关于天气的信息，与选举方式没有反义关系。"}, {"text": "图书馆", "is_correct": false, "explanation": "无关：图书馆是借阅书籍的场所，与选举方式没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "无关：花园是种植花草的地方，与选举方式没有反义关系。"}], "correct_answer": "间接选举", "explanations": {"间接选举": "反义：间接选举由代表投票，直接选举由选民亲自投票，二者相对。", "天气预报": "无关：天气预报是关于天气的信息，与选举方式没有反义关系。", "图书馆": "无关：图书馆是借阅书籍的场所，与选举方式没有反义关系。", "花园": "无关：花园是种植花草的地方，与选举方式没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间接选举", "is_correct": true, "explanation": "反义：间接选举由代表投票，直接选举由选民亲自投票，二者相对。"}, {"text": "课程表", "is_correct": false, "explanation": "无关：课程表是安排上课时间的表格，与选举方式没有反义关系。"}, {"text": "博物馆", "is_correct": false, "explanation": "无关：博物馆是展示文物的场所，与选举方式没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "无关：草地是长满草的地面，与选举方式没有反义关系。"}], "correct_answer": "间接选举", "explanations": {"间接选举": "反义：间接选举由代表投票，直接选举由选民亲自投票，二者相对。", "课程表": "无关：课程表是安排上课时间的表格，与选举方式没有反义关系。", "博物馆": "无关：博物馆是展示文物的场所，与选举方式没有反义关系。", "草地": "无关：草地是长满草的地面，与选举方式没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "选民直接投票选出代表或领导人的选举方式。", "primary_collocate": null, "pronunciation": "zhí jiē xuǎn jǔ", "ipa": "ʈʂɨ˧˥ tɕje˥ ɕɥɛn˨˩˦ tɕy˨˩˦", "syllable_count": 4, "sentences": [{"text": "在直接选举中，选民自己投票选出市长。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的总统由直接选举产生。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直接选举让每个选民都有机会表达意见。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们村今年第一次用了直接选举的办法。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和间接选举不同，直接选举不用代表来投票。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用直接选举的方式选出了学生会主席。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直接选举的结果很快就出来了。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是直接选举。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人认为直接选举比较公平。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直接选举那天，镇上的人都去投票了。", "target_word": "直接选举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "直接选举|选民直接投票选出代表领导人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直接选举", "is_correct": true, "explanation": "正确。选民亲自投票选出市长，符合直接选举的含义。"}, {"text": "间接选举", "is_correct": false, "explanation": "语义：间接选举由代表投票，与句中“选民自己投票”相反。"}, {"text": "民意调查", "is_correct": false, "explanation": "语义：民意调查只征求意见，不投票选出人，与“投票选出市长”不符。"}, {"text": "票箱", "is_correct": false, "explanation": "搭配：“在…中”表示方式或过程，票箱是物件，不能说“在票箱中”选出市长。"}], "explanations": {"直接选举": "正确。选民亲自投票选出市长，符合直接选举的含义。", "间接选举": "语义：间接选举由代表投票，与句中“选民自己投票”相反。", "民意调查": "语义：民意调查只征求意见，不投票选出人，与“投票选出市长”不符。", "票箱": "搭配：“在…中”表示方式或过程，票箱是物件，不能说“在票箱中”选出市长。"}, "sentence_index": 0, "correct_answer": "直接选举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校用公开考试直接选举了优秀学生。", "explanation": "这里应该用〈选拔〉。选举由选民投票产生人选，考试按成绩挑选人才要用选拔。"}, {"text": "周末我们在三家饭店里直接选举了一家。", "explanation": "这里应该用〈选择〉。选举是选民投票选出代表或领导人，个人在几家饭店中挑一家要用选择。"}, {"text": "学校直接选举了新老师。", "explanation": "这里应该用〈聘用〉。选举靠选民投票产生人选，学校招聘教师要用聘用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接选举", "is_correct": true, "explanation": "正确。直接选举产生的结果就是选出的人选，句意通顺。"}, {"text": "生日蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会有“结果”出来，句子说不通。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，不是能产生“结果”的过程，句意不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是吃的东西，不会有“结果”出来，句意不通。"}], "explanations": {"直接选举": "正确。直接选举产生的结果就是选出的人选，句意通顺。", "生日蛋糕": "语义：蛋糕不会有“结果”出来，句子说不通。", "词典": "语义：词典是工具书，不是能产生“结果”的过程，句意不通。", "午饭": "语义：午饭是吃的东西，不会有“结果”出来，句意不通。"}, "sentence_index": 6, "correct_answer": "直接选举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上级直接选举了新的校长。", "explanation": "这里应该用〈任命〉。选举靠选民投票，上级指派人选要用任命。"}, {"text": "工厂直接选举了三名新工人。", "explanation": "这里应该用〈雇佣〉。选举产生的是选出的人选，工厂招用工人要用雇佣。"}, {"text": "他直接选举了一台新电脑。", "explanation": "这里应该用〈选购〉。选举是选民投票选出代表或领导人，个人挑买商品要用选购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个月，社区进行了一张直接选举。", "corrected_sentence": "上个月，社区进行了一次直接选举。", "error_description": "量词错误：“张”用于纸、桌子等平面物件，“直接选举”是一次活动，应用量词“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校这学期还要进行过一次直接选举。", "corrected_sentence": "学校这学期还要进行一次直接选举。", "error_description": "体标错误：“还要”表示将来，不能与经历体“过”同用，应去掉“过”，说“还要进行一次直接选举”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
