INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "原处是东西以前在的那个地方。", "primary_collocate": null, "pronunciation": "yuán chù", "ipa": "ɥɛn˧˥ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "书不在原处，我找不到它。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完东西，请放回原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跑出去玩，后来又回到原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图还在原处，没有人动过。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子拿走以后，原处是空的。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机放回原处就去睡觉了。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很久，还是站在原处不动。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我把桌子又搬回了原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞放在原处，明天还要用。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们收拾完，每样东西都在原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原處", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西以前所在的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e59cd1e-273a-489b-abf0-17bb4fcc0b71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原处", "is_correct": true, "explanation": "正确：原处指东西以前所在的那个地方。"}, {"text": "远处", "is_correct": false, "explanation": "远处（yuǎn chù）与原处（yuán chù）第一音节声调不同（第三声与第二声），意思是远的地方。"}, {"text": "原初", "is_correct": false, "explanation": "原初（yuán chū）与原处（yuán chù）末音节声调不同（第一声与第四声），意思是最开始的时候。"}, {"text": "元初", "is_correct": false, "explanation": "元初（yuán chū）与原处（yuán chù）末音节声调不同（第一声与第四声），意思是元朝初年。"}], "explanations": {"原处": "正确：原处指东西以前所在的那个地方。", "远处": "远处（yuǎn chù）与原处（yuán chù）第一音节声调不同（第三声与第二声），意思是远的地方。", "原初": "原初（yuán chū）与原处（yuán chù）末音节声调不同（第一声与第四声），意思是最开始的时候。", "元初": "元初（yuán chū）与原处（yuán chù）末音节声调不同（第一声与第四声），意思是元朝初年。"}, "sentence_index": null, "correct_answer": "原处"}, "level_3": {"options": [{"text": "原处", "is_correct": true, "explanation": "正确：原处指东西以前所在的地方，与“找不到”的语境相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：书不会放在海洋里，与“不在”后的处所语境不合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：书不会放在天空里，与句中的语境不合。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“不在”后接处所，“时间”不是处所，不能说“书不在时间”。"}], "explanations": {"原处": "正确：原处指东西以前所在的地方，与“找不到”的语境相符。", "海洋": "语义：书不会放在海洋里，与“不在”后的处所语境不合。", "天空": "语义：书不会放在天空里，与句中的语境不合。", "时间": "搭配：“不在”后接处所，“时间”不是处所，不能说“书不在时间”。"}, "sentence_index": 0, "correct_answer": "原处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这半年他的工作一直在原处踏步。", "explanation": "这里应该用〈原地〉。“原地踏步”是固定说法，比喻没有进步；“原处”只指地点，不能和“踏步”搭配。"}, {"text": "这件毛衣洗后仍保持原处，没有缩水。", "explanation": "这里应该用〈原样〉。“原处”指地点，衣物洗后状态不变要说“保持原样”，不能说“保持原处”。"}, {"text": "这件事的原处让我们都很担心。", "explanation": "这里应该用〈原因〉。“原处”指东西原来的地方，不能用来指事情的起因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原处", "is_correct": true, "explanation": "正确：原处指原来的地方，与“站在”相符。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是抽象内容，人不能“站在”故事上。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是液体，人不能“站在”眼泪上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“站在”后接处所，“声音”不是处所，不能说“站在声音”。"}], "explanations": {"原处": "正确：原处指原来的地方，与“站在”相符。", "故事": "语义：故事是抽象内容，人不能“站在”故事上。", "眼泪": "语义：眼泪是液体，人不能“站在”眼泪上。", "声音": "搭配：“站在”后接处所，“声音”不是处所，不能说“站在声音”。"}, "sentence_index": 6, "correct_answer": "原处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在原处工作了十年，从来没换过公司。", "explanation": "这里应该用〈原单位〉。“原处”只指东西原来的位置，不指工作的单位。"}, {"text": "请把翻译和原处对照一下，看看有没有错。", "explanation": "这里应该用〈原文〉。“原处”指地方，不能指被翻译的文字。"}, {"text": "我们还是按原处计划，明天早上出发。", "explanation": "这里应该用〈原定〉。“原处”是表示地点的名词，不能修饰“计划”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "东西一直在原处在。", "corrected_sentence": "东西一直在原处。", "error_description": "多余成分：句末多加了“在”，表示位置只说“在原处”，“原处”后不能再加“在”，应说“东西一直在原处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把它搬回了在原处。", "corrected_sentence": "她把它搬回了原处。", "error_description": "多余成分：“搬回了”后直接接处所“原处”，不需要“在”；多加“在”是错误，应说“搬回了原处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "于是是说前面的事发生了,接着就有了后面的事。", "primary_collocate": null, "pronunciation": "yú shì", "ipa": "y˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师讲完了，于是同学们下课了。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不够，于是我没买那件衣服。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，于是请了一天假。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，于是妈妈抱起了他。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都累了，于是坐下来休息。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门没关，于是小猫跑了进来。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到得太早，于是先去喝茶。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，于是我借了他的。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天晴了，于是我们去公园玩。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听说那里很美，于是决定去看看。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "于是：前事发生，接着有后事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "于是", "is_correct": true, "explanation": "yú shì：连词，表示前事发生后接着有后事，正是本句的意思。"}, {"text": "预示", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是预示，不是于是。"}, {"text": "玉石", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是玉石。"}, {"text": "雨势", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨势。"}, {"text": "鱼食", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是鱼的食物。"}], "explanations": {"于是": "yú shì：连词，表示前事发生后接着有后事，正是本句的意思。", "预示": "yù（第四声）与 yú（第二声）声调不同，意思是预示，不是于是。", "玉石": "yù（第四声）与 yú（第二声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是玉石。", "雨势": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨势。", "鱼食": "shí（第二声）与 shì（第四声）声调不同，意思是鱼的食物。"}, "sentence_index": null, "correct_answer": "于是"}, "level_3": {"options": [{"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，而「老师讲完」与「同学下课」之间没有转折关系，不能用。"}, {"text": "于是", "is_correct": true, "explanation": "于是：承接前事，引出接着发生的后事，讲完课之后下课，正确。"}, {"text": "不过", "is_correct": false, "explanation": "语义：不过同样表示转折，句中前后并不相反，不能用。"}, {"text": "然而", "is_correct": false, "explanation": "语义：然而表示转折（且偏书面），而「老师讲完」与「同学下课」是顺承关系，不能用。"}], "explanations": {"但是": "语义：但是表示转折，而「老师讲完」与「同学下课」之间没有转折关系，不能用。", "于是": "于是：承接前事，引出接着发生的后事，讲完课之后下课，正确。", "不过": "语义：不过同样表示转折，句中前后并不相反，不能用。", "然而": "语义：然而表示转折（且偏书面），而「老师讲完」与「同学下课」是顺承关系，不能用。"}, "sentence_index": 0, "correct_answer": "于是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果明天不下雨，于是我们去爬山。", "explanation": "这里应该用〈那么〉。于是引出的是已经发生的事之后的结果，假设的情况要用那么。"}, {"text": "这家店的菜很好吃，于是价格也便宜。", "explanation": "这里应该用〈而且〉。于是表示前事之后接着的事，两个优点并列要用而且。"}, {"text": "他答应了，于是后来没去。", "explanation": "这里应该用〈但是〉。于是表示接续或因果，而「答应」与「后来没去」是转折关系，要用但是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "于是", "is_correct": true, "explanation": "yú shì：连词，表示前事发生后接着有后事，正是本句的意思。"}, {"text": "仪式", "is_correct": false, "explanation": "yí（第二声）与 yú（第二声）声调相同，韵母不同（i 与 ü），意思是仪式。"}, {"text": "逾时", "is_correct": false, "explanation": "yú（第二声）相同，shí（第二声）与 shì（第四声）声调不同，意思是超过规定的时间，不是于是。"}, {"text": "遇事", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，shì 相同，意思是遇到事情，不是于是。"}], "explanations": {"于是": "yú shì：连词，表示前事发生后接着有后事，正是本句的意思。", "仪式": "yí（第二声）与 yú（第二声）声调相同，韵母不同（i 与 ü），意思是仪式。", "逾时": "yú（第二声）相同，shí（第二声）与 shì（第四声）声调不同，意思是超过规定的时间，不是于是。", "遇事": "yù（第四声）与 yú（第二声）声调不同，shì 相同，意思是遇到事情，不是于是。"}, "sentence_index": null, "correct_answer": "于是"}, "level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "语义：而是用于纠正前面的否定说法，前句并没有否定，不能用。"}, {"text": "于是", "is_correct": true, "explanation": "于是：承接前事，引出接着发生的后事，到得早之后先去喝茶，正确。"}, {"text": "否则", "is_correct": false, "explanation": "语义：否则表示「如果不这样，就会怎样」，与「到得早→先喝茶」的顺承不符，不能用。"}, {"text": "不然", "is_correct": false, "explanation": "语义：不然表示假设中的另一种选择，与前句的顺承不符。"}], "explanations": {"而是": "语义：而是用于纠正前面的否定说法，前句并没有否定，不能用。", "于是": "于是：承接前事，引出接着发生的后事，到得早之后先去喝茶，正确。", "否则": "语义：否则表示「如果不这样，就会怎样」，与「到得早→先喝茶」的顺承不符，不能用。", "不然": "语义：不然表示假设中的另一种选择，与前句的顺承不符。"}, "sentence_index": 6, "correct_answer": "于是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天不想出门，于是外面太冷。", "explanation": "这里应该用〈因为〉。于是引出的是前事之后的结果，不能用来说明原因，这里应说「因为外面太冷」。"}, {"text": "妈妈一边做饭，于是听广播。", "explanation": "这里〈于是〉用错了。于是表示前事之后接着发生的事，而做饭和听广播是同时进行的，应表达同时，不能用接续的于是。"}, {"text": "我们把窗户关上，于是雨水进来。", "explanation": "这里应该用〈以免〉。以免表示为了避免某种情况，于是表示结果，这句话把意思说反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天亮了，于是因此大家起床了。", "corrected_sentence": "天亮了，于是大家起床了。", "error_description": "错误：于是和因此都表示因果，同时使用造成重复。正确做法是去掉「因此」，只用「于是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们到了车站，所以于是买了票。", "corrected_sentence": "我们到了车站，于是买了票。", "error_description": "错误：“所以”与“于是”都表示因果承接，二者不能叠用，应删去「所以」，即“我们到了车站，于是买了票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
