INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88414, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词,表示后一事承接前一事,常含有因果关系。", "primary_collocate": null, "pronunciation": "yú shì", "ipa": "y˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "天黑了，于是我们回家了。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没带伞，于是跑回了家。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得饿了，于是做了一碗面。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来了，于是我多做了两个菜。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，于是大家走着去学校。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学汉语，于是买了一本书。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太热，于是他打开了窗。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天下雨了，于是比赛改到明天。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找不到路，于是问了一位老人。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影很好看，于是我又看了一遍。", "target_word": "于是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "于是：承接前事，常含因果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "于是", "is_correct": true, "explanation": "yú shì：连词，承接前事、引出后事，正是本句的意思。"}, {"text": "预示", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是预示，不是于是。"}, {"text": "玉石", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是玉石。"}, {"text": "雨势", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨势。"}, {"text": "鱼食", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是鱼的食物。"}], "explanations": {"于是": "yú shì：连词，承接前事、引出后事，正是本句的意思。", "预示": "yù（第四声）与 yú（第二声）声调不同，意思是预示，不是于是。", "玉石": "yù（第四声）与 yú（第二声）声调不同，shí（第二声）与 shì（第四声）声调也不同，意思是玉石。", "雨势": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨势。", "鱼食": "shí（第二声）与 shì（第四声）声调不同，意思是鱼的食物。"}, "sentence_index": null, "correct_answer": "于是"}, "level_3": {"options": [{"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，而「天黑了」与「回家了」之间没有转折关系，不能用。"}, {"text": "于是", "is_correct": true, "explanation": "于是：承接前事，引出由此而来的后事，句中是天黑之后回家，正确。"}, {"text": "不过", "is_correct": false, "explanation": "语义：不过同样表示转折，句中前后并不相反，不能用。"}, {"text": "然而", "is_correct": false, "explanation": "语义：然而表示转折（且偏书面），而「天黑了」与「回家了」是顺承关系，不能用。"}], "explanations": {"但是": "语义：但是表示转折，而「天黑了」与「回家了」之间没有转折关系，不能用。", "于是": "于是：承接前事，引出由此而来的后事，句中是天黑之后回家，正确。", "不过": "语义：不过同样表示转折，句中前后并不相反，不能用。", "然而": "语义：然而表示转折（且偏书面），而「天黑了」与「回家了」是顺承关系，不能用。"}, "sentence_index": 0, "correct_answer": "于是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "如果明天下雨，于是我们取消比赛。", "explanation": "这里应该用〈那么〉。于是引出的是已经发生的事之后的结果，假设的情况要用那么。"}, {"text": "他会说汉语，于是也会说英语。", "explanation": "这里应该用〈而且〉。于是表示前事引出的结果，两种语言能力之间没有因果关系，并列要用而且。"}, {"text": "他很努力，于是没有考上。", "explanation": "这里应该用〈但是〉。于是表示顺承或因果，而「努力」与「没考上」是转折关系，要用但是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88414, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "于是", "is_correct": true, "explanation": "yú shì：连词，承接前事、引出后事，正是本句的意思。"}, {"text": "仪式", "is_correct": false, "explanation": "yí（第二声）与 yú（第二声）声调相同，韵母不同（i 与 ü），意思是仪式。"}, {"text": "逾时", "is_correct": false, "explanation": "yú（第二声）相同，shí（第二声）与 shì（第四声）声调不同，意思是超过规定的时间，不是于是。"}, {"text": "遇事", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，shì 相同，意思是遇到事情，不是于是。"}], "explanations": {"于是": "yú shì：连词，承接前事、引出后事，正是本句的意思。", "仪式": "yí（第二声）与 yú（第二声）声调相同，韵母不同（i 与 ü），意思是仪式。", "逾时": "yú（第二声）相同，shí（第二声）与 shì（第四声）声调不同，意思是超过规定的时间，不是于是。", "遇事": "yù（第四声）与 yú（第二声）声调不同，shì 相同，意思是遇到事情，不是于是。"}, "sentence_index": null, "correct_answer": "于是"}, "level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "语义：而是用于纠正前面的否定说法，前句并没有否定，不能用。"}, {"text": "于是", "is_correct": true, "explanation": "于是：承接前事，引出由此而来的后事，房间太热所以开窗，正确。"}, {"text": "否则", "is_correct": false, "explanation": "语义：否则表示「如果不这样，就会怎样」，与「太热→开窗」的顺承不符，不能用。"}, {"text": "不然", "is_correct": false, "explanation": "语义：不然表示假设中的另一种选择，与「太热→打开窗」的顺承不符。"}], "explanations": {"而是": "语义：而是用于纠正前面的否定说法，前句并没有否定，不能用。", "于是": "于是：承接前事，引出由此而来的后事，房间太热所以开窗，正确。", "否则": "语义：否则表示「如果不这样，就会怎样」，与「太热→开窗」的顺承不符，不能用。", "不然": "语义：不然表示假设中的另一种选择，与「太热→打开窗」的顺承不符。"}, "sentence_index": 6, "correct_answer": "于是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没来，于是他生病了。", "explanation": "这里应该用〈因为〉。于是引出的是前事之后的结果，不能用来说明原因。"}, {"text": "他一边吃饭，于是看书。", "explanation": "这里〈于是〉用错了。于是表示前事之后接着发生的事，而吃饭和看书是同时进行的，应表达同时，不能用接续的于是。"}, {"text": "他早点出门，于是迟到了。", "explanation": "这里〈于是〉用错了。于是表示顺承、合乎常理的结果，而早出门却迟到是出乎意料的结果，应该用〈结果〉或〈却〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停了，于是所以我们出去散步。", "corrected_sentence": "雨停了，于是我们出去散步。", "error_description": "错误：于是和所以都表示因果，同时使用造成重复。正确做法是去掉「所以」，只用「于是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刮风了，于是于是比赛推迟了。", "corrected_sentence": "刮风了，于是比赛推迟了。", "error_description": "重复错误：「于是于是」应为「于是」。连词“于是”只用一次，重复使用不合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88415, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分开", "is_correct": true, "explanation": "分开与“相遇”意思相反，指两人从一起到分离。"}, {"text": "思考", "is_correct": false, "explanation": "无关：思考是动词，但与“相遇”没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "无关：生长指植物或人的发育，与“相遇”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "无关：完成指做完某件事，与“相遇”没有反义关系。"}], "correct_answer": "分开", "explanations": {"分开": "分开与“相遇”意思相反，指两人从一起到分离。", "思考": "无关：思考是动词，但与“相遇”没有反义关系。", "生长": "无关：生长指植物或人的发育，与“相遇”没有反义关系。", "完成": "无关：完成指做完某件事，与“相遇”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
