INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88415, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "相遇是两个人在路上碰到了。", "primary_collocate": null, "pronunciation": "xiāng yù", "ipa": "ɕjɑŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "我和老朋友在路上相遇了。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在街口相遇，笑着打招呼。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放学路上，我和小王常常相遇。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在回家的路上相遇过一次。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人在小路上相遇，都停了下来。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天早上，我和老师在路上相遇。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和妹妹在公园门口相遇了。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在回家的路上，和同学相遇了。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在桥上相遇，说了几句话。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天上班路上，都和他相遇。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相遇了", "label": "体标：了"}, {"form": "相遇过", "label": "体标：过"}], "register": "书面语", "sense_fingerprint": "两个人在路上碰到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相遇", "is_correct": true, "explanation": "相遇指两个人在路上碰到了。这里是我和老朋友在路上碰到，正好相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚指两人成为夫妻，不能说是在路上发生的事。"}, {"text": "相信", "is_correct": false, "explanation": "配价：“相信”后面要带宾语，不能只说“在路上相信了”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指人来到世界，不能发生在路上。"}], "explanations": {"相遇": "相遇指两个人在路上碰到了。这里是我和老朋友在路上碰到，正好相合。", "结婚": "语义：结婚指两人成为夫妻，不能说是在路上发生的事。", "相信": "配价：“相信”后面要带宾语，不能只说“在路上相信了”。", "出生": "语义：出生指人来到世界，不能发生在路上。"}, "sentence_index": 0, "correct_answer": "相遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人在回家的路上相遇过一次。", "explanation": "语义：这里只有一个人，应改用〈路过〉；“相遇”要求彼此双方碰上。"}, {"text": "我们明天在公司相遇，讨论合同。", "explanation": "这里应该用〈会面〉。相遇指偶然碰到，有计划的见面要用会面。"}, {"text": "这两本书在书架上相遇了。", "explanation": "语义：这里误用了“相遇”，两本书只能说〈摆放〉，不能说相遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相遇", "is_correct": true, "explanation": "相遇指两个人在路上碰到了。这里是他和妹妹在公园门口碰到，正好相合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是身体不舒服，与“在公园门口”的碰面意思不相关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“在公园门口”的碰面不相关。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书籍，不能与“公园门口”搭配。"}], "explanations": {"相遇": "相遇指两个人在路上碰到了。这里是他和妹妹在公园门口碰到，正好相合。", "生病": "语义：生病是身体不舒服，与“在公园门口”的碰面意思不相关。", "睡觉": "语义：睡觉与“在公园门口”的碰面不相关。", "出版": "搭配：“出版”用于书籍，不能与“公园门口”搭配。"}, "sentence_index": 6, "correct_answer": "相遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天在家里都和他相遇。", "explanation": "语义：相遇指在外面偶然碰到，在家里碰面应该说“见面”。"}, {"text": "我们下午三点在车站相遇，一起去看电影。", "explanation": "这里应该用〈约会〉。相遇指偶然碰到，事先约好的见面要用约会。"}, {"text": "我一个人在上班路上相遇了。", "explanation": "语义：这里只有一个人，“相遇”要求彼此双方碰上，应改说〈走着〉之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
