INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88416, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彼此遇见；碰上。", "primary_collocate": null, "pronunciation": "xiāng yù", "ipa": "ɕjɑŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "多年以后，他们在机场相遇了。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两支球队在决赛中相遇。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在大学里相遇，后来成了朋友。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相遇的那天，天正下着雨。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说，人和人相遇是一种缘分。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个老同学在火车站相遇，非常高兴。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到会在这里和你相遇。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在旅行中相遇，聊了一个晚上。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两条河在这里相遇，流向大海。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位作家直到晚年才第一次相遇。", "target_word": "相遇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相遇了", "label": "体标：了"}, {"form": "相遇过", "label": "体标：过"}], "register": "书面语", "sense_fingerprint": "彼此遇见、碰上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.va