INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相遇", "is_correct": true, "explanation": "相遇指彼此遇见、碰上。这里是他们在机场重逢，正好相合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病是身体不舒服，与“在机场相遇”的意思不相关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与“在机场相遇”的意思不相关。"}, {"text": "相信", "is_correct": false, "explanation": "配价：“相信”后面要带宾语，不能只说“在机场相信了”。"}], "explanations": {"相遇": "相遇指彼此遇见、碰上。这里是他们在机场重逢，正好相合。", "生病": "语义：生病是身体不舒服，与“在机场相遇”的意思不相关。", "睡觉": "语义：睡觉与“在机场相遇”的意思不相关。", "相信": "配价：“相信”后面要带宾语，不能只说“在机场相信了”。"}, "sentence_index": 0, "correct_answer": "相遇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人在机场相遇了。", "explanation": "语义：这里只有一个人，应改用〈到达〉；“相遇”要求彼此双方碰上。"}, {"text": "我们明天在公司相遇，讨论合同。", "explanation": "这里应该用〈会面〉。相遇指偶然碰到，有计划的见面要用会面。"}, {"text": "这两本书在书架上相遇了。", "explanation": "语义：这里误用了“相遇”，两本书只能说〈摆放〉，不能说相遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相遇", "is_correct": true, "explanation": "相遇指彼此遇见、碰上。这里说没想到会在这里和你遇见，正好相合。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书籍，不能与“和你”搭配。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体生病，与“在这里和你”的意思不相关。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指人来到世界，不能用来表示见面。"}], "explanations": {"相遇": "相遇指彼此遇见、碰上。这里说没想到会在这里和你遇见，正好相合。", "出版": "搭配：“出版”用于书籍，不能与“和你”搭配。", "感冒": "语义：感冒是身体生病，与“在这里和你”的意思不相关。", "出生": "语义：出生指人来到世界，不能用来表示见面。"}, "sentence_index": 6, "correct_answer": "相遇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两位作家直到晚年才第一次相遇，但两人从没见过面。", "explanation": "语义：这里把“相遇”用在两人从未见过面的句子里，相遇指彼此碰上，与“从没见过面”矛盾；应说〈还没见面〉。"}, {"text": "两本书直到晚年才第一次相遇。", "explanation": "语义：这里误用了“相遇”，两本书只能说〈放在一起〉，不能表示碰面。"}, {"text": "两位作家在电话里第一次相遇。", "explanation": "语义：相遇指当面碰上，在电话里只能说〈通话〉，不能说相遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在车站被相遇了。", "corrected_sentence": "他们在车站相遇了。", "error_description": "错误：“相遇”是不及物动词，不能用“被”构成被动句。正确：应说“他们在车站相遇了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两条河在这里相遇着，合成了一条大河。", "corrected_sentence": "两条河在这里相遇，合成了一条大河。", "error_description": "错误：“相遇”后面多加了“着”。正确：这里表示已经发生的相遇，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
