INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88417, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参照是看着别人做的样子，照着去做。", "primary_collocate": null, "pronunciation": "cān zhào", "ipa": "tsʰan˥ ʈʂau˥˩", "syllable_count": 2, "sentences": [{"text": "他参照老师的样子，认真地写字。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我参照妈妈的做法，做了一个蛋糕。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你参照这张图片，画一只小猫。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友参照哥哥的动作，学习跳舞。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参照书上的步骤，做了一件衣服。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工可以参照老同事的办法工作。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你参照这个样子，再做一个一样的。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们参照老师的示范，练习写毛笔字。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我参照菜谱上的方法，做了一盘鱼。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参照朋友的房间，布置了自己的家。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参照着", "label": "体标"}, {"form": "参照了", "label": "体标"}, {"form": "参照过", "label": "体标"}, {"form": "参照物", "label": "复合"}], "register": "通用", "sense_fingerprint": "看着别人的样子照着做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”多接纸张、文件、协议，不能说“撕毁老师的样子”。"}, {"text": "参照", "is_correct": true, "explanation": "正确：参照是看着别人的样子，照着去做。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑，与“认真地写字”的语境不符。"}, {"text": "违背", "is_correct": false, "explanation": "搭配：“违背”多接规则、要求，不能说“违背老师的样子”。"}], "explanations": {"撕毁": "搭配：“撕毁”多接纸张、文件、协议，不能说“撕毁老师的样子”。", "参照": "正确：参照是看着别人的样子，照着去做。", "嘲笑": "语义：“嘲笑”是取笑，与“认真地写字”的语境不符。", "违背": "搭配：“违背”多接规则、要求，不能说“违背老师的样子”。"}, "sentence_index": 0, "correct_answer": "参照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下个月我要参照学校的足球比赛。", "explanation": "这里应该用〈参加〉。“参照”是照着别人的做法去做，参与比赛要用〈参加〉。"}, {"text": "周末我们一起参照了科技馆。", "explanation": "这里应该用〈参观〉。“参照”指照着别人的样子做，去场所看看要用〈参观〉。"}, {"text": "他每天早上参照生病的奶奶。", "explanation": "这里应该用〈照顾〉。“参照”的对象是别人的做法或样子，照料人要用〈照顾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢掉不要，与“再做一个一样的”语境矛盾。"}, {"text": "参照", "is_correct": true, "explanation": "正确：参照是看着别人的样子，照着去做。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与“再做一个一样的”语境矛盾。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多接记录、规定，不能说“打破这个样子”。"}], "explanations": {"抛弃": "语义：“抛弃”是丢掉不要，与“再做一个一样的”语境矛盾。", "参照": "正确：参照是看着别人的样子，照着去做。", "拒绝": "语义：“拒绝”是不接受，与“再做一个一样的”语境矛盾。", "打破": "搭配：“打破”多接记录、规定，不能说“打破这个样子”。"}, "sentence_index": 6, "correct_answer": "参照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参照了这次会议。", "explanation": "这里应该用〈参加〉。“参照”是照着别人的做法去做，出席会议要用〈参加〉。"}, {"text": "他代表学校参照了这次作文比赛。", "explanation": "这里应该用〈参加〉。“参照”是照着别人的做法去做，参与比赛要用〈参加〉。"}, {"text": "月光参照着湖面。", "explanation": "这里应该用〈照耀〉。“参照”不能表示光线照射，光线照在湖面上要用〈照耀〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
