INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88418, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参考并对照。", "primary_collocate": null, "pronunciation": "cān zhào", "ipa": "tsʰan˥ ʈʂau˥˩", "syllable_count": 2, "sentences": [{"text": "写报告时，可以参照去年的资料。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格请参照下面的表格。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要参照学校的规定来办。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们参照市场价格，定了新的价钱。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生参照检查结果，决定了治疗方法。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译时，他常参照几本词典。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以参照其他国家的经验，改进工作。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请参照说明书上的数字调整机器。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师参照往年的成绩，出了今年的题。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写合同要参照法律的规定。", "target_word": "参照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参照着", "label": "体标"}, {"form": "参照了", "label": "体标"}, {"form": "参照过", "label": "体标"}, {"form": "参照物", "label": "复合"}], "register": "通用", "sense_fingerprint": "参考资料或标准并对照", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑，对资料无法这样做，与“写报告时参考资料”的语境不符。"}, {"text": "参照", "is_correct": true, "explanation": "正确：参照指参考并对照，写报告时可以参考去年的资料。"}, {"text": "违背", "is_correct": false, "explanation": "搭配：“违背”多接规则、要求，不能说“违背去年的资料”。"}, {"text": "辩论", "is_correct": false, "explanation": "搭配：“辩论”指围绕观点争论，不能说“辩论去年的资料”。"}], "explanations": {"嘲笑": "语义：“嘲笑”是取笑，对资料无法这样做，与“写报告时参考资料”的语境不符。", "参照": "正确：参照指参考并对照，写报告时可以参考去年的资料。", "违背": "搭配：“违背”多接规则、要求，不能说“违背去年的资料”。", "辩论": "搭配：“辩论”指围绕观点争论，不能说“辩论去年的资料”。"}, "sentence_index": 0, "correct_answer": "参照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次参照了那场音乐会。", "explanation": "这里应该用〈参加〉。“参照”指参考并对照，去现场参与活动要用〈参加〉。"}, {"text": "春节时，我们一起参照了寺庙。", "explanation": "这里应该用〈参拜〉。“参照”不指去寺庙，去寺庙烧香拜佛要用〈参拜〉。"}, {"text": "护士每天参照那位老人。", "explanation": "这里应该用〈照料〉。“参照”的对象是资料、做法，照料病人要用〈照料〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驳斥", "is_correct": false, "explanation": "搭配：“驳斥”多接观点、言论，不接“经验”。"}, {"text": "参照", "is_correct": true, "explanation": "正确：参照指参考并对照，可以借鉴其他国家的经验来改进工作。"}, {"text": "嘲讽", "is_correct": false, "explanation": "语义：“嘲讽”是讥笑，与“改进工作”的语境相反。"}, {"text": "鄙视", "is_correct": false, "explanation": "语义：“鄙视”是看不起，与“改进工作”借鉴经验的语境相反。"}], "explanations": {"驳斥": "搭配：“驳斥”多接观点、言论，不接“经验”。", "参照": "正确：参照指参考并对照，可以借鉴其他国家的经验来改进工作。", "嘲讽": "语义：“嘲讽”是讥笑，与“改进工作”的语境相反。", "鄙视": "语义：“鄙视”是看不起，与“改进工作”借鉴经验的语境相反。"}, "sentence_index": 6, "correct_answer": "参照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天参照了学校的运动会。", "explanation": "这里应该用〈参加〉。“参照”是参考、对照的意思，参与活动要用〈参加〉。"}, {"text": "周末我们一起参照了工厂。", "explanation": "这里应该用〈参观〉。“参照”不指去工厂看看，去工厂看看要用〈参观〉。"}, {"text": "他每天认真参照那位小孩。", "explanation": "这里应该用〈照看〉。“参照”的对象是资料、做法，照看孩子要用〈照看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前参照了过这份资料。", "corrected_sentence": "我以前参照过这份资料。", "error_description": "错误：“过”表示经历，“了”表示完成，二者不能同时用在“参照”后。应只说“参照过这份资料”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一边参照了着说明书，一边组装玩具。", "corrected_sentence": "他一边参照着说明书，一边组装玩具。", "error_description": "错误：“了”与“着”不能同时用在“参照”后，应去掉“了”，说“参照着说明书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
