INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88419, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日月是太阳和月亮。", "primary_collocate": null, "pronunciation": "rì yuè", "ipa": "ɻ̩˥˩ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "日月从东边升起，在西边落下。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上有日月和星星。", "target_word": "日月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古人天天看日月，知道时间。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日月都是天上的东西。", "target_word": "日月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "日月照亮了大地。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人看着日月升落，慢慢知道了一天有多长。", "target_word": "日月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，日月是天上最亮的两个东西。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那幅画画着天上的日月和山。", "target_word": "日月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳和月亮合起来，就是日月。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人拜日月，希望天气好。", "target_word": "日月", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "日月：名词，天上的太阳和月亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 东边 (Zipf 3.76), 升起 (Zipf 3.91), 西边 (Zipf 3.81), 落下 (Zipf 3.98)']::text[], '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日月", "is_correct": true, "explanation": "日月：指天上的太阳和月亮，能从东边升起、在西边落下，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会从东边升起，与天体的运动相悖。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“升起”“落下”不用于花朵。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：山脉是固定的地形，不会升起或落下。"}], "explanations": {"日月": "日月：指天上的太阳和月亮，能从东边升起、在西边落下，符合句意。", "房子": "语义：房子不会从东边升起，与天体的运动相悖。", "花朵": "搭配：“升起”“落下”不用于花朵。", "山脉": "语义：山脉是固定的地形，不会升起或落下。"}, "sentence_index": 0, "correct_answer": "日月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天中午，日月很热，大家都不想出门。", "explanation": "这里应该用〈太阳〉。日月指太阳和月亮两者，单指白天发热的太阳要说太阳。"}, {"text": "墙上挂着一张日月，每天撕一页。", "explanation": "这里应该用〈日历〉。日月指太阳和月亮，不能指每天撕页的日期本，要说日历。"}, {"text": "中秋节的晚上，日月特别圆。", "explanation": "这里应该用〈月亮〉。日月包括太阳，指中秋夜圆圆的天体时只能说月亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日月", "is_correct": true, "explanation": "日月：指太阳和月亮，是天上最亮的两个东西，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不发光，不能是天上最亮的东西。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“天上最亮的两个东西”只指发光体，河流不能这样说。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原在地上，不是天上的东西。"}], "explanations": {"日月": "日月：指太阳和月亮，是天上最亮的两个东西，符合句意。", "石头": "语义：石头不发光，不能是天上最亮的东西。", "河流": "搭配：“天上最亮的两个东西”只指发光体，河流不能这样说。", "草原": "语义：草原在地上，不是天上的东西。"}, "sentence_index": 6, "correct_answer": "日月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中午的日月毒得很，大家都躲进了屋里。", "explanation": "这里应该用〈日头〉。日月指太阳和月亮的合称，形容中午阳光毒辣时要单说日头。"}, {"text": "晚上，天上挂着一个日月，又圆又亮。", "explanation": "这里应该用〈月亮〉。日月指太阳和月亮两个天体，晚上挂在天上的一个圆东西是月亮。"}, {"text": "晴朗的夜晚，天上的日月特别多。", "explanation": "这里应该用〈星星〉。日月只指一个太阳和一个月亮，不能说“特别多”，许多天体要说星星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日月们每天从东边升起，从西边落下。", "corrected_sentence": "日月每天从东边升起，从西边落下。", "error_description": "错误：“日月”指太阳和月亮，不能加“们”表示复数。正确：日月每天从东边升起。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古人常常观察日月们来推算季节。", "corrected_sentence": "古人常常观察日月来推算季节。", "error_description": "错误：“日月”不能加“们”表示复数。正确：观察日月来推算季节。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
