INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指时间、岁月，即一段时光。", "primary_collocate": null, "pronunciation": "rì yuè", "ipa": "ɻ̩˥˩ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "日月过得真快，孩子已经长大了。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在国外的那些日月里，我常常想家。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人回想起过去的日月，心里很平静。", "target_word": "日月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些日月虽然苦，但我们都很快乐。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日月不等人，我们要好好学习。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在山里过了十年平静的日月。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把美好的日月写进了日记里。", "target_word": "日月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年的日月里，我们一直互相陪伴。", "target_word": "日月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日月一天天过去，他终于学会了开车。", "target_word": "日月", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这平凡的日月里，他一直没有放弃。", "target_word": "日月", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "日月：名词，引申指时间、岁月、日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日月", "is_correct": true, "explanation": "日月：指时间、岁月，作主语，与“过得真快”的句意相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是时间，不会“过得真快”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“过得真快”多用于时间或生活，汽车不能这样说。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不表示时间，不能“过得真快”。"}], "explanations": {"日月": "日月：指时间、岁月，作主语，与“过得真快”的句意相符。", "房子": "语义：房子不是时间，不会“过得真快”。", "汽车": "搭配：“过得真快”多用于时间或生活，汽车不能这样说。", "石头": "语义：石头不表示时间，不能“过得真快”。"}, "sentence_index": 0, "correct_answer": "日月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们只过了三个日月，就搬走了。", "explanation": "这里应该用〈月〉。日月泛指一段时光，不能当作计量单位来数，计数要说“三个月”。"}, {"text": "今天的日月是十号。", "explanation": "这里应该用〈日期〉。日月指一段时间或岁月，不能用来指某一天的日期。"}, {"text": "这个日月，我们都很激动。", "explanation": "这里应该用〈时刻〉。日月指较长的一段时间，不能指某个时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日月", "is_correct": true, "explanation": "日月：指岁月或一段时光，可以写进日记里，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是可以写进日记的美好事情。"}, {"text": "凳子", "is_correct": false, "explanation": "语义：凳子不是“美好”的事，不能写进日记。"}, {"text": "砖头", "is_correct": false, "explanation": "搭配：“美好”修饰抽象的经历或时光，不能修饰砖头。"}], "explanations": {"日月": "日月：指岁月或一段时光，可以写进日记里，符合句意。", "桌子": "语义：桌子不是可以写进日记的美好事情。", "凳子": "语义：凳子不是“美好”的事，不能写进日记。", "砖头": "搭配：“美好”修饰抽象的经历或时光，不能修饰砖头。"}, "sentence_index": 6, "correct_answer": "日月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个周末的日月很好，适合去爬山。", "explanation": "这里应该用〈天气〉。日月指时间、岁月，不能用来形容天气的好坏，说天气好要用“天气”。"}, {"text": "我每天写日月，记录生活的点滴。", "explanation": "这里应该用〈日记〉。日月不能指记录每天事情的本子。"}, {"text": "我们日月去工作，晚上休息。", "explanation": "这里应该用〈白天〉。日月是指时间段的名词，不能用来表示白天这一时段，也不能作时间状语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日月们飞快地过去，我们都长大了。", "corrected_sentence": "日月飞快地过去，我们都长大了。", "error_description": "错误：“日月”表示时间时不能加“们”表示复数。正确：日月飞快地过去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这些日月们都记在了心里。", "corrected_sentence": "他把这些日月都记在了心里。", "error_description": "错误：“日月”表示时间时不能加“们”。正确：他把这些日月都记在了心里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
