INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88421, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看上去是用眼睛一看，觉得是这个样子。", "primary_collocate": null, "pronunciation": "kàn shàng qù", "ipa": "kʰan˥˩ ʂaŋ˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "这个苹果看上去很新鲜。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看上去有点儿累。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天看上去要下雨了。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜看上去很好吃。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个房间看上去很干净。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆看上去不太大。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看上去很年轻，其实已经三十岁了。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书看上去很旧，但是内容很好。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去很高兴，可是一句话也没说。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山看上去不高，爬起来很累。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用眼睛一看就得出印象，觉得像是某个样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看上去", "is_correct": true, "explanation": "看上去：用眼睛一看得出的印象，与“很新鲜”搭配自然。"}, {"text": "听起来", "is_correct": false, "explanation": "语义：“听起来”靠听觉判断，苹果的新鲜度不能用耳朵听出来。"}, {"text": "觉得", "is_correct": false, "explanation": "语义：“觉得”的主语必须是有感受的人，苹果不会觉得新鲜。"}, {"text": "拿起来", "is_correct": false, "explanation": "搭配：“拿起来”说的是手感的轻重，不用来评价苹果是否新鲜。"}], "explanations": {"看上去": "看上去：用眼睛一看得出的印象，与“很新鲜”搭配自然。", "听起来": "语义：“听起来”靠听觉判断，苹果的新鲜度不能用耳朵听出来。", "觉得": "语义：“觉得”的主语必须是有感受的人，苹果不会觉得新鲜。", "拿起来": "搭配：“拿起来”说的是手感的轻重，不用来评价苹果是否新鲜。"}, "sentence_index": 0, "correct_answer": "看上去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电话里看上去他很生气。", "explanation": "这里应该用〈听上去〉。看上去依靠视觉，电话里只能听见声音，要根据声音判断时用听上去。"}, {"text": "这束花看上去很香，你闻闻。", "explanation": "这里应该用〈闻上去〉。香是气味，看上去只能判断外观，判断花香要用闻上去。"}, {"text": "这首歌看上去很好听，你听听。", "explanation": "这里应该用〈听上去〉。好听是听觉上的判断，看上去依靠视觉，要用听上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看上去", "is_correct": true, "explanation": "看上去：外表给人的印象，与后面“其实已经三十岁”形成对比。"}, {"text": "做起来", "is_correct": false, "explanation": "语义：“做起来”说的是做事的感觉，不能用来描述人的外表年龄。"}, {"text": "说得", "is_correct": false, "explanation": "搭配：“说得”说的是说话的方式，不用来描述年龄和外貌。"}, {"text": "想得", "is_correct": false, "explanation": "语义：“想”是心理活动，不能让人从外表看出年轻。"}], "explanations": {"看上去": "看上去：外表给人的印象，与后面“其实已经三十岁”形成对比。", "做起来": "语义：“做起来”说的是做事的感觉，不能用来描述人的外表年龄。", "说得": "搭配：“说得”说的是说话的方式，不用来描述年龄和外貌。", "想得": "语义：“想”是心理活动，不能让人从外表看出年轻。"}, "sentence_index": 6, "correct_answer": "看上去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看上去他是对的。", "explanation": "这里是说话人的判断，应该用〈认为〉。看上去只说外表给人的印象，不能用来表示自己的看法。"}, {"text": "我看上去他去了北京。", "explanation": "这里是已经了解的情况，应该用〈知道〉。看上去只看外表，他去了哪里不能靠外观判断。"}, {"text": "我看上去有人在敲门。", "explanation": "这里说的是听到的声音，应该用〈听见〉。看上去依靠视觉，不能用来表示听到了什么。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子看上去了很结实。", "corrected_sentence": "这把椅子看上去很结实。", "error_description": "错误：“看上去”后面多加了“了”。正确说法是“看上去很结实”，“看上去”表示外表的判断，不带完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件外套看上去着很暖和，你穿吧。", "corrected_sentence": "这件外套看上去很暖和，你穿吧。", "error_description": "错误：“看上去”后面多加了“着”。正确说法是“看上去很暖和”，这里不需要“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
