INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外表看起来。", "primary_collocate": null, "pronunciation": "kàn shàng qù", "ipa": "kʰan˥˩ ʂaŋ˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "这个人看上去很老实。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看上去像个学生。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服看上去很贵。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看上去比我小几岁。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只狗看上去很凶，其实很听话。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车看上去很新，价钱却不高。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去三十多岁。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子看上去不大，里面东西很多。", "target_word": "看上去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人看上去很健康。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店看上去很高级。", "target_word": "看上去", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "只就人或物的外表、外观来判断，不涉及内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看上去", "is_correct": true, "explanation": "看上去：只凭外表得出的判断，与“很老实”搭配自然。"}, {"text": "吃起来", "is_correct": false, "explanation": "语义：“吃起来”说的是食物的口感，不能用来判断人的性格。"}, {"text": "读起来", "is_correct": false, "explanation": "语义：“读起来”说的是文字或文章给人的感觉，不能用于人。"}, {"text": "拿起来", "is_correct": false, "explanation": "搭配：“拿起来”说的是手感的轻重，不用来评价人的性格。"}], "explanations": {"看上去": "看上去：只凭外表得出的判断，与“很老实”搭配自然。", "吃起来": "语义：“吃起来”说的是食物的口感，不能用来判断人的性格。", "读起来": "语义：“读起来”说的是文字或文章给人的感觉，不能用于人。", "拿起来": "搭配：“拿起来”说的是手感的轻重，不用来评价人的性格。"}, "sentence_index": 0, "correct_answer": "看上去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头看上去很香。", "explanation": "这里应该用〈闻上去〉。香是气味，看上去只能判断外观，判断气味要用闻上去。"}, {"text": "电话里看上去她很高兴。", "explanation": "这里应该用〈听上去〉。电话里只能听见声音，看上去依靠视觉，根据声音判断要用听上去。"}, {"text": "看上去他的生日是三月。", "explanation": "这里是根据已知信息说的，应该用〈据我所知〉。生日不能从外表看出来，看上去不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看上去", "is_correct": true, "explanation": "看上去：只凭外表得出的判断，与“三十多岁”的年龄印象相符。"}, {"text": "闻起来", "is_correct": false, "explanation": "语义：“闻起来”说的是气味给人的感觉，不能用来判断人的年龄。"}, {"text": "写下来", "is_correct": false, "explanation": "语义：“写下来”表示把内容记在纸上，是动作，不能表示对外表的判断。"}, {"text": "变成", "is_correct": false, "explanation": "搭配：“变成”要求有变化的过程，句中没有变化，不能这样用。"}], "explanations": {"看上去": "看上去：只凭外表得出的判断，与“三十多岁”的年龄印象相符。", "闻起来": "语义：“闻起来”说的是气味给人的感觉，不能用来判断人的年龄。", "写下来": "语义：“写下来”表示把内容记在纸上，是动作，不能表示对外表的判断。", "变成": "搭配：“变成”要求有变化的过程，句中没有变化，不能这样用。"}, "sentence_index": 6, "correct_answer": "看上去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看上去他说的是真话。", "explanation": "这里是说话人的判断，应该用〈认为〉。看上去只说外表给人的印象，不能表示自己的看法。"}, {"text": "我看上去他去了北京。", "explanation": "这里是已经了解的情况，应该用〈知道〉。看上去只看外表，他去了哪里不能靠外观判断。"}, {"text": "我看上去他记得这件事。", "explanation": "这里是说话人的推测，应该用〈觉得〉。看上去只说外表给人的印象，不能表示自己的想法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这匹马看上去了很壮。", "corrected_sentence": "这匹马看上去很壮。", "error_description": "错误：“看上去”后面多加了“了”。正确说法是“看上去很壮”，“看上去”表示外表的判断，不带完成的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子看上去着很精神。", "corrected_sentence": "这个孩子看上去很精神。", "error_description": "错误：在“看上去”后面加了“着”。正确说法是直接说“看上去很精神”，这里不需要“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
