INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88423, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "为时是指事情用了多少时间，后面接时间长度，如「这次会议为时三天」。", "primary_collocate": null, "pronunciation": "wéi shí", "ipa": "weɪ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这次会议为时三天。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这条路为时两个月。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行为时一周，我们玩得很开心。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的实习为时半年。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛为时两个小时。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的运动会为时两天。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次培训为时十天，每天都要上课。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个工程为时三年，终于完成了。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次展览为时一个月，欢迎大家来看。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的讨论为时不长，很快就结束了。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為時", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为时:(事情)用了多少时间,后面接时间长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67aa835c-524f-4aad-8e43-c58392166a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88423, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是动词，指事情用了多少时间，是正确答案。"}, {"text": "委实", "is_correct": false, "explanation": "委实（wěi shí）与为时（wéi shí）第一音节声调不同，意思是确实，不指时间长度。"}, {"text": "卫视", "is_correct": false, "explanation": "卫视（wèi shì）与为时（wéi shí）两个音节声调都不同，指卫星电视频道。"}, {"text": "威势", "is_correct": false, "explanation": "威势（wēi shì）与为时（wéi shí）两个音节声调都不同，意思是威严的气势。"}, {"text": "为使", "is_correct": false, "explanation": "为使（wéi shǐ）与为时（wéi shí）第二音节声调不同，意思是为了让。"}], "explanations": {"为时": "为时是动词，指事情用了多少时间，是正确答案。", "委实": "委实（wěi shí）与为时（wéi shí）第一音节声调不同，意思是确实，不指时间长度。", "卫视": "卫视（wèi shì）与为时（wéi shí）两个音节声调都不同，指卫星电视频道。", "威势": "威势（wēi shì）与为时（wéi shí）两个音节声调都不同，意思是威严的气势。", "为使": "为使（wéi shǐ）与为时（wéi shí）第二音节声调不同，意思是为了让。"}, "sentence_index": null, "correct_answer": "为时"}, "level_3": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是动词，表示用了多少时间，此处说会议用了三天。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”用于电影或节目，不能说会议放映三天。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”针对商品，会议不能出售，此句说不通。"}, {"text": "生长", "is_correct": false, "explanation": "语义：会议不会生长，“生长”与会议的概念不相容。"}], "explanations": {"为时": "为时是动词，表示用了多少时间，此处说会议用了三天。", "放映": "搭配：“放映”用于电影或节目，不能说会议放映三天。", "出售": "搭配：“出售”针对商品，会议不能出售，此句说不通。", "生长": "语义：会议不会生长，“生长”与会议的概念不相容。"}, "sentence_index": 0, "correct_answer": "为时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我为时三天学习英语。", "explanation": "这里应该用〈花〉：我花三天学英语。为时只用于会议、工程等事件的持续时间，不能以人作主语。"}, {"text": "小王为时三天完成了任务。", "explanation": "这里应该用〈用时〉：小王用时三天完成了任务。为时只说会议、工程等事件持续的时间，不能以人作主语。"}, {"text": "这个包为时两百元。", "explanation": "这里应该用〈花费〉：这个包花费两百元。为时只用于时间长度，说钱数要用“花费”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是动词，表示用了多少时间，此处说培训用了十天。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于节目或影片，不能说培训播放十天。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于文章或言论，培训不能发表十天，此句说不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，不能用来计量培训的时间，此句意思不通。"}], "explanations": {"为时": "为时是动词，表示用了多少时间，此处说培训用了十天。", "播放": "搭配：“播放”用于节目或影片，不能说培训播放十天。", "发表": "搭配：“发表”用于文章或言论，培训不能发表十天，此句说不通。", "睡": "语义：“睡”指睡觉，不能用来计量培训的时间，此句意思不通。"}, "sentence_index": 6, "correct_answer": "为时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书为时三百页。", "explanation": "这里应该用〈有〉：这本书有三百页。为时后面只接时间长度，不接页数。"}, {"text": "这间教室为时五十个座位。", "explanation": "这里应该用〈有〉：这间教室有五十个座位。为时后面只接时间长度，不接座位数。"}, {"text": "这次会议为时三个代表。", "explanation": "这里应该用〈有〉：这次会议有三个代表。为时后面只接时间长度，不接人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛很为时四天。", "corrected_sentence": "这次比赛为时四天。", "error_description": "错误在于副词“很”的位置。“为时”是动词，不能被“很”修饰，应直接说“这次比赛为时四天”，不能说“这次比赛很为时四天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个项目为时了两年，大家都很辛苦。", "corrected_sentence": "这个项目为时两年，大家都很辛苦。", "error_description": "错误形式：“为时了两年”。正确形式：“为时两年”。“为时”是动词，本身不带“了”，直接接时间即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
