INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经历的时间;多用于固定说法,如「为时已晚」「为时不远」。", "primary_collocate": null, "pronunciation": "wéi shí", "ipa": "weɪ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "现在开始学习，还不算为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他后悔没早点努力，可惜为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛才开始，现在说谁会赢还为时尚早。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你肯努力，哪怕现在才开始，也不算为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛才开始，现在下结论为时过早。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信，我们团聚的日子为时不远。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你发现问题，恐怕为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习新东西永远不会为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想改变自己，什么时候开始都不算为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在才想到复习，是不是为时已晚了？", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為時", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为时:经历的时间,多用于为时已晚、为时不远等固定说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67aa835c-524f-4aad-8e43-c58392166a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时在“为时已晚”中指经历的时间，是正确答案。"}, {"text": "委实", "is_correct": false, "explanation": "委实（wěi shí）与为时（wéi shí）第一音节声调不同，意思是确实，不用于“已晚”的说法。"}, {"text": "卫视", "is_correct": false, "explanation": "卫视（wèi shì）与为时（wéi shí）两个音节声调都不同，指卫星电视频道。"}, {"text": "威势", "is_correct": false, "explanation": "威势（wēi shì）与为时（wéi shí）两个音节声调都不同，意思是威严的气势。"}, {"text": "为使", "is_correct": false, "explanation": "为使（wéi shǐ）与为时（wéi shí）第二音节声调不同，意思是为了让。"}], "explanations": {"为时": "为时在“为时已晚”中指经历的时间，是正确答案。", "委实": "委实（wěi shí）与为时（wéi shí）第一音节声调不同，意思是确实，不用于“已晚”的说法。", "卫视": "卫视（wèi shì）与为时（wéi shí）两个音节声调都不同，指卫星电视频道。", "威势": "威势（wēi shì）与为时（wéi shí）两个音节声调都不同，意思是威严的气势。", "为使": "为使（wéi shǐ）与为时（wéi shí）第二音节声调不同，意思是为了让。"}, "sentence_index": null, "correct_answer": "为时"}, "level_3": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，“年龄已晚”说不通，此处说的是经历的时间。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”不能用“已晚”来形容。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”与“已晚”搭配不当。"}], "explanations": {"为时": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。", "年龄": "语义：“年龄”指岁数，“年龄已晚”说不通，此处说的是经历的时间。", "人数": "搭配：“人数”不能用“已晚”来形容。", "体重": "搭配：“体重”与“已晚”搭配不当。"}, "sentence_index": 0, "correct_answer": "为时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服为时已晚。", "explanation": "这里应该用〈过时〉：这件衣服过时了。「为时已晚」说的是做某事太迟，不能用来形容物品落后。"}, {"text": "比赛下个月才开始，现在报名为时已晚。", "explanation": "这里应该用〈还来得及〉：比赛下个月才开始，现在报名还来得及。「为时已晚」表示太晚，时间充裕时不能用。"}, {"text": "他的成绩为时很好。", "explanation": "这里应该用〈优秀〉：他的成绩很优秀。「为时」只表示经历的时间，不能用来形容成绩的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习的结果，不能说“成绩已晚”。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能用“已晚”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”与“已晚”搭配不通，此处说不通。"}], "explanations": {"为时": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。", "成绩": "语义：“成绩”指学习的结果，不能说“成绩已晚”。", "体温": "搭配：“体温”不能用“已晚”来形容。", "身高": "搭配：“身高”与“已晚”搭配不通，此处说不通。"}, "sentence_index": 6, "correct_answer": "为时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我为时三天看完了这本书。", "explanation": "这里应该用〈花〉：我花了三天看完这本书。「为时」作名词只用于「为时已晚」「为时不远」等固定说法，不能作谓语。"}, {"text": "这条路为时三公里。", "explanation": "这里应该用〈有〉：这条路有三公里长。为时只用于经历的时间，不用来说路的长度。"}, {"text": "离考试还有很久，为时已晚。", "explanation": "这里应该用〈还来得及〉：离考试还有很久，还来得及。“为时已晚”表示太晚，时间充裕时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在下结论，还为时已早。", "corrected_sentence": "现在下结论，还为时尚早。", "error_description": "错误形式：“为时已早”。正确形式：“为时尚早”。“已”表示已经，与“早”矛盾；表示时间还早要用“尚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事情拖到现在，为时尚晚。", "corrected_sentence": "事情拖到现在，为时已晚。", "error_description": "错误形式：“为时尚晚”。正确形式：“为时已晚”。“已晚”表示已经太晚；“尚”表示仍然，不能与“晚”搭配表示太晚。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8331ff59-ca01-46b3-a95a-7fe76d3603d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可喜", "is_correct": true, "explanation": "“可喜”与“可悲”是反义词：一个令人高兴，一个令人难过、值得同情。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物头绪多、不简单，与“可悲”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“可悲”不构成反义。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容不紧张、不费力，与“可悲”的情感义不构成反义。"}], "correct_answer": "可喜", "explanations": {"可喜": "“可喜”与“可悲”是反义词：一个令人高兴，一个令人难过、值得同情。", "复杂": "“复杂”形容事物头绪多、不简单，与“可悲”没有反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“可悲”不构成反义。", "轻松": "“轻松”形容不紧张、不费力，与“可悲”的情感义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可喜", "is_correct": true, "explanation": "“可喜”与“可悲”是反义词：一个令人高兴，一个令人难过、值得同情。"}, {"text": "湿润", "is_correct": false, "explanation": "“湿润”形容含有适量水分，与“可悲”没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”形容不熟悉，与“可悲”的情感义不构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不平滑，与“可悲”没有反义关系。"}], "correct_answer": "可喜", "explanations": {"可喜": "“可喜”与“可悲”是反义词：一个令人高兴，一个令人难过、值得同情。", "湿润": "“湿润”形容含有适量水分，与“可悲”没有反义关系。", "陌生": "“陌生”形容不熟悉，与“可悲”的情感义不构成反义。", "粗糙": "“粗糙”形容表面不平滑，与“可悲”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可悲是让人心里很难过，觉得很可怜。", "primary_collocate": null, "pronunciation": "kě bēi", "ipa": "kʰɤ˨˩ pei˥", "syllable_count": 2, "sentences": [{"text": "他一个人老去，没有朋友，真可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一件可悲的事。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了钱，他和家人断了联系，太可悲了。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不会为别人高兴的人是可悲的。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老人独自过年，我觉得很可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的命运很可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子没书读，这个现实很可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到老都没有说出真话，多么可悲！", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人只会骗人，实在可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让许多人无家可归，非常可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "让人觉得难过又可怜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可悲", "is_correct": true, "explanation": "“可悲”表示令人难过、值得同情，正符合一个人孤独老去、没有朋友的处境。"}, {"text": "可喜", "is_correct": false, "explanation": "语义：“可喜”表示值得高兴，与“没有朋友”的孤独处境相反。"}, {"text": "可观", "is_correct": false, "explanation": "搭配：“可观”多用于数量、收入，不能用来评价一个人的处境。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容讨人喜欢，用来说孤独的老人不合适。"}], "explanations": {"可悲": "“可悲”表示令人难过、值得同情，正符合一个人孤独老去、没有朋友的处境。", "可喜": "语义：“可喜”表示值得高兴，与“没有朋友”的孤独处境相反。", "可观": "搭配：“可观”多用于数量、收入，不能用来评价一个人的处境。", "可爱": "语义：“可爱”形容讨人喜欢，用来说孤独的老人不合适。"}, "sentence_index": 0, "correct_answer": "可悲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于通过了考试，真可悲。", "explanation": "这里表示高兴，应用〈可喜〉。“可悲”表示令人难过、值得同情，不能用于值得高兴的事。"}, {"text": "这个方案很可悲，我觉得完全行得通。", "explanation": "这里是说方案能够实行，应用〈可行〉。“可悲”表示令人同情，不能用来形容切实可行的方案。"}, {"text": "他做事很可悲，我们都放心地把工作交给他。", "explanation": "这里是说值得信赖，应用〈可靠〉。“可悲”表示令人同情，不能用来形容值得放心托付的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可悲", "is_correct": true, "explanation": "“可悲”说明这个现实令人难过、令人同情，与“孩子没书读”相符。"}, {"text": "可口", "is_correct": false, "explanation": "搭配：“可口”形容食物好吃，不能用来形容现实。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”是赞美之词，孩子没书读的现实不能用它来形容。"}, {"text": "可靠", "is_correct": false, "explanation": "语义：“可靠”形容值得信赖，不能用来形容这种现实。"}], "explanations": {"可悲": "“可悲”说明这个现实令人难过、令人同情，与“孩子没书读”相符。", "可口": "搭配：“可口”形容食物好吃，不能用来形容现实。", "美丽": "语义：“美丽”是赞美之词，孩子没书读的现实不能用它来形容。", "可靠": "语义：“可靠”形容值得信赖，不能用来形容这种现实。"}, "sentence_index": 6, "correct_answer": "可悲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔奖金真可悲，足够买一辆车。", "explanation": "这里是说数量很多，应用〈可观〉。“可悲”令人同情，不能用来形容数额很大的奖金。"}, {"text": "这碗面真可悲，我一口气吃了两大碗。", "explanation": "这里是说好吃，应用〈可口〉。“可悲”令人同情，与“一口气吃了两大碗”的满足感矛盾。"}, {"text": "我们一起过节，大家都觉得很可悲。", "explanation": "这里是开心，应用〈快乐〉。“可悲”表示令人难过，不能形容大家一起过节的开心场面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "眼看老房子被拆掉，这是很可悲事。", "corrected_sentence": "眼看老房子被拆掉，这是很可悲的事。", "error_description": "“很可悲”修饰名词“事”时中间要加“的”，应说“很可悲的事”，不能说“很可悲事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这一生过很可悲。", "corrected_sentence": "他这一生过得很可悲。", "error_description": "“过得很可悲”中的“得”连接动词与补语，不能省略。应说“他这一生过得很可悲”，不能说“他这一生过很可悲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
