INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88426, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "令人悲伤、感到惋惜的。", "primary_collocate": null, "pronunciation": "kě bēi", "ipa": "kʰɤ˨˩ pei˥", "syllable_count": 2, "sentences": [{"text": "这么好的人才被浪费了，真可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才华没人发现，实在可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座老房子被拆了，真是可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次小小的错误毁了他的一生，太可悲了。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可悲的是，他到最后也没明白。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的结局真可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小鸟死在了笼子里，场面很可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老作家的书没人读，很可悲。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友因为小事吵架，最后不再说话，太可悲了。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他可悲的一生就这样结束了。", "target_word": "可悲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "令人悲伤并为之惋惜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可悲", "is_correct": true, "explanation": "“可悲”表示令人悲伤、值得惋惜，与人才被浪费的情形相符。"}, {"text": "可靠", "is_correct": false, "explanation": "语义：“可靠”形容值得信赖，与人才被浪费的遗憾不符。"}, {"text": "可观", "is_correct": false, "explanation": "搭配：“可观”多用于数量、收益，不用于评价人才的遭遇。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容讨人喜欢，用来说被浪费的人才不合适。"}], "explanations": {"可悲": "“可悲”表示令人悲伤、值得惋惜，与人才被浪费的情形相符。", "可靠": "语义：“可靠”形容值得信赖，与人才被浪费的遗憾不符。", "可观": "搭配：“可观”多用于数量、收益，不用于评价人才的遭遇。", "可爱": "语义：“可爱”形容讨人喜欢，用来说被浪费的人才不合适。"}, "sentence_index": 0, "correct_answer": "可悲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她终于拿到了奖学金，真可悲。", "explanation": "这里表示高兴，应用〈可喜〉。“可悲”表示令人难过，不能用于值得高兴的事。"}, {"text": "这只大狗冲过来，真可悲，我吓得拔腿就跑。", "explanation": "这里是说让人害怕，应用〈可怕〉。“可悲”表示令人同情，不能用来形容让人害怕的场面。"}, {"text": "这套办法真可悲，我们试过了，效果很好。", "explanation": "这里是说办法切实可行，应用〈可行〉。“可悲”令人同情，不能用来形容行之有效的办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可悲", "is_correct": true, "explanation": "“可悲”表示令人悲伤、值得惋惜，描述小鸟死去的场面正相符。"}, {"text": "可口", "is_correct": false, "explanation": "搭配：“可口”形容食物好吃，不能用来形容场面。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容好看，用于小鸟死去的场面不合适。"}, {"text": "可靠", "is_correct": false, "explanation": "语义：“可靠”形容值得信赖，不能用来形容这个场面。"}], "explanations": {"可悲": "“可悲”表示令人悲伤、值得惋惜，描述小鸟死去的场面正相符。", "可口": "搭配：“可口”形容食物好吃，不能用来形容场面。", "美丽": "语义：“美丽”形容好看，用于小鸟死去的场面不合适。", "可靠": "语义：“可靠”形容值得信赖，不能用来形容这个场面。"}, "sentence_index": 6, "correct_answer": "可悲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位司机每次都准时，真可悲。", "explanation": "这里是赞扬守时，应用〈可靠〉。“可悲”表示令人同情，不用来称赞人的可信赖。"}, {"text": "他一次捐出的钱真可悲，足够盖一所学校。", "explanation": "这里是说数量很大，应用〈可观〉。“可悲”令人同情，不能用来形容数额很大的捐款。"}, {"text": "我们一起去公园，大家玩得非常可悲。", "explanation": "这里是开心，应用〈快乐〉。“可悲”表示令人难过，不能形容大家玩得开心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把画都烧了，这种做法真很可悲。", "corrected_sentence": "他把画都烧了，这种做法真可悲。", "error_description": "“真”和“很”都是程度副词，不能同时修饰“可悲”，应只用其中一个，说“真可悲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他那副样子被真可悲。", "corrected_sentence": "他那副样子真可悲。", "error_description": "“可悲”是形容词，不能用“被”字句。应说“他那副样子真可悲”，不能在“真”前加“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
