INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真书是一种方方正正的写字样子。", "primary_collocate": null, "pronunciation": "zhēn shū", "ipa": "ʈʂən˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "老师说真书的字方方正正，很好认。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子刚学写字，先从真书写起。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真书的每一笔都写得清清楚楚。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的真书写得又正又好看。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上的真书是爷爷写的。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写真书的时候，手要稳，心要静。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢真书，不喜欢写得很快的草书。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的牌子上，写着方方正正的真书。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要写好真书，一笔一画都不能马虎。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在练习真书，教室里很安静。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真書", "label": "繁体"}], "register": "书面", "sense_fingerprint": "方方正正的写字样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草书", "is_correct": false, "explanation": "语义：草书笔画连贯、潦草简省，与“方方正正”相矛盾。"}, {"text": "真书", "is_correct": true, "explanation": "真书指方方正正、容易辨认的写字样子，与“方方正正，很好认”相符。"}, {"text": "行书", "is_correct": false, "explanation": "语义：行书字形流动、笔画连绵，不能用“方方正正”来形容。"}, {"text": "大篆", "is_correct": false, "explanation": "语义：大篆是古老的篆书，字形圆转繁复、不易辨认，与“方方正正，很好认”不合。"}], "explanations": {"草书": "语义：草书笔画连贯、潦草简省，与“方方正正”相矛盾。", "真书": "真书指方方正正、容易辨认的写字样子，与“方方正正，很好认”相符。", "行书": "语义：行书字形流动、笔画连绵，不能用“方方正正”来形容。", "大篆": "语义：大篆是古老的篆书，字形圆转繁复、不易辨认，与“方方正正，很好认”不合。"}, "sentence_index": 0, "correct_answer": "真书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的真书写得行云流水。", "explanation": "这里应该用〈行书〉。真书字形方正，不能用“行云流水”来形容。"}, {"text": "他的真书写得龙飞凤舞。", "explanation": "这里应该用〈草书〉。真书方方正正、端正工整，不能用“龙飞凤舞”来形容。"}, {"text": "他的真书写得蚕头燕尾。", "explanation": "这里应该用〈隶书〉。隶书有“蚕头燕尾”的笔法，真书笔画方正规整，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾", "is_correct": false, "explanation": "语义：“我喜欢垃圾”语义不通，与句中“喜欢”和“不喜欢”的对比不合。"}, {"text": "真书", "is_correct": true, "explanation": "真书是方正的字体，与句中“不喜欢写得很快的草书”形成对比，语义相符。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是有害之物，不能作为“喜欢”的对象与草书形成对比。"}, {"text": "乱码", "is_correct": false, "explanation": "语义：乱码是显示错误的字符，不是一种字体，不能和“草书”形成喜欢与不喜欢的对比。"}], "explanations": {"垃圾": "语义：“我喜欢垃圾”语义不通，与句中“喜欢”和“不喜欢”的对比不合。", "真书": "真书是方正的字体，与句中“不喜欢写得很快的草书”形成对比，语义相符。", "病毒": "语义：病毒是有害之物，不能作为“喜欢”的对象与草书形成对比。", "乱码": "语义：乱码是显示错误的字符，不是一种字体，不能和“草书”形成喜欢与不喜欢的对比。"}, "sentence_index": 6, "correct_answer": "真书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的真书写得又圆又匀。", "explanation": "这里应该用〈篆书〉。真书字形方正，不能用“圆”和“匀”来形容。"}, {"text": "孩子们在纸上写真书，写得龙飞凤舞。", "explanation": "这里应该用〈狂草〉。真书方正端正，不能用“龙飞凤舞”来形容；龙飞凤舞的笔势属于狂草。"}, {"text": "他的真书写得笔画相连，一气呵成。", "explanation": "这里应该用〈行书〉。真书一笔一画分开写，笔画相连、一气呵成的是行书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上挂着一幅方方正正地真书。", "corrected_sentence": "墙上挂着一幅方方正正的真书。", "error_description": "修饰名词要用“的”，不能用“地”；“地”只用于修饰动词。错误形式是“方方正正地真书”，正确形式是“方方正正的真书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一只真书，写得很端正。", "corrected_sentence": "他写了一幅真书，写得很端正。", "error_description": "量词错误。“真书”是书写的字体，书法作品用“幅”计量，“只”用于动物，应说“一幅真书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
