INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "汉字书体之一，即楷书。", "primary_collocate": null, "pronunciation": "zhēn shū", "ipa": "ʈʂən˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "汉字有很多书体，真书是其中一种。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "真书是汉字书体里最容易认的一种。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一张古人写的真书作品。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本字帖里都是真书，没有别的字体。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这幅真书挂在了书房里。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起行书，真书更适合学生练习。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用真书抄过很多书。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块牌子上的字是真书，不是草书。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们说出真书和行书的不同。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就用毛笔练真书。", "target_word": "真书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "真書", "label": "繁体"}], "register": "书面", "sense_fingerprint": "汉字书体之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汉字", "is_correct": false, "explanation": "搭配：“汉字”不属于书体的类别，不能用在“……是其中一种”这一句式中。"}, {"text": "真书", "is_correct": true, "explanation": "真书是汉字书体之一，符合“汉字有很多书体，……是其中一种”的语境。"}, {"text": "拼音", "is_correct": false, "explanation": "语义：拼音是注音方法，不是汉字的书体。"}, {"text": "标点", "is_correct": false, "explanation": "语义：标点是书面符号，不是书体，与句意不符。"}], "explanations": {"汉字": "搭配：“汉字”不属于书体的类别，不能用在“……是其中一种”这一句式中。", "真书": "真书是汉字书体之一，符合“汉字有很多书体，……是其中一种”的语境。", "拼音": "语义：拼音是注音方法，不是汉字的书体。", "标点": "语义：标点是书面符号，不是书体，与句意不符。"}, "sentence_index": 0, "correct_answer": "真书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写的真书又快又连笔。", "explanation": "这里应该用〈行书〉。真书笔画分明、写法工整，不能用“快”和“连笔”来形容。"}, {"text": "他写的真书龙飞凤舞。", "explanation": "这里应该用〈草书〉。真书方正端正，不能用“龙飞凤舞”来形容。"}, {"text": "他写的真书字形扁扁的，有蚕头燕尾。", "explanation": "这里应该用〈隶书〉。字形扁、有蚕头燕尾的是隶书，真书字形方正。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑是现代的器物，古人不可能用它来抄书，与句意矛盾。"}, {"text": "真书", "is_correct": true, "explanation": "真书是书体之一，古人用真书抄书，句意通顺。"}, {"text": "雕版", "is_correct": false, "explanation": "搭配：“抄”不能与“雕版”搭配，雕版是刻板印刷的工具，不用于抄写。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代的器物，古人不可能用它来抄书。"}], "explanations": {"电脑": "语义：电脑是现代的器物，古人不可能用它来抄书，与句意矛盾。", "真书": "真书是书体之一，古人用真书抄书，句意通顺。", "雕版": "搭配：“抄”不能与“雕版”搭配，雕版是刻板印刷的工具，不用于抄写。", "手机": "语义：手机是现代的器物，古人不可能用它来抄书。"}, "sentence_index": 6, "correct_answer": "真书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小就用毛笔练真书，笔势狂放不羁。", "explanation": "这里应该用〈狂草〉。真书方正端正，不能用“狂放不羁”来形容；狂放的笔势属于狂草。"}, {"text": "他写的真书蚕头燕尾。", "explanation": "这里应该用〈隶书〉。隶书有“蚕头燕尾”的笔法，真书笔画方正规整，不能这样形容。"}, {"text": "他写的真书圆圆润润的。", "explanation": "这里应该用〈篆书〉。篆书笔画匀称圆润，真书不能用“圆圆润润”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候练过过真书。", "corrected_sentence": "我小时候练过真书。", "error_description": "多了一个“过”：动词“练”后的体标“过”只用一次，应说“练过真书”，不能重复为“练过过真书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把真书写了很端正。", "corrected_sentence": "他把真书写得很端正。", "error_description": "动词带补语要用“得”引出，不能用“了”。错误形式是“写了很端正”，正确形式是“写得很端正”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
