INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奖是做得好的人拿到的礼物。", "primary_collocate": null, "pronunciation": "jiǎng", "ipa": "tɕjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "小明考了第一名，妈妈给了他一个奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，这个奖是给你的，因为你很努力。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个做完作业的孩子一个小奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟跑得最快，所以拿到了奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想拿一个奖，所以今天一定认真做。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌唱得好，得到了一个奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖是一本很漂亮的书。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天画画比赛，每个人都有奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把奖放在桌子上，笑着看了很久。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做对十个题，就能得到一个奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "獎", "label": "繁体"}, {"form": "奖品", "label": "复合"}], "register": "中性", "sense_fingerprint": "做得好的人拿到的礼物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奖", "is_correct": true, "explanation": "正确答案：奖（jiǎng，第三声），指做得好的人拿到的礼物。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是江。"}, {"text": "降", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是下降。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是减少。"}], "explanations": {"奖": "正确答案：奖（jiǎng，第三声），指做得好的人拿到的礼物。", "江": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是江。", "降": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是下降。", "抢": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺。", "减": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是减少。"}, "sentence_index": null, "correct_answer": "奖"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是奖励，与“考了第一名”的奖励语境冲突。"}, {"text": "奖", "is_correct": true, "explanation": "正确：奖是为成绩好的人给予的礼物，与“考了第一名”“给”相配。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“给”的宾语应是礼物，“感冒”是疾病，不能说“给了一个感冒”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是可以送给学生的奖励。"}], "explanations": {"作业": "语义：作业是学习任务，不是奖励，与“考了第一名”的奖励语境冲突。", "奖": "正确：奖是为成绩好的人给予的礼物，与“考了第一名”“给”相配。", "感冒": "搭配：“给”的宾语应是礼物，“感冒”是疾病，不能说“给了一个感冒”。", "老师": "语义：老师是人，不是可以送给学生的奖励。"}, "sentence_index": 0, "correct_answer": "奖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟跑得最快，所以拿到了一只奖。", "explanation": "这里应该用〈个〉。“只”多用于小动物等个体，奖用“个”计量。"}, {"text": "他在商店买了一个奖。", "explanation": "这里应该用〈礼物〉。奖是因成绩得到的，不能在商店买，买的对象应是礼物。"}, {"text": "他每天吃完奖后就去玩。", "explanation": "这里应该用〈饭〉。“吃”只能搭配食物，奖是礼物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88429, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奖", "is_correct": true, "explanation": "正确答案：奖（jiǎng，第三声），指做得好的人拿到的礼物。"}, {"text": "将", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是将要。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是酱，如酱油。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是用剪刀剪。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想。"}], "explanations": {"奖": "正确答案：奖（jiǎng，第三声），指做得好的人拿到的礼物。", "将": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是将要。", "酱": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是酱，如酱油。", "剪": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是用剪刀剪。", "想": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想。"}, "sentence_index": null, "correct_answer": "奖"}, "level_3": {"options": [{"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不能是一本漂亮的书，句意荒谬。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能是一本漂亮的书，句意矛盾。"}, {"text": "奖", "is_correct": true, "explanation": "正确：“奖”即这个礼物，与“是一本很漂亮的书”指同一对象。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话不是书，与“一本很漂亮的书”不指同一事物。"}], "explanations": {"老鼠": "语义：老鼠不能是一本漂亮的书，句意荒谬。", "蛋糕": "语义：蛋糕是食物，不能是一本漂亮的书，句意矛盾。", "奖": "正确：“奖”即这个礼物，与“是一本很漂亮的书”指同一对象。", "电话": "语义：电话不是书，与“一本很漂亮的书”不指同一事物。"}, "sentence_index": 6, "correct_answer": "奖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "做对十个题，就能喝掉一个奖。", "explanation": "这里“喝”只能搭配饮料，奖是礼物或物品，不能喝。"}, {"text": "做对十个题，就能骑一个奖。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、马等，奖是礼物，不能骑。"}, {"text": "做对十个题，就能把一个奖讲给老师听。", "explanation": "这里应该用〈故事〉。“讲”用于故事、道理，奖是实物，不能讲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给表现好的学生准备了一只奖。", "corrected_sentence": "老师给表现好的学生准备了一个奖。", "error_description": "量词错误：“只”用于小动物等个体，奖应用量词“个”，应改为“一个奖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把奖们放在书架上。", "corrected_sentence": "他把奖放在书架上。", "error_description": "错误：“奖们”。“们”主要用于指人的名词，“奖”是物品，不能加“们”，应改为“他把奖放在书架上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
