INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为鼓励或表扬而给予的荣誉或财物。", "primary_collocate": null, "pronunciation": "jiǎng", "ipa": "tɕjɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他在比赛中拿到了一个奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖是给最好的老师的。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的小说得过很多奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给跑得最快的人发了一个奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的奖由校长亲自发给大家。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想拿这个奖，今天终于成功了。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影在国际上拿过三个奖。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖不但有证书，还有一万元钱。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把奖送给了帮助过他的老师。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿到奖后，高兴得说不出话来。", "target_word": "奖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "獎", "label": "繁体"}, {"form": "奖金", "label": "复合"}], "register": "中性", "sense_fingerprint": "为鼓励或表扬而给予的荣誉或财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奖", "is_correct": true, "explanation": "正确答案：奖（jiǎng，第三声），指为鼓励或表扬而给予的荣誉或财物。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是江。"}, {"text": "降", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是下降。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是减少。"}], "explanations": {"奖": "正确答案：奖（jiǎng，第三声），指为鼓励或表扬而给予的荣誉或财物。", "江": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是江。", "降": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是下降。", "抢": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺。", "减": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是减少。"}, "sentence_index": null, "correct_answer": "奖"}, "level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：比赛中拿到的是奖项，雨伞与比赛无关，句意不通。"}, {"text": "奖", "is_correct": true, "explanation": "正确：奖指比赛中获得的奖项，与“在比赛中拿到”搭配，可用量词“个”。"}, {"text": "考试", "is_correct": false, "explanation": "配价：“拿到”的宾语应是可以拿的东西，“考试”是活动，不能被拿到。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是比赛中可以拿到的物件。"}], "explanations": {"雨伞": "语义：比赛中拿到的是奖项，雨伞与比赛无关，句意不通。", "奖": "正确：奖指比赛中获得的奖项，与“在比赛中拿到”搭配，可用量词“个”。", "考试": "配价：“拿到”的宾语应是可以拿的东西，“考试”是活动，不能被拿到。", "老师": "语义：老师是人，不是比赛中可以拿到的物件。"}, "sentence_index": 0, "correct_answer": "奖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次迟到，被老师奖了一顿。", "explanation": "这里“奖”被当成了惩罚，应换成〈批评〉。奖表示表扬或奖励，不能用于迟到后的训斥。"}, {"text": "公司给跑得最快的人发了一只奖。", "explanation": "这里应该用〈个〉或〈项〉。“只”多用于小动物或成对器官中的一个，奖应用“个”或“项”计量。"}, {"text": "公司给跑得最快的人涨了一次奖。", "explanation": "这里应该用〈工资〉。“涨”用于工资、价格，奖不能说“涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奖", "is_correct": true, "explanation": "正确答案：奖（jiǎng，第三声），指为鼓励或表扬而给予的荣誉或财物。"}, {"text": "将", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是将要。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是酱，如酱油。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是用剪刀剪。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想。"}], "explanations": {"奖": "正确答案：奖（jiǎng，第三声），指为鼓励或表扬而给予的荣誉或财物。", "将": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是将要。", "酱": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是酱，如酱油。", "剪": "jiǎn 与 jiǎng 韵母不同（-n 与 -ng），意思是用剪刀剪。", "想": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是想。"}, "sentence_index": null, "correct_answer": "奖"}, "level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能被“国际上拿过”作为奖项。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是能在国际上“拿过”的荣誉，句意矛盾。"}, {"text": "奖", "is_correct": true, "explanation": "正确：奖指获得的荣誉，“在国际上拿过”与之搭配，量词“个”可用。"}, {"text": "馒头", "is_correct": false, "explanation": "语义：馒头是食物，不能在国际上作为奖项被拿过。"}], "explanations": {"老虎": "语义：老虎是动物，不能被“国际上拿过”作为奖项。", "手机": "语义：手机不是能在国际上“拿过”的荣誉，句意矛盾。", "奖": "正确：奖指获得的荣誉，“在国际上拿过”与之搭配，量词“个”可用。", "馒头": "语义：馒头是食物，不能在国际上作为奖项被拿过。"}, "sentence_index": 6, "correct_answer": "奖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他取得了好奖后，高兴得说不出话来。", "explanation": "这里应该用〈成绩〉。“取得”和“好”搭配成绩，奖一般说“大奖”或“获奖”，不说“好奖”。"}, {"text": "他穿上了一个奖，高兴得说不出话来。", "explanation": "这里“奖”被当成了衣物，应换成〈衣服〉。“穿”用于衣物，奖是荣誉或财物，不能穿。"}, {"text": "他拿到了一个奖，把它吃了下去，高兴得说不出话来。", "explanation": "这里“奖”被当成了食物。“吃”只能搭配食物，奖是荣誉或财物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她为这项研究拿到了一只重要的奖。", "corrected_sentence": "她为这项研究拿到了一个重要的奖。", "error_description": "量词错误：“只”用于小动物等个体，奖应用量词“个”或“项”，应改为“一个重要的奖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是老师颁给学生奖。", "corrected_sentence": "这是老师颁给学生的奖。", "error_description": "结构助词错误：“颁给学生”修饰名词“奖”时需要加“的”，应为“颁给学生的奖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
