INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88431, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "严密是很紧很仔细，没有一点漏洞。", "primary_collocate": null, "pronunciation": "yán mì", "ipa": "jɛn˧˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "他的计划很严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对这座楼进行了严密的检查。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同写得非常严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论证很严密，没有一点错误。", "target_word": "严密", "complexity_tier": "T3", "furigana": "tā de lùnzhèng hěn yánmì, méiyǒu yì diǎn cuòwù.", "sentence_source": "generated"}, {"text": "公司有严密的管理制度。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子需要严密的调查。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的推理十分严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院对病人进行严密的观察。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的方案很严密，大家都同意。", "target_word": "严密", "complexity_tier": "T3", "furigana": "lǎoshī de fāng''àn hěn yánmì, dàjiā dōu tóngyì.", "sentence_source": "generated"}, {"text": "这家银行的安全措施非常严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嚴密", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周密仔细、没有漏洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严密", "is_correct": true, "explanation": "正确：严密形容计划周全、没有漏洞，与“他的计划很”相合。"}, {"text": "热情", "is_correct": false, "explanation": "语义：热情形容人的态度，不能用来形容计划。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆多形容声音或食物，不搭配“计划”。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：冷清形容场所或气氛冷落，不能描述计划的周全程度。"}], "explanations": {"严密": "正确：严密形容计划周全、没有漏洞，与“他的计划很”相合。", "热情": "语义：热情形容人的态度，不能用来形容计划。", "清脆": "搭配：清脆多形容声音或食物，不搭配“计划”。", "冷清": "语义：冷清形容场所或气氛冷落，不能描述计划的周全程度。"}, "sentence_index": 0, "correct_answer": "严密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情很严密，一直在笑。", "explanation": "这里应该用〈愉快〉。严密形容计划、论证等周全无漏，不用来形容心情；心情好要说愉快。"}, {"text": "这家饭店的菜很严密。", "explanation": "这里应该用〈好吃〉。严密形容计划、制度、论证等周全无漏，不用来形容菜的味道。"}, {"text": "他的歌唱得很严密。", "explanation": "这里应该用〈好听〉。严密指周全无漏，不用来形容歌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严密", "is_correct": true, "explanation": "正确：严密形容推理周全、无漏洞，与“他的推理十分”相合。"}, {"text": "炽热", "is_correct": false, "explanation": "语义：炽热形容温度或情感强烈，不能形容推理的周密。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：嘹亮形容声音响亮，不能用来形容推理。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：潮湿形容环境或物体含水多，不能用于推理。"}], "explanations": {"严密": "正确：严密形容推理周全、无漏洞，与“他的推理十分”相合。", "炽热": "语义：炽热形容温度或情感强烈，不能形容推理的周密。", "嘹亮": "搭配：嘹亮形容声音响亮，不能用来形容推理。", "潮湿": "语义：潮湿形容环境或物体含水多，不能用于推理。"}, "sentence_index": 6, "correct_answer": "严密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街上非常严密，人来人往。", "explanation": "这里应该用〈热闹〉。严密用于计划、制度、论证，不用于形容街道的热闹。"}, {"text": "他对朋友很严密，经常请客。", "explanation": "这里应该用〈大方〉。严密形容做事周全，不用来形容待人慷慨。"}, {"text": "他的笑容很严密。", "explanation": "这里应该用〈灿烂〉。严密指周全无漏，不用来形容笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的计划没严密，很多地方都有漏洞。", "corrected_sentence": "他的计划不严密，很多地方都有漏洞。", "error_description": "错误：“没严密”，正确：“不严密”。形容词作谓语表示否定时用“不”，“没”不能直接修饰形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他严密得检查了每一个细节。", "corrected_sentence": "他严密地检查了每一个细节。", "error_description": "错误：“严密得检查”，正确：“严密地检查”。“严密”修饰动词作状语时应用“地”，不用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
