INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88432, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "结合得紧密，没有空隙或疏漏。", "primary_collocate": null, "pronunciation": "yán mì", "ipa": "jɛn˧˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "这两块木板拼得很严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把窗户关得很严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子盖得严密，水进不去。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套的接缝缝得很严密，风吹不进来。", "target_word": "严密", "complexity_tier": "T3", "furigana": "zhè jiàn wàitào de jiēfèng féng de hěn yánmì, fēng chuī bu jìnlái.", "sentence_source": "generated"}, {"text": "这堵墙砌得很严密，连风也吹不进。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子被他封得很严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶盖拧得不够严密，水漏出来了。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门窗装得很严密，屋里很暖和。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把管子接得很严密。", "target_word": "严密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些零件装得非常严密，一点缝都没有。", "target_word": "严密", "complexity_tier": "T3", "furigana": "zhè xiē língjiàn zhuāng de fēicháng yánmì, yì diǎn fèng dōu méiyǒu.", "sentence_source": "generated"}], "morphological_forms": [{"form": "嚴密", "label": "繁体"}], "register": "中性", "sense_fingerprint": "结合紧密、没有空隙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严密", "is_correct": true, "explanation": "正确：严密形容结合紧密、没有空隙，与“这两块木板拼得很”相合。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：慷慨形容人的心性或态度，不能形容木板的拼接。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：伤心形容人的情绪，不能用于描述木板拼接的状态。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：甜美多形容声音、笑容，不搭配“拼得”的木板。"}], "explanations": {"严密": "正确：严密形容结合紧密、没有空隙，与“这两块木板拼得很”相合。", "慷慨": "语义：慷慨形容人的心性或态度，不能形容木板的拼接。", "伤心": "语义：伤心形容人的情绪，不能用于描述木板拼接的状态。", "甜美": "搭配：甜美多形容声音、笑容，不搭配“拼得”的木板。"}, "sentence_index": 0, "correct_answer": "严密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的颜色很严密。", "explanation": "这里应该用〈鲜亮〉。严密指结合紧密、没有空隙，不用来形容颜色的鲜亮程度。"}, {"text": "这张桌子的价格很严密。", "explanation": "这里应该用〈便宜〉。严密指结合紧密、没有空隙，不用来形容价格的高低。"}, {"text": "这盘菜的咸淡很严密。", "explanation": "这里应该用〈合适〉。严密指结合紧密、没有空隙，不用来形容菜的咸淡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严密", "is_correct": true, "explanation": "正确：严密形容结合紧密，与“瓶盖拧得不够”相合，且与“水漏出来了”的结果对应。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：亲切形容人的态度，不能形容瓶盖的拧紧程度。"}, {"text": "圆润", "is_correct": false, "explanation": "搭配：圆润多形容声音或线条，不搭配“拧得不够”的瓶盖。"}, {"text": "疲惫", "is_correct": false, "explanation": "语义：疲惫形容人的身体状态，不能用于瓶盖。"}], "explanations": {"严密": "正确：严密形容结合紧密，与“瓶盖拧得不够”相合，且与“水漏出来了”的结果对应。", "亲切": "语义：亲切形容人的态度，不能形容瓶盖的拧紧程度。", "圆润": "搭配：圆润多形容声音或线条，不搭配“拧得不够”的瓶盖。", "疲惫": "语义：疲惫形容人的身体状态，不能用于瓶盖。"}, "sentence_index": 6, "correct_answer": "严密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的香味很严密。", "explanation": "这里应该用〈浓郁〉。严密指结合紧密、没有空隙，不用来形容香味的浓淡。"}, {"text": "他跑得很严密。", "explanation": "这里应该用〈快〉。严密指结合紧密、没有空隙，不用来形容跑步的快慢。"}, {"text": "这个西瓜很严密。", "explanation": "这里应该用〈甜〉。严密不用于形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盖子盖得没严密，香味跑不出来。", "corrected_sentence": "这个盖子盖得很严密，香味跑不出来。", "error_description": "错误：“没严密”，正确：“很严密”。“没”不能直接修饰形容词；这里根据后文“香味跑不出来”，应为肯定的“盖得很严密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他严密得封好了箱子。", "corrected_sentence": "他严密地封好了箱子。", "error_description": "错误：“严密得封好”，正确：“严密地封好”。“严密”修饰动词作状语时应用“地”，不用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
