INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88433, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神父是教堂里主持仪式的人。", "primary_collocate": null, "pronunciation": "shén fu", "ipa": "ʂən˧˥ fu", "syllable_count": 2, "sentences": [{"text": "神父在教堂里工作。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位神父。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天，神父带大家唱歌。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父笑着对孩子说你好。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂门口站着一位神父。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父每天早上都打扫教堂。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请神父来主持婚礼。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父的家就在教堂后面。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个神父很和气，大家都喜欢他。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们问神父，教堂几点开门。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老神父", "label": "复合"}], "register": "中性", "sense_fingerprint": "教堂里主持仪式的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神父", "is_correct": true, "explanation": "神父 shén fu：天主教、东正教中主持仪式的人，是正确答案。"}, {"text": "生父", "is_correct": false, "explanation": "生父（shēng fù）与 shén fu 的韵母和声调都不同，意思是亲生父亲。"}, {"text": "圣父", "is_correct": false, "explanation": "圣父（shèng fù）与 shén fu 的韵母和声调都不同，指天主教中三位一体的第一位。"}, {"text": "神符", "is_correct": false, "explanation": "神符（shén fú）第二个音节声调不同（fú 与 fu），意思是画有神秘文字或图形的符。"}], "explanations": {"神父": "神父 shén fu：天主教、东正教中主持仪式的人，是正确答案。", "生父": "生父（shēng fù）与 shén fu 的韵母和声调都不同，意思是亲生父亲。", "圣父": "圣父（shèng fù）与 shén fu 的韵母和声调都不同，指天主教中三位一体的第一位。", "神符": "神符（shén fú）第二个音节声调不同（fú 与 fu），意思是画有神秘文字或图形的符。"}, "sentence_index": null, "correct_answer": "神父"}, "level_3": {"options": [{"text": "神父", "is_correct": true, "explanation": "正确：神父是在教堂里主持仪式、从事教会工作的人，符合语境。"}, {"text": "船长", "is_correct": false, "explanation": "语义：船长负责船只航行，不在教堂里工作，与语境冲突。"}, {"text": "矿工", "is_correct": false, "explanation": "语义：矿工在矿井里工作，不会在教堂里工作。"}, {"text": "大钟", "is_correct": false, "explanation": "配价：“工作”的施事应是人，大钟不能在教堂里工作。"}], "explanations": {"神父": "正确：神父是在教堂里主持仪式、从事教会工作的人，符合语境。", "船长": "语义：船长负责船只航行，不在教堂里工作，与语境冲突。", "矿工": "语义：矿工在矿井里工作，不会在教堂里工作。", "大钟": "配价：“工作”的施事应是人，大钟不能在教堂里工作。"}, "sentence_index": 0, "correct_answer": "神父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位穿长裙的女神父每天在教堂里照顾病人。", "explanation": "这里应该用〈修女〉。神父指男性神职人员；在教会服务的女性称修女。"}, {"text": "清真寺里有一位老神父，每天带领大家做礼拜。", "explanation": "这里应该用〈阿訇〉。神父是天主教、东正教的神职人员；清真寺的伊斯兰教教职人员称阿訇。"}, {"text": "传说中的神父会腾云驾雾。", "explanation": "这里应该用〈神仙〉。神父指人间的神职人员，不指传说中腾云驾雾的神仙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神父", "is_correct": true, "explanation": "正确：神父是主持仪式的神职人员，可以主持婚礼。"}, {"text": "猪", "is_correct": false, "explanation": "语义：猪是动物，不能主持婚礼。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是昆虫，不能主持婚礼。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“主持婚礼”的施事应是人，椅子不能主持婚礼。"}], "explanations": {"神父": "正确：神父是主持仪式的神职人员，可以主持婚礼。", "猪": "语义：猪是动物，不能主持婚礼。", "蚊子": "语义：蚊子是昆虫，不能主持婚礼。", "椅子": "配价：“主持婚礼”的施事应是人，椅子不能主持婚礼。"}, "sentence_index": 6, "correct_answer": "神父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寺庙后院的老神父每天在树下打坐。", "explanation": "这里应该用〈和尚〉。神父是基督教系统的神职人员；寺庙里的佛教僧人称和尚。"}, {"text": "她是一位神父，常在孤儿院照顾孩子。", "explanation": "这里应该用〈修女〉。神父指男性神职人员，女性的宗教人员称修女。"}, {"text": "道观的神父每天在门口念经。", "explanation": "这里应该用〈道士〉。神父属于基督教系统；道观里的道教人员称道士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥神父。", "corrected_sentence": "我哥哥是神父。", "error_description": "错误形式：“我哥哥神父”。作谓语的名词前要用动词“是”，正确形式为“我哥哥是神父”，缺少“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们镇上来了一位神父们。", "corrected_sentence": "我们镇上来了一位神父。", "error_description": "错误形式：“一位神父们”。“们”表示复数，不能与数量词“一位”同时使用。正确形式：“一位神父”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
