INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天主教、东正教中主持宗教仪式的神职人员。", "primary_collocate": null, "pronunciation": "shén fu", "ipa": "ʂən˧˥ fu", "syllable_count": 2, "sentences": [{"text": "神父在教堂里主持仪式。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位神父每个星期天都讲话。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老神父给孩子们讲故事。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚那天，神父问了他们几句话。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父穿着黑色的长衣服。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去教堂找神父聊聊。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父为大家祈祷。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位神父在小镇住了三十年。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父说，人要有爱心。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的神父帮助了穷人。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老神父", "label": "复合"}], "register": "正式", "sense_fingerprint": "天主教、东正教中主持宗教仪式的神职人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神父", "is_correct": true, "explanation": "神父 shén fu：天主教、东正教中主持宗教仪式的神职人员，是正确答案。"}, {"text": "生父", "is_correct": false, "explanation": "生父（shēng fù）与 shén fu 的韵母和声调都不同，意思是亲生父亲，不是神职人员。"}, {"text": "圣父", "is_correct": false, "explanation": "圣父（shèng fù）与 shén fu 的韵母和声调都不同，指天主教中三位一体的第一位。"}, {"text": "神符", "is_correct": false, "explanation": "神符（shén fú）第二个音节声调不同（fú 与 fu），意思是画有神秘文字或图形的符。"}], "explanations": {"神父": "神父 shén fu：天主教、东正教中主持宗教仪式的神职人员，是正确答案。", "生父": "生父（shēng fù）与 shén fu 的韵母和声调都不同，意思是亲生父亲，不是神职人员。", "圣父": "圣父（shèng fù）与 shén fu 的韵母和声调都不同，指天主教中三位一体的第一位。", "神符": "神符（shén fú）第二个音节声调不同（fú 与 fu），意思是画有神秘文字或图形的符。"}, "sentence_index": null, "correct_answer": "神父"}, "level_3": {"options": [{"text": "神父", "is_correct": true, "explanation": "正确：神父是天主教、东正教中主持仪式的神职人员，符合“教堂里主持仪式”。"}, {"text": "和尚", "is_correct": false, "explanation": "语义：和尚是佛教僧人，不在教堂主持仪式，与“教堂里”的语境冲突。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“主持仪式”要求有人作施事，厨房不能主持仪式。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不主持宗教仪式，与“主持仪式”的语境冲突。"}], "explanations": {"神父": "正确：神父是天主教、东正教中主持仪式的神职人员，符合“教堂里主持仪式”。", "和尚": "语义：和尚是佛教僧人，不在教堂主持仪式，与“教堂里”的语境冲突。", "厨房": "配价：“主持仪式”要求有人作施事，厨房不能主持仪式。", "厨师": "语义：厨师不主持宗教仪式，与“主持仪式”的语境冲突。"}, "sentence_index": 0, "correct_answer": "神父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教堂里的那位女神父正在教孩子们唱歌。", "explanation": "这里应该用〈修女〉。神父指男性神职人员；在教会服务的女性称修女。"}, {"text": "寺庙里住着一位老神父，他每天吃素。", "explanation": "这里应该用〈和尚〉。神父是天主教、东正教的神职人员；寺庙里的佛教僧人称和尚。"}, {"text": "道观里的老神父每天早上打扫院子。", "explanation": "这里应该用〈道士〉。神父属于基督教系统；道观里的道教人员称道士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神父", "is_correct": true, "explanation": "正确：神父是主持宗教仪式的神职人员，可以为大家祈祷。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“祈祷”的施事应是人，石头不能祈祷。"}, {"text": "苹果", "is_correct": false, "explanation": "配价：苹果是水果，不能为大家祈祷。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：桌子是家具，不能为大家祈祷。"}], "explanations": {"神父": "正确：神父是主持宗教仪式的神职人员，可以为大家祈祷。", "石头": "配价：“祈祷”的施事应是人，石头不能祈祷。", "苹果": "配价：苹果是水果，不能为大家祈祷。", "桌子": "配价：桌子是家具，不能为大家祈祷。"}, "sentence_index": 6, "correct_answer": "神父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上的神父住在云里。", "explanation": "这里应该用〈神仙〉。神父指人间主持仪式的神职人员，不指天上的神仙。"}, {"text": "清真寺里的神父每天带领大家祈祷。", "explanation": "这里应该用〈阿訇〉。神父是天主教、东正教的神职人员；清真寺里的伊斯兰教教职人员称阿訇。"}, {"text": "她是一位神父，每个星期天在教堂帮忙。", "explanation": "这里应该用〈修女〉。神父指男性神职人员，女性的宗教人员称修女，不能用神父指女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们请了三只神父来主持婚礼。", "corrected_sentence": "他们请了三位神父来主持婚礼。", "error_description": "错误形式：“三只神父”。“只”多用于动物，不用于人；神父指人，应用量词“位”。正确形式：“三位神父”，把量词“只”换成“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他神父。", "corrected_sentence": "他是神父。", "error_description": "错误形式：“他神父”。作谓语的名词前要用动词“是”，正确形式为“他是神父”，缺少“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": false, "explanation": "“高兴”是心情，与“相同”不构成反义关系。"}, {"text": "不同", "is_correct": true, "explanation": "“不同”与“相同”构成反义，指彼此没有一样的地方。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“相同”无反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁，与“相同”无反义关系。"}], "correct_answer": "不同", "explanations": {"高兴": "“高兴”是心情，与“相同”不构成反义关系。", "不同": "“不同”与“相同”构成反义，指彼此没有一样的地方。", "明亮": "“明亮”形容光线或颜色，与“相同”无反义关系。", "干净": "“干净”形容清洁，与“相同”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或动静，与“相同”无反义关系。"}, {"text": "不同", "is_correct": true, "explanation": "“不同”与“相同”构成反义，指彼此没有一样的地方。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白或分明，与“相同”无反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“相同”无反义关系。"}], "correct_answer": "不同", "explanations": {"安静": "“安静”指没有声音或动静，与“相同”无反义关系。", "不同": "“不同”与“相同”构成反义，指彼此没有一样的地方。", "清楚": "“清楚”形容明白或分明，与“相同”无反义关系。", "粗糙": "“粗糙”形容表面不光滑，与“相同”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相同就是一样,没有不一样的地方。", "primary_collocate": null, "pronunciation": "xiāng tóng", "ipa": "/ɕjɑŋ˥ tʰʊŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "这两件衣服的颜色相同。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩的生日相同，都是五月三号。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的想法完全相同。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个杯子大小相同，你随便拿一个。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字的读音相同，意思不同。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和她的爱好相同，所以常常一起玩。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们穿着相同的校服。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎的长相几乎相同。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的价格相同，都是三十元。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在相同的小区里。", "target_word": "相同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相同", "label": "否定"}, {"form": "相同点", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一样，没有不一样的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”只用来形容人的智力，不能用来形容颜色。"}, {"text": "相同", "is_correct": true, "explanation": "“相同”指颜色一样，与“这两件衣服的颜色”相合。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能用来形容颜色。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”指身材或体积大，用来说颜色不合语义。"}], "explanations": {"聪明": "搭配：“聪明”只用来形容人的智力，不能用来形容颜色。", "相同": "“相同”指颜色一样，与“这两件衣服的颜色”相合。", "勇敢": "搭配：“勇敢”形容人的品质，不能用来形容颜色。", "高大": "语义：“高大”指身材或体积大，用来说颜色不合语义。"}, "sentence_index": 0, "correct_answer": "相同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个孩子长得很相同，只是一个高一点。", "explanation": "这里应该用〈相似〉。“相同”指完全一样，长相有高矮差别时只能说“相似”。"}, {"text": "这两个城市的气温很相同，只差零点三度。", "explanation": "这里应该用〈相近〉。“相同”指完全一样，只差零点三度时要说“相近”。"}, {"text": "这两个数的大小相同，一个是三点五，一个是三点六。", "explanation": "这里应该用〈相近〉。“相同”指完全一样，两个数不同时只能说“相近”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，校服不能寂寞。"}, {"text": "诚实", "is_correct": false, "explanation": "搭配：“诚实”形容人的品行，不能用来修饰校服。"}, {"text": "相同", "is_correct": true, "explanation": "“相同”指款式一样，与“穿着”“校服”相合。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”形容人的情绪态度，与校服的款式无关。"}], "explanations": {"寂寞": "语义：“寂寞”形容人的心情，校服不能寂寞。", "诚实": "搭配：“诚实”形容人的品行，不能用来修饰校服。", "相同": "“相同”指款式一样，与“穿着”“校服”相合。", "冷静": "语义：“冷静”形容人的情绪态度，与校服的款式无关。"}, "sentence_index": 6, "correct_answer": "相同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国的经济水平很相同，只是还差一点点。", "explanation": "这里应该用〈接近〉。“相同”指完全一样，还差一点点时要说“接近”。"}, {"text": "两台电脑的价格很相同，相差不到一百元。", "explanation": "这里应该用〈相近〉。“相同”指完全一样，价格相差不到一百元时只能说“相近”。"}, {"text": "我们两家的房子相同，一家三层，一家两层。", "explanation": "这里应该用〈相似〉。“相同”指完全一样，房子层数不同时只能说“相似”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的爱好他相同。", "corrected_sentence": "我的爱好和他相同。", "error_description": "错误形式：“我的爱好他相同”；正确形式：“我的爱好和他相同”。“相同”表示与某人或某物一样，比较对象前要用“和”或“跟”引出，不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和他的爱好没相同。", "corrected_sentence": "我和他的爱好不相同。", "error_description": "错误形式：“没相同”；正确形式：“不相同”。“相同”是形容词，表示性质，否定时要用“不”，不能用“没”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
