INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88437, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "称心是东西正好合自己的想法，心里满意。", "primary_collocate": null, "pronunciation": "chèn xīn", "ipa": "ʈʂʰən˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他终于找到了一份称心的工作。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋很合脚，是一双称心的鞋。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子位置很好，我们终于买到了称心的房子。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找一个称心的住处不容易。", "target_word": "称心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们花了很久，终于挑到一把称心的椅子。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买的手机很称心。", "target_word": "称心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买到称心的礼物，她笑了。", "target_word": "称心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办公室又大又亮，他觉得很称心。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作工资不高，也不太称心。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直没找到称心的东西，只好空手回家。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称心如意", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西或事物正好符合自己的想法，所以心里满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "称心", "is_correct": true, "explanation": "称心（chèn xīn）：东西正好合自己的心意，让人满意。"}, {"text": "成心", "is_correct": false, "explanation": "成心（chéng xīn）与称心只在韵母 eng 与 en 及声调上不同，意思是故意。"}, {"text": "诚心", "is_correct": false, "explanation": "诚心（chéng xīn）与称心的韵母 eng/en 和声调不同，意思是真诚的心意。"}, {"text": "尘心", "is_correct": false, "explanation": "尘心（chén xīn）与称心只在声调上不同，意思是世俗的欲念。"}], "explanations": {"称心": "称心（chèn xīn）：东西正好合自己的心意，让人满意。", "成心": "成心（chéng xīn）与称心只在韵母 eng 与 en 及声调上不同，意思是故意。", "诚心": "诚心（chéng xīn）与称心的韵母 eng/en 和声调不同，意思是真诚的心意。", "尘心": "尘心（chén xīn）与称心只在声调上不同，意思是世俗的欲念。"}, "sentence_index": null, "correct_answer": "称心"}, "level_3": {"options": [{"text": "称心", "is_correct": true, "explanation": "称心：东西合自己的心意，与“工作”搭配自然。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说的是价格，不用来形容工作。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”描述坡度，不能用来形容工作。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”描述物体的形状，工作没有形状。"}], "explanations": {"称心": "称心：东西合自己的心意，与“工作”搭配自然。", "便宜": "搭配：“便宜”说的是价格，不用来形容工作。", "陡峭": "语义：“陡峭”描述坡度，不能用来形容工作。", "圆": "体貌：“圆”描述物体的形状，工作没有形状。"}, "sentence_index": 0, "correct_answer": "称心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被老板骂了一顿，心里很称心。", "explanation": "这里表示委屈，应该用〈委屈〉。称心表示满意，被骂时不能用称心来形容。"}, {"text": "这次考试没考好，他很称心。", "explanation": "这里表示沮丧，应该用〈沮丧〉。称心表示满意，考试没考好时不能用称心来形容。"}, {"text": "他的钱包被偷了，心里很称心。", "explanation": "这里表示懊恼，应该用〈懊恼〉。称心表示满意，钱包被偷时不能用称心来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称心", "is_correct": true, "explanation": "称心：东西合心意，与“礼物”搭配自然，买到以后她高兴。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”描述地势，不能用来形容礼物。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容人或态度，不能用来形容礼物。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，礼物不用这个词。"}], "explanations": {"称心": "称心：东西合心意，与“礼物”搭配自然，买到以后她高兴。", "陡峭": "语义：“陡峭”描述地势，不能用来形容礼物。", "严肃": "语义：“严肃”形容人或态度，不能用来形容礼物。", "高大": "体貌：“高大”形容人或物的体形，礼物不用这个词。"}, "sentence_index": 6, "correct_answer": "称心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试考砸了，他很称心。", "explanation": "这里表示沮丧，应该用〈沮丧〉。称心表示满意，考砸了不能用称心来形容。"}, {"text": "比赛输了，大家都很称心。", "explanation": "这里表示失望，应该用〈失望〉。称心表示满意，不能用来描述失望的心情。"}, {"text": "他被骗了，很称心。", "explanation": "这里表示生气，应该用〈生气〉。称心表示满意，不能用来描述生气的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个决定让我们都的称心。", "corrected_sentence": "这个决定让我们都很称心。", "error_description": "错误：“称心”前面用了“的”，应该用程度副词“很”。正确说法是“都很称心”，“很”修饰形容词，不用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的新电脑用很称心。", "corrected_sentence": "他的新电脑用得很称心。", "error_description": "错误：动词“用”后漏掉了补语的“得”。正确说法是“用得很称心”，动词后要用“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
