INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88438, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "合乎心意；满意。", "primary_collocate": null, "pronunciation": "chèn xīn", "ipa": "ʈʂʰən˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这门亲事父母都很称心。", "target_word": "称心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行过得很称心。", "target_word": "称心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直想找个称心的对象。", "target_word": "称心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的沙发又软又大，真称心。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板给我换了一张称心的桌子。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情办得这么顺利，大家都很称心。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租便宜，地方也安静，住着很称心。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想要一台称心的电脑，看了很多家店。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的结果不称心，我们再试一次吧。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有一件事称心，他今天心情很差。", "target_word": "称心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "称心如意", "label": "复合"}], "register": "中性", "sense_fingerprint": "结果、对象或环境合乎心意，让人满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1658dd2-89c0-42f7-8194-bcb92d4cc577') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "称心", "is_correct": true, "explanation": "称心（chèn xīn）：结果或对象合乎心意，让人满意。"}, {"text": "成心", "is_correct": false, "explanation": "成心（chéng xīn）与称心只在韵母 eng 与 en 及声调上不同，意思是故意。"}, {"text": "诚心", "is_correct": false, "explanation": "诚心（chéng xīn）与称心的韵母 eng/en 和声调不同，意思是真诚的心意。"}, {"text": "尘心", "is_correct": false, "explanation": "尘心（chén xīn）与称心只在声调上不同，意思是世俗的欲念。"}], "explanations": {"称心": "称心（chèn xīn）：结果或对象合乎心意，让人满意。", "成心": "成心（chéng xīn）与称心只在韵母 eng 与 en 及声调上不同，意思是故意。", "诚心": "诚心（chéng xīn）与称心的韵母 eng/en 和声调不同，意思是真诚的心意。", "尘心": "尘心（chén xīn）与称心只在声调上不同，意思是世俗的欲念。"}, "sentence_index": null, "correct_answer": "称心"}, "level_3": {"options": [{"text": "称心", "is_correct": true, "explanation": "称心：结果合心意，与“父母都很”搭配自然。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说的是价格，不能用来评价亲事。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”说的是味道，不能用来形容父母或亲事。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”说的是地形，不用来形容亲事。"}], "explanations": {"称心": "称心：结果合心意，与“父母都很”搭配自然。", "便宜": "搭配：“便宜”说的是价格，不能用来评价亲事。", "辣": "语义：“辣”说的是味道，不能用来形容父母或亲事。", "陡峭": "搭配：“陡峭”说的是地形，不用来形容亲事。"}, "sentence_index": 0, "correct_answer": "称心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被老板骂了一顿，心里很称心。", "explanation": "这里表示委屈，应该用〈委屈〉。称心表示满意，被骂时不能用称心来形容。"}, {"text": "这次考试考砸了，他很称心。", "explanation": "这里表示沮丧，应该用〈沮丧〉。称心表示满意，考砸了不能用称心来形容。"}, {"text": "听到噩耗，他很称心。", "explanation": "这里表示难过，应该用〈难过〉。称心表示满意，听到噩耗时不能用称心来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称心", "is_correct": true, "explanation": "称心：居住的感受合心意，与前面的“房租便宜，地方也安静”相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，不能用来形容居住的感受。"}, {"text": "凶", "is_correct": false, "explanation": "语义：“凶”形容人的脾气，不能用来形容住处。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述人或动物的体形，不能用来形容住处。"}], "explanations": {"称心": "称心：居住的感受合心意，与前面的“房租便宜，地方也安静”相符。", "甜": "语义：“甜”说的是味道，不能用来形容居住的感受。", "凶": "语义：“凶”形容人的脾气，不能用来形容住处。", "胖": "体貌：“胖”描述人或动物的体形，不能用来形容住处。"}, "sentence_index": 6, "correct_answer": "称心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛输了，大家都很称心。", "explanation": "这里表示失望，应该用〈失望〉。称心表示满意，不能用来描述失望的心情。"}, {"text": "他在众人面前摔了一跤，很称心。", "explanation": "这里表示尴尬，应该用〈尴尬〉。称心表示满意，当众摔倒时不能用称心来形容。"}, {"text": "他被骗了，很称心。", "explanation": "这里表示生气，应该用〈生气〉。称心表示满意，不能用来描述生气的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗衣机用很称心。", "corrected_sentence": "这台洗衣机用得很称心。", "error_description": "错误：动词“用”后漏掉了补语的“得”。正确说法是“用得很称心”，动词后要用“得”引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次装修大家都的称心。", "corrected_sentence": "这次装修大家都很称心。", "error_description": "错误：“称心”前面用了“的”，应该用程度副词“很”。正确说法是“大家都很称心”，“很”修饰形容词，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a3812d8-7839-487f-b572-05e94d91e72a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
