INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88439, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "回条是写给别人的小字条，告诉他你已经知道了。", "primary_collocate": null, "pronunciation": "huí tiáo", "ipa": "xweɪ˧˥ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我给妈妈留了一张回条，说我知道了。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友写了一张回条，说他知道了。", "target_word": "回条", "complexity_tier": "T3", "furigana": "péng you xiě le yì zhāng huí tiáo, shuō tā zhī dào le.", "sentence_source": "generated"}, {"text": "桌上有一张回条，是小王写的。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看完信，随手写了回条。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在回条上写了“知道了”。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给老师的回条很短，只有三个字。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把回条放在门上，就走了。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到你的回条，我很高兴。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给同学写了回条，告诉他我已经知道。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张回条上写着“好的，谢谢”。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张回条", "label": "量词"}, {"form": "回條", "label": "繁体"}], "register": "口语", "sense_fingerprint": "写给别人表示已知道的小字条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回条", "is_correct": true, "explanation": "正确：“回条”是写给别人的小字条，可以用来说“我知道了”。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不用来写“我知道了”这样的话，与语境不符。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“说我知道了”需要能写字的载体，饼干不能这样用。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能用来留下一句话，与“说我知道了”不合。"}], "explanations": {"回条": "正确：“回条”是写给别人的小字条，可以用来说“我知道了”。", "地图": "语义：地图不用来写“我知道了”这样的话，与语境不符。", "饼干": "搭配：“说我知道了”需要能写字的载体，饼干不能这样用。", "桌子": "语义：桌子不能用来留下一句话，与“说我知道了”不合。"}, "sentence_index": 0, "correct_answer": "回条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上写一张回条，记下自己一天做了什么。", "explanation": "这里应该用〈日记〉。回条是写给别人的小字条，告诉对方你已经知道了；每天记下自己做的事要用日记。"}, {"text": "我给同学寄了一张回条，邀请他参加生日会。", "explanation": "这里应该用〈请柬〉。回条是写给别人的小字条，告诉对方你已经知道了；邀请别人参加活动要用请柬。"}, {"text": "老师让我们把回条带回家，签字后交回学校。", "explanation": "这里说的是收到后要交回的凭条，不是写给人的小字条，属于另一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回条", "is_correct": true, "explanation": "正确：“回条”是小字条，可以放在门上留给别人看。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车是大型车辆，不能用“放在门上”这样留下信息。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“放”要求有形体的物品作宾语，空气不能被放在门上。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能被放在门上，与“放在门上，就走了”不合。"}], "explanations": {"回条": "正确：“回条”是小字条，可以放在门上留给别人看。", "卡车": "语义：卡车是大型车辆，不能用“放在门上”这样留下信息。", "空气": "配价：“放”要求有形体的物品作宾语，空气不能被放在门上。", "海洋": "语义：海洋不能被放在门上，与“放在门上，就走了”不合。"}, "sentence_index": 6, "correct_answer": "回条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "快递员留下一张回条，让我在上面签名，然后交回给他。", "explanation": "这里说的是收到东西后交回的凭条，不是写给别人的小字条，属于另一个意思。"}, {"text": "买东西后，店员给我一张回条，当作凭证。", "explanation": "这里应该用〈收据〉。回条是写给别人的小字条，告诉对方你已经知道了；买东西付款后的凭证叫收据。"}, {"text": "学校发了一张回条，通知全班明天放假。", "explanation": "这里应该用〈通知单〉。这句说的是学校发给全班的通知，应该用通知单；回条是写给别人的小字条，告诉对方你已经知道了，不用来发通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我给爸爸留了一只回条，说我已经知道了。", "corrected_sentence": "我给爸爸留了一张回条，说我已经知道了。", "error_description": "量词错误：回条是纸片，应该说“一张回条”，不能说“一只回条”（“只”多用于动物）。正确说法是：我给爸爸留了一张回条，说我已经知道了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他留给我一张的回条，说他知道了。", "corrected_sentence": "他留给我一张回条，说他知道了。", "error_description": "结构助词错误：数量词“一张”后直接接名词“回条”，中间不能加“的”，应说“一张回条”，不能说“一张的回条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
