INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88440, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "收到物品或通知后交回的凭条。", "primary_collocate": null, "pronunciation": "huí tiáo", "ipa": "xweɪ˧˥ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "收到包裹后，请在回条上签名。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长要把回条交给老师。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张回条要明天交回学校。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收到通知，马上填好了回条。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员请我在回条上写名字。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把回条放在桌子上。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带回条，老师不高兴。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校发了一张回条，让家长签字。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回条上要写日期和姓名。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把回条寄回公司。", "target_word": "回条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张回条", "label": "量词"}, {"form": "回條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "收到后交回的凭条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回条", "is_correct": true, "explanation": "正确：“回条”是收到包裹后交回的凭条，可以在上面签名。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以签名的纸片，“在天气上签名”说不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不能拿来签名，与“收到包裹后”的语境不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“签名”要求有承载文字的平面，空气不能用于签名。"}], "explanations": {"回条": "正确：“回条”是收到包裹后交回的凭条，可以在上面签名。", "天气": "语义：天气不是可以签名的纸片，“在天气上签名”说不通。", "早饭": "语义：早饭不能拿来签名，与“收到包裹后”的语境不符。", "空气": "搭配：“签名”要求有承载文字的平面，空气不能用于签名。"}, "sentence_index": 0, "correct_answer": "回条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店员递给我一张回条，这是我买东西的凭证。", "explanation": "这里应该用〈收据〉。回条是收到后交回的凭条，买东西付款后的凭证叫收据。"}, {"text": "我借钱给他，他写了一张回条。", "explanation": "这里应该用〈借条〉。回条是收到物品或通知后交回的凭条；借钱时写下的凭据叫借条。"}, {"text": "他生病了，写了一张回条向老师请三天假。", "explanation": "这里应该用〈请假条〉。回条是收到物品或通知后交回的凭条；向老师请假要写请假条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回条", "is_correct": true, "explanation": "正确：“回条”是需要交回的凭条，忘带它，老师会不高兴。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不是学生需要交回的东西，“忘了带太阳”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“带”一般搭配可以携带的物件，空气不能这样说。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：宇宙不是学生需要带来的物品，与“老师不高兴”的语境不符。"}], "explanations": {"回条": "正确：“回条”是需要交回的凭条，忘带它，老师会不高兴。", "太阳": "语义：太阳不是学生需要交回的东西，“忘了带太阳”说不通。", "空气": "搭配：“带”一般搭配可以携带的物件，空气不能这样说。", "宇宙": "语义：宇宙不是学生需要带来的物品，与“老师不高兴”的语境不符。"}, "sentence_index": 6, "correct_answer": "回条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给妈妈留了一张回条，说他先走了。", "explanation": "这里说的是写给别人的小字条，属于另一个意思，不是收到后交回的凭条。"}, {"text": "这张回条上画着一朵花，像一张贺卡。", "explanation": "这里应该用〈贺卡〉。回条是收到物品或通知后交回的凭条；装饰用的祝福卡要说贺卡。"}, {"text": "商场门口发了一张回条，上面写着大减价的消息。", "explanation": "这里应该用〈传单〉。回条是收到物品或通知后交回的凭条；宣传信息要用传单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你在这只回条上填写学号。", "corrected_sentence": "请你在这张回条上填写学号。", "error_description": "量词错误：回条是纸片，应该说“这张回条”，不能说“这只回条”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那本回条交给了老师。", "corrected_sentence": "我把那张回条交给了老师。", "error_description": "量词错误：回条是纸片，应该用“张”，不能用“本”（“本”多用于书册）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
