INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "论坛是现场大家一起说话、谈事情的讨论会或场所，多在房间里举行。", "primary_collocate": null, "pronunciation": "lùn tán", "ipa": "/lu̯ən˥˩ tʰan˧˥/", "syllable_count": 2, "sentences": [{"text": "学校的论坛在三楼的大房间里举行。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午，论坛在三楼的大房间开始。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班每周五都在教室里开论坛。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个论坛不大，只能坐五十个人。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在论坛上谈了很多旅行的事。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个论坛每周五晚上都有人来聊天。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在一次钓鱼论坛上认识了很多朋友。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论坛的门开着，大家都走进去了。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在论坛上发言，大家都认真听。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个论坛让大家有地方说话。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "现场大家一起谈事情的讨论会或会场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操场", "is_correct": false, "explanation": "语义：操场在户外，不会在三楼的房间里举行活动。"}, {"text": "足球", "is_correct": false, "explanation": "搭配：“举行”要接活动名称，“足球”是实物，不能说“足球在…举行”。"}, {"text": "论坛", "is_correct": true, "explanation": "正确：论坛指房间里大家谈事情的地方，“在大房间里举行”符合语境。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，不是举行聚会的场所。"}], "explanations": {"操场": "语义：操场在户外，不会在三楼的房间里举行活动。", "足球": "搭配：“举行”要接活动名称，“足球”是实物，不能说“足球在…举行”。", "论坛": "正确：论坛指房间里大家谈事情的地方，“在大房间里举行”符合语境。", "图书馆": "语义：图书馆是借阅书籍的地方，不是举行聚会的场所。"}, "sentence_index": 0, "correct_answer": "论坛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天中午，论坛里大家在吃饭。", "explanation": "这里应该用〈食堂〉。论坛是大家说话、谈事情的地方，吃饭要去食堂。"}, {"text": "这个论坛里堆满了货物。", "explanation": "这里应该用〈仓库〉。论坛是谈事情的地方，不能堆放货物，堆货物要用仓库。"}, {"text": "这个论坛每天都有很多病人看病。", "explanation": "这里应该用〈医院〉。论坛是大家一起谈事情的地方，病人看病要去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工具箱", "is_correct": false, "explanation": "语义：工具箱是装工具的箱子，不能在里面认识朋友。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：鱼缸是养鱼的容器，人不会在里面认识朋友。"}, {"text": "论坛", "is_correct": true, "explanation": "正确：“一次钓鱼论坛”是爱好者现场聚在一起交流的活动，“在…上认识很多朋友”符合语境。"}, {"text": "餐具", "is_correct": false, "explanation": "搭配：“钓鱼”修饰的名词要能指场所或组织，“钓鱼餐具”不能作为认识朋友的地方。"}], "explanations": {"工具箱": "语义：工具箱是装工具的箱子，不能在里面认识朋友。", "鱼缸": "语义：鱼缸是养鱼的容器，人不会在里面认识朋友。", "论坛": "正确：“一次钓鱼论坛”是爱好者现场聚在一起交流的活动，“在…上认识很多朋友”符合语境。", "餐具": "搭配：“钓鱼”修饰的名词要能指场所或组织，“钓鱼餐具”不能作为认识朋友的地方。"}, "sentence_index": 6, "correct_answer": "论坛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "论坛里有很多人在打篮球。", "explanation": "这里应该用〈体育馆〉。论坛是大家谈事情的地方，打篮球要去体育馆。"}, {"text": "论坛里有人在做饭，香味飘出来了。", "explanation": "这里应该用〈厨房〉。论坛是大家谈事情的地方，做饭要去厨房。"}, {"text": "这个论坛里养着很多小鸡。", "explanation": "这里应该用〈鸡舍〉。论坛是谈事情的地方，不能养鸡，养鸡要去鸡舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次论坛图书馆二楼的大厅举行。", "corrected_sentence": "这次论坛在图书馆二楼的大厅举行。", "error_description": "错误形式：“这次论坛图书馆二楼的大厅举行”；正确形式：“这次论坛在图书馆二楼的大厅举行”。处所短语前要用介词“在”引出，漏掉“在”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条论坛明天下午举行。", "corrected_sentence": "这个论坛明天下午举行。", "error_description": "量词错误：“论坛”指讨论会时用量词“个”或“场”，不能用“条”。“条”用于细长的东西，如河流、裤子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
