INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人们就某些问题发表意见、展开讨论的场所,多指网络平台。", "primary_collocate": null, "pronunciation": "lùn tán", "ipa": "/lu̯ən˥˩ tʰan˧˥/", "syllable_count": 2, "sentences": [{"text": "我常在这个论坛上看别人的意见。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在论坛发了一个帖子，问怎么学汉语。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个论坛里有很多人讨论电影。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论坛上的人都在谈这件新闻。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我注册了一个汽车论坛的账号。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们到学校的论坛上发帖交流学习方法。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论坛里有人回答了我的问题。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个论坛很热闹，每天都有新帖子。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在论坛上认识了一个很好的朋友。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每晚睡前都看一会儿论坛。", "target_word": "论坛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "網絡論壇", "label": "繁体"}, {"form": "网络论坛", "label": "复合词"}], "register": "中性", "sense_fingerprint": "网络上发表意见、讨论问题的平台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信箱", "is_correct": false, "explanation": "搭配：“在…上”要接能展示文字的平面或屏幕，信箱是箱子，不能说“在这个信箱上看别人的意见”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，没有人在那里发表和阅读意见。"}, {"text": "论坛", "is_correct": true, "explanation": "正确：论坛是网上供人发表意见、讨论问题的平台，与“看别人的意见”相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花、休息的地方，与“看别人的意见”无关。"}], "explanations": {"信箱": "搭配：“在…上”要接能展示文字的平面或屏幕，信箱是箱子，不能说“在这个信箱上看别人的意见”。", "厨房": "语义：厨房是做饭的地方，没有人在那里发表和阅读意见。", "论坛": "正确：论坛是网上供人发表意见、讨论问题的平台，与“看别人的意见”相符。", "花园": "语义：花园是种花、休息的地方，与“看别人的意见”无关。"}, "sentence_index": 0, "correct_answer": "论坛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常在论坛上吃午饭。", "explanation": "这里应该用〈饭馆〉。论坛是网上讨论问题的平台，不是吃饭的地方，吃午饭要去饭馆。"}, {"text": "我在论坛上洗了个澡。", "explanation": "这里应该用〈浴室〉。论坛是讨论问题、交流意见的平台，洗澡要去浴室。"}, {"text": "我在论坛上游了一个小时泳。", "explanation": "这里应该用〈游泳池〉。论坛是网上讨论问题的平台，游泳要去游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书架", "is_correct": false, "explanation": "语义：书架是放书的家具，不会有人在里面回答问题。"}, {"text": "论坛", "is_correct": true, "explanation": "正确：论坛是人们讨论问题、互相回答的地方，与“有人回答了我的问题”相符。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜是放衣服的家具，与“有人回答了我的问题”无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“回答问题”需要能交流的场所，“冰箱里有人回答问题”不搭配。"}], "explanations": {"书架": "语义：书架是放书的家具，不会有人在里面回答问题。", "论坛": "正确：论坛是人们讨论问题、互相回答的地方，与“有人回答了我的问题”相符。", "衣柜": "语义：衣柜是放衣服的家具，与“有人回答了我的问题”无关。", "冰箱": "搭配：“回答问题”需要能交流的场所，“冰箱里有人回答问题”不搭配。"}, "sentence_index": 6, "correct_answer": "论坛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在杂志上发表了一个论坛。", "explanation": "这里应该用〈论文〉。论坛是供人讨论的场所，不是可以发表的文章，发表要用论文。"}, {"text": "下午我们在论坛上踢足球。", "explanation": "这里应该用〈球场〉。论坛是讨论问题的场所，踢足球要去球场。"}, {"text": "我把论坛装进了书包里。", "explanation": "这里应该用〈笔记本〉。论坛不是实物，不能装进书包，书包里装的是笔记本等物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一只很好的论坛。", "corrected_sentence": "我找到了一个很好的论坛。", "error_description": "量词错误：“论坛”应使用量词“个”，说“一个很好的论坛”；“只”用于动物或成对物品中的一个，不能用于论坛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天我论坛上发了一个帖子。", "corrected_sentence": "今天我在论坛上发了一个帖子。", "error_description": "漏字：“论坛”作处所时，前面要加介词“在”，应说“在论坛上发帖子”，漏掉“在”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
