INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因式是数学里乘在一起能变成一个式子的各个小式子。", "primary_collocate": null, "pronunciation": "yīn shì", "ipa": "in˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "把多项式写成几个因式相乘。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个因式乘在一起，就是原来的式子。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个因式都比原来的式子简单。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写出了三个因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个式子写成两个因式的乘积。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个式子可以拆成几个因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个因式相乘，得到一个新的式子。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每个因式都检查了一遍。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三个因式中，有一个是常数。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些因式相乘，正好等于原式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "因式分解", "label": "复合"}, {"form": "公因式", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "术语", "sense_fingerprint": "乘在一起组成原式的各个式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确答案：因式（yīn shì），指乘在一起组成原式的各个式子。"}, {"text": "英式", "is_correct": false, "explanation": "yīng 与 yīn 韵尾不同（ng 与 n），“英式”意思是英国式样。"}, {"text": "衣饰", "is_correct": false, "explanation": "yī 没有 n 韵尾，与 yīn 不同；“衣饰”意思是服装上的装饰。"}, {"text": "隐式", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，“隐式”意思是不明显表达出来的形式。"}], "explanations": {"因式": "正确答案：因式（yīn shì），指乘在一起组成原式的各个式子。", "英式": "yīng 与 yīn 韵尾不同（ng 与 n），“英式”意思是英国式样。", "衣饰": "yī 没有 n 韵尾，与 yīn 不同；“衣饰”意思是服装上的装饰。", "隐式": "yǐn（第三声）与 yīn（第一声）声调不同，“隐式”意思是不明显表达出来的形式。"}, "sentence_index": null, "correct_answer": "因式"}, "level_3": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确：“因式”指乘在一起组成原式的式子，与“写成几个……相乘”相符。"}, {"text": "句子", "is_correct": false, "explanation": "语义：要写成相乘的是式子，不是句子，“句子相乘”没有意义。"}, {"text": "方式", "is_correct": false, "explanation": "搭配：“相乘”的对象应是数或式子，不能说“方式相乘”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：式子不能相乘成玩具，与数学语境不符。"}], "explanations": {"因式": "正确：“因式”指乘在一起组成原式的式子，与“写成几个……相乘”相符。", "句子": "语义：要写成相乘的是式子，不是句子，“句子相乘”没有意义。", "方式": "搭配：“相乘”的对象应是数或式子，不能说“方式相乘”。", "玩具": "语义：式子不能相乘成玩具，与数学语境不符。"}, "sentence_index": 0, "correct_answer": "因式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "10的因式有1、2、5和10。", "explanation": "这里应该用〈因数〉。整数的约数叫因数，因式只用于多项式。"}, {"text": "两个数相乘的因式是十二。", "explanation": "这里应该用〈乘积〉。乘积是相乘得到的数值结果，因式是乘在一起组成原式的各个式子，不是结果。"}, {"text": "他分析了事故的主要因式。", "explanation": "这里应该用〈因素〉。因素指导致事情发生的原因；因式是数学术语，指乘在一起组成原式的式子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88445, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确答案：因式（yīn shì），指乘在一起组成原式的各个式子。"}, {"text": "一是", "is_correct": false, "explanation": "yī 没有 n 韵尾，与 yīn 不同；“一是”意思是第一、其一。"}, {"text": "银饰", "is_correct": false, "explanation": "yín（第二声）与 yīn（第一声）声调不同，“银饰”是银质首饰。"}, {"text": "阴湿", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“阴湿”意思是阴暗潮湿。"}, {"text": "因时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“因时”意思是依据时机。"}], "explanations": {"因式": "正确答案：因式（yīn shì），指乘在一起组成原式的各个式子。", "一是": "yī 没有 n 韵尾，与 yīn 不同；“一是”意思是第一、其一。", "银饰": "yín（第二声）与 yīn（第一声）声调不同，“银饰”是银质首饰。", "阴湿": "shī（第一声）与 shì（第四声）声调不同，“阴湿”意思是阴暗潮湿。", "因时": "shí（第二声）与 shì（第四声）声调不同，“因时”意思是依据时机。"}, "sentence_index": null, "correct_answer": "因式"}, "level_3": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确：“因式”指乘在一起组成原式的式子，与“相乘，得到一个新的式子”相符。"}, {"text": "数字", "is_correct": false, "explanation": "语义：两个数字相乘得到的是数，不是新的式子。"}, {"text": "图形", "is_correct": false, "explanation": "语义：图形不能相乘，与“得到一个新的式子”不符。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“相乘”不用于乐器，与前面的“相乘”搭配不当。"}], "explanations": {"因式": "正确：“因式”指乘在一起组成原式的式子，与“相乘，得到一个新的式子”相符。", "数字": "语义：两个数字相乘得到的是数，不是新的式子。", "图形": "语义：图形不能相乘，与“得到一个新的式子”不符。", "乐器": "搭配：“相乘”不用于乐器，与前面的“相乘”搭配不当。"}, "sentence_index": 6, "correct_answer": "因式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这三本因式乘起来正好是原式。", "explanation": "这里应该用〈个〉。“本”用于书籍，因式是抽象的式子，不能用“本”计量。"}, {"text": "这两根因式相乘，得到原式。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，因式不能用“根”计量。"}, {"text": "这一堆因式乘起来正好是原式。", "explanation": "这里应该用〈个〉。“堆”指堆在一起的东西，因式是单个的式子，不能用“堆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个因式很都简单。", "corrected_sentence": "每个因式都很简单。", "error_description": "“都”应紧跟“每个因式”，位于“很”之前，写作“每个因式都很简单”；“很都简单”把“都”放在“很”后，语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这三个的因式中，有两个是一次式。", "corrected_sentence": "这三个因式中，有两个是一次式。", "error_description": "“的”不能插在数量词“三个”和“因式”之间；应写作“这三个因式中”，多出的“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
