INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学中能整除某个多项式的式子。", "primary_collocate": null, "pronunciation": "yīn shì", "ipa": "in˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个多项式有两个因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们，这个式子的因式是什么。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个多项式的因式，必须能整除它。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能找出这个多项式的另一个因式吗？", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能整除多项式的式子，就叫它的因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多项式的因式不止一个。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算了半天，才发现这不是它的因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们学习怎样判断一个因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多项式最简单的因式是什么？", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用除法检查，这个式子确实是原式的因式。", "target_word": "因式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "因式分解", "label": "复合"}, {"form": "公因式", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "术语", "sense_fingerprint": "能整除多项式的式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6854af22-f18f-4c1c-baff-63ef8b47a3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确答案：因式（yīn shì），指能整除多项式的式子。"}, {"text": "英式", "is_correct": false, "explanation": "yīng 与 yīn 韵尾不同（ng 与 n），“英式”意思是英国式样。"}, {"text": "银饰", "is_correct": false, "explanation": "yín（第二声）与 yīn（第一声）声调不同，“银饰”是银质首饰。"}, {"text": "一是", "is_correct": false, "explanation": "yī 没有 n 韵尾，与 yīn 不同；“一是”意思是第一、其一。"}, {"text": "衣饰", "is_correct": false, "explanation": "yī 没有 n 韵尾，与 yīn 不同；“衣饰”意思是服装上的装饰。"}], "explanations": {"因式": "正确答案：因式（yīn shì），指能整除多项式的式子。", "英式": "yīng 与 yīn 韵尾不同（ng 与 n），“英式”意思是英国式样。", "银饰": "yín（第二声）与 yīn（第一声）声调不同，“银饰”是银质首饰。", "一是": "yī 没有 n 韵尾，与 yīn 不同；“一是”意思是第一、其一。", "衣饰": "yī 没有 n 韵尾，与 yīn 不同；“衣饰”意思是服装上的装饰。"}, "sentence_index": null, "correct_answer": "因式"}, "level_3": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确：“因式”指能整除多项式的式子，与“多项式有两个”相符。"}, {"text": "方程", "is_correct": false, "explanation": "语义：多项式不含等号，不能说它有“方程”。"}, {"text": "句子", "is_correct": false, "explanation": "语义：多项式是数学式子，不是句子，不能说有“两个句子”。"}, {"text": "直角", "is_correct": false, "explanation": "语义：直角是几何图形里的角，多项式里没有角，不能说它有“两个直角”。"}], "explanations": {"因式": "正确：“因式”指能整除多项式的式子，与“多项式有两个”相符。", "方程": "语义：多项式不含等号，不能说它有“方程”。", "句子": "语义：多项式是数学式子，不是句子，不能说有“两个句子”。", "直角": "语义：直角是几何图形里的角，多项式里没有角，不能说它有“两个直角”。"}, "sentence_index": 0, "correct_answer": "因式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们来找出12的另一个因式吧。", "explanation": "这里应该用〈因数〉。整数的约数叫因数，因式只用于多项式。"}, {"text": "这次失败有很多因式。", "explanation": "这里应该用〈因素〉。因素指导致事情发生的原因，因式是数学术语，只指能整除多项式的式子。"}, {"text": "这三个数相乘得到的因式是六。", "explanation": "这里应该用〈乘积〉。乘积是相乘得到的数值结果，因式是能整除多项式的式子，不是数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确答案：因式（yīn shì），指能整除多项式的式子。"}, {"text": "饮食", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，shí（第二声）与 shì（第四声）声调也不同；“饮食”意思是吃和喝。"}, {"text": "阴湿", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，“阴湿”意思是阴暗潮湿。"}, {"text": "隐式", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，“隐式”意思是不明显表达出来的形式。"}, {"text": "因时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“因时”意思是依据时机。"}], "explanations": {"因式": "正确答案：因式（yīn shì），指能整除多项式的式子。", "饮食": "yǐn（第三声）与 yīn（第一声）声调不同，shí（第二声）与 shì（第四声）声调也不同；“饮食”意思是吃和喝。", "阴湿": "shī（第一声）与 shì（第四声）声调不同，“阴湿”意思是阴暗潮湿。", "隐式": "yǐn（第三声）与 yīn（第一声）声调不同，“隐式”意思是不明显表达出来的形式。", "因时": "shí（第二声）与 shì（第四声）声调不同，“因时”意思是依据时机。"}, "sentence_index": null, "correct_answer": "因式"}, "level_3": {"options": [{"text": "因式", "is_correct": true, "explanation": "正确：“因式”指能整除原式的式子，与“算了半天，才发现这不是它的”相符。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“算了半天”指计算，礼物不是能算出来的东西，与前文冲突。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“算了半天”指计算，花朵与计算过程无关。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车与前面“算了半天”的计算语境无关。"}], "explanations": {"因式": "正确：“因式”指能整除原式的式子，与“算了半天，才发现这不是它的”相符。", "礼物": "语义：“算了半天”指计算，礼物不是能算出来的东西，与前文冲突。", "花朵": "语义：“算了半天”指计算，花朵与计算过程无关。", "汽车": "语义：汽车与前面“算了半天”的计算语境无关。"}, "sentence_index": 6, "correct_answer": "因式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛输了，主要因式是准备不够。", "explanation": "这里应该用〈因素〉。因素指影响结果的原因；因式是数学术语，只指能整除多项式的式子。"}, {"text": "18的因式有1、2、3、6、9和18。", "explanation": "这里应该用〈因数〉。整数的约数叫因数；因式只用于多项式。"}, {"text": "这个方程的因式是x等于2。", "explanation": "这里应该用〈解〉。使方程成立的值叫方程的解；因式是能整除多项式的式子，不是一个取值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找到了一条因式。", "corrected_sentence": "他找到了一个因式。", "error_description": "量词用错：“条”用于细长的东西，因式是抽象的式子，应用量词“个”，写作“一个因式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个因式们都很简单。", "corrected_sentence": "这几个因式都很简单。", "error_description": "“们”不能与“几个”这类数量词连用，“几个因式”已表示多数，应去掉“们”，写作“这几个因式都很简单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4644e2b-2452-4b5a-847d-11381538e0dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88447, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "落后：水平低、走在别人后面，是“先进”的反义词。"}, {"text": "美丽", "is_correct": false, "explanation": "美丽：形容好看，与“先进”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：形容没有声音或动作，与“先进”没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "善良：形容心地好，与“先进”没有反义关系。"}], "correct_answer": "落后", "explanations": {"落后": "落后：水平低、走在别人后面，是“先进”的反义词。", "美丽": "美丽：形容好看，与“先进”没有反义关系。", "安静": "安静：形容没有声音或动作，与“先进”没有反义关系。", "善良": "善良：形容心地好，与“先进”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88447, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "落后：水平低、走在别人后面，是“先进”的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线充足或颜色鲜亮，与“先进”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂：形容头绪多、不简单，与“先进”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "温和：形容性情或气候平和，与“先进”没有反义关系。"}], "correct_answer": "落后", "explanations": {"落后": "落后：水平低、走在别人后面，是“先进”的反义词。", "明亮": "明亮：形容光线充足或颜色鲜亮，与“先进”没有反义关系。", "复杂": "复杂：形容头绪多、不简单，与“先进”没有反义关系。", "温和": "温和：形容性情或气候平和，与“先进”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88447, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "先进就是比别人好,走在前面。", "primary_collocate": null, "pronunciation": "xiān jìn", "ipa": "ɕi̯ɛn˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他的想法很先进。", "target_word": "先进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个班的学习方法很先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校的设备很先进。", "target_word": "先进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他总是走在前面，想法比别人先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂的机器非常先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我们班的做法最先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在北京参观过一家很先进的医院。", "target_word": "先进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用的是最先进的方法。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那里的农业技术比我们先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然这台电脑很旧，但在当时很先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "先进性", "label": "复合"}, {"form": "先進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "先进：形容词，比别人好、走在前面（想法、做法、设备）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88447, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先进", "is_correct": true, "explanation": "先进：形容词，比别人好、走在前面，是本题要听辨的词。"}, {"text": "现金", "is_correct": false, "explanation": "现金 xiàn jīn 两个音节的声调都与 xiān jìn 不同，意思是钱币。"}, {"text": "相近", "is_correct": false, "explanation": "相近 xiāng jìn 的第一音节韵母是 -ang 而非 -an，意思是接近、差不多。"}, {"text": "仙境", "is_correct": false, "explanation": "仙境 xiān jìng 末尾是 -ng 而非 -n，意思是仙人居住的地方。"}, {"text": "新近", "is_correct": false, "explanation": "新近 xīn jìn 第一音节比 xiān jìn 少一个 a，韵母是 -in，意思是最近。"}], "explanations": {"先进": "先进：形容词，比别人好、走在前面，是本题要听辨的词。", "现金": "现金 xiàn jīn 两个音节的声调都与 xiān jìn 不同，意思是钱币。", "相近": "相近 xiāng jìn 的第一音节韵母是 -ang 而非 -an，意思是接近、差不多。", "仙境": "仙境 xiān jìng 末尾是 -ng 而非 -n，意思是仙人居住的地方。", "新近": "新近 xīn jìn 第一音节比 xiān jìn 少一个 a，韵母是 -in，意思是最近。"}, "sentence_index": null, "correct_answer": "先进"}, "level_3": {"options": [{"text": "先进", "is_correct": true, "explanation": "先进：形容想法比别人好、走在前面，与“很”搭配，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，不能用来形容想法。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写高度，不能用于想法。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”指含水分多，不能形容想法。"}], "explanations": {"先进": "先进：形容想法比别人好、走在前面，与“很”搭配，符合句意。", "咸": "语义：“咸”指味道，不能用来形容想法。", "矮": "体貌：“矮”描写高度，不能用于想法。", "湿": "语义：“湿”指含水分多，不能形容想法。"}, "sentence_index": 0, "correct_answer": "先进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她今天的裙子很先进，大家都在看她。", "explanation": "这里应该用〈时髦〉。先进用于技术、方法、思想，形容衣着的潮流要说时髦。"}, {"text": "他对学习很先进，每天都早早来到教室。", "explanation": "这里应该用〈认真〉。先进指水平高、方法新，形容对学习的态度要说认真。"}, {"text": "这个运动员跑得很先进，每次都得第一。", "explanation": "这里应该用〈快〉。先进指技术、方法、思想等领先，形容跑步的速度要说快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先进", "is_correct": true, "explanation": "先进：修饰医院，表示水平领先，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能形容医院。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”多用于重量或负担，不能修饰医院。"}, {"text": "软", "is_correct": false, "explanation": "语义：“软”形容质地柔软，不能形容医院的水平。"}], "explanations": {"先进": "先进：修饰医院，表示水平领先，符合句意。", "甜": "语义：“甜”指味道，不能形容医院。", "轻": "搭配：“轻”多用于重量或负担，不能修饰医院。", "软": "语义：“软”形容质地柔软，不能形容医院的水平。"}, "sentence_index": 6, "correct_answer": "先进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟很先进，三岁就会背唐诗了。", "explanation": "这里应该用〈聪明〉。先进指技术、方法等领先，形容小孩的头脑要说聪明。"}, {"text": "这幅画的颜色很先进，看得人眼睛很舒服。", "explanation": "这里应该用〈鲜艳〉。先进指水平高、方法新，形容颜色的鲜艳要说鲜艳。"}, {"text": "他很先进，常常逗得大家笑个不停。", "explanation": "这里应该用〈幽默〉。先进不能形容人的风趣，要说幽默。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们常用最先进地仪器检查产品。", "corrected_sentence": "他们常用最先进的仪器检查产品。", "error_description": "错误：“先进”修饰名词“仪器”时要用“的”，写成“地”不对（“地”用于修饰动词）。正确：最先进的仪器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
