INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88448, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "处于领先地位的;水平高、方法新的。", "primary_collocate": null, "pronunciation": "xiān jìn", "ipa": "ɕi̯ɛn˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的科学技术很先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院有先进的医疗设备。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司买了最先进的机器。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们学习国外先进的管理经验。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种技术在世界上很先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所大学的教学方法很先进。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要用先进的方法提高产量。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是目前世界上最先进的手机。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他参观过一家设备很先进的工厂。", "target_word": "先进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起老方法，新方法更先进，也更快。", "target_word": "先进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "先进性", "label": "复合"}, {"form": "先進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "先进：形容词，处于领先地位、水平高、方法新（技术、设备、管理）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88448, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先进", "is_correct": true, "explanation": "先进：形容词，处于领先地位、水平高、方法新，是本题要听辨的词。"}, {"text": "现金", "is_correct": false, "explanation": "现金 xiàn jīn 两个音节的声调都与 xiān jìn 不同，意思是钱币。"}, {"text": "相近", "is_correct": false, "explanation": "相近 xiāng jìn 的第一音节韵母是 -ang 而非 -an，意思是接近、差不多。"}, {"text": "仙境", "is_correct": false, "explanation": "仙境 xiān jìng 末尾是 -ng 而非 -n，意思是仙人居住的地方。"}], "explanations": {"先进": "先进：形容词，处于领先地位、水平高、方法新，是本题要听辨的词。", "现金": "现金 xiàn jīn 两个音节的声调都与 xiān jìn 不同，意思是钱币。", "相近": "相近 xiāng jìn 的第一音节韵母是 -ang 而非 -an，意思是接近、差不多。", "仙境": "仙境 xiān jìng 末尾是 -ng 而非 -n，意思是仙人居住的地方。"}, "sentence_index": null, "correct_answer": "先进"}, "level_3": {"options": [{"text": "先进", "is_correct": true, "explanation": "先进：形容科学技术处于领先地位，与“很”搭配，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，不能形容科学技术。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写高度，不能形容科学技术。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，不能形容科学技术。"}], "explanations": {"先进": "先进：形容科学技术处于领先地位，与“很”搭配，符合句意。", "咸": "语义：“咸”指味道，不能形容科学技术。", "矮": "体貌：“矮”描写高度，不能形容科学技术。", "圆": "语义：“圆”形容形状，不能形容科学技术。"}, "sentence_index": 0, "correct_answer": "先进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个教练很先进，每天都笑呵呵的。", "explanation": "这里应该用〈和气〉。先进用于技术、方法、思想，不能形容性格，要说和气。"}, {"text": "这间屋子很先进，地上连一点灰都没有。", "explanation": "这里应该用〈干净〉。先进指水平高、方法新，形容屋子整洁要说干净。"}, {"text": "他的脾气很先进，从不跟人吵架。", "explanation": "这里应该用〈温和〉。先进用于技术、方法、思想，不能形容脾气，要说温和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先进", "is_correct": true, "explanation": "先进：修饰方法，表示水平领先，符合句意。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”形容宽度，不能用来形容方法的先进程度。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”形容温度，不能修饰方法。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”多修饰物体或内容，不能修饰方法。"}], "explanations": {"先进": "先进：修饰方法，表示水平领先，符合句意。", "窄": "语义：“窄”形容宽度，不能用来形容方法的先进程度。", "凉": "语义：“凉”形容温度，不能修饰方法。", "厚": "搭配：“厚”多修饰物体或内容，不能修饰方法。"}, "sentence_index": 6, "correct_answer": "先进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子很先进，问题一问一个准。", "explanation": "这里应该用〈聪明〉。先进指技术、方法等领先，形容小孩的头脑要说聪明。"}, {"text": "这个木盒擦得很先进，亮得能照出人影。", "explanation": "这里应该用〈光亮〉。先进指水平高、方法新，形容擦拭后的光泽要说光亮。"}, {"text": "他讲的笑话很先进，大家都爱听。", "explanation": "这里应该用〈幽默〉。先进不能形容笑话的风趣，要说幽默。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在工厂里常用最先进地设备生产零件。", "corrected_sentence": "他们在工厂里常用最先进的设备生产零件。", "error_description": "错误：“先进”修饰名词“设备”时要用“的”，写成“地”不对（“地”用于修饰动词）。正确：最先进的设备。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种新的测量方法比旧方法最先进，也更准确。", "corrected_sentence": "这种新的测量方法比旧方法更先进，也更准确。", "error_description": "错误：“比”字句中表示比较要用“更”，不能用表示最高级的“最”。错误形式是「比……最先进」，正确形式是「比……更先进」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
