INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "窗户是墙上能看到外面、也能透进光的地方。", "primary_collocate": null, "pronunciation": "chuāng hu", "ipa": "ʈʂʰwɑŋ˥ xu", "syllable_count": 2, "sentences": [{"text": "我家的窗户朝南，屋里很亮。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，窗户一直在响。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在窗户前，看着外面的雪。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的窗户太小，有点儿黑。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我喜欢开着窗户睡觉。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户玻璃脏了，该洗了。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把窗户都关好。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从窗户里看见了朋友。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户上有很多小水珠。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座老房子的窗户是木头做的。", "target_word": "窗户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扇", "label": "量词"}, {"form": "窗户纸", "label": "复合"}, {"form": "窗戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "墙上能看外面、透光的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c4b9b2f-50a8-4d73-9791-1b73b884d009') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "窗户", "is_correct": true, "explanation": "窗户是房屋上透光的开口，朝南的窗户能让屋里很亮，符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不透光，朝南的墙不能让屋里变亮，与“屋里很亮”矛盾。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明设备，不说“朝南”，也不是采光的部位，与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“朝南”一般用于房屋、窗户、门等，不用于冰箱。"}], "explanations": {"窗户": "窗户是房屋上透光的开口，朝南的窗户能让屋里很亮，符合句意。", "墙": "语义：墙不透光，朝南的墙不能让屋里变亮，与“屋里很亮”矛盾。", "灯": "语义：灯是照明设备，不说“朝南”，也不是采光的部位，与句意不符。", "冰箱": "搭配：“朝南”一般用于房屋、窗户、门等，不用于冰箱。"}, "sentence_index": 0, "correct_answer": "窗户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个花瓶是窗户做的，很容易碎。", "explanation": "这里应该用〈玻璃〉。说某物是什么材料做的，要用“玻璃”；窗户是房屋上的开口，不是材料。"}, {"text": "窗户是蓝色的布做的，晚上拉上能挡住光。", "explanation": "这里应该用〈窗帘〉。挂在窗前、用布做的、可以拉上挡光的是窗帘；窗户是墙上透光的开口。"}, {"text": "我在电脑上打开了好几个窗户，切换起来很麻烦。", "explanation": "这里应该用〈窗口〉。电脑程序打开的画面叫窗口，窗户是墙上的开口，不指电脑里的画面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": true, "explanation": "窗户可以开合，“把窗户都关好”符合句意。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不能被关好，“关”只能用于能开合的东西。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能开合，不能说“关好”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“关”与“空气”不搭配，要说“关好窗户、门”等可以开合的东西。"}], "explanations": {"窗户": "窗户可以开合，“把窗户都关好”符合句意。", "墙": "语义：墙不能被关好，“关”只能用于能开合的东西。", "桌子": "语义：桌子不能开合，不能说“关好”。", "空气": "搭配：“关”与“空气”不搭配，要说“关好窗户、门”等可以开合的东西。"}, "sentence_index": 6, "correct_answer": "窗户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在售票窗户前排队买票。", "explanation": "这里应该用〈窗口〉。售票处的服务口叫窗口，窗户是房屋墙上的开口。"}, {"text": "她每天早上照窗户，看看自己的头发。", "explanation": "这里应该用〈镜子〉。照自己的样子要用镜子；窗户是墙上能看到外面的地方。"}, {"text": "他把书放在窗户上，就去做饭了。", "explanation": "这里应该用〈窗台〉。东西要放在窗台上，窗户是开合的部分，不用来放书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里冷，他把一块窗户关上了。", "corrected_sentence": "夜里冷，他把一扇窗户关上了。", "error_description": "错误在量词：窗户的量词是“扇”，不能说“一块窗户”。应为“一扇窗户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风太大，一块窗户被吹开了。", "corrected_sentence": "风太大，一扇窗户被吹开了。", "error_description": "错误在量词：窗户的量词是“扇”，不能说“一块窗户”。应为“一扇窗户”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49d88280-2aa6-4945-91de-62f5bf45eae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
