INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国度是一个国家所在的地方。", "primary_collocate": null, "pronunciation": "guó dù", "ipa": "kwo˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "他离开家乡，来到了另一个国度。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞了十个小时，到了另一个国度。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国度，我没有朋友。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住在不同的国度，很少见面。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个国度生活了五年。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了陌生的国度，我有点怕。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国度在海的另一边。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去一个暖和的国度过冬。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很久以前搬到了一个很远的国度。", "target_word": "国度", "complexity_tier": "T3", "furigana": "tā hěn jiǔ yǐqián bān dào le yí gè hěn yuǎn de guódù", "sentence_source": "generated"}, {"text": "那个国度的天气很热。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个国度", "label": "量词"}, {"form": "國度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个国家所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88451, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国度", "is_correct": true, "explanation": "正确答案：国度（guó dù），指一个国家所在的地方。"}, {"text": "国都", "is_correct": false, "explanation": "国都（guó dū）与国度（guó dù）的区别在于第二个音节声调：dū（第一声）与 dù（第四声），意思是首都。"}, {"text": "过度", "is_correct": false, "explanation": "过度（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是超过限度。"}, {"text": "过渡", "is_correct": false, "explanation": "过渡（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是事物之间的中间阶段。"}], "explanations": {"国度": "正确答案：国度（guó dù），指一个国家所在的地方。", "国都": "国都（guó dū）与国度（guó dù）的区别在于第二个音节声调：dū（第一声）与 dù（第四声），意思是首都。", "过度": "过度（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是超过限度。", "过渡": "过渡（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是事物之间的中间阶段。"}, "sentence_index": null, "correct_answer": "国度"}, "level_3": {"options": [{"text": "国度", "is_correct": true, "explanation": "正确答案：“来到了另一个国度”指到达另一个国家所在的地方。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“来到”的对象是地方，梦想不是可以到达的地方。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：疾病不是地方，不能说“来到”。"}, {"text": "想法", "is_correct": false, "explanation": "搭配：“来到”后接的是地点，不能接“想法”这类抽象名词。"}], "explanations": {"国度": "正确答案：“来到了另一个国度”指到达另一个国家所在的地方。", "梦想": "语义：“来到”的对象是地方，梦想不是可以到达的地方。", "疾病": "语义：疾病不是地方，不能说“来到”。", "想法": "搭配：“来到”后接的是地点，不能接“想法”这类抽象名词。"}, "sentence_index": 0, "correct_answer": "国度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的国度在三楼，门是红色的。", "explanation": "这里应该用〈房间〉。国度指一个国家所在的地方，不能指楼里的一个房间。"}, {"text": "我把书放进了书包的国度里。", "explanation": "这是把“国度”当成书包内部的空间讲。国度指一个国家所在的地方，不能指物品的内部。"}, {"text": "我的钱包里有一个国度。", "explanation": "这是把“国度”当成小容器内部的空间讲。国度指一个国家所在的地方，不能指物品的内部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国度", "is_correct": true, "explanation": "正确答案：“这个国度在海的另一边”指一个国家位于海的另一边。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是地点，不能说“在海的另一边”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是地点，不能用“在海的另一边”来描述。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“在……另一边”的主语应是具体的人、物或地点，“感情”不能这样搭配。"}], "explanations": {"国度": "正确答案：“这个国度在海的另一边”指一个国家位于海的另一边。", "时间": "语义：时间不是地点，不能说“在海的另一边”。", "价格": "语义：价格不是地点，不能用“在海的另一边”来描述。", "感情": "搭配：“在……另一边”的主语应是具体的人、物或地点，“感情”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "国度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块面包有五个国度。", "explanation": "这是把“国度”当成食物的组成部分讲。国度指一个国家所在的地方，不能指食物的组成部分。"}, {"text": "这件衬衫的国度太大了。", "explanation": "这是把“国度”当成衣物的范围讲。国度指一个国家所在的地方，不能指衣服的大小。"}, {"text": "这张桌子的国度有一米宽。", "explanation": "这是把“国度”当成物体的大小讲。国度指一个国家所在的地方，不能指桌子的尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只国度的人都很热情。", "corrected_sentence": "那个国度的人都很热情。", "error_description": "“国度”前应该用量词“个”，不能用“只”。“只”用于动物、成对的东西等，国度是国家，应说“那个国度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候就梦想去一个温暖的国度们生活。", "corrected_sentence": "他小时候就梦想去一个温暖的国度生活。", "error_description": "“国度”后面不能加“们”。“们”只用于人或有生命的群体，这里应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
