INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家（多用于书面）。", "primary_collocate": null, "pronunciation": "guó dù", "ipa": "kwo˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这是一个美丽的国度。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过很多遥远的国度。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国度都有自己的文化。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国度的人很爱唱歌。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个国度，冬天特别长。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他梦想去一个没有战争的国度。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国度的历史非常长。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一个神奇的国度。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国度的人民很友好。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看不同国度的风景。", "target_word": "国度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个国度", "label": "量词"}, {"form": "國度", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc8d081-6bea-4594-9ad4-67f2274bb8ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国度", "is_correct": true, "explanation": "正确答案：国度（guó dù），指国家，多用于书面。"}, {"text": "国都", "is_correct": false, "explanation": "国都（guó dū）与国度（guó dù）的区别在于第二个音节声调：dū（第一声）与 dù（第四声），意思是首都。"}, {"text": "过度", "is_correct": false, "explanation": "过度（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是超过限度。"}, {"text": "过渡", "is_correct": false, "explanation": "过渡（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是事物之间的中间阶段。"}], "explanations": {"国度": "正确答案：国度（guó dù），指国家，多用于书面。", "国都": "国都（guó dū）与国度（guó dù）的区别在于第二个音节声调：dū（第一声）与 dù（第四声），意思是首都。", "过度": "过度（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是超过限度。", "过渡": "过渡（guò dù）与国度（guó dù）的区别在于第一个音节声调：guò（第四声）与 guó（第二声），意思是事物之间的中间阶段。"}, "sentence_index": null, "correct_answer": "国度"}, "level_3": {"options": [{"text": "国度", "is_correct": true, "explanation": "正确答案：“这是一个美丽的国度”指一个国家，与“国度”的意思一致。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是地方，不能用“美丽的”修饰。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验活动，不指地方，“美丽的考试”说不通。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“美丽”不能修饰疾病，“感冒”是病名，不能放在“美丽的”之后。"}], "explanations": {"国度": "正确答案：“这是一个美丽的国度”指一个国家，与“国度”的意思一致。", "作业": "语义：“作业”是学习任务，不是地方，不能用“美丽的”修饰。", "考试": "语义：“考试”是测验活动，不指地方，“美丽的考试”说不通。", "感冒": "搭配：“美丽”不能修饰疾病，“感冒”是病名，不能放在“美丽的”之后。"}, "sentence_index": 0, "correct_answer": "国度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国度的楼上有一家书店。", "explanation": "这里应该用〈楼〉。国度指整个国家，不能指一栋楼。"}, {"text": "这个国度的袜子湿了。", "explanation": "这是把“国度”当成衣物讲。国度指整个国家，不能指一件衣物。"}, {"text": "我家的国度有三间卧室。", "explanation": "这是把“国度”当成房屋讲。国度只指国家，不能指一套房子的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国度", "is_correct": true, "explanation": "正确答案：“这个国度的历史非常长”指一个国家的历史，与“国度”的意思一致。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有历史，“历史非常长”不能用来描述天气。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情没有历史，“历史非常长”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“历史”不与“身高”搭配，身高不能有历史。"}], "explanations": {"国度": "正确答案：“这个国度的历史非常长”指一个国家的历史，与“国度”的意思一致。", "天气": "语义：天气没有历史，“历史非常长”不能用来描述天气。", "心情": "语义：心情没有历史，“历史非常长”说不通。", "身高": "搭配：“历史”不与“身高”搭配，身高不能有历史。"}, "sentence_index": 6, "correct_answer": "国度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把书放在国度里，然后关上了抽屉。", "explanation": "这里应该用〈书包〉。国度指整个国家，不能指一个可以放东西、关起来的小容器。"}, {"text": "这辆汽车有五个国度。", "explanation": "这是把“国度”当成汽车的部件讲。国度只指国家，不能指车的组成部分。"}, {"text": "他的左手上有一个国度。", "explanation": "这是把“国度”当成身体部位讲。国度指整个国家，不能指手上的某个位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只国度的首都很漂亮。", "corrected_sentence": "那个国度的首都很漂亮。", "error_description": "“国度”前应该用量词“个”，不能用“只”。“只”用于动物、成对的东西等，国度是国家，应说“那个国度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多国度们的人都来这里学习。", "corrected_sentence": "很多国度的人都来这里学习。", "error_description": "“国度”后面不能加“们”。“们”只用于人或有生命的群体，应说“很多国度的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe85e85b-b923-4d72-872e-bb5531d5b0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：「公共」指属于大家，与之相对的是「私人」，指属于个人。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：「美丽」形容外貌好看，与「公共」没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：「寒冷」形容温度，与「公共」不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：「聪明」形容智力，与「公共」不构成反义。"}], "correct_answer": "私人", "explanations": {"私人": "反义：「公共」指属于大家，与之相对的是「私人」，指属于个人。", "美丽": "无关：「美丽」形容外貌好看，与「公共」没有反义关系。", "寒冷": "无关：「寒冷」形容温度，与「公共」不构成反义。", "聪明": "无关：「聪明」形容智力，与「公共」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：「公共」指属于大家，与之相对的是「私人」，指属于个人。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：「高兴」形容心情愉快，与「公共」没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "无关：「干燥」形容水分少，与「公共」不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：「勇敢」形容性格，与「公共」不构成反义。"}], "correct_answer": "私人", "explanations": {"私人": "反义：「公共」指属于大家，与之相对的是「私人」，指属于个人。", "高兴": "无关：「高兴」形容心情愉快，与「公共」没有反义关系。", "干燥": "无关：「干燥」形容水分少，与「公共」不构成反义。", "勇敢": "无关：「勇敢」形容性格，与「公共」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "公共是说大家都可以用,不是只给一个人的。", "primary_collocate": null, "pronunciation": "gōng gòng", "ipa": "kʊŋ˥ kʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个公园是公共的，谁都可以进去。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共电话在楼下，大家都能用。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的公共椅子可以随便坐。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把公共的东西带回家。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有一个公共厕所。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑是公共的，不是我一个人的。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书是公共的，要爱护它们。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公共地方，请小声说话。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共自行车很方便，一小时只要一块钱。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公共的杯子洗干净了。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共汽车", "label": "复合"}, {"form": "公共场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家都可以使用、不属于某一个人的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "正确：「公共」指大家都可以使用，与「谁都可以进去」相符。"}, {"text": "私有", "is_correct": false, "explanation": "语义：「私有」指属于个人，与「谁都可以进去」矛盾。"}, {"text": "封闭", "is_correct": false, "explanation": "语义：「封闭」指不对外开放，与「谁都可以进去」矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：「高」形容高度，不能用来说明公园的性质。"}], "explanations": {"公共": "正确：「公共」指大家都可以使用，与「谁都可以进去」相符。", "私有": "语义：「私有」指属于个人，与「谁都可以进去」矛盾。", "封闭": "语义：「封闭」指不对外开放，与「谁都可以进去」矛盾。", "高": "体貌：「高」形容高度，不能用来说明公园的性质。"}, "sentence_index": 0, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们是公共的朋友。", "explanation": "这里应该用〈共同〉。「公共」指属于社会或大家使用的事物，不用来说人与人之间共有的关系。"}, {"text": "他做事很公共。", "explanation": "这里应该用〈公正〉。「公共」表示属于大家，不表示做事是否公平。"}, {"text": "这场比赛很公共。", "explanation": "这里应该用〈公平〉。「公共」不用来评价比赛是否公平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "正确：「公共」指大家共用，与「图书馆的书」相符，也与「要爱护它们」相合。"}, {"text": "个人", "is_correct": false, "explanation": "语义：「个人」指属于某一个人，与「图书馆的书」矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：「透明」形容外观可以看穿，不能用来说明书的归属。"}, {"text": "私人", "is_correct": false, "explanation": "语义：「私人」指属于个人，图书馆的书属于公共机构，与句意矛盾。"}], "explanations": {"公共": "正确：「公共」指大家共用，与「图书馆的书」相符，也与「要爱护它们」相合。", "个人": "语义：「个人」指属于某一个人，与「图书馆的书」矛盾。", "透明": "体貌：「透明」形容外观可以看穿，不能用来说明书的归属。", "私人": "语义：「私人」指属于个人，图书馆的书属于公共机构，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格很公共。", "explanation": "这里应该用〈公道〉。「公共」指属于大家使用的，不用来说价格是否合理。"}, {"text": "这份评价很公共。", "explanation": "这里应该用〈公允〉。「公共」不用来说评价是否客观，只表示属于大家。"}, {"text": "这是我的公共电话，别随便打。", "explanation": "这里应该用〈私人〉。电话是我个人的，应说「私人电话」；「公共」指大家都能用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个公园是公共了，大家都能去。", "corrected_sentence": "那个公园是公共的，大家都能去。", "error_description": "错误：“是公共了”；正确：“是公共的”。说明事物性质用“是……的”，“公共”后面应该用“的”，不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子是公共，谁都可以坐。", "corrected_sentence": "这把椅子是公共的，谁都可以坐。", "error_description": "「是公共的」中的「的」不能省。写成「是公共」语法不完整，应改为「是公共的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：「公共」指属于社会、大家共享，与之相对的是「私人」。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：「漂亮」形容外貌好看，与「公共」没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "无关：「干燥」形容水分少，与「公共」不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：「勇敢」形容性格，与「公共」不构成反义。"}], "correct_answer": "私人", "explanations": {"私人": "反义：「公共」指属于社会、大家共享，与之相对的是「私人」。", "漂亮": "无关：「漂亮」形容外貌好看，与「公共」没有反义关系。", "干燥": "无关：「干燥」形容水分少，与「公共」不构成反义。", "勇敢": "无关：「勇敢」形容性格，与「公共」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
