INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属于社会的、大家共同使用或享有的。", "primary_collocate": null, "pronunciation": "gōng gòng", "ipa": "kʊŋ˥ kʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "城市里的公共设施越来越多了。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护公共环境是每个人的事。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和空气都是公共资源。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共交通让上班的人少花了很多钱。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该爱护公共财产。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给这个小区修了新的公共花园。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共图书馆对所有人免费开放。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公共场合大声说话，让人不舒服。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共卫生对大家的健康很重要。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有很多公共游泳池。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共汽车", "label": "复合"}, {"form": "公共场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "属于社会、由大家共同使用或享有的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4d28e6-7979-4651-8cd9-9569e5fdfab4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "正确：「公共」指属于社会、大家共同享有的，与「城市里的设施」相符。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「高」形容高度，不说「高设施」，也不表示设施属于大家共同使用。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：设施不会有聪明与否，「聪明」与句意不符。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：「寒冷」形容温度，不能用来修饰设施。"}], "explanations": {"公共": "正确：「公共」指属于社会、大家共同享有的，与「城市里的设施」相符。", "高": "搭配：「高」形容高度，不说「高设施」，也不表示设施属于大家共同使用。", "聪明": "语义：设施不会有聪明与否，「聪明」与句意不符。", "寒冷": "语义：「寒冷」形容温度，不能用来修饰设施。"}, "sentence_index": 0, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们有一个公共的爱好。", "explanation": "这里应该用〈共同〉。「公共」指属于社会、大家可用的，不用来说人之间的共同兴趣。"}, {"text": "裁判做事很公共。", "explanation": "这里应该用〈公正〉。「公共」表示属于社会，不表示裁判是否公平。"}, {"text": "分配的方法很公共。", "explanation": "这里应该用〈公平〉。「公共」不用来评价分配是否公平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "正确：「公共图书馆」指向社会开放的图书馆，与「对所有人免费开放」相符。"}, {"text": "封闭", "is_correct": false, "explanation": "语义：「封闭」指不对外开放，与「对所有人免费开放」矛盾。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：「秘密」指不公开，与「对所有人免费开放」矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：「透明」形容能看穿的外观，「透明图书馆」不自然，也与免费开放无关。"}], "explanations": {"公共": "正确：「公共图书馆」指向社会开放的图书馆，与「对所有人免费开放」相符。", "封闭": "语义：「封闭」指不对外开放，与「对所有人免费开放」矛盾。", "秘密": "语义：「秘密」指不公开，与「对所有人免费开放」矛盾。", "透明": "搭配：「透明」形容能看穿的外观，「透明图书馆」不自然，也与免费开放无关。"}, "sentence_index": 6, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一个公共游泳池。", "explanation": "这里应该用〈私人〉。游泳池属于自家，应说「私人游泳池」，「公共」指大家共用。"}, {"text": "这是他公共的兴趣。", "explanation": "这里应该用〈个人〉。兴趣属于个人，不是大家共用的，应说「个人的兴趣」。"}, {"text": "这次的收费很公共。", "explanation": "这里应该用〈公道〉。「公共」不表示收费是否合理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都应该保护公共了财产。", "corrected_sentence": "每个人都应该保护公共财产。", "error_description": "错误：「公共了财产」；正确：「公共财产」。「了」是动态助词，不能附在定语「公共」与名词「财产」之间，应删去「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游泳池是公共，谁都能去。", "corrected_sentence": "这个游泳池是公共的，谁都能去。", "error_description": "「是公共的」中的「的」不能省。写成「是公共」语法不完整，应改为「是公共的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f460b798-3109-4386-aff8-0ca32633218a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
