INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88455, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "可见是从前面说的事，能看出后面的结果。", "primary_collocate": null, "pronunciation": "kě jiàn", "ipa": "kʰɤ˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他一直在加班，可见工作很忙。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上没有人，可见天气太冷。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她读了三遍，可见她很喜欢这本书。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服都湿了，可见雨下得很大。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说没事，可见他不生气。", "target_word": "可见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在看他，可见他很有名。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户开着，可见有人来过。", "target_word": "可见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次考试都第一，可见他很聪明。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书卖了十万本，可见很受欢迎。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她天天早起跑步，可见很爱运动。", "target_word": "可见", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可見", "label": "繁体"}], "register": "中性", "sense_fingerprint": "连词：从前面的事看出后面的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d06d0e-067c-4c11-97ae-a74e588d261c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可见", "is_correct": true, "explanation": "“可见”由“一直在加班”推出“工作很忙”的结论，语境相符。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不然会怎样，前面要是负面假设，与“加班”的推断不符。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与后面的“但/还是”呼应，句中没有，不能这样用。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与后面的“就”呼应，句中没有“就”。"}], "explanations": {"可见": "“可见”由“一直在加班”推出“工作很忙”的结论，语境相符。", "否则": "语义：“否则”表示不然会怎样，前面要是负面假设，与“加班”的推断不符。", "尽管": "搭配：“尽管”要与后面的“但/还是”呼应，句中没有，不能这样用。", "只要": "搭配：“只要”要与后面的“就”呼应，句中没有“就”。"}, "sentence_index": 0, "correct_answer": "可见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "假如明天放假，可见我们就不去上班了。", "explanation": "这里应该用〈那么〉。“可见”只能根据已知事实推断结论，不能引出假设条件下的结果；“假如……”后的结果应用“那么”。"}, {"text": "尽管天气很冷，可见他还是穿得很少。", "explanation": "这里应该用〈但是〉。“可见”不能表示转折；“尽管天气很冷”后面要用“但是/可是”引出相反的情况。"}, {"text": "我可见他在做作业。", "explanation": "这里的“可见”作动词只表示“能看到”（如“可见的范围”），不能带小句表示“看见”，应说〈看见〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可见", "is_correct": true, "explanation": "“可见”由“窗户开着”推断出“有人来过”，语境相符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后面的“但/却”呼应，句中没有，不能这样用。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”后面要用“都/也”呼应，句中没有，不能这样用。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示因好处而避免坏结果，与“窗户开着”的推断不符。"}], "explanations": {"可见": "“可见”由“窗户开着”推断出“有人来过”，语境相符。", "虽然": "搭配：“虽然”要与后面的“但/却”呼应，句中没有，不能这样用。", "无论": "搭配：“无论”后面要用“都/也”呼应，句中没有，不能这样用。", "幸亏": "语义：“幸亏”表示因好处而避免坏结果，与“窗户开着”的推断不符。"}, "sentence_index": 6, "correct_answer": "可见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听见敲门，可见去开了门。", "explanation": "这里应该用〈于是〉。“可见”引出推断的结论，不能表示动作的先后承接，应用“于是”。"}, {"text": "他很努力，可见成绩不好。", "explanation": "这里应该用〈然而〉。“可见”只能引出由前文推出的结论，不能表示转折，“很努力”与“成绩不好”是转折关系。"}, {"text": "他先去超市，可见买完了菜。", "explanation": "这里应该用〈然后〉。“可见”引出推断出的结论，不能表示先后承接；“去超市”之后“买菜”应用“然后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直在看书，可见了他很用功。", "corrected_sentence": "他一直在看书，可见他很用功。", "error_description": "“可见”是连词，不带体标“了”，应说“可见他很用功”，不能在“可见”后加“了”说“可见了他很用功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口放着一双鞋，可见了他已经到了。", "corrected_sentence": "门口放着一双鞋，可见他已经到了。", "error_description": "“可见”是连词，不带体标“了”，应说“可见他已经到了”，不能在“可见”后加“了”说“可见了他已经到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
