INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88459, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "去年是上一年。", "primary_collocate": null, "pronunciation": "qù nián", "ipa": "tɕʰy˥˩ ni̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "去年冬天我在北京住了三个月。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年夏天很热。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我是去年来中国的。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年我们去过上海。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去年还不会说汉语。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年的今天，我第一次见到她。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年冬天下了很多雪。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸去年买了一辆新车。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的东西比去年贵。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年的这个时候，我们还在上课。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "去年：名词（时间词），上一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88459, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去年", "is_correct": true, "explanation": "“去年”指上一年，与句中“去年冬天”的过去经历相符。"}, {"text": "前天", "is_correct": false, "explanation": "搭配：“前天”指具体的某一天，不能与季节“冬天”一起作时间状语，句意不通。"}, {"text": "明年", "is_correct": false, "explanation": "体貌：“明年”指将来，与表示已完成的“住了”冲突。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”指一天中的时段，不能与“冬天”这个季节组合，句意不通。"}], "explanations": {"去年": "“去年”指上一年，与句中“去年冬天”的过去经历相符。", "前天": "搭配：“前天”指具体的某一天，不能与季节“冬天”一起作时间状语，句意不通。", "明年": "体貌：“明年”指将来，与表示已完成的“住了”冲突。", "上午": "搭配：“上午”指一天中的时段，不能与“冬天”这个季节组合，句意不通。"}, "sentence_index": 0, "correct_answer": "去年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年这个时候我们都会去海边。", "explanation": "这里应该用〈往年〉。“去年”只指上一年这一个具体时间，“都会”表示多年反复的习惯，要用“往年”。"}, {"text": "去年这里年年都下雪。", "explanation": "这里应该用〈每年〉。“去年”只指一个年份，与“年年”表示的多年重复相矛盾，要用“每年”。"}, {"text": "去年我们会去上海工作。", "explanation": "这里应该用〈将来〉。“去年”指已经过去的时间，不能和表示将要发生的“会”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88459, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去年", "is_correct": true, "explanation": "“去年”指上一年，与“下了很多雪”的过去叙述相符。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：“今天”指当天，不能与整个季节“冬天”组合，句意不通。"}, {"text": "后天", "is_correct": false, "explanation": "体貌：“后天”指将来，与表示已完成的“了”（下了）冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“昨天”指某一天，不能与整个季节“冬天”组合，句意不通。"}], "explanations": {"去年": "“去年”指上一年，与“下了很多雪”的过去叙述相符。", "今天": "搭配：“今天”指当天，不能与整个季节“冬天”组合，句意不通。", "后天": "体貌：“后天”指将来，与表示已完成的“了”（下了）冲突。", "昨天": "搭配：“昨天”指某一天，不能与整个季节“冬天”组合，句意不通。"}, "sentence_index": 6, "correct_answer": "去年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年这里都会下大雪。", "explanation": "这里应该用〈历年〉。“去年”只指一个年份，“都会”表示多年的规律，要用“历年”。"}, {"text": "去年的这个时候，我们将会去北京。", "explanation": "这里应该用〈明年〉。“去年”指已经过去的一年，不能和表示将来的“将会”搭配。"}, {"text": "那件事是去年发生的，已经是两年前的事了。", "explanation": "这里应该用〈前年〉。“去年”指上一年，而句中说的是两年前的事，要用“前年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88459, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年的在北京住了三个月。", "corrected_sentence": "我去年在北京住了三个月。", "error_description": "错误：时间词「去年」后面不加「的」，它应直接放在主语「我」之后。错误形式是「我去年的在北京住了三个月」，正确形式是「我去年在北京住了三个月」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88459, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年冬天我们会第一次看到雪。", "corrected_sentence": "去年冬天我们第一次看到雪。", "error_description": "错误：“去年”指已经过去的时间，不能与表示将要发生的“会”搭配。错误形式是「去年冬天我们会第一次看到雪」，正确形式是「去年冬天我们第一次看到雪」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
