INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88460, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今年的前一年。", "primary_collocate": null, "pronunciation": "qù nián", "ipa": "tɕʰy˥˩ ni̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "今年比去年冷。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年我二十岁，去年我十九岁。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年的书我还留着。", "target_word": "去年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的雨比去年多得多。", "target_word": "去年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年我们班有三十个学生，今年有三十五个。", "target_word": "去年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年考上了大学，去年还在高中。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年的衣服今年穿太小了。", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去年住在哪儿，今年还住那儿吗？", "target_word": "去年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年我只会写一百个字，现在会写很多了。", "target_word": "去年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天他来过这里，今年没有来。", "target_word": "去年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "去年：名词（时间词），今年的前一年，常与今年对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去年", "is_correct": true, "explanation": "“去年”是“今年”的前一年，与“今年比去年冷”的对比相符。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指下一年，尚未到来，无法与今年已经发生的冷暖相比较。"}, {"text": "前天", "is_correct": false, "explanation": "搭配：“前天”指一天，不能与“今年”这样的年份作比较对象。"}, {"text": "上午", "is_correct": false, "explanation": "搭配：“上午”指一天中的时段，不能与“今年”比较冷暖。"}], "explanations": {"去年": "“去年”是“今年”的前一年，与“今年比去年冷”的对比相符。", "明年": "语义：“明年”指下一年，尚未到来，无法与今年已经发生的冷暖相比较。", "前天": "搭配：“前天”指一天，不能与“今年”这样的年份作比较对象。", "上午": "搭配：“上午”指一天中的时段，不能与“今年”比较冷暖。"}, "sentence_index": 0, "correct_answer": "去年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年的雨会比今年多得多。", "explanation": "这里应该用〈明年〉。“去年”指已经过去的时间，不能和表示将要发生的“会”搭配。"}, {"text": "去年的雨每年都比今年多。", "explanation": "这里应该用〈往年〉。“去年”只指一个年份，与“每年都”表示的多年规律相冲突，要用“往年”。"}, {"text": "我们是去年认识的，那已经是两年前的事了。", "explanation": "这里应该用〈前年〉。“去年”指今年的前一年，而句中说的是两年前的事，要用“前年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去年", "is_correct": true, "explanation": "“去年”是今年的前一年，去年买的衣服今年穿太小了，前后对比相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的一天，与“今年穿太小了”说的已发生情况冲突，句意不通。"}, {"text": "今天", "is_correct": false, "explanation": "搭配：“今天”指一天，不能与“今年”一起限定同一件衣服的时间，搭配不当。"}, {"text": "每天", "is_correct": false, "explanation": "语义：“每天”表示反复发生，与“今年穿太小了”指具体某一年的情况不符。"}], "explanations": {"去年": "“去年”是今年的前一年，去年买的衣服今年穿太小了，前后对比相符。", "明天": "语义：“明天”指将来的一天，与“今年穿太小了”说的已发生情况冲突，句意不通。", "今天": "搭配：“今天”指一天，不能与“今年”一起限定同一件衣服的时间，搭配不当。", "每天": "语义：“每天”表示反复发生，与“今年穿太小了”指具体某一年的情况不符。"}, "sentence_index": 6, "correct_answer": "去年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年夏天他要来这里，今年没有来。", "explanation": "这里应该用〈明年〉。“去年”指已经过去的一年，不能与表示将要发生的“要”搭配。"}, {"text": "去年夏天他历年都来这里，今年没有来。", "explanation": "这里不能用〈去年〉，应改为〈往年〉。“去年夏天”只指一个夏天，与“历年都来”表示的多年习惯相冲突。"}, {"text": "去年夏天他年年来这里，今年没有来。", "explanation": "这里应该用〈每年〉。“去年夏天”只指一个夏天，不能与“年年”的多年重复并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年冬天比去年多冷了。", "corrected_sentence": "今年冬天比去年冷多了。", "error_description": "“比”字句中，形容词后应用“冷多了”表示程度差别。错误形式是「比去年多冷了」，正确形式是「比去年冷多了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年夏天的来过这里。", "corrected_sentence": "他去年夏天来过这里。", "error_description": "错误：时间词「去年夏天」后面不加「的」，应直接接动词「来过」。错误形式是「他去年夏天的来过这里」，正确形式是「他去年夏天来过这里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
