INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88461, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃饭是把饭和菜放进嘴里吃下去。", "primary_collocate": null, "pronunciation": "chī fàn", "ipa": "ʈʂʰɨ˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "孩子自己吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他吃饭的时候不说话。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷牙不好，吃饭很慢。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟吃饭时喜欢看电视。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她拿着筷子吃饭。", "target_word": "吃饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，不想吃饭。", "target_word": "吃饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明吃饭太快，肚子疼了。", "target_word": "吃饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭前要先洗手。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我用勺子吃饭，不用筷子。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈说，吃饭不要看手机。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃过饭", "label": "体标形式"}, {"form": "吃着饭", "label": "体标形式"}], "register": "口语", "sense_fingerprint": "动词：吃饭，强调把饭菜送进嘴里吃下去的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '314b788a-db43-4be2-9cd0-4c586b32fd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃饭", "is_correct": true, "explanation": "正确：“吃饭”指孩子自己进食，与句意相合。"}, {"text": "喝酒", "is_correct": false, "explanation": "语义：孩子不宜饮酒，“孩子自己喝酒”与“孩子”的身份冲突，句子不通。"}, {"text": "上班", "is_correct": false, "explanation": "语义：上班是成年人的事，与“孩子”冲突，句子不通。"}, {"text": "开车", "is_correct": false, "explanation": "语义：孩子不能自己开车，“孩子自己开车”与语境冲突，句子不通。"}], "explanations": {"吃饭": "正确：“吃饭”指孩子自己进食，与句意相合。", "喝酒": "语义：孩子不宜饮酒，“孩子自己喝酒”与“孩子”的身份冲突，句子不通。", "上班": "语义：上班是成年人的事，与“孩子”冲突，句子不通。", "开车": "语义：孩子不能自己开车，“孩子自己开车”与语境冲突，句子不通。"}, "sentence_index": 0, "correct_answer": "吃饭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子渴了，要吃饭。", "explanation": "这里应该用〈喝水〉。喝水指饮用液体解渴；吃饭指吃正餐，不用来解渴。"}, {"text": "我太困了，想早点吃饭。", "explanation": "这里应该用〈睡觉〉。困了应当睡觉；吃饭是进食，不能解困。"}, {"text": "他每天早上吃饭一杯牛奶。", "explanation": "这里应该用〈喝〉。牛奶是饮料，要说“喝一杯牛奶”；“吃饭”不能带“牛奶”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃饭", "is_correct": true, "explanation": "正确：“吃饭”与“肚子疼”构成因果，句意合理。"}, {"text": "读书", "is_correct": false, "explanation": "语义：读书太快与肚子疼没有因果关系，句子不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌太快与肚子疼没有因果关系，句子不通。"}, {"text": "关心", "is_correct": false, "explanation": "配价：“关心”要带宾语，“小明关心太快”说不完整。"}], "explanations": {"吃饭": "正确：“吃饭”与“肚子疼”构成因果，句意合理。", "读书": "语义：读书太快与肚子疼没有因果关系，句子不通。", "唱歌": "语义：唱歌太快与肚子疼没有因果关系，句子不通。", "关心": "配价：“关心”要带宾语，“小明关心太快”说不完整。"}, "sentence_index": 6, "correct_answer": "吃饭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渴了，想去吃饭。", "explanation": "这里应该用〈喝水〉。渴了应当喝水；吃饭是吃正餐，不用来解渴。"}, {"text": "他一听这话就吃饭了，醋意十足。", "explanation": "这里应该用〈吃醋〉。吃醋指因嫉妒而心生不快；吃饭是进食，不表示嫉妒。"}, {"text": "饭馆一吃饭，客人就动筷子了。", "explanation": "这里应该用〈上菜〉。上菜指把菜端上桌，饭馆不会吃饭，“吃饭”的主语必须是进食的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃饭得很快。", "corrected_sentence": "他吃饭吃得很快。", "error_description": "错误：“吃饭得很快”。正确：“吃饭吃得很快”。“吃饭”是离合词，补语“得”要接在动词“吃”之后，所以需要重复“吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟吃饭吃很快。", "corrected_sentence": "我弟弟吃饭吃得很快。", "error_description": "错误：“吃饭吃很快”。正确：“吃饭吃得很快”。表示程度的补语前必须加“得”，不能直接接形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
