INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88463, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在我看是说出自己的想法时先说的话。", "primary_collocate": null, "pronunciation": "zài wǒ kàn", "ipa": "t͡saɪ̯⁵¹ wɔ²¹⁴ kʰan⁵¹", "syllable_count": 3, "sentences": [{"text": "在我看，孩子应该多出去玩。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我怎么办，我说：“在我看，先休息吧。”", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我看，那家饭店的菜太咸了。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们都同意吗？在我看，这样不太好。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我看，这件衣服太贵了。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我看，多读书比多玩手机好。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我看，老师今天有点儿累。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我看，这个问题不是钱的问题。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说得很好，不过在我看，还可以更简单。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我看，周末去公园比在家好。", "target_word": "在我看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "开场语：说出自己想法时先说的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在我看", "is_correct": true, "explanation": "在我看用在句首，引出说话人的想法，与“孩子应该多出去玩”的建议相符。"}, {"text": "据悉", "is_correct": false, "explanation": "语域：据悉是书面报道用语，用在家常建议前很不自然。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：顺便表示顺带做事，与这句的建议语气不符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：白白表示徒然，与“孩子应该多出去玩”的建议不协调。"}], "explanations": {"在我看": "在我看用在句首，引出说话人的想法，与“孩子应该多出去玩”的建议相符。", "据悉": "语域：据悉是书面报道用语，用在家常建议前很不自然。", "顺便": "语义：顺便表示顺带做事，与这句的建议语气不符。", "白白": "语义：白白表示徒然，与“孩子应该多出去玩”的建议不协调。"}, "sentence_index": 0, "correct_answer": "在我看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在我看，我家有三口人。", "explanation": "这里不能用〈在我看〉。它是开场语，用来引出说话人自己的想法；家里有几口人是客观情况，不需要这样引出。"}, {"text": "在我看，今天是星期五。", "explanation": "星期几是客观事实，不需要用“在我看”引出个人想法。"}, {"text": "在我看，这本书有三百页。", "explanation": "页数是客观事实，用“在我看”把事实说成个人想法，不符合这个词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在我看", "is_correct": true, "explanation": "在我看用在句首，引出说话人的想法，与“老师今天有点儿累”的判断相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：竟然表示出乎意料，与“老师有点儿累”这种平常判断不符。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：偏偏表示与预期相反，与这句的平常判断不协调。"}, {"text": "不料", "is_correct": false, "explanation": "语域：不料是叙述性书面语，用在口语开场语位置不自然。"}], "explanations": {"在我看": "在我看用在句首，引出说话人的想法，与“老师今天有点儿累”的判断相符。", "竟然": "语义：竟然表示出乎意料，与“老师有点儿累”这种平常判断不符。", "偏偏": "语义：偏偏表示与预期相反，与这句的平常判断不协调。", "不料": "语域：不料是叙述性书面语，用在口语开场语位置不自然。"}, "sentence_index": 6, "correct_answer": "在我看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在我看，这个月有三十一天。", "explanation": "这里不能用〈在我看〉。它是开场语，用来引出说话人自己的想法；一个月有几天是客观事实，不能这样引出。"}, {"text": "在我看，我今年三十岁。", "explanation": "年龄是个人的客观情况，不需要用“在我看”引出想法，这样用是不当的。"}, {"text": "在我看，地球围绕太阳转。", "explanation": "地球围绕太阳转是客观事实，用“在我看”把事实说成个人想法，不符合这个词的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在我看了，他今天不会来了。", "corrected_sentence": "在我看，他今天不会来了。", "error_description": "“在我看”是固定开场语，后面不能加“了”，应说“在我看，……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在我看见，这件事情应该早点儿说。", "corrected_sentence": "在我看，这件事情应该早点儿说。", "error_description": "“在我看”是固定开场语，“看”后不能加“见”，应说“在我看，……”，不说“在我看见，……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
