INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88465, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总统选举是大家投票，选出国家的领头人。", "primary_collocate": null, "pronunciation": "zǒng tǒng xuǎn jǔ", "ipa": "tsʊŋ˨˩ tʰʊŋ˨˩ ɕɥɛn˨˩ tɕy˨˩", "syllable_count": 4, "sentences": [{"text": "这个国家每四年有一次总统选举。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选举那天，很多人去投票。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对总统选举很感兴趣。", "target_word": "总统选举", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视上正在报道总统选举的结果。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选举让人民选出自己的领导人。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的总统选举有三个人参加。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选举前，每个人都在讨论谁会赢。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在国外看了一次总统选举。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次总统选举，年轻人也来投票了。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选举结束后，新总统发表了讲话。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "總統選舉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家投票选出国家领头人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119ba6ca-7230-41f9-9941-35fce59bfea3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总统选举", "is_correct": true, "explanation": "“总统选举”是可以举行的选举活动，能与“每四年有一次”搭配。"}, {"text": "议会", "is_correct": false, "explanation": "语义：“议会”是机构，不是能“每四年有一次”发生的事件。"}, {"text": "选票", "is_correct": false, "explanation": "语义：“选票”是纸张，不能作为“每四年有一次”的事件。"}, {"text": "宪法", "is_correct": false, "explanation": "搭配：“有一次”计数的是事件，“宪法”一般说“修订”，不能说“有一次宪法”。"}], "explanations": {"总统选举": "“总统选举”是可以举行的选举活动，能与“每四年有一次”搭配。", "议会": "语义：“议会”是机构，不是能“每四年有一次”发生的事件。", "选票": "语义：“选票”是纸张，不能作为“每四年有一次”的事件。", "宪法": "搭配：“有一次”计数的是事件，“宪法”一般说“修订”，不能说“有一次宪法”。"}, "sentence_index": 0, "correct_answer": "总统选举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家今年有一台总统选举。", "explanation": "量词错误：“台”用于机器、节目等，不用于选举活动；这里应该用〈次〉或〈场〉。"}, {"text": "他把总统选举放进了冰箱。", "explanation": "语义：“总统选举”是一项活动，不是能放进冰箱的物品。"}, {"text": "我昨天吃了一碗总统选举。", "explanation": "语义：“吃”的宾语应是食物，“总统选举”是一项活动，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总统选举", "is_correct": true, "explanation": "“总统选举”是一项选举活动，可以放在“前”之前，且与“谁会赢”相符。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：“冠军”是称号，不是可以放在“前”之前讨论的事件。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“地震”是自然灾害，与“讨论谁会赢”不相关。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“谁会赢”一般搭配比赛、选举等有胜负的事，“考试”不说“谁会赢”。"}], "explanations": {"总统选举": "“总统选举”是一项选举活动，可以放在“前”之前，且与“谁会赢”相符。", "冠军": "语义：“冠军”是称号，不是可以放在“前”之前讨论的事件。", "地震": "语义：“地震”是自然灾害，与“讨论谁会赢”不相关。", "考试": "搭配：“谁会赢”一般搭配比赛、选举等有胜负的事，“考试”不说“谁会赢”。"}, "sentence_index": 6, "correct_answer": "总统选举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们给总统选举量了身高。", "explanation": "语义：“量身高”的对象应是人，“总统选举”是活动，不能量身高。"}, {"text": "他是一位很好的总统选举。", "explanation": "语义：“总统选举”是活动，不是人，不能用“一位”或“很好的”修饰指人。"}, {"text": "总统选举跑到超市买了菜。", "explanation": "语义：“总统选举”是活动，不能主动去超市买菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台总统选举的投票率很高。", "corrected_sentence": "这次总统选举的投票率很高。", "error_description": "量词错误：“台”用于机器、节目等，不能修饰选举活动；修饰“总统选举”应用“次”，正确形式为“这次总统选举”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把总统选举的结果很快就出来了。", "corrected_sentence": "这次总统选举的结果很快就出来了。", "error_description": "量词错误：“把”多用于有柄的器物，不能修饰选举活动；修饰“总统选举”应用“次”，正确形式为“这次总统选举”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
