INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "选民投票选出国家总统的活动。", "primary_collocate": null, "pronunciation": "zǒng tǒng xuǎn jǔ", "ipa": "tsʊŋ˨˩ tʰʊŋ˨˩ ɕɥɛn˨˩ tɕy˨˩", "syllable_count": 4, "sentences": [{"text": "总统选举的投票站早上八点开门。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选民们排队参加总统选举。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场总统选举很热闹，大家都很关心。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了总统选举是怎么进行的。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国的总统选举在十一月举行。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次参加总统选举，心里有点紧张。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选举的结果明天早上才会公布。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里也举办了一场模拟总统选举。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了总统选举，候选人到处发表演讲。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统选举期间，街上有很多海报。", "target_word": "总统选举", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "總統選舉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "选民投票选出国家总统的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119ba6ca-7230-41f9-9941-35fce59bfea3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总统选举", "is_correct": true, "explanation": "“总统选举”的投票站是为选举设立的场所，“总统选举的投票站”说得通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：投票站是为选举设立的场所，“冰箱”与之没有关系，“冰箱的投票站”说不通。"}, {"text": "选票", "is_correct": false, "explanation": "搭配：“选票”不能用来修饰“投票站”，两者不搭配。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：投票站是为选举设立的场所，“冠军”与之没有关系。"}], "explanations": {"总统选举": "“总统选举”的投票站是为选举设立的场所，“总统选举的投票站”说得通。", "冰箱": "语义：投票站是为选举设立的场所，“冰箱”与之没有关系，“冰箱的投票站”说不通。", "选票": "搭配：“选票”不能用来修饰“投票站”，两者不搭配。", "冠军": "语义：投票站是为选举设立的场所，“冠军”与之没有关系。"}, "sentence_index": 0, "correct_answer": "总统选举"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家有一座总统选举。", "explanation": "量词错误：“座”用于建筑、山等，不用于选举活动；这里应该用〈次〉或〈场〉。"}, {"text": "他把总统选举借给了朋友。", "explanation": "语义：“总统选举”是活动，不是能借给别人的物品。"}, {"text": "总统选举生病了，躺在床上。", "explanation": "语义：“总统选举”是活动，不能像人一样生病、躺在床上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总统选举", "is_correct": true, "explanation": "“总统选举”是有结果可以公布的活动，与“结果明天早上才会公布”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是有结果需要公布的活动，与“明天早上公布”说不通。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”没有需要公布的结果，与“明天早上才会公布”不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“结果”可以说“选举的结果”“考试的结果”，不能说“冰箱的结果”。"}], "explanations": {"总统选举": "“总统选举”是有结果可以公布的活动，与“结果明天早上才会公布”相符。", "天气": "语义：“天气”不是有结果需要公布的活动，与“明天早上公布”说不通。", "菜谱": "语义：“菜谱”没有需要公布的结果，与“明天早上才会公布”不符。", "冰箱": "搭配：“结果”可以说“选举的结果”“考试的结果”，不能说“冰箱的结果”。"}, "sentence_index": 6, "correct_answer": "总统选举"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位很好的总统选举。", "explanation": "语义：“总统选举”是活动，不是人，不能用“一位”或“很好的”修饰指人。"}, {"text": "他把总统选举当成午饭吃了。", "explanation": "语义：“吃”的宾语应是食物，“总统选举”是活动，不能当午饭吃。"}, {"text": "他每天早上都给总统选举浇水。", "explanation": "语义：“浇水”的对象应是植物，“总统选举”是活动，不能浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "总统选举结束着，街上的海报也撤掉了。", "corrected_sentence": "总统选举结束了，街上的海报也撤掉了。", "error_description": "体貌错误：“结束”表示动作已完成，应用“了”，不能用“着”。正确形式为“总统选举结束了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台总统选举的候选人很多，大家都很关心。", "corrected_sentence": "这场总统选举的候选人很多，大家都很关心。", "error_description": "量词错误：“台”用于机器、节目等，不能修饰选举活动；修饰“总统选举”应用“场”，正确形式为“这场总统选举”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
