INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "撤销原定的事项或规定,使其不再有效。", "primary_collocate": null, "pronunciation": "qǔ xiāo", "ipa": "tɕʰy˨˩ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "因为下大雨，今天的比赛取消了。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校取消了周末的考试。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司取消了那个旧规定。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他取消了明天去北京的机票。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把今天的会议取消了。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店取消了我们的预订。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航班取消了，我们只好回家。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他取消过一次约会。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理取消了所有人的假期。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为什么取消这个活动？", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取消了", "label": "体标"}, {"form": "取消过", "label": "体标"}], "register": "中性", "sense_fingerprint": "撤销原定的安排或规定，使其失效", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e1ab4a-5687-4830-8ee0-0311191f4520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取消", "is_correct": true, "explanation": "正确。下大雨导致比赛无法举行，所以用“取消”，表示撤销原定的比赛。"}, {"text": "开始", "is_correct": false, "explanation": "语义：比赛“开始”与“因为下大雨”没有因果联系，句意矛盾。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的主语要是人或团体，“比赛”不能作“参加”的主语。"}, {"text": "取得", "is_correct": false, "explanation": "配价：“取得”后要带成绩、成果等宾语，“取得了”没有宾语，句子不完整。"}], "explanations": {"取消": "正确。下大雨导致比赛无法举行，所以用“取消”，表示撤销原定的比赛。", "开始": "语义：比赛“开始”与“因为下大雨”没有因果联系，句意矛盾。", "参加": "搭配：“参加”的主语要是人或团体，“比赛”不能作“参加”的主语。", "取得": "配价：“取得”后要带成绩、成果等宾语，“取得了”没有宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "取消"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他取消了吸烟的习惯。", "explanation": "这里应该用〈戒掉〉。取消用于已定的安排或规定，戒除习惯要说戒掉。"}, {"text": "他取消了刚才说的那句话。", "explanation": "这里应该用〈收回〉。取消的对象是安排或规定，已经说出口的话要说收回。"}, {"text": "公司取消了那个员工。", "explanation": "这里应该用〈辞退〉。取消用于事项或规定，不直接用于指人，让员工离职要说辞退。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取消", "is_correct": true, "explanation": "正确。航班停飞，乘客只好回家，所以用“取消”。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“航班便宜了”与“只好回家”没有因果关系，句意不通。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记”要求人作主语或登记的内容作宾语，“航班登记了”不成立。"}, {"text": "旅行", "is_correct": false, "explanation": "搭配：“旅行”的主语应是人，“航班旅行了”不通，也与句意不合。"}], "explanations": {"取消": "正确。航班停飞，乘客只好回家，所以用“取消”。", "便宜": "语义：“航班便宜了”与“只好回家”没有因果关系，句意不通。", "登记": "搭配：“登记”要求人作主语或登记的内容作宾语，“航班登记了”不成立。", "旅行": "搭配：“旅行”的主语应是人，“航班旅行了”不通，也与句意不合。"}, "sentence_index": 6, "correct_answer": "取消"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把地上的积水取消了。", "explanation": "这里是“排除、清除”积水的意思，指把具体的水去掉。取消用于已定的事项或规定，不用于具体的物体，因此不符合本义。"}, {"text": "他取消了肩上的疲劳。", "explanation": "这里是“消除”身体上疲劳的意思，指使疲劳感消失。取消用于事项或规定，不用于身体的感受，因此不符合本义。"}, {"text": "他取消了纸上的错字。", "explanation": "这里是“擦去”字迹的意思，指把纸上的字去掉。取消用于事项或规定，不用于具体的字迹，因此不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把运动会取消。", "corrected_sentence": "学校把运动会取消了。", "error_description": "错误：用“把”字句时，“取消”后面缺少“了”，句子不完整。正确：应说“学校把运动会取消了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校取消着那次考试。", "corrected_sentence": "学校取消了那次考试。", "error_description": "错误：“取消”后加了“着”，表示动作持续。正确：“取消”是一次性完成的动作，应说“取消了”，表示已经撤销。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88471, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
