INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88471, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "各自是每一个人自己，不是大家一起。", "primary_collocate": null, "pronunciation": "gè zì", "ipa": "kɤ˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "下课以后，同学们各自回家了。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天各自准备一份材料。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，大家各自洗自己的碗。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩吵完架，各自走开了。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行结束后，朋友们各自回到了自己的城市。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和姐姐各自在房间里看书。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，每个人要各自完成自己的题。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱请你们各自保管好。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们各自带着自己的玩具来到公园。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说好各自付自己的钱。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个人自己做，不是一起做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88471, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "各自", "is_correct": true, "explanation": "正确：“各自”指每个人自己的，不是大家一起。"}, {"text": "个子", "is_correct": false, "explanation": "gè 与 gè 相同，但第二个音节 zi 为轻声，与 zì（第四声）声调不同，意思是身高。"}, {"text": "格子", "is_correct": false, "explanation": "gézi 第一个音节为第二声，与 gè（第四声）声调不同，意思是方格图案。"}, {"text": "鸽子", "is_correct": false, "explanation": "gēzi 第一个音节为第一声，与 gè 声调不同，第二音节为轻声，意思是鸽子。"}], "explanations": {"各自": "正确：“各自”指每个人自己的，不是大家一起。", "个子": "gè 与 gè 相同，但第二个音节 zi 为轻声，与 zì（第四声）声调不同，意思是身高。", "格子": "gézi 第一个音节为第二声，与 gè（第四声）声调不同，意思是方格图案。", "鸽子": "gēzi 第一个音节为第一声，与 gè 声调不同，第二音节为轻声，意思是鸽子。"}, "sentence_index": null, "correct_answer": "各自"}, "level_3": {"options": [{"text": "彼此", "is_correct": false, "explanation": "搭配：“彼此”表示相互，要求双方互动，“同学们彼此回家了”说不通。"}, {"text": "各自", "is_correct": true, "explanation": "正确：“各自”表示每人自己，符合“同学们……回家了”。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包含说话人，与“同学们”所指的人群重复冲突。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指说话人和同学之外的人，与句中“同学们”冲突。"}], "explanations": {"彼此": "搭配：“彼此”表示相互，要求双方互动，“同学们彼此回家了”说不通。", "各自": "正确：“各自”表示每人自己，符合“同学们……回家了”。", "咱们": "语义：“咱们”包含说话人，与“同学们”所指的人群重复冲突。", "别人": "语义：“别人”指说话人和同学之外的人，与句中“同学们”冲突。"}, "sentence_index": 0, "correct_answer": "各自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈下班后各自去超市买菜了。", "explanation": "这里应该用〈独自〉。“各自”指几方各自的行动，只有一个人时要用“独自”。"}, {"text": "我每天晚上各自做作业。", "explanation": "这里应该用〈自己〉。“各自”需要两个以上的主体，只说我一个人时用“自己”。"}, {"text": "我们班各自选了一位班长。", "explanation": "这里应该用〈共同〉。全班只选出一位班长，是大家一起选的；“各自”表示几方分别行动，与“一位班长”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大家", "is_correct": false, "explanation": "语义：“大家”指全体共同，与“每个人”各自完成的意思矛盾。"}, {"text": "各自", "is_correct": true, "explanation": "正确：“各自”表示每人自己，符合“每个人要……完成自己的题”。"}, {"text": "他人", "is_correct": false, "explanation": "语义：“他人”指别人，与句中“自己的题”冲突。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”口语色彩较重，且指别人，与“自己的题”冲突。"}], "explanations": {"大家": "语义：“大家”指全体共同，与“每个人”各自完成的意思矛盾。", "各自": "正确：“各自”表示每人自己，符合“每个人要……完成自己的题”。", "他人": "语义：“他人”指别人，与句中“自己的题”冲突。", "人家": "语域：“人家”口语色彩较重，且指别人，与“自己的题”冲突。"}, "sentence_index": 6, "correct_answer": "各自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车是我们各自拥有的。", "explanation": "这里应该用〈共同〉。这辆车只有一辆，是大家共同拥有的；“各自”表示各人分别拥有，不能用于同一件东西。"}, {"text": "这张沙发是我们各自买的。", "explanation": "这里应该用〈一起〉。这张沙发只买了一张，是大家一起买的；“各自买的”表示每人分别买，与只有一张矛盾。"}, {"text": "这台冰箱是我们各自用的。", "explanation": "这里应该用〈合用〉。这台冰箱是大家合用的；“各自用”表示每人有自己的，与只有一台矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放学以后，孩子们各自的回家了。", "corrected_sentence": "放学以后，孩子们各自回家了。", "error_description": "“各自”作状语修饰动词时后面不加“的”。应为“各自回家”，多出的“的”不能放在“各自”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "散会以后，大家一起各自走了。", "corrected_sentence": "散会以后，大家各自走了。", "error_description": "“各自”表示每人分别行动，与“一起”矛盾。应删去“一起”，改为“大家各自走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
