INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88472, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指各人自己或各个方面自己的一个。", "primary_collocate": null, "pronunciation": "gè zì", "ipa": "kɤ˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "两个国家都有各自的文化。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家公司各自的优点都很明显。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种动物都有各自的生活方式。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生各自的想法不一样。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国和日本都有各自的节日。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个班都选出了各自的代表。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种办法都有各自的好处和坏处。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们各自的家都离学校很远。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家各自的看法，我们都要听一听。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个城市各自有各自的特点。", "target_word": "各自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "各个方面各有自己的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7650858-8e73-466d-9c43-9b60207a9353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88472, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "各自", "is_correct": true, "explanation": "正确：“各自”指每个人自己的，不是大家一起。"}, {"text": "个子", "is_correct": false, "explanation": "gè 与 gè 相同，但第二个音节 zi 为轻声，与 zì（第四声）声调不同，意思是身高。"}, {"text": "格子", "is_correct": false, "explanation": "gézi 第一个音节为第二声，与 gè（第四声）声调不同，意思是方格图案。"}, {"text": "鸽子", "is_correct": false, "explanation": "gēzi 第一个音节为第一声，与 gè 声调不同，第二音节为轻声，意思是鸽子。"}], "explanations": {"各自": "正确：“各自”指每个人自己的，不是大家一起。", "个子": "gè 与 gè 相同，但第二个音节 zi 为轻声，与 zì（第四声）声调不同，意思是身高。", "格子": "gézi 第一个音节为第二声，与 gè（第四声）声调不同，意思是方格图案。", "鸽子": "gēzi 第一个音节为第一声，与 gè 声调不同，第二音节为轻声，意思是鸽子。"}, "sentence_index": null, "correct_answer": "各自"}, "level_3": {"options": [{"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，“都有别人的文化”与“两个国家都有自己的”不符。"}, {"text": "各自", "is_correct": true, "explanation": "正确：“各自”表示每个对象自己的，符合“两个国家都有……的文化”。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指全体，不能表示两个国家各自拥有。"}, {"text": "互相", "is_correct": false, "explanation": "语法：“互相”只能修饰动词，不能说“互相的文化”。"}], "explanations": {"别人": "语义：“别人”指他人，“都有别人的文化”与“两个国家都有自己的”不符。", "各自": "正确：“各自”表示每个对象自己的，符合“两个国家都有……的文化”。", "大家": "语义：“大家”指全体，不能表示两个国家各自拥有。", "互相": "语法：“互相”只能修饰动词，不能说“互相的文化”。"}, "sentence_index": 0, "correct_answer": "各自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我各自的房间很干净。", "explanation": "这里应该用〈自己〉。“各自的”要求两个以上的人或事物各有一份，只说我一个人时用“自己的”。"}, {"text": "她各自的生日是五月一号。", "explanation": "这里应该用〈自己〉。只有她一个人，不能说“各自的”，应说“她自己的生日”。"}, {"text": "这个房间是他各自的。", "explanation": "这里应该用〈独有〉。房间只属于一个人，“各自的”要求多个对象各有，这里要用“独有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人家", "is_correct": false, "explanation": "语义：“人家”指别人，与作主语的“两种办法”不符。"}, {"text": "各自", "is_correct": true, "explanation": "正确：“各自”表示每种办法自己的，符合“两种办法都有……的好处和坏处”。"}, {"text": "大伙", "is_correct": false, "explanation": "语域：“大伙”口语色彩重，且指人群，不能修饰“办法”。"}, {"text": "他人", "is_correct": false, "explanation": "语义：“他人”指别人，“都有他人的好处和坏处”与“两种办法”不符。"}], "explanations": {"人家": "语义：“人家”指别人，与作主语的“两种办法”不符。", "各自": "正确：“各自”表示每种办法自己的，符合“两种办法都有……的好处和坏处”。", "大伙": "语域：“大伙”口语色彩重，且指人群，不能修饰“办法”。", "他人": "语义：“他人”指别人，“都有他人的好处和坏处”与“两种办法”不符。"}, "sentence_index": 6, "correct_answer": "各自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子是我们各自的财产。", "explanation": "这里应该用〈共同〉。这套房子只有一套，是我们共同的财产；“各自的”表示每人分别拥有，与一套房子矛盾。"}, {"text": "这辆车是我们两个人各自的车。", "explanation": "这里应该用〈共同〉。只有一辆车，是两个人共同的车；“各自的”表示每人各有一辆，与一辆车矛盾。"}, {"text": "这台冰箱是我们几家各自的。", "explanation": "这里应该用〈共有〉。只有一台冰箱，是几家共有的；“各自的”表示每家各有一台，与一台矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三所学校各自操场都很大。", "corrected_sentence": "三所学校各自的操场都很大。", "error_description": "“各自”修饰名词时要加“的”。应为“各自的操场”，漏掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个班各自自己的成绩都不错。", "corrected_sentence": "三个班各自的成绩都不错。", "error_description": "“各自”已经表示每个班自己的，后面不能再加“自己”。应为“各自的成绩”，多出了“自己”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5e1f9d6-9cae-4794-b652-01952c2d0684') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自卑", "is_correct": true, "explanation": "正确。“自卑”是“自豪”的反义词，指觉得自己不如别人、抬不起头，与“自豪”的骄傲感相反。"}, {"text": "平静", "is_correct": false, "explanation": "“平静”形容心情不起伏，与“自豪”没有对立关系，不是它的反义词。"}, {"text": "紧张", "is_correct": false, "explanation": "“紧张”形容心里不安、有压力，与“自豪”不构成反义关系。"}, {"text": "惊讶", "is_correct": false, "explanation": "“惊讶”表示出乎意料的反应，与“自豪”不是反义词。"}], "correct_answer": "自卑", "explanations": {"自卑": "正确。“自卑”是“自豪”的反义词，指觉得自己不如别人、抬不起头，与“自豪”的骄傲感相反。", "平静": "“平静”形容心情不起伏，与“自豪”没有对立关系，不是它的反义词。", "紧张": "“紧张”形容心里不安、有压力，与“自豪”不构成反义关系。", "惊讶": "“惊讶”表示出乎意料的反应，与“自豪”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自卑", "is_correct": true, "explanation": "正确。“自卑”是“自豪”的反义词，指觉得自己不如别人，与“做成这件事”后的骄傲感相反。"}, {"text": "激动", "is_correct": false, "explanation": "“激动”形容情绪强烈振奋，与“自豪”不是反义关系。"}, {"text": "害羞", "is_correct": false, "explanation": "“害羞”形容不好意思的心理，与“自豪”不构成反义词。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情没有压力，与“自豪”不是反义词。"}], "correct_answer": "自卑", "explanations": {"自卑": "正确。“自卑”是“自豪”的反义词，指觉得自己不如别人，与“做成这件事”后的骄傲感相反。", "激动": "“激动”形容情绪强烈振奋，与“自豪”不是反义关系。", "害羞": "“害羞”形容不好意思的心理，与“自豪”不构成反义词。", "轻松": "“轻松”形容心情没有压力，与“自豪”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自豪是做成了事，心里觉得很光荣。", "primary_collocate": null, "pronunciation": "zì háo", "ipa": "tsɹ̩˥˩ xɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我第一次做出蛋糕，心里很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自己修好了电脑，觉得很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完全程以后，她非常自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学会了游泳，心里很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我通过了考试，心里特别自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做成了这件大事，十分自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写完了第一本书，感到很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我自己种的菜长大了，我很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修好了老师的旧车，自豪极了。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做成了这件事，应该自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自豪感", "label": "复合词"}, {"form": "自豪地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "自己做成一件事后心里觉得光荣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自豪", "is_correct": true, "explanation": "正确。“自豪”表示做成事情后心里感到光荣，与“第一次做出蛋糕”的成就相符。"}, {"text": "惭愧", "is_correct": false, "explanation": "语义：“惭愧”表示因做错事而不安，与“第一次做出蛋糕”这一成就不符。"}, {"text": "难过", "is_correct": false, "explanation": "语义：“难过”表示伤心，与做出蛋糕的成功情境相矛盾。"}, {"text": "冷淡", "is_correct": false, "explanation": "搭配：“冷淡”形容对人或事的态度，不能用来描述“心里”的感受。"}], "explanations": {"自豪": "正确。“自豪”表示做成事情后心里感到光荣，与“第一次做出蛋糕”的成就相符。", "惭愧": "语义：“惭愧”表示因做错事而不安，与“第一次做出蛋糕”这一成就不符。", "难过": "语义：“难过”表示伤心，与做出蛋糕的成功情境相矛盾。", "冷淡": "搭配：“冷淡”形容对人或事的态度，不能用来描述“心里”的感受。"}, "sentence_index": 0, "correct_answer": "自豪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说了谎，心里很自豪。", "explanation": "这里应该用〈惭愧〉。“自豪”指做成事情后的光荣感，说谎不是值得骄傲的事，应该感到惭愧。"}, {"text": "我考试不及格，心里很自豪。", "explanation": "这里应该用〈沮丧〉。“自豪”指为做成的事感到光荣，考试不及格应当感到沮丧，不能用“自豪”。"}, {"text": "他吃饱饭后，心里很自豪。", "explanation": "这里应该用〈满足〉。吃饱饭是普通的生活状态，不是需要争取的成果，不能用“自豪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自豪", "is_correct": true, "explanation": "正确。“自豪”表示写完第一本书后心里的光荣感，与句子的情境相符。"}, {"text": "惊慌", "is_correct": false, "explanation": "语义：“惊慌”指慌乱害怕，与写完书后的成就感不符。"}, {"text": "委屈", "is_correct": false, "explanation": "语义：“委屈”表示受了不公平的对待，与写完书这件事的情境不符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”表示不愿劳动或学习，与写完第一本书后的成就感不符。"}], "explanations": {"自豪": "正确。“自豪”表示写完第一本书后心里的光荣感，与句子的情境相符。", "惊慌": "语义：“惊慌”指慌乱害怕，与写完书后的成就感不符。", "委屈": "语义：“委屈”表示受了不公平的对待，与写完书这件事的情境不符。", "懒惰": "语义：“懒惰”表示不愿劳动或学习，与写完第一本书后的成就感不符。"}, "sentence_index": 6, "correct_answer": "自豪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忘了朋友的生日，心里很自豪。", "explanation": "这里应该用〈内疚〉。“自豪”指做成事情后的光荣感，忘记朋友生日不是成就，应表达内疚。"}, {"text": "他在朋友面前丢了脸，心里很自豪。", "explanation": "这里应该用〈尴尬〉。“自豪”指做成事情后的光荣感，在朋友面前丢脸不是光荣的事，应表达尴尬。"}, {"text": "他听说朋友生病，心里很自豪。", "explanation": "这里应该用〈担心〉。朋友生病不是做成的事，不能用“自豪”来表达，应表示担心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为考上大学地自豪。", "corrected_sentence": "他为考上大学而自豪。", "error_description": "错误：“而”用成了“地”。“为……而自豪”中“而”连接原因与“自豪”，不能用“地”把“自豪”变成修饰成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她考试得了第一，很自豪的笑了。", "corrected_sentence": "她考试得了第一，很自豪地笑了。", "error_description": "错误：“自豪”后应用“地”修饰动词“笑”，不能用“的”。“的”连接定语和名词，“笑”是动词，应说“很自豪地笑了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
