INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88474, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "因为自己或所属的集体取得成绩而感到光荣。", "primary_collocate": null, "pronunciation": "zì háo", "ipa": "tsɹ̩˥˩ xɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我为我们的学校感到自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人为长城感到自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队赢了比赛，大家都很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为自己的家乡自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学拿了第一名，老师很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为中国人，我感到很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为女儿的成绩感到自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的产品卖到了很多国家，大家很自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到国旗升起来，运动员们自豪极了。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为自己的民族感到自豪。", "target_word": "自豪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自豪感", "label": "复合词"}, {"form": "自豪地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "为自己或所属集体的成绩、身份感到光荣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2eaceed3-cfb3-4336-83f4-e9f64a49ecba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自豪", "is_correct": true, "explanation": "正确。“自豪”表示为学校的光荣而感到骄傲，与句子的意思相符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材或建筑的大小，不是一种心情，不能说“为学校感到高大”。"}, {"text": "冷淡", "is_correct": false, "explanation": "搭配：“冷淡”形容对人的态度，“感到冷淡”与为学校的光荣感搭配不当。"}, {"text": "惊慌", "is_correct": false, "explanation": "语义：“惊慌”表示慌乱害怕，与为学校感到光荣的情感不符。"}], "explanations": {"自豪": "正确。“自豪”表示为学校的光荣而感到骄傲，与句子的意思相符。", "高大": "搭配：“高大”形容身材或建筑的大小，不是一种心情，不能说“为学校感到高大”。", "冷淡": "搭配：“冷淡”形容对人的态度，“感到冷淡”与为学校的光荣感搭配不当。", "惊慌": "语义：“惊慌”表示慌乱害怕，与为学校感到光荣的情感不符。"}, "sentence_index": 0, "correct_answer": "自豪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为家乡的垃圾问题感到自豪。", "explanation": "这里应该用〈惭愧〉。“自豪”指为光荣的成就感到骄傲，家乡的垃圾问题不是光荣的事，不能用“自豪”。"}, {"text": "他为家乡的污染感到自豪。", "explanation": "这里应该用〈生气〉。污染是负面的事情，不能为它感到自豪。"}, {"text": "他为家乡的失败感到自豪。", "explanation": "这里应该用〈遗憾〉。“自豪”只用于值得骄傲的成果，不能用于失败的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自豪", "is_correct": true, "explanation": "正确。“自豪”表示为女儿取得的成绩感到光荣，与句子的意思相符。"}, {"text": "方便", "is_correct": false, "explanation": "搭配：“方便”形容做事容易、便利，不表示心情，不能说“为女儿的成绩感到方便”。"}, {"text": "轻蔑", "is_correct": false, "explanation": "语义：“轻蔑”表示看不起，与为女儿的成绩感到光荣的情感相反。"}, {"text": "厌烦", "is_correct": false, "explanation": "语义：“厌烦”表示不耐烦，与为女儿的成绩感到光荣的情感不合。"}], "explanations": {"自豪": "正确。“自豪”表示为女儿取得的成绩感到光荣，与句子的意思相符。", "方便": "搭配：“方便”形容做事容易、便利，不表示心情，不能说“为女儿的成绩感到方便”。", "轻蔑": "语义：“轻蔑”表示看不起，与为女儿的成绩感到光荣的情感相反。", "厌烦": "语义：“厌烦”表示不耐烦，与为女儿的成绩感到光荣的情感不合。"}, "sentence_index": 6, "correct_answer": "自豪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做错了事，觉得很自豪。", "explanation": "这里应该用〈羞耻〉。做错事不是光荣的事，不能用“自豪”。"}, {"text": "他生病了，为此感到自豪。", "explanation": "这里应该用〈难过〉。生病不是取得成绩，不能为此感到自豪，应表达难过。"}, {"text": "他每次上课都迟到，却为此很自豪。", "explanation": "这里应该用〈自责〉。“自豪”指因取得成绩而光荣，每次迟到不是成绩，应表达自责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市为自己的历史感到地自豪。", "corrected_sentence": "这座城市为自己的历史感到自豪。", "error_description": "错误：“感到”和“自豪”之间多了“地”。“地”用来修饰动词，不能放在“感到”之后，应说“感到自豪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师被学生的进步感到自豪。", "corrected_sentence": "老师为学生的进步感到自豪。", "error_description": "错误：“为”用成了“被”。“为……感到自豪”表示因某事而感到光荣，“被”表示被动，不能与“感到自豪”搭配，应说“为学生的进步感到自豪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4e0c495-239d-425c-b015-2ec449796370') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
