INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88477, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在地是说就在这个地方的。", "primary_collocate": null, "pronunciation": "zài dì", "ipa": "tsaɪ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这家店用的都是在地食材。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃在地的小吃。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板是在地人，对这里很熟。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子有很多在地文化。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请在地的老人讲故事。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的在地茶很有名。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想办一个在地市集。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找在地朋友带我逛逛。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店只卖在地牛奶。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地的老师最了解这里的孩子。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在地人", "label": "复合"}, {"form": "在地化", "label": "复合"}], "register": "中性", "sense_fingerprint": "就在这个地方的，出自这里的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个别", "is_correct": false, "explanation": "语义：“个别”指少数、零星，与“都是”表示全部的意思矛盾。"}, {"text": "在地", "is_correct": true, "explanation": "在地：修饰“食材”，指产自本地，符合语境。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能用来修饰食材。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”说人的品性，不能用来修饰食材。"}], "explanations": {"个别": "语义：“个别”指少数、零星，与“都是”表示全部的意思矛盾。", "在地": "在地：修饰“食材”，指产自本地，符合语境。", "年轻": "搭配：“年轻”说人的年龄，不能用来修饰食材。", "懒惰": "搭配：“懒惰”说人的品性，不能用来修饰食材。"}, "sentence_index": 0, "correct_answer": "在地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜都是从国外空运来的，却非常在地。", "explanation": "这里应该用〈进口〉。在地指产自本地，与“从国外空运来的”矛盾，不能用来形容外来食材。"}, {"text": "这家公司在纽约，他每天从北京坐飞机上班，却是在地员工。", "explanation": "这里应该用〈外派〉。在地员工指在当地工作的人，与“每天从北京坐飞机上班”矛盾。"}, {"text": "这座博物馆的在地文物全部从欧洲运来。", "explanation": "这里应该用〈海外〉。在地指就在本地，与“从欧洲运来”矛盾，外来的文物应说海外文物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指冷落无人，与“想办”的积极意图矛盾。"}, {"text": "在地", "is_correct": true, "explanation": "在地：修饰“市集”，指本地的，符合语境。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或动物的身形，不能修饰市集。"}, {"text": "胆小", "is_correct": false, "explanation": "搭配：“胆小”形容人或动物的性格，不能修饰市集。"}], "explanations": {"冷清": "语义：“冷清”指冷落无人，与“想办”的积极意图矛盾。", "在地": "在地：修饰“市集”，指本地的，符合语境。", "瘦小": "体貌：“瘦小”形容人或动物的身形，不能修饰市集。", "胆小": "搭配：“胆小”形容人或动物的性格，不能修饰市集。"}, "sentence_index": 6, "correct_answer": "在地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他报了一门在地课程，每天都要飞去别的国家上。", "explanation": "这里应该用〈海外〉。在地课程指本地的课程，与“每天都要飞去别的国家上”矛盾，应说海外课程。"}, {"text": "他是在地人，却一直住在伦敦，从没回过这里。", "explanation": "这里应该用〈外地人〉。在地人指就在本地的人，与“一直住在伦敦”矛盾。"}, {"text": "这家店的在地老板常年住在纽约，很少回来。", "explanation": "这里应该用〈外籍〉。在地老板指就在当地经营的人，与“常年住在纽约”矛盾，应说外籍老板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个市场卖的都是在地地蔬菜。", "corrected_sentence": "这个市场卖的都是在地蔬菜。", "error_description": "“在地”修饰名词时后面直接接名词，不加“地”（“地”用于动词、形容词作状语）。误加“地”，应说“在地蔬菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店卖的牛奶是在地。", "corrected_sentence": "这家店卖的牛奶是在地的。", "error_description": "词类错误：“在地”是区别词，不能直接放在“是”后面作谓语，必须用“是……的”格式。句中缺少“的”，应说“是在地的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
