INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88478, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本地的;当地的。", "primary_collocate": null, "pronunciation": "zài dì", "ipa": "tsaɪ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "在地文化是这座城市的特色。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位在地艺术家画了很多老街。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想帮助在地农民卖水果。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地的产业需要更多年轻人。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日是在地居民一起办的。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地语言正在慢慢消失。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府支持在地小店发展。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客喜欢听在地人讲老故事。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了在地的历史。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要多用在地的材料盖房子。", "target_word": "在地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "在地人", "label": "复合"}, {"form": "在地化", "label": "复合"}], "register": "书面", "sense_fingerprint": "本地的、当地的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”说气候或物体的状态，不说文化。"}, {"text": "在地", "is_correct": true, "explanation": "在地：修饰“文化”，指本地的，符合语境。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或动物的身形，不能修饰文化。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格高，不能用来修饰文化。"}], "explanations": {"干燥": "搭配：“干燥”说气候或物体的状态，不说文化。", "在地": "在地：修饰“文化”，指本地的，符合语境。", "瘦小": "体貌：“瘦小”形容人或动物的身形，不能修饰文化。", "昂贵": "搭配：“昂贵”说价格高，不能用来修饰文化。"}, "sentence_index": 0, "correct_answer": "在地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的菜都是从国外空运来的，却非常在地。", "explanation": "这里应该用〈外来〉。在地指产自本地，与“从国外空运来的”矛盾，不能用来形容外来食材。"}, {"text": "这次会议在国外举行，主办方却说是在地活动。", "explanation": "这里应该用〈海外〉。在地活动指就在本地举办，与“在国外举行”矛盾，应说海外活动。"}, {"text": "他一直在国外工作，却自称是在地员工。", "explanation": "这里应该用〈外派〉。在地员工指在当地工作的人，与“一直在国外工作”矛盾，应说外派员工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人的品性，不能修饰小店。"}, {"text": "在地", "is_correct": true, "explanation": "在地：修饰“小店”，指本地的，符合语境。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”与“小店”的“小”相矛盾。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”指面积广大，与“小店”的“小”相矛盾。"}], "explanations": {"懒惰": "搭配：“懒惰”形容人的品性，不能修饰小店。", "在地": "在地：修饰“小店”，指本地的，符合语境。", "高大": "语义：“高大”与“小店”的“小”相矛盾。", "辽阔": "语义：“辽阔”指面积广大，与“小店”的“小”相矛盾。"}, "sentence_index": 6, "correct_answer": "在地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他报了一门在地课程，每天都要飞去别的国家上。", "explanation": "这里应该用〈海外〉。在地课程指本地的课程，与“每天都要飞去别的国家上”矛盾，应说海外课程。"}, {"text": "他是在地人，却一直住在伦敦，从没回过这里。", "explanation": "这里应该用〈外地人〉。在地人指就在本地的人，与“一直住在伦敦”矛盾。"}, {"text": "这家店的在地老板常年住在纽约，很少回来。", "explanation": "这里应该用〈外地〉。在地老板指就在当地经营的人，与“常年住在纽约”矛盾，应说外地老板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家茶馆用的都是在地地茶叶。", "corrected_sentence": "这家茶馆用的都是在地茶叶。", "error_description": "“在地”修饰名词时后面直接接名词，不加“地”（“地”用于动词、形容词作状语）。误加“地”，应说“在地茶叶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请了一只在地人来讲故事。", "corrected_sentence": "我们请了一位在地人来讲故事。", "error_description": "“在地人”指人，计量人要用“位”或“个”，不用“只”。应说“一位在地人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回来", "is_correct": true, "explanation": "“回来”与“回去”意义相反，表示回到说话人所在的地方。"}, {"text": "进入", "is_correct": false, "explanation": "“进入”表示由外往里走，与“回去”没有反义关系。"}, {"text": "坐下", "is_correct": false, "explanation": "“坐下”表示由站到坐的动作，与“回去”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“回去”的动作和方向都无关，不构成反义关系。"}], "correct_answer": "回来", "explanations": {"回来": "“回来”与“回去”意义相反，表示回到说话人所在的地方。", "进入": "“进入”表示由外往里走，与“回去”没有反义关系。", "坐下": "“坐下”表示由站到坐的动作，与“回去”没有反义关系。", "睡觉": "语义：“睡觉”与“回去”的动作和方向都无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回来", "is_correct": true, "explanation": "“回来”与“回去”意义相反，表示回到说话人所在的地方。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”与“回去”的动作和方向都无关，不构成反义关系。"}, {"text": "登记", "is_correct": false, "explanation": "“登记”指办理登记手续，与“回去”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”指进食，与“回去”没有反义关系。"}], "correct_answer": "回来", "explanations": {"回来": "“回来”与“回去”意义相反，表示回到说话人所在的地方。", "写字": "语义：“写字”与“回去”的动作和方向都无关，不构成反义关系。", "登记": "“登记”指办理登记手续，与“回去”没有反义关系。", "吃饭": "“吃饭”指进食，与“回去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回去是从别的地方走回原来的地方。", "primary_collocate": null, "pronunciation": "huí qù", "ipa": "xweɪ˧˥ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "我在公司，六点回去。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去超市买菜，买完就回去。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩完了，该回去了。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先回去，我再坐一会儿。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去朋友家玩，晚上回去。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他吃过饭就回去了。", "target_word": "回去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们都回去了。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面太冷，我们快回去吧。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你从公园回去时，请买点水果。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在老家住了三天，昨天回去了。", "target_word": "回去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回去了", "label": "体标"}, {"form": "回去过", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：从别处走回原来所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d06d0e-067c-4c11-97ae-a74e588d261c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回去", "is_correct": true, "explanation": "“回去”表示从公司返回原来的地方，与“六点”下班的语境相符。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”指离开国境，与“在公司”“六点”的语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”需要在考场进行，与“在公司”的语境不符。"}, {"text": "回忆", "is_correct": false, "explanation": "配价：“回忆”是及物动词，后面通常要带宾语，如“回忆往事”，句中没有宾语。"}], "explanations": {"回去": "“回去”表示从公司返回原来的地方，与“六点”下班的语境相符。", "出国": "语义：“出国”指离开国境，与“在公司”“六点”的语境不符。", "考试": "语义：“考试”需要在考场进行，与“在公司”的语境不符。", "回忆": "配价：“回忆”是及物动词，后面通常要带宾语，如“回忆往事”，句中没有宾语。"}, "sentence_index": 0, "correct_answer": "回去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从没到过那家超市，今晚要回去那家超市。", "explanation": "这里应该用〈去〉。“回去”表示返回以前待过的地方，他从未到过那家超市，应说“去那家超市”。"}, {"text": "妈妈在家等我，你快回去吧，我也马上回去了家里看她。", "explanation": "这里应该用〈回〉。“回去”不能直接带处所宾语“家里”，应说“回家里”或“回家”。"}, {"text": "门开着，你直接回去房间里坐吧，那是我的房间。", "explanation": "这里应该用〈进去〉。“回去”指回到自己原来的地方，进入别人的房间应说“进去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回去", "is_correct": true, "explanation": "“回去”表示同学们离开教室返回原地，与“下课后”相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“下课后”再“上课”与语境矛盾，不能说“同学们都上课了”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语只能是天气，“同学们”不能下雨，与句意不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与“下课后”的时间和语境不符。"}], "explanations": {"回去": "“回去”表示同学们离开教室返回原地，与“下课后”相符。", "上课": "语义：“下课后”再“上课”与语境矛盾，不能说“同学们都上课了”。", "下雨": "语义：“下雨”的主语只能是天气，“同学们”不能下雨，与句意不符。", "出生": "语义：“出生”指人降生，与“下课后”的时间和语境不符。"}, "sentence_index": 6, "correct_answer": "回去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚从公司回去，现在在我家。", "explanation": "这里应该用〈回来〉。“回去”表示离开说话人所在地回到原处，这里“他”已在说话人家中，应说“回来”。"}, {"text": "我在门口，你回去帮我开门。", "explanation": "这里应该用〈过来〉。“回去”指回到对方原来的地方，请对方到说话人所在的门口帮忙要用“过来”。"}, {"text": "明天你回去我公司找我。", "explanation": "这里应该用〈来〉。“回去”指回到原来的地方，“我公司”不是对方原来所在之处，请对方到说话人这里应说“来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先回去家，你们再来吧。", "corrected_sentence": "我先回家，你们再来吧。", "error_description": "“回去”后不能直接接处所名词“家”，表示回家应说“回家”，这里应去掉“去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把书回去了。", "corrected_sentence": "他把书带回去了。", "error_description": "“回去”不能直接带物品作宾语，把东西带回去要加“带”，这里应说“把书带回去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
