INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蝴蝶是翅膀很漂亮的小虫子，会在花上飞。", "primary_collocate": null, "pronunciation": "hú dié", "ipa": "xu˧˥ tjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "花园里有一只蝴蝶在花上飞。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩跑过去想抓那只蝴蝶。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶的翅膀红红的，真漂亮。", "target_word": "蝴蝶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，花开了，蝴蝶也来了。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只白色的蝴蝶停在我的手上。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿着网，在草地上追蝴蝶。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶飞得很轻，一点声音也没有。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在花旁边看见两只蝴蝶。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只蝴蝶的翅膀上有黄色的点。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，蝴蝶都飞回树叶下面躲雨。", "target_word": "蝴蝶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "蝴蝶结", "label": "复合词"}, {"form": "蝴蝶兰", "label": "复合词"}], "register": "中性", "sense_fingerprint": "翅膀漂亮、在花上飞的小虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会飞，句中“在花上飞”与之矛盾。"}, {"text": "蝴蝶", "is_correct": true, "explanation": "蝴蝶：会在花上飞的小虫，与句中的“花园”“花上飞”相符。"}, {"text": "树", "is_correct": false, "explanation": "搭配：量词“只”用于动物，不搭配“树”（树应说“棵”）。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不能在花上飞。"}], "explanations": {"石头": "语义：石头不会飞，句中“在花上飞”与之矛盾。", "蝴蝶": "蝴蝶：会在花上飞的小虫，与句中的“花园”“花上飞”相符。", "树": "搭配：量词“只”用于动物，不搭配“树”（树应说“棵”）。", "房子": "语义：房子是建筑物，不能在花上飞。"}, "sentence_index": 0, "correct_answer": "蝴蝶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的池塘边，一只蝴蝶在水面上点水产卵。", "explanation": "这里应该用〈蜻蜓〉。蜻蜓常在水面上点水产卵，蝴蝶不这样做，“蝴蝶”不能这样用。"}, {"text": "他的手被一只蝴蝶蜇了一下。", "explanation": "这里应该用〈蜜蜂〉。蜜蜂等昆虫会用毒针蜇人，蝴蝶没有这种本领，“蝴蝶”不能这样用。"}, {"text": "蝴蝶在窗角织了一张网。", "explanation": "这里应该用〈蜘蛛〉。蜘蛛会吐丝织网，蝴蝶不会织网，“蝴蝶”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会飞，“飞得很轻”与之不合。"}, {"text": "蝴蝶", "is_correct": true, "explanation": "蝴蝶：有翅膀、会轻盈飞行，与“飞得很轻”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "体貌：玻璃坚硬而沉重，外形上不能轻盈飞行，与“飞得很轻”不符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用具，不会自己飞，与句意不合。"}], "explanations": {"小狗": "语义：小狗不会飞，“飞得很轻”与之不合。", "蝴蝶": "蝴蝶：有翅膀、会轻盈飞行，与“飞得很轻”相符。", "玻璃": "体貌：玻璃坚硬而沉重，外形上不能轻盈飞行，与“飞得很轻”不符。", "雨伞": "语义：雨伞是用具，不会自己飞，与句意不合。"}, "sentence_index": 6, "correct_answer": "蝴蝶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏夜的草丛里，一只蝴蝶一闪一闪地发光。", "explanation": "这里应该用〈萤火虫〉。萤火虫的身体能发光，蝴蝶没有这种特点，“蝴蝶”不能这样用。"}, {"text": "一队蝴蝶把食物搬回了洞穴。", "explanation": "这里应该用〈蚂蚁〉。蚂蚁成群搬运食物回洞穴，蝴蝶不这样做，“蝴蝶”不能这样用。"}, {"text": "蝴蝶背着壳，慢慢地爬过湿润的草地。", "explanation": "这里应该用〈蜗牛〉。蜗牛背着壳慢慢爬行，蝴蝶没有壳，“蝴蝶”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在院子里捉到一条蝴蝶。", "corrected_sentence": "妹妹在院子里捉到一只蝴蝶。", "error_description": "错误：量词用错。“条”用于鱼、蛇等细长的东西，蝴蝶应用“只”。正确说法是“一只蝴蝶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只很大蝴蝶飞过来了。", "corrected_sentence": "一只很大的蝴蝶飞过来了。", "error_description": "错误：“很大”修饰名词时要加“的”，漏掉“的”是错误。正确说法是“很大的蝴蝶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。"}, {"text": "全体", "is_correct": false, "explanation": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。"}, {"text": "整体", "is_correct": false, "explanation": "不是反义：“整体”指全部的集合，与“多数”不构成对立。"}, {"text": "群体", "is_correct": false, "explanation": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。", "全体": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。", "整体": "不是反义：“整体”指全部的集合，与“多数”不构成对立。", "群体": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。"}, {"text": "个体", "is_correct": false, "explanation": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。"}, {"text": "全部", "is_correct": false, "explanation": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。"}, {"text": "人群", "is_correct": false, "explanation": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。", "个体": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。", "全部": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。", "人群": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "多数是人或东西里面,比一半多的那一些。", "primary_collocate": null, "pronunciation": "duō shù", "ipa": "twɔ˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "我的朋友里，多数住在北京。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班有三十个人，多数是女生。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数老师星期六不上班。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买来的苹果，多数是红的。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家多数人喜欢吃面。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书，多数是新买的。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数小孩儿喜欢吃糖。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，多数人带着伞。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜里多数是我做的。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学多数通过了考试。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多数", "label": "复合"}, {"form": "多数人", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或东西里比一半多的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e1ab4a-5687-4830-8ee0-0311191f4520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“多数”指朋友中比一半多的人，作主语，句意通顺。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”是地方，不是朋友，“城市住在北京”句意不通。"}, {"text": "公寓", "is_correct": false, "explanation": "搭配：“住”的主语要是人，“公寓”不能作“住”的主语。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不属于朋友的范畴，与句中的“住在北京”不搭。"}], "explanations": {"多数": "正确。“多数”指朋友中比一半多的人，作主语，句意通顺。", "城市": "语义：“城市”是地方，不是朋友，“城市住在北京”句意不通。", "公寓": "搭配：“住”的主语要是人，“公寓”不能作“住”的主语。", "厨房": "语义：“厨房”不属于朋友的范畴，与句中的“住在北京”不搭。"}, "sentence_index": 0, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了多数个苹果。", "explanation": "这里应该用〈好几〉。多数指一组中超过半数的部分，不能直接放在量词“个”前表示不定的数量，这里要说买了好几个。"}, {"text": "买来的苹果，多数是三斤。", "explanation": "这里应该用〈重量〉。多数表示比例，不能表示重量，要说重量是三斤。"}, {"text": "我们班的多数是三十个。", "explanation": "这里应该用〈人数〉。多数不能表示具体数目，说班里的人数是三十个要用人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“多数小孩儿喜欢吃糖”指大部分孩子喜欢，“多数”作主语，句意通顺。"}, {"text": "成年", "is_correct": false, "explanation": "语义：“成年小孩儿”自相矛盾，与“小孩儿喜欢吃糖”冲突。"}, {"text": "老年", "is_correct": false, "explanation": "语义：“老年小孩儿”自相矛盾，与“小孩儿”的意思冲突。"}, {"text": "大学生", "is_correct": false, "explanation": "搭配：“大学生”与“小孩儿”不能并列修饰同一个名词，搭配不当。"}], "explanations": {"多数": "正确。“多数小孩儿喜欢吃糖”指大部分孩子喜欢，“多数”作主语，句意通顺。", "成年": "语义：“成年小孩儿”自相矛盾，与“小孩儿喜欢吃糖”冲突。", "老年": "语义：“老年小孩儿”自相矛盾，与“小孩儿”的意思冲突。", "大学生": "搭配：“大学生”与“小孩儿”不能并列修饰同一个名词，搭配不当。"}, "sentence_index": 6, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班同学多数次通过了考试。", "explanation": "这里应该用〈多次〉。多数表示超过半数的部分，不修饰次数，说通过了很多次要用多次。"}, {"text": "全班同学多数地通过了考试。", "explanation": "这里不能把“多数”当副词加“地”用，表示“顺利”的意思要用〈顺利〉。多数只表示超过半数的部分。"}, {"text": "全班同学多数了考试。", "explanation": "这里应该用〈通过〉。多数是名词，指超过半数的部分，不能当动词带宾语，要说通过了考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区一个多数住户养了狗。", "corrected_sentence": "我们小区多数住户养了狗。", "error_description": "错误：“多数”前面加了量词“一个”。正确：“多数”不带量词，直接说“多数住户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学以后，很多数学生去图书馆。", "corrected_sentence": "放学以后，多数学生去图书馆。", "error_description": "错误：“多数”前面加了副词“很”（很多数）。正确：“多数”不受“很”修饰，应说“多数学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”意义相对，指一组中所占比例较小的那部分。"}, {"text": "全体", "is_correct": false, "explanation": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。"}, {"text": "整体", "is_correct": false, "explanation": "不是反义：“整体”指全部的集合，与“多数”不构成对立。"}, {"text": "群体", "is_correct": false, "explanation": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”意义相对，指一组中所占比例较小的那部分。", "全体": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。", "整体": "不是反义：“整体”指全部的集合，与“多数”不构成对立。", "群体": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。"}, {"text": "个体", "is_correct": false, "explanation": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。"}, {"text": "全部", "is_correct": false, "explanation": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。"}, {"text": "人群", "is_correct": false, "explanation": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。", "个体": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。", "全部": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。", "人群": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较大的数量;超过半数的部分。", "primary_collocate": null, "pronunciation": "duō shù", "ipa": "twɔ˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "多数人同意这个办法。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，多数同学选了第二个办法。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班多数学生喜欢踢足球。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票的结果由多数人决定。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家店买东西的，多数是老人。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数时候，我坐地铁上班。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数人要听多数人的意见。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的多数商店晚上十点关门。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数孩子都怕打针。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里多数人不会说日语。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多数", "label": "复合"}, {"form": "多数人", "label": "复合"}], "register": "中性", "sense_fingerprint": "超过半数的较大部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e1ab4a-5687-4830-8ee0-0311191f4520') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“多数人”指超过半数的人，与“同意这个办法”相符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：“植物人”指没有意识的人，无法表示同意，句意冲突。"}, {"text": "木头", "is_correct": false, "explanation": "语义：“木头人”指呆板不动的人，不能表示同意办法。"}, {"text": "纸人", "is_correct": false, "explanation": "语义：“纸人”是纸做的人偶，不能表示同意办法，句意不通。"}], "explanations": {"多数": "正确。“多数人”指超过半数的人，与“同意这个办法”相符。", "植物": "语义：“植物人”指没有意识的人，无法表示同意，句意冲突。", "木头": "语义：“木头人”指呆板不动的人，不能表示同意办法。", "纸人": "语义：“纸人”是纸做的人偶，不能表示同意办法，句意不通。"}, "sentence_index": 0, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我多数三岁。", "explanation": "这里应该用〈大〉。多数指超过半数的部分，不能比较年龄，要说比我大三岁。"}, {"text": "你有多数钱？", "explanation": "这里应该用〈多少〉。多数表示超过半数的部分，不用于询问钱的数量，问数量要用多少。"}, {"text": "班里的多数是三十。", "explanation": "这里应该用〈人数〉。多数指部分占整体的比例，不能表示具体数目，说人数是三十要用人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“少数人要听多数人的意见”是常见说法，“多数人”指超过半数的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头人”不是能提意见的人，与句意不通。"}, {"text": "外星", "is_correct": false, "explanation": "语义：“外星人”不在现实社会中，无法提出意见，句意不通。"}, {"text": "机器", "is_correct": false, "explanation": "语义：“机器人”不是要被少数人听取意见的群体，句意不通。"}], "explanations": {"多数": "正确。“少数人要听多数人的意见”是常见说法，“多数人”指超过半数的人。", "石头": "语义：“石头人”不是能提意见的人，与句意不通。", "外星": "语义：“外星人”不在现实社会中，无法提出意见，句意不通。", "机器": "语义：“机器人”不是要被少数人听取意见的群体，句意不通。"}, "sentence_index": 6, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去过多数次日本。", "explanation": "这里应该用〈多次〉。多数表示超过半数的部分，不修饰次数，说去过很多次要用多次。"}, {"text": "他多数每天跑步。", "explanation": "这里应该用〈经常〉。多数表示部分，不表示动作的频率，说每天做某事的频繁程度要用经常。"}, {"text": "这个房间很多数。", "explanation": "这里应该用〈大〉。多数是名词，指超过半数的部分，不能作形容词谓语描述房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里一个多数同学都喜欢这门课。", "corrected_sentence": "班里多数同学都喜欢这门课。", "error_description": "错误：“多数”前面加了量词“一个”。正确：“多数”不带量词，直接修饰名词，说“多数同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末的时候，很多数人在家休息。", "corrected_sentence": "周末的时候，多数人在家休息。", "error_description": "错误：“多数”前面加了副词“很”（很多数）。正确：“多数”不受“很”修饰，应说“多数人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96276b-a330-4831-a2a4-3b52a87bc571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
