INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88485, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "填补是把缺少的地方补上，让它满起来。", "primary_collocate": null, "pronunciation": "tián bǔ", "ipa": "tʰjɛn˧˥ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人用水泥填补墙上的小洞。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用泥土填补了地上的坑。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用石膏把墙上的裂缝填补了。", "target_word": "填补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牙医用特殊材料填补我的牙洞。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有个坑，工人正在填补。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用沙子填补木板之间的空隙。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用油漆填补了桌子上的划痕。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边的堤坝破了，大家用石头填补缺口。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后路面有很多小坑，需要填补。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明用橡皮泥填补了玩具上的洞。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "填补了", "label": "完成体"}, {"form": "填补过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用东西把洞、缝、坑等缺少的地方补满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88485, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "语义：挖是挖出、凿深，洞会变得更深，与「填补」把洞补满的意思相反。"}, {"text": "填补", "is_correct": true, "explanation": "填补：用水泥把小洞补满，符合句意，正确答案。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：扩大会使洞变得更大，与「补上小洞」的意思相反。"}, {"text": "打磨", "is_correct": false, "explanation": "搭配：打磨用于使表面光滑，不能用来处理墙上的洞。"}], "explanations": {"挖": "语义：挖是挖出、凿深，洞会变得更深，与「填补」把洞补满的意思相反。", "填补": "填补：用水泥把小洞补满，符合句意，正确答案。", "扩大": "语义：扩大会使洞变得更大，与「补上小洞」的意思相反。", "打磨": "搭配：打磨用于使表面光滑，不能用来处理墙上的洞。"}, "sentence_index": 0, "correct_answer": "填补"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们填补了几条新资料。", "explanation": "这里应该用〈补充〉。填补用于空缺、空白，资料不是空缺，增加新内容要用补充。"}, {"text": "请在表格上填补你的姓名。", "explanation": "这里应该用〈填写〉。填补是补上空缺，表格上的空栏要用填写。"}, {"text": "往杯子里填补水。", "explanation": "这里应该用〈倒〉。填补是把缺口补满，往杯子里倒水不是补缺口，要用倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放大", "is_correct": false, "explanation": "语义：放大会使划痕变得更明显，与「填补」补平划痕的意思相反。"}, {"text": "填补", "is_correct": true, "explanation": "填补：用油漆把划痕补平，符合句意，正确答案。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦用于擦去污渍，不能用油漆来擦划痕。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：打碎会弄坏桌面，与「填补划痕」的意思相反。"}], "explanations": {"放大": "语义：放大会使划痕变得更明显，与「填补」补平划痕的意思相反。", "填补": "填补：用油漆把划痕补平，符合句意，正确答案。", "擦": "搭配：擦用于擦去污渍，不能用油漆来擦划痕。", "打碎": "语义：打碎会弄坏桌面，与「填补划痕」的意思相反。"}, "sentence_index": 6, "correct_answer": "填补"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人填补了坏掉的水管。", "explanation": "这里应该用〈修复〉。填补是把缺口补满，坏掉的水管要修复，不是补满缺口。"}, {"text": "我们要填补这次失误。", "explanation": "这里应该用〈补救〉。填补针对空缺，失误要用补救。"}, {"text": "他周末去填补数学。", "explanation": "这里应该用〈补习〉。填补指补上空缺，补课学习要用补习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修理工用沥青了填补路面的裂缝。", "corrected_sentence": "修理工用沥青填补路面的裂缝。", "error_description": "错误：「了」被放在了动词「填补」之前，位置错误。「了」只能放在动词之后表示动作完成（如「填补了」），这里不需要「了」，直接说「用沥青填补路面的裂缝」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明用橡皮泥填补很平整。", "corrected_sentence": "小明用橡皮泥填补得很平整。", "error_description": "错误：填补后面接补语「很平整」，中间漏掉了「得」。正确形式是「填补得很平整」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
