INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "补足空缺。", "primary_collocate": null, "pronunciation": "tián bǔ", "ipa": "tʰjɛn˧˥ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这项技术填补了国内的空白。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司招了新人，填补人才缺口。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她来填补老张留下的空缺。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书填补了这个领域的空白。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府想办法填补财政缺口。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读了很多书，想填补知识上的空白。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队请来新球员，填补了后卫的空缺。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要尽快填补管理上的漏洞。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店填补了小区没有超市的空缺。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用自己的钱填补了公司的亏空。", "target_word": "填补", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "填补了", "label": "完成体"}, {"form": "填补过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "补足人员、知识、领域、资金等方面的空白或缺口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复制", "is_correct": false, "explanation": "语义：复制是照样再做一份，与「填补空白」的意思不符。"}, {"text": "填补", "is_correct": true, "explanation": "填补：补上国内的空白，符合句意，正确答案。"}, {"text": "清扫", "is_correct": false, "explanation": "搭配：清扫用于清除垃圾、灰尘，不能用来搭配「空白」。"}, {"text": "画", "is_correct": false, "explanation": "语义：画是描绘图形，与「技术填补空白」的意思不符。"}], "explanations": {"复制": "语义：复制是照样再做一份，与「填补空白」的意思不符。", "填补": "填补：补上国内的空白，符合句意，正确答案。", "清扫": "搭配：清扫用于清除垃圾、灰尘，不能用来搭配「空白」。", "画": "语义：画是描绘图形，与「技术填补空白」的意思不符。"}, "sentence_index": 0, "correct_answer": "填补"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要填补新的知识。", "explanation": "这里应该用〈补充〉。填补要求原有空白，这里是增加新内容，应用补充。"}, {"text": "公司填补了几个员工。", "explanation": "这里应该用〈增加〉。填补是补上已有的空缺，招聘新员工这种人数增多要用增加。"}, {"text": "这次改革填补了工作效率。", "explanation": "这里应该用〈提高〉。填补用于空缺、空白，效率要用提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失去", "is_correct": false, "explanation": "语义：失去是丢掉，与「请来新球员补上空缺」的意思相反。"}, {"text": "填补", "is_correct": true, "explanation": "填补：新球员补上后卫的空缺，符合句意，正确答案。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪用于枝叶、头发等，不能用来修剪空缺。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：挑选的对象是人或物，空缺不能被挑选。"}], "explanations": {"失去": "语义：失去是丢掉，与「请来新球员补上空缺」的意思相反。", "填补": "填补：新球员补上后卫的空缺，符合句意，正确答案。", "修剪": "搭配：修剪用于枝叶、头发等，不能用来修剪空缺。", "挑选": "搭配：挑选的对象是人或物，空缺不能被挑选。"}, "sentence_index": 6, "correct_answer": "填补"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用自己的钱填补了公司的债务。", "explanation": "这里应该用〈偿还〉。填补针对空缺或亏空，归还欠款要用偿还。"}, {"text": "我们要尽快填补误会。", "explanation": "这里应该用〈消除〉。填补针对缺失之处，误会是要排除的问题，要用消除。"}, {"text": "这次聚会填补了许多乐趣。", "explanation": "这里应该用〈增添〉。填补是补上空缺，给聚会增加乐趣要用增添。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种新材料了填补市场上的空白。", "corrected_sentence": "这种新材料填补市场上的空白。", "error_description": "错误：「了」被放在了动词「填补」之前，位置错误。「了」只能放在动词之后表示动作完成（如「填补了」），这里不需要「了」，直接说「这种新材料填补市场上的空白」即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套方案把管理上的漏洞填补很完整。", "corrected_sentence": "这套方案把管理上的漏洞填补得很完整。", "error_description": "错误：填补后面接补语「很完整」，中间漏掉了「得」。正确形式是「填补得很完整」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
