INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姑娘是年纪不大的女孩子。", "primary_collocate": null, "pronunciation": "gū niang", "ipa": "ku˥ njɑŋ", "syllable_count": 2, "sentences": [{"text": "那个姑娘在公园里玩球。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个姑娘才八岁，已经会画画了。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姑娘穿着新鞋子很高兴。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里有十个姑娘，十五个男孩。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个姑娘哭了，妈妈马上抱起她。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姑娘们在教室里唱歌。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个姑娘很聪明，爱看书。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁的姑娘每天跟奶奶散步。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩给姑娘讲了一个笑话。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姑娘拿着气球，笑得很开心。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "小姑娘", "label": "复合"}], "register": "口语", "sense_fingerprint": "年纪不大的女孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会在公园里玩球。"}, {"text": "姑娘", "is_correct": true, "explanation": "姑娘：指年纪小的女孩子，能在公园玩球，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能玩球。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“玩球”要求能主动活动的主体，汽车不能这样搭配。"}], "explanations": {"桌子": "语义：桌子是家具，不会在公园里玩球。", "姑娘": "姑娘：指年纪小的女孩子，能在公园玩球，符合语境。", "石头": "语义：石头是无生命的物体，不能玩球。", "汽车": "搭配：“玩球”要求能主动活动的主体，汽车不能这样搭配。"}, "sentence_index": 0, "correct_answer": "姑娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位姑娘已经七十岁了。", "explanation": "这里应该用〈老奶奶〉。姑娘指年纪不大的女孩子，不用来指七十岁的老人。"}, {"text": "我哥哥是个很高的姑娘。", "explanation": "这里应该用〈小伙子〉。姑娘指女孩子，不能指男性的哥哥。"}, {"text": "这位姑娘已经八十岁了。", "explanation": "这里应该用〈老太太〉。姑娘指年纪不大的女孩子，不能用来指八十岁的老人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不会看书，与“爱看书”矛盾。"}, {"text": "姑娘", "is_correct": true, "explanation": "姑娘：指年纪不大的女孩子，聪明、爱看书，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“爱看书”要求有意识的人作主语，冰箱不能。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯是器物，不能聪明，也不会看书。"}], "explanations": {"老虎": "语义：老虎是动物，不会看书，与“爱看书”矛盾。", "姑娘": "姑娘：指年纪不大的女孩子，聪明、爱看书，符合语境。", "冰箱": "搭配：“爱看书”要求有意识的人作主语，冰箱不能。", "茶杯": "语义：茶杯是器物，不能聪明，也不会看书。"}, "sentence_index": 6, "correct_answer": "姑娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位姑娘已经有八个孙子了。", "explanation": "这里应该用〈老大娘〉。姑娘指年纪不大的女孩子，不能指已有孙子的老人。"}, {"text": "这位姑娘已经退休了。", "explanation": "这里应该用〈老太太〉。姑娘指年纪不大的女孩子，不能指已经退休的老年女性。"}, {"text": "那位姑娘今年九十岁了。", "explanation": "这里应该用〈老婆婆〉。姑娘指年纪不大的女孩子，不能指九十岁的老人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那三个小姑娘们在公园里玩球。", "corrected_sentence": "那三个小姑娘在公园里玩球。", "error_description": "“小姑娘们”的“们”与数词“三个”同用是多余的，应说“三个小姑娘”，不说“三个小姑娘们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "隔壁来了一只小姑娘，很活泼。", "corrected_sentence": "隔壁来了一位小姑娘，很活泼。", "error_description": "“小姑娘”指人，计量时应用“位”或“个”，不用“只”（“只”用于动物等）。应说“一位小姑娘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
