INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年轻的未婚女子；也指女孩儿。", "primary_collocate": null, "pronunciation": "gū niang", "ipa": "ku˥ njɑŋ", "syllable_count": 2, "sentences": [{"text": "那个姑娘穿着红裙子。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位姑娘长得很漂亮。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伙子看见姑娘，脸一下红了。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姑娘，请问去车站怎么走？", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的姑娘都会唱歌。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是个没结婚的姑娘。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个姑娘正在河边洗衣服。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱上了一位善良的姑娘。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姑娘笑着把花送给了他。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻姑娘在花店工作。", "target_word": "姑娘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "小姑娘", "label": "复合"}], "register": "口语", "sense_fingerprint": "年轻的未婚女子，也指女孩儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“穿着”要求人或动物作主语，石头不能穿衣服。"}, {"text": "姑娘", "is_correct": true, "explanation": "姑娘：指年轻女子，能穿红裙子，符合语境。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，穿红裙子与常理不符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“穿着”不能用于桌子这类家具。"}], "explanations": {"石头": "搭配：“穿着”要求人或动物作主语，石头不能穿衣服。", "姑娘": "姑娘：指年轻女子，能穿红裙子，符合语境。", "老虎": "语义：老虎是动物，穿红裙子与常理不符。", "桌子": "搭配：“穿着”不能用于桌子这类家具。"}, "sentence_index": 0, "correct_answer": "姑娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位姑娘是我的母亲。", "explanation": "这里不应用“姑娘”。姑娘指未婚的年轻女子，与“是我的母亲”（已婚长辈）矛盾。"}, {"text": "那个姑娘是我爸爸的哥哥。", "explanation": "这里不应用“姑娘”。姑娘指年轻女子，不能指男性长辈。"}, {"text": "这个姑娘是我的妻子。", "explanation": "这里不应用“姑娘”。姑娘指未婚的年轻女子，与“是我的妻子”（已婚）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不会洗衣服。"}, {"text": "姑娘", "is_correct": true, "explanation": "姑娘：指女性，能在河边洗衣服，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“洗衣服”要求有行为能力的人作主语，冰箱不能。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“洗衣服”要求有行为能力的人作主语，汽车不能。"}], "explanations": {"书包": "语义：书包是物品，不会洗衣服。", "姑娘": "姑娘：指女性，能在河边洗衣服，符合语境。", "冰箱": "搭配：“洗衣服”要求有行为能力的人作主语，冰箱不能。", "汽车": "搭配：“洗衣服”要求有行为能力的人作主语，汽车不能。"}, "sentence_index": 6, "correct_answer": "姑娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位姑娘已经退休了，每天在公园下棋。", "explanation": "这里应该用〈老太太〉。姑娘指年轻未婚的女子，与“已经退休”矛盾，不能指退休的老年女性。"}, {"text": "这位姑娘七十岁了，还在带孙子。", "explanation": "这里应该用〈老太太〉。姑娘指年轻女子，不能指七十岁的老人。"}, {"text": "那位姑娘正在教孙子写字。", "explanation": "这里应该用〈老妇人〉。“教孙子”说明是长辈，姑娘指年轻女子，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那三个姑娘们在河边唱歌。", "corrected_sentence": "那三个姑娘在河边唱歌。", "error_description": "“姑娘们”的“们”与数词“三个”同用是多余的，应说“三个姑娘”，不说“三个姑娘们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里来了一只新姑娘，很活泼。", "corrected_sentence": "班里来了一个新姑娘，很活泼。", "error_description": "“姑娘”指人，计量时应用“个”或“位”，不用“只”（“只”用于动物等）。应说“一个新姑娘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
