INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88489, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行政管理是政府或机关把日常的事安排好。", "primary_collocate": null, "pronunciation": "xíng zhèng guǎn lǐ", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "这所学校的行政管理做得很好。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在公司负责行政管理。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的行政管理能让大家工作更方便。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学校做行政管理工作，以后想去政府部门。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的行政管理很有条理，老师们都很满意。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的行政管理需要很多耐心。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室总是不够用，说明行政管理需要改进。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对行政管理很感兴趣。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的行政管理越来越规范了。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想请一位懂行政管理的人。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政管理部门", "label": "复合"}], "register": "书面", "sense_fingerprint": "政府或机关把日常事务安排妥当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政管理", "is_correct": true, "explanation": "正确：行政管理指学校、机关等安排日常事务的工作，“这所学校的行政管理做得很好”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能被“做”，学校的工作才能说“做得很好”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或物的重量，不是学校的工作内容。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是微生物或有害程序，与学校的管理工作无关。"}], "explanations": {"行政管理": "正确：行政管理指学校、机关等安排日常事务的工作，“这所学校的行政管理做得很好”符合语境。", "天气": "搭配：“天气”不能被“做”，学校的工作才能说“做得很好”。", "体重": "语义：体重是人或物的重量，不是学校的工作内容。", "病毒": "语义：病毒是微生物或有害程序，与学校的管理工作无关。"}, "sentence_index": 0, "correct_answer": "行政管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个行政管理很好吃，我想再吃一碗。", "explanation": "语义：这里把〈行政管理〉当作食物，但它指政府或机关把日常的事安排好，不能吃，也不能说“好吃”。"}, {"text": "行政管理在院子里玩耍。", "explanation": "语义：这里把〈行政管理〉当作会玩耍的活物，但它指政府或机关把日常的事安排好，不是有生命的东西，不能玩耍。"}, {"text": "她的行政管理很高，大家都很佩服她。", "explanation": "这里应该用〈水平〉。行政管理的高低要说“水平”，不说“行政管理很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政管理", "is_correct": true, "explanation": "正确：会议室不够用说明管理方面需要改进，“行政管理需要改进”符合语境。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地面的高度，与会议室的管理无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是需要“改进”的管理对象，这句话说的是管理工作。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体态特征，不能用来指机构的管理。"}], "explanations": {"行政管理": "正确：会议室不够用说明管理方面需要改进，“行政管理需要改进”符合语境。", "海拔": "语义：海拔是地面的高度，与会议室的管理无关。", "颜色": "语义：颜色不是需要“改进”的管理对象，这句话说的是管理工作。", "身高": "体貌：身高是人的体态特征，不能用来指机构的管理。"}, "sentence_index": 6, "correct_answer": "行政管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司想请一位行政管理。", "explanation": "指人时要说〈行政管理人员〉。行政管理是工作领域，不能直接指人。"}, {"text": "公司想把行政管理搬到楼上。", "explanation": "语义：这里把〈行政管理〉当作可以搬动的东西，但它指政府或机关把日常的事安排好，不是实物；说机构所在的楼层，应用〈行政部门〉。"}, {"text": "公司想请一位行政管理很便宜的人。", "explanation": "搭配：行政管理没有价钱，不能说“很便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校开了一只行政管理课，很受欢迎。", "corrected_sentence": "学校开了一门行政管理课，很受欢迎。", "error_description": "量词错误：“行政管理课”作课程时，量词应用“门”，不用“只”。错误形式是“一只”，正确形式是“一门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我们的行政管理没改进了很多。", "corrected_sentence": "这个月我们的行政管理改进了很多。", "error_description": "否定与体标错误：“没”表示否定时不能与“了”同用。错误形式是“没改进了很多”，正确形式是“改进了很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
