INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家机关或组织处理日常事务的管理工作。", "primary_collocate": null, "pronunciation": "xíng zhèng guǎn lǐ", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "这个部门主要做行政管理工作。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行政管理要按照国家的规定来做。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的行政管理需要公开透明。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市政府做了十年行政管理工作。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行政管理和技术工作不一样。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织的行政管理由办公室负责。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学的行政管理需要不断完善。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她申请了一个行政管理的职位。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行政管理的目的是让机关正常工作。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家正在改进行政管理的方法。", "target_word": "行政管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政管理部门", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家机关或组织处理日常事务的管理工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5345ed11-06b2-4130-89ce-bb50ae77b3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政管理", "is_correct": true, "explanation": "正确：部门做的是处理日常事务的管理工作，“行政管理工作”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“做天气工作”不能说，“做”只接工作、事务。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“做……工作”要求的是工作领域，天空不是部门可以做的工作内容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是部门的工作。"}], "explanations": {"行政管理": "正确：部门做的是处理日常事务的管理工作，“行政管理工作”符合语境。", "天气": "搭配：“做天气工作”不能说，“做”只接工作、事务。", "天空": "语义：“做……工作”要求的是工作领域，天空不是部门可以做的工作内容。", "体重": "语义：体重是身体的重量，不是部门的工作。"}, "sentence_index": 0, "correct_answer": "行政管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市政府的行政管理下了一场大雨。", "explanation": "语义：这里把〈行政管理〉当作天气现象，但它指国家机关或组织处理日常事务的工作，不会下雨。"}, {"text": "他在市政府做的行政管理很咸。", "explanation": "搭配：行政管理没有味道，不能说“很咸”。"}, {"text": "他在市政府的行政管理跑得很快。", "explanation": "语义：行政管理是工作或制度，不会“跑”，应说办事效率高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政管理", "is_correct": true, "explanation": "正确：大学的管理工作需要不断完善，“行政管理需要完善”符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体态特征，不能用来指大学的管理。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能“完善”，大学的管理才需要完善。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地面高度，与大学的管理无关。"}], "explanations": {"行政管理": "正确：大学的管理工作需要不断完善，“行政管理需要完善”符合语境。", "身高": "体貌：身高是人的体态特征，不能用来指大学的管理。", "颜色": "语义：颜色不能“完善”，大学的管理才需要完善。", "海拔": "语义：海拔是地面高度，与大学的管理无关。"}, "sentence_index": 6, "correct_answer": "行政管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家正在请一位行政管理来工作。", "explanation": "指人时要说〈行政管理人员〉。行政管理是工作领域，不能直接指人。"}, {"text": "国家正在为行政管理送生日礼物。", "explanation": "语义：行政管理是抽象的工作和制度，不能收礼物，也不能过生日。"}, {"text": "国家正在给行政管理洗澡。", "explanation": "语义：行政管理是抽象的工作，不是人或动物，不能“洗澡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他接手了一只行政管理工作。", "corrected_sentence": "他接手了一项行政管理工作。", "error_description": "量词错误：“行政管理工作”应用“项”，不用“只”。错误形式是“一只”，正确形式是“一项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年国家的行政管理没改进了不少。", "corrected_sentence": "这几年国家的行政管理改进了不少。", "error_description": "否定与体标错误：“没”表示否定时不能与“了”同用。错误形式是“没改进了不少”，正确形式是“改进了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34fe6152-7971-4806-a660-cd4a4206742a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
