INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "拍摄好的电影胶片或视频,也指电影作品。", "primary_collocate": null, "pronunciation": "yǐng piàn", "ipa": "iŋ˨˩˦ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这部影片我已经看过三次了。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部影片是去年拍的。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演把影片剪短了十分钟。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节上，有很多外国影片。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部影片的声音和画面都很好。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室里放了一部教学影片。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部影片得过很多奖。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍的影片在网上有很多人看。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影片里的音乐很好听。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部影片只有九十分钟，不太长。", "target_word": "影片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}], "register": "中性", "sense_fingerprint": "拍摄完成的电影胶片、视频或电影作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "影片", "is_correct": true, "explanation": "“影片”指拍摄好的电影作品，可以用“部”计量，“看过三次了”符合语境。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“看”用于影像作品，音乐是用来听的，不能说看过三次音乐。"}, {"text": "录音", "is_correct": false, "explanation": "搭配：录音是用来听的，不能与“看过”搭配，与“看过三次了”冲突。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是用来玩的，不是可以“看过”的影像作品，与句子语境不符。"}], "explanations": {"影片": "“影片”指拍摄好的电影作品，可以用“部”计量，“看过三次了”符合语境。", "音乐": "搭配：“看”用于影像作品，音乐是用来听的，不能说看过三次音乐。", "录音": "搭配：录音是用来听的，不能与“看过”搭配，与“看过三次了”冲突。", "游戏": "语义：游戏是用来玩的，不是可以“看过”的影像作品，与句子语境不符。"}, "sentence_index": 0, "correct_answer": "影片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天读了一部影片，写了读后感。", "explanation": "这里应该用〈小说〉。读的是文字作品，影片是拍好的作品，要用“看”，不能说“读”。"}, {"text": "她用一个下午在纸上画了一张影片。", "explanation": "这里应该用〈画〉。画是用笔画出来的，影片是拍摄好的作品，不能用笔画。"}, {"text": "这部影片有四十集，每天播一集。", "explanation": "这里应该用〈电视剧〉。影片是一次放完的作品，不分集播出，分集播出的要用电视剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影片", "is_correct": true, "explanation": "“影片”是可以得奖的作品，“得过很多奖”符合语境。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“部”是作品的量词，乐器不用“部”计量，“这部乐器”不成立，句子只能用“影片”。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“部”不用于地图，地图用“张”计量，句子不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“部”不配面包，面包用“个”或“块”计量，句子不通。"}], "explanations": {"影片": "“影片”是可以得奖的作品，“得过很多奖”符合语境。", "乐器": "搭配：“部”是作品的量词，乐器不用“部”计量，“这部乐器”不成立，句子只能用“影片”。", "地图": "搭配：“部”不用于地图，地图用“张”计量，句子不通。", "面包": "搭配：“部”不配面包，面包用“个”或“块”计量，句子不通。"}, "sentence_index": 6, "correct_answer": "影片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在影片门口买了两张票，进去看电影。", "explanation": "这里应该用〈影院〉。影院是买票、放映的地方，影片是放映的内容，没有门口。"}, {"text": "这部影片在剧场里演了三个小时，演员很累。", "explanation": "这里应该用〈话剧〉。话剧是现场表演，影片是录制好的作品，不能在剧场现场演。"}, {"text": "我把一张影片贴在教室门口，大家都来看。", "explanation": "这里应该用〈海报〉。海报是可以贴的印刷品，影片是电影作品，不能贴在门口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天看了一张影片，很感动。", "corrected_sentence": "我昨天看了一部影片，很感动。", "error_description": "量词错误：“影片”作为作品应用“部”计量，“一张”应改为“一部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部影片我们一起看了完吧。", "corrected_sentence": "这部影片我们一起看完了吧。", "error_description": "补语语序错误：结果补语“完”应紧跟动词，说“看完了”，不能说“看了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
