INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88493, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "壮大是变得更大更强。", "primary_collocate": null, "pronunciation": "zhuàng dà", "ipa": "tʂwɑŋ˥˩ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这家小公司一年比一年壮大。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的队伍慢慢壮大了。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过十年努力，我们的力量壮大了。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学习小组一天天壮大。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友越来越多，我们的团队壮大起来了。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社团越来越壮大，有一百多人。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家发展了，经济也壮大了。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司已经壮大到五百人了。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的小店不断壮大，变成了大超市。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者队伍壮大以后，帮助的人更多了。", "target_word": "壮大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "壮大了", "label": "体标"}, {"form": "壮大起来", "label": "补语"}], "register": "中性", "sense_fingerprint": "自己变得更大更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3763d68d-fe1a-4cec-95df-e92983c5cf23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88493, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "壮大", "is_correct": true, "explanation": "正确：壮大（zhuàng dà）意思是变得更大更强。"}, {"text": "长大", "is_correct": false, "explanation": "zhǎng 与 zhuàng 韵母不同（少了 u），声调也不同；长大意思是成长变大。"}, {"text": "胀大", "is_correct": false, "explanation": "zhàng 与 zhuàng 韵母不同（少了 u），声调相同；胀大意思是因膨胀而变大。"}, {"text": "张大", "is_correct": false, "explanation": "zhāng 与 zhuàng 韵母不同（少了 u），声调也不同；张大意思是把东西撑开、扩大。"}], "explanations": {"壮大": "正确：壮大（zhuàng dà）意思是变得更大更强。", "长大": "zhǎng 与 zhuàng 韵母不同（少了 u），声调也不同；长大意思是成长变大。", "胀大": "zhàng 与 zhuàng 韵母不同（少了 u），声调相同；胀大意思是因膨胀而变大。", "张大": "zhāng 与 zhuàng 韵母不同（少了 u），声调也不同；张大意思是把东西撑开、扩大。"}, "sentence_index": null, "correct_answer": "壮大"}, "level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "正确：壮大指变得更大更强，与「一年比一年」的增长趋势相符。"}, {"text": "倒闭", "is_correct": false, "explanation": "语义：倒闭指企业停业垮掉，与「一年比一年」的增长趋势相反。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：结婚只用于人，不用于公司。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：唱歌是人的动作，不能用于公司，句子也不成立。"}], "explanations": {"壮大": "正确：壮大指变得更大更强，与「一年比一年」的增长趋势相符。", "倒闭": "语义：倒闭指企业停业垮掉，与「一年比一年」的增长趋势相反。", "结婚": "搭配：结婚只用于人，不用于公司。", "唱歌": "搭配：唱歌是人的动作，不能用于公司，句子也不成立。"}, "sentence_index": 0, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他通过锻炼壮大了体质，身体越来越好。", "explanation": "这里应该用〈增强〉。壮大多用于团体、组织或力量的变大，体质、能力等要用增强。"}, {"text": "这个月的房租壮大了不少。", "explanation": "这里应该用〈上涨〉。壮大指规模或力量变大变强，房租的涨价要用上涨。"}, {"text": "他的脸色这几天慢慢壮大起来。", "explanation": "这里应该用〈红润〉。壮大指规模或力量变大变强，脸色的好转要用红润。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88493, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "正确：壮大指经济变得更强，与「国家发展了」相符。"}, {"text": "消失", "is_correct": false, "explanation": "语义：消失与「发展了」的方向相反，句子前后矛盾。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：停滞指不再前进，与「国家发展了」的前后关系矛盾。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：迟到的主语应是人，不用于经济。"}], "explanations": {"壮大": "正确：壮大指经济变得更强，与「国家发展了」相符。", "消失": "语义：消失与「发展了」的方向相反，句子前后矛盾。", "停滞": "语义：停滞指不再前进，与「国家发展了」的前后关系矛盾。", "迟到": "搭配：迟到的主语应是人，不用于经济。"}, "sentence_index": 6, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "远处的这座大桥非常壮大。", "explanation": "这里应该用〈壮观〉。壮大用于团体或力量的变强，描述景象的雄伟要用壮观。"}, {"text": "他一顿饭吃了三碗，食欲特别壮大。", "explanation": "这里应该用〈旺盛〉。壮大不用于食欲，形容食欲大要用旺盛。"}, {"text": "这个月的工作非常壮大。", "explanation": "这里应该用〈繁忙〉。壮大指团体或力量变大，形容工作多要用繁忙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88493, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小公司这几年把壮大了。", "corrected_sentence": "这家小公司这几年壮大了。", "error_description": "错误形式是「把壮大了」，正确形式是「壮大了」。在这个义项中，「壮大」是不及物动词，不能用于「把」字句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88493, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店慢慢壮大下来了。", "corrected_sentence": "这家书店慢慢壮大起来了。", "error_description": "错误形式是「壮大下来」，正确形式是「壮大起来」。「起来」表示事物由少到多、由弱到强而持续发展，「下来」表示由动到静或由高到低，不能用于「壮大」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
