INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88494, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "壮大", "is_correct": true, "explanation": "正确：壮大（zhuàng dà）意思是使团体或力量变得强大。"}, {"text": "长大", "is_correct": false, "explanation": "zhǎng 与 zhuàng 韵母不同（少了 u），声调也不同；长大意思是成长变大。"}, {"text": "胀大", "is_correct": false, "explanation": "zhàng 与 zhuàng 韵母不同（少了 u），声调相同；胀大意思是因膨胀而变大。"}, {"text": "张大", "is_correct": false, "explanation": "zhāng 与 zhuàng 韵母不同（少了 u），声调也不同；张大意思是把东西撑开、扩大。"}], "explanations": {"壮大": "正确：壮大（zhuàng dà）意思是使团体或力量变得强大。", "长大": "zhǎng 与 zhuàng 韵母不同（少了 u），声调也不同；长大意思是成长变大。", "胀大": "zhàng 与 zhuàng 韵母不同（少了 u），声调相同；胀大意思是因膨胀而变大。", "张大": "zhāng 与 zhuàng 韵母不同（少了 u），声调也不同；张大意思是把东西撑开、扩大。"}, "sentence_index": null, "correct_answer": "壮大"}, "level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "正确：壮大指使力量变强大，与「努力」和「自己的力量」相符。"}, {"text": "倒闭", "is_correct": false, "explanation": "语义：倒闭指企业停业，与「努力」要让力量变强的意思相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是不及物动词，不能带宾语「自己的力量」。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：翻译的对象是语言或文字，不能用于「力量」。"}], "explanations": {"壮大": "正确：壮大指使力量变强大，与「努力」和「自己的力量」相符。", "倒闭": "语义：倒闭指企业停业，与「努力」要让力量变强的意思相反。", "睡觉": "配价：睡觉是不及物动词，不能带宾语「自己的力量」。", "翻译": "搭配：翻译的对象是语言或文字，不能用于「力量」。"}, "sentence_index": 0, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的学习成绩壮大了。", "explanation": "这里应该用〈提高〉。壮大用于团体或力量，成绩、水平的上升要用提高。"}, {"text": "这次旅行让我的眼界壮大了。", "explanation": "这里应该用〈开阔〉。壮大不修饰眼界，形容见识变广要用开阔。"}, {"text": "老师的讲解让我的知识壮大了很多。", "explanation": "这里应该用〈丰富〉。壮大指团体或力量变大，知识的增多要用丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壮大", "is_correct": true, "explanation": "正确：壮大指使经济变强，与「要发展教育」的目标相符。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：冷落指不重视，与「就要发展教育」的目标相反。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：消灭经济与「发展教育」的目标矛盾，句子不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：欣赏多用于作品、风景，不用于经济。"}], "explanations": {"壮大": "正确：壮大指使经济变强，与「要发展教育」的目标相符。", "冷落": "语义：冷落指不重视，与「就要发展教育」的目标相反。", "消灭": "语义：消灭经济与「发展教育」的目标矛盾，句子不通。", "欣赏": "搭配：欣赏多用于作品、风景，不用于经济。"}, "sentence_index": 6, "correct_answer": "壮大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力地壮大好习惯。", "explanation": "这里应该用〈保持〉。壮大用于团体或力量，习惯要用保持。"}, {"text": "我们花了一上午，把房间壮大得很干净。", "explanation": "这里应该用〈打扫〉。壮大表示力量或规模变大，房间变干净要用打扫。"}, {"text": "修理工壮大了这台电脑。", "explanation": "这里应该用〈维修〉。壮大指团体或力量变大，电脑出故障后修复要用维修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要努力壮大了本地的企业。", "corrected_sentence": "我们要努力壮大本地的企业。", "error_description": "错误形式是「壮大了本地的企业」，正确形式是「壮大本地的企业」。句中表示将来的愿望，「壮大」后面不能加表示完成的「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府希望让中小企业壮大下来。", "corrected_sentence": "政府希望让中小企业壮大起来。", "error_description": "错误形式是「壮大下来」，正确形式是「壮大起来」。「起来」表示由弱到强的持续变化，「下来」不能用于「壮大」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be51c686-fcf4-468c-b04e-498f8f788a98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
