INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个时期的几年之内；也指某一朝代某段时期。", "primary_collocate": null, "pronunciation": "nián jiān", "ipa": "njɛn˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "嘉庆年间，这条河发过大水。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷出生于民国年间。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝道光年间，这里有一家很大的茶馆。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年间，小镇变化很大。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那首诗是唐朝天宝年间写的。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宋朝绍兴年间，很多人喜欢喝茶。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这三年间，他学会了开车。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咸丰年间，这里发生了一场大火。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城墙是明朝洪武年间修的。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝正德年间，有人发现了这口井。", "target_word": "年间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "年间：几年之内，或某朝代的某段时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4833d5f1-cf75-4236-a0b9-bf3c5753a5f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地点", "is_correct": false, "explanation": "语义：“嘉庆”是年号，指时间，“地点”指场所，不能说明河流发大水的时期。"}, {"text": "年间", "is_correct": true, "explanation": "“年间”指某个年号之内的几年，此处是嘉庆年间，与“嘉庆”连用表示时期。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“嘉庆”后接的是时期，不能接“价格”，句子说的是河流的水灾。"}, {"text": "时刻", "is_correct": false, "explanation": "搭配：“时刻”指具体的一个时间点，不能与“嘉庆”这样的年号连用。"}], "explanations": {"地点": "语义：“嘉庆”是年号，指时间，“地点”指场所，不能说明河流发大水的时期。", "年间": "“年间”指某个年号之内的几年，此处是嘉庆年间，与“嘉庆”连用表示时期。", "价格": "语义：“嘉庆”后接的是时期，不能接“价格”，句子说的是河流的水灾。", "时刻": "搭配：“时刻”指具体的一个时间点，不能与“嘉庆”这样的年号连用。"}, "sentence_index": 0, "correct_answer": "年间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在旅行年间，他一直在拍照。", "explanation": "这里应该用〈期间〉。“年间”指几年之内的时期，“旅行期间”指旅行进行的时段，不说“旅行年间”。"}, {"text": "今天年间，小镇下了一场大雨。", "explanation": "这里应删去“年间”，“今天”已足够。“年间”指以年为单位的时期，不能用来指某一天。"}, {"text": "这三个年间，小镇变化很大。", "explanation": "“年间”前的数量不用量词“个”，应说“这三年间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：“在这三……”后接时间段，“人口”指人的总数，不能表示时间。"}, {"text": "年间", "is_correct": true, "explanation": "“年间”指几年之内的一段时期，与数量“三”连用表示时间跨度。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“在这三……”表示时间，“窗户”是物体，句子说的是学开车的时期。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：数词“三”后接“年”或“个月”等时间单位，“数字”不能直接跟在“三”后面表示时间。"}], "explanations": {"人口": "语义：“在这三……”后接时间段，“人口”指人的总数，不能表示时间。", "年间": "“年间”指几年之内的一段时期，与数量“三”连用表示时间跨度。", "窗户": "语义：“在这三……”表示时间，“窗户”是物体，句子说的是学开车的时期。", "数字": "搭配：数词“三”后接“年”或“个月”等时间单位，“数字”不能直接跟在“三”后面表示时间。"}, "sentence_index": 6, "correct_answer": "年间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明朝一个年间，有人发现了这口井。", "explanation": "“年间”前不用量词“个”，应说“明朝正德年间”。"}, {"text": "这个星期年间，有人发现了这口井。", "explanation": "这里应删去“年间”，“这个星期”已足够。“年间”只用于以年为单位的时期，不能用于一周。"}, {"text": "在试验年间，他们每天记录数据。", "explanation": "这里应该用〈阶段〉。“年间”指以年为单位的较长时期，不用来指“试验”这样的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这五个年间学会了三门外语。", "corrected_sentence": "他在这五年间学会了三门外语。", "error_description": "错误形式“五个年间”，正确形式“五年间”。“年间”前的数词后直接接“年”，不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在那几个年间攒够了钱买房。", "corrected_sentence": "他在那几年间攒够了钱买房。", "error_description": "错误形式“那几个年间”，正确形式“那几年间”。“年间”前的“几”后直接接“年”，不加量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b191e992-eefc-4e04-b3bd-8a4642e702a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
