INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88497, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行为艺术是用自己的身体动作来表现想法的艺术。", "primary_collocate": null, "pronunciation": "xíng wéi yì shù", "ipa": "ɕiŋ˧˥ weɪ˧˥ i˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "他在广场上做了一场行为艺术。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不懂这个行为艺术想说什么。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行为艺术用身体来表现想法。", "target_word": "行为艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢艺术，也很喜欢看行为艺术。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女孩的行为艺术吸引了很多人。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看了一场行为艺术表演。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用行为艺术告诉大家要爱护环境。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行为艺术不用画笔，也不用音乐。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人在表演行为艺术，大家都围着看。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看到行为艺术时觉得很奇怪。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行為藝術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用身体动作表现想法的艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119ba6ca-7230-41f9-9941-35fce59bfea3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88497, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行为艺术", "is_correct": true, "explanation": "正确：「做了一场」搭配表演、活动类名词，行为艺术是用身体表演的艺术形式。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不是可以「做」的活动，不能与「一场」搭配。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：「做了一场」后面应是活动或表演，咖啡是饮料，不能「做一场」，应说「一杯咖啡」。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是场所，不是可以「做一场」的活动或表演。"}], "explanations": {"行为艺术": "正确：「做了一场」搭配表演、活动类名词，行为艺术是用身体表演的艺术形式。", "地铁": "语义：地铁是交通工具，不是可以「做」的活动，不能与「一场」搭配。", "咖啡": "搭配：「做了一场」后面应是活动或表演，咖啡是饮料，不能「做一场」，应说「一杯咖啡」。", "图书馆": "语义：图书馆是场所，不是可以「做一场」的活动或表演。"}, "sentence_index": 0, "correct_answer": "行为艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她喜欢艺术，也很喜欢看一只行为艺术。", "explanation": "这里应该用〈场〉。行为艺术是一场表演活动，量词用「场」；「只」用于动物或单个物品，不能数它。"}, {"text": "她喜欢艺术，也很喜欢吃行为艺术。", "explanation": "这里〈吃〉的宾语不能是行为艺术。它是身体动作的表演，不是可以吃的东西，应说「看」或「欣赏」。"}, {"text": "她喜欢艺术，也很喜欢在画布上画行为艺术。", "explanation": "这里的〈画〉不能以行为艺术为对象。行为艺术靠身体动作完成，不是画在画布上的作品，无论用「画」还是「绘画」都讲不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88497, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行为艺术", "is_correct": true, "explanation": "正确：「用某种方式告诉大家」需要一种表达手段，行为艺术可以承担这个作用。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能用来向大家传达「要爱护环境」这样的信息。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育用品，不能用来表达想法或告诉大家道理。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：「告诉」的工具一般是语言、文字或图像，不能说用「耳朵」去告诉别人。"}], "explanations": {"行为艺术": "正确：「用某种方式告诉大家」需要一种表达手段，行为艺术可以承担这个作用。", "冰箱": "语义：冰箱是家用电器，不能用来向大家传达「要爱护环境」这样的信息。", "篮球": "语义：篮球是体育用品，不能用来表达想法或告诉大家道理。", "耳朵": "搭配：「告诉」的工具一般是语言、文字或图像，不能说用「耳朵」去告诉别人。"}, "sentence_index": 6, "correct_answer": "行为艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我第一次搬行为艺术时觉得很沉。", "explanation": "这里应该用〈雕塑〉。搬运的是有重量的实物作品，行为艺术是身体表演，不是可以搬动的东西。"}, {"text": "我第一次看到行为艺术时觉得它很咸。", "explanation": "这里〈咸〉只用于味道。行为艺术是身体表演，没有味道，不能这样形容它。"}, {"text": "我第一次看到一把行为艺术时觉得很奇怪。", "explanation": "这里应该用〈场〉。「把」用于有柄的物品，行为艺术是一场表演，不能用「把」来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我去看了一只行为艺术。", "corrected_sentence": "周末我去看了一场行为艺术。", "error_description": "错误形式：「一只」；正确形式：「一场」。「只」用于动物或单个物品，行为艺术是一场表演，应使用量词「场」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前看了过一场行为艺术。", "corrected_sentence": "我以前看过一场行为艺术。", "error_description": "错误形式：「看了过」同时用了「了」和「过」两个动态助词。正确形式：「看过」，表示以前有过这种经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
