INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以艺术家的身体和行为为表现手段的当代艺术形式。", "primary_collocate": null, "pronunciation": "xíng wéi yì shù", "ipa": "ɕiŋ˧˥ weɪ˧˥ i˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "行为艺术是当代艺术的一种形式。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺术家以行为艺术出名。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美术馆里正在展出行为艺术作品。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用行为艺术表现城市生活的压力。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术家在街上躺了一整天，这是一次行为艺术。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻艺术家选择行为艺术来表达自己。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览里有绘画，也有行为艺术。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为艺术只有身体，没有任何道具。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行为艺术常常让观众参与进来。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场行为艺术只演了十分钟，却让人想了很久。", "target_word": "行为艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行為藝術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以艺术家身体和行为为手段的当代艺术形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119ba6ca-7230-41f9-9941-35fce59bfea3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行为艺术", "is_correct": true, "explanation": "正确：句子给出的是一种当代艺术形式，行为艺术正是以身体行为表现的当代艺术。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是艺术形式，与「当代艺术的一种形式」的定义相矛盾。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车是交通工具，不属于艺术形式，不能作为「当代艺术的一种」。"}, {"text": "哥们", "is_correct": false, "explanation": "语义：「哥们」指朋友，是人，不是艺术形式，不能作为「当代艺术的一种形式」。"}], "explanations": {"行为艺术": "正确：句子给出的是一种当代艺术形式，行为艺术正是以身体行为表现的当代艺术。", "数学": "语义：数学是一门学科，不是艺术形式，与「当代艺术的一种形式」的定义相矛盾。", "火车": "语义：火车是交通工具，不属于艺术形式，不能作为「当代艺术的一种」。", "哥们": "语义：「哥们」指朋友，是人，不是艺术形式，不能作为「当代艺术的一种形式」。"}, "sentence_index": 0, "correct_answer": "行为艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用一幅行为艺术表现城市生活的压力。", "explanation": "这里不能用〈幅〉。「幅」用于画作、照片，行为艺术是身体表演的艺术形式，不能这样数。"}, {"text": "她搬来行为艺术，用它表现城市生活的压力。", "explanation": "「搬」的对象必须是有形的实物。行为艺术是身体表演，不能被搬来。"}, {"text": "她用行为艺术吃掉城市生活的压力。", "explanation": "这里应该用〈表现〉。「吃」的对象是食物，「压力」不能被吃掉，句意不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行为艺术", "is_correct": true, "explanation": "正确：「也有」后面并列的是展览中的另一类作品，行为艺术可以作为展品出现。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不是展览的内容，不能与绘画并列作为展示。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，不属于展览内容，不能与绘画并列。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的感受，不是展品，不能与绘画并列出现在展览里。"}], "explanations": {"行为艺术": "正确：「也有」后面并列的是展览中的另一类作品，行为艺术可以作为展品出现。", "考试": "语义：考试是测验，不是展览的内容，不能与绘画并列作为展示。", "早餐": "语义：早餐是食物，不属于展览内容，不能与绘画并列。", "心情": "语义：心情是人的感受，不是展品，不能与绘画并列出现在展览里。"}, "sentence_index": 6, "correct_answer": "行为艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把行为艺术只演了十分钟，却让人想了很久。", "explanation": "这里应该用〈场〉。「把」用于有柄的物品，行为艺术是一场表演，不能用「把」来数。"}, {"text": "这场行为艺术的味道很苦，却让人想了很久。", "explanation": "这里〈苦〉用于味道。行为艺术是表演，没有味道，不能这样形容它。"}, {"text": "这场行为艺术只喝了十分钟，却让人想了很久。", "explanation": "这里应该用〈演〉。〈喝〉的宾语必须是饮品，行为艺术是表演，不能被「喝」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在研究一只行为艺术。", "corrected_sentence": "他在研究一种行为艺术。", "error_description": "错误形式：「一只」；正确形式：「一种」。「只」用于单个动物或物品，行为艺术是一种艺术类别，应使用量词「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前见了过一种行为艺术。", "corrected_sentence": "我以前见过一种行为艺术。", "error_description": "错误形式：「见了过」同时用了「了」和「过」两个动态助词。正确形式：「见过」，表示以前有过这种经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "成绩是做事或学习后得到的好坏结果。", "primary_collocate": null, "pronunciation": "chéng jì", "ipa": "tʂʰɤŋ˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这次考试，他的成绩很好。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的数学成绩比去年高了。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把成绩发给了大家。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天学习，成绩一直不错。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的成绩不好，妈妈有点儿担心。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩什么时候出来？", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的英语成绩是多少分？", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在看自己的成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学期，我的成绩进步了很多。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体育成绩比语文成绩好。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成績", "label": "繁体"}, {"form": "成绩单", "label": "复合"}], "register": "中性", "sense_fingerprint": "学习或考试后得到的分数和结果，好坏都可以", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外貌，与“这次考试”无关，不能说“这次考试，他的长相很好”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高度，与考试的结果无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不用“很好”来评价，“很好”不搭配体重。"}, {"text": "成绩", "is_correct": true, "explanation": "正确：成绩指考试后得到的结果，“这次考试，他的成绩很好”符合语境。"}], "explanations": {"长相": "体貌：“长相”指外貌，与“这次考试”无关，不能说“这次考试，他的长相很好”。", "身高": "语义：身高是身体的高度，与考试的结果无关。", "体重": "搭配：“体重”不用“很好”来评价，“很好”不搭配体重。", "成绩": "正确：成绩指考试后得到的结果，“这次考试，他的成绩很好”符合语境。"}, "sentence_index": 0, "correct_answer": "成绩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行让我有了很多成绩。", "explanation": "这里应该用〈收获〉。成绩指做事或学习后得到的好坏结果，旅行中的体会和见闻要用收获。"}, {"text": "这次比赛的成绩是一万元。", "explanation": "这里应该用〈奖金〉。成绩指做事或学习后得到的好坏结果，不能用来表示钱数，钱数要说奖金。"}, {"text": "他每年都要付很多成绩。", "explanation": "这里应该用〈学费〉。成绩是做事或学习后得到的结果，不能用来付，要付的是学费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成绩", "is_correct": true, "explanation": "正确：问“多少分”的是考试的成绩，“英语成绩”符合语境。"}, {"text": "名次", "is_correct": false, "explanation": "搭配：“多少分”问的是分数，“名次”是排列位置，不能用“多少分”提问。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”与英语分数无关，不能问“英语脾气是多少分”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“英语心情”不成立，心情不是学科的分数，“多少分”问的是英语成绩。"}], "explanations": {"成绩": "正确：问“多少分”的是考试的成绩，“英语成绩”符合语境。", "名次": "搭配：“多少分”问的是分数，“名次”是排列位置，不能用“多少分”提问。", "脾气": "语义：“脾气”与英语分数无关，不能问“英语脾气是多少分”。", "心情": "语义：“英语心情”不成立，心情不是学科的分数，“多少分”问的是英语成绩。"}, "sentence_index": 6, "correct_answer": "成绩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这个月的成绩增加了三公斤。", "explanation": "这里应该用〈体重〉。成绩是做事或学习后得到的结果，不能用公斤计量，说体重增加才用公斤。"}, {"text": "我家的成绩有三层楼。", "explanation": "这里应该用〈房子〉。成绩是结果，不是建筑，说几层楼要用房子。"}, {"text": "我闻到了成绩的香味。", "explanation": "这里应该用〈咖啡〉。成绩是做事或学习后的结果，没有香味，闻到的香味来自咖啡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的数学成绩很开心。", "corrected_sentence": "他的数学成绩很好。", "error_description": "搭配错误：“成绩”是结果，不能“开心”；形容成绩的好坏要用“好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拿到了一张很好的成绩。", "corrected_sentence": "他拿到了一个很好的成绩。", "error_description": "量词错误：“成绩”应使用量词“个”，“张”用于纸、桌子等平面物品，不能说“一张成绩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88500, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
