INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作或学习取得的结果,多指好的结果。", "primary_collocate": null, "pronunciation": "chéng jì", "ipa": "tʂʰɤŋ˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "经过一年的努力，他取得了好成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的工作成绩很好。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们辛苦一年，终于有了成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板夸他在工作中做出了成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍在比赛中取得了好成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看成绩，也要看过程。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些成绩是大家一起做出来的。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来公司，就拿出了不错的成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，我们的科学研究取得了很大的成绩。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了这些成绩，大家都很高兴。", "target_word": "成绩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成績", "label": "繁体"}, {"form": "成绩单", "label": "复合"}], "register": "中性", "sense_fingerprint": "工作、比赛或研究中取得的成果，多指好的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27aa944-4970-41c8-bf8a-939657fdc139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人活了多久，不是努力取得的结果，不能说“取得了好年龄”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高度，不是努力的结果。"}, {"text": "成绩", "is_correct": true, "explanation": "正确：取得成绩是常见搭配，指工作、学习等取得的好结果，与“经过一年的努力”相符。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是物体占的空间，与努力的结果无关。"}], "explanations": {"年龄": "语义：年龄是人活了多久，不是努力取得的结果，不能说“取得了好年龄”。", "身高": "语义：身高是身体的高度，不是努力的结果。", "成绩": "正确：取得成绩是常见搭配，指工作、学习等取得的好结果，与“经过一年的努力”相符。", "体积": "语义：体积是物体占的空间，与努力的结果无关。"}, "sentence_index": 0, "correct_answer": "成绩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次散步让我有了很多成绩。", "explanation": "这里应该用〈收获〉。成绩指工作或学习取得的结果，散步中的体会要用收获。"}, {"text": "从我家到学校的成绩很远。", "explanation": "这里应该用〈路程〉。成绩是工作或学习取得的结果，不能用来说距离，距离远要用路程。"}, {"text": "我每天早上都洗成绩。", "explanation": "这里应该用〈脸〉。成绩是工作或学习取得的结果，不能用来洗，早上洗的是脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人活了多久，不能由大家一起做出来。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外貌，不能说“一起做出来”。"}, {"text": "成绩", "is_correct": true, "explanation": "正确：成绩是靠大家努力做出来的结果，“做出来”搭配成绩。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，与“做出来”无关。"}], "explanations": {"年龄": "语义：年龄是人活了多久，不能由大家一起做出来。", "长相": "体貌：“长相”指外貌，不能说“一起做出来”。", "成绩": "正确：成绩是靠大家努力做出来的结果，“做出来”搭配成绩。", "体温": "语义：体温是身体的温度，与“做出来”无关。"}, "sentence_index": 6, "correct_answer": "成绩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对这次旅行的成绩很深。", "explanation": "这里应该用〈感受〉。成绩指工作、学习或比赛中取得的结果，内心的感受要用感受。"}, {"text": "他的成绩很好听。", "explanation": "这里应该用〈声音〉。成绩是结果，不能用“好听”来形容，形容声音才说好听。"}, {"text": "我的成绩是九千元。", "explanation": "这里应该用〈工资〉。成绩是做事或学习后的结果，不是钱，说多少钱要用工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这一年在工作中取得了不错地成绩。", "corrected_sentence": "他这一年在工作中取得了不错的成绩。", "error_description": "结构助词错误：“成绩”前的修饰语应用“的”，“地”用于修饰动词、形容词等谓语性成分，不能用在名词前，应说“不错的成绩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个部门今年做出了一块很好的成绩。", "corrected_sentence": "这个部门今年做出了一个很好的成绩。", "error_description": "量词错误：“成绩”应使用量词“个”或“项”，“块”用于成块的东西，不能用于成绩。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0532ba-6252-44e5-9717-9238022b99fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
