INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88501, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "外派是被公司或国家派到别的地方去工作。", "primary_collocate": null, "pronunciation": "wài pài", "ipa": "wai˥˩ pʰai˥˩", "syllable_count": 2, "sentences": [{"text": "公司要把他外派到上海工作。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司去年外派了我哥哥去日本。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想外派，因为孩子还很小。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经外派过两年，很想家。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算外派几个人去美国办公室。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外派的工作很辛苦，他常常想家。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王外派到非洲以后，很少回家。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定外派小李去北京分公司工作。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外派期间，公司给他租了房子。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿意外派到别的国家工作吗？", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外派了", "label": "体标"}, {"form": "外派过", "label": "体标"}, {"form": "外派人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "公司或国家派人到外地或外国工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88501, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外派", "is_correct": true, "explanation": "正确：“外派”指被公司或国家派到外地或外国工作。"}, {"text": "外卖", "is_correct": false, "explanation": "pài 与 mài 只有声母不同（p／m），意思是送餐上门或在外售卖的食物。"}, {"text": "外拍", "is_correct": false, "explanation": "pài（第四声）与 pāi（第一声）声调不同，意思是在户外拍摄。"}, {"text": "歪派", "is_correct": false, "explanation": "wài（第四声）与 wāi（第一声）声调不同，意思是硬把错误或罪名加到别人身上。"}], "explanations": {"外派": "正确：“外派”指被公司或国家派到外地或外国工作。", "外卖": "pài 与 mài 只有声母不同（p／m），意思是送餐上门或在外售卖的食物。", "外拍": "pài（第四声）与 pāi（第一声）声调不同，意思是在户外拍摄。", "歪派": "wài（第四声）与 wāi（第一声）声调不同，意思是硬把错误或罪名加到别人身上。"}, "sentence_index": null, "correct_answer": "外派"}, "level_3": {"options": [{"text": "外派", "is_correct": true, "explanation": "正确：“外派”指被派到外地工作，与“到上海工作”相合。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”指解雇，与“到上海工作”的派遣意思相反。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指结束工作，不能与“到上海工作”搭配。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：“辞职”是不及物动词，不能带“把他”的宾语。"}], "explanations": {"外派": "正确：“外派”指被派到外地工作，与“到上海工作”相合。", "辞退": "语义：“辞退”指解雇，与“到上海工作”的派遣意思相反。", "退休": "语义：“退休”指结束工作，不能与“到上海工作”搭配。", "辞职": "配价：“辞职”是不及物动词，不能带“把他”的宾语。"}, "sentence_index": 0, "correct_answer": "外派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我和朋友去北京外派。", "explanation": "这里应该用〈旅游〉。外派指公司或国家派人去外地工作，周末去北京玩不能说外派。"}, {"text": "我每天晚饭后去公园外派。", "explanation": "这里应该用〈散步〉。外派指被派去外地工作，饭后在公园散步不能说外派。"}, {"text": "我每天下午在操场外派。", "explanation": "这里应该用〈跑步〉。外派指被派去外地工作，在操场跑步不能说外派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88501, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外派", "is_correct": true, "explanation": "正确：“外派”指被派到外地工作，与“到非洲以后”的语境相合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是休闲活动，不能表示被派去外地工作。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“到非洲以后”的去向语境不搭。"}, {"text": "病倒", "is_correct": false, "explanation": "配价：“病倒”不能带“到+地点”的补语。"}], "explanations": {"外派": "正确：“外派”指被派到外地工作，与“到非洲以后”的语境相合。", "散步": "语义：“散步”是休闲活动，不能表示被派去外地工作。", "睡觉": "语义：“睡觉”与“到非洲以后”的去向语境不搭。", "病倒": "配价：“病倒”不能带“到+地点”的补语。"}, "sentence_index": 6, "correct_answer": "外派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我和妈妈去超市外派。", "explanation": "这里应该用〈买菜〉。外派指被派去外地工作，去超市买东西不能说外派。"}, {"text": "春节我要回老家外派。", "explanation": "这里应该用〈探亲〉。外派指被派去外地工作，回家看望亲人应说“探亲”。"}, {"text": "妈妈每天在厨房外派，做得很好吃。", "explanation": "这里应该用〈做饭〉。外派指被派去外地工作，在厨房做饭不能说外派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88501, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友下个月要外派了到伦敦工作。", "corrected_sentence": "我的朋友下个月要外派到伦敦工作。", "error_description": "“了”不能插在“外派”和“到”之间；且“下个月要”指将来，不能用“了”。应删去“了”，说“外派到伦敦工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88501, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥外派了过三次，每次都很辛苦。", "corrected_sentence": "我哥哥外派过三次，每次都很辛苦。", "error_description": "“了”与“过”不能同时用在动词后：表示经历的“过”不与“了”并用，应去掉“了”，说“外派过三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
