INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被派往外地或外国工作。", "primary_collocate": null, "pronunciation": "wài pài", "ipa": "wai˥˩ pʰai˥˩", "syllable_count": 2, "sentences": [{"text": "他从大学毕业后，就外派到南方的分公司。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生外派到山区，帮助那里的病人。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家外派了很多老师去农村学校。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫外派到国外，一年只回来一次。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把我外派到了一个很小的城市。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说下个月要外派一批工程师。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外派到南京工作后，要自己做饭了。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他外派了三年才回到总公司。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外派的人能拿到更多的工资。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们外派以前，先开了一次会。", "target_word": "外派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外派了", "label": "体标"}, {"form": "外派过", "label": "体标"}, {"form": "外派人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "被派往外地或外国工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfb60cc5-2c9b-4622-a473-6ce24ef464ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88502, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外派", "is_correct": true, "explanation": "正确：“外派”指被派往外地或外国工作。"}, {"text": "外卖", "is_correct": false, "explanation": "pài 与 mài 只有声母不同（p／m），意思是送餐上门或在外售卖的食物。"}, {"text": "外拍", "is_correct": false, "explanation": "pài（第四声）与 pāi（第一声）声调不同，意思是在户外拍摄。"}, {"text": "歪派", "is_correct": false, "explanation": "wài（第四声）与 wāi（第一声）声调不同，意思是硬把错误或罪名加到别人身上。"}], "explanations": {"外派": "正确：“外派”指被派往外地或外国工作。", "外卖": "pài 与 mài 只有声母不同（p／m），意思是送餐上门或在外售卖的食物。", "外拍": "pài（第四声）与 pāi（第一声）声调不同，意思是在户外拍摄。", "歪派": "wài（第四声）与 wāi（第一声）声调不同，意思是硬把错误或罪名加到别人身上。"}, "sentence_index": null, "correct_answer": "外派"}, "level_3": {"options": [{"text": "外派", "is_correct": true, "explanation": "正确：“外派”指被派往外地工作，与“到南方的分公司”相合。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“大学毕业后”去工作的语境矛盾。"}, {"text": "留学", "is_correct": false, "explanation": "语义：“留学”指到国外读书，与“到南方的分公司”工作不符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指在学校读书，与“大学毕业后”去分公司工作矛盾。"}], "explanations": {"外派": "正确：“外派”指被派往外地工作，与“到南方的分公司”相合。", "退休": "语义：“退休”指离开工作岗位，与“大学毕业后”去工作的语境矛盾。", "留学": "语义：“留学”指到国外读书，与“到南方的分公司”工作不符。", "上学": "语义：“上学”指在学校读书，与“大学毕业后”去分公司工作矛盾。"}, "sentence_index": 0, "correct_answer": "外派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假期他和朋友去云南外派。", "explanation": "这里应该用〈旅行〉。外派指被派去外地工作，休闲出游应说“旅行”。"}, {"text": "我表妹去医院外派，住了两天。", "explanation": "这里应该用〈看病〉。外派指被派去外地工作，去医院治病应说“看病”。"}, {"text": "春节我要回老家外派，住一个星期。", "explanation": "这里应该用〈探亲〉。外派指被派去外地工作，回家看望亲人应说“探亲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外派", "is_correct": true, "explanation": "正确：“外派”指被派往外地工作，与“到南京工作后”的语境相合。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”指去国外，南京在国内，与“到南京工作”矛盾。"}, {"text": "下岗", "is_correct": false, "explanation": "语义：“下岗”指失去工作，与“到南京工作”正好相反。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是体育活动，不能表示被派去外地工作。"}], "explanations": {"外派": "正确：“外派”指被派往外地工作，与“到南京工作后”的语境相合。", "出国": "语义：“出国”指去国外，南京在国内，与“到南京工作”矛盾。", "下岗": "语义：“下岗”指失去工作，与“到南京工作”正好相反。", "游泳": "语义：“游泳”是体育活动，不能表示被派去外地工作。"}, "sentence_index": 6, "correct_answer": "外派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我和朋友去商场外派。", "explanation": "这里应该用〈逛街〉。外派指被派到外地或外国工作，购物休闲不能说外派。"}, {"text": "他每天坐地铁外派。", "explanation": "这里应该用〈上班〉。外派指被派到外地工作，每天在本地通勤应说“上班”。"}, {"text": "奶奶每天早上去公园外派。", "explanation": "这里应该用〈锻炼〉。外派指被派去工作，早晨在公园锻炼身体不能说外派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次公司外派着小张到成都工作。", "corrected_sentence": "这次公司外派小张到成都工作。", "error_description": "体标误用：“外派”是一次性的派遣动作，不能带表示持续的“着”，应去掉“着”，说“外派小张到成都工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的同事外派了过两次，回来后都很累。", "corrected_sentence": "我的同事外派过两次，回来后都很累。", "error_description": "“了”与“过”不能同时用在动词后：表示经历的“过”不与“了”并用，应去掉“了”，说“外派过两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2edd13e3-0dfc-4492-8163-e0f64239493b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
