INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "爱国是很爱自己的国家。", "primary_collocate": null, "pronunciation": "ài guó", "ipa": "ai̯˥˩ kuo̯˧˥", "syllable_count": 2, "sentences": [{"text": "那位军人特别爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你爱国吗？我当然爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国的学生在广场上唱起了国歌。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生都给了国家，真是爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到国旗升起，他激动得流了泪，因为他爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱国，看到国旗就会站直。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说长大后要当兵，因为他爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家爱国，放弃国外的好工作回来了。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国的人不会做伤害国家的事。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐爱国，一直关心国家大事。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愛國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很爱自己的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88503, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱国", "is_correct": true, "explanation": "正确答案，意思是很爱自己的国家。"}, {"text": "外国", "is_correct": false, "explanation": "wài 与 ài 相比多了声母 w，意思是外国，不是爱国。"}, {"text": "卖国", "is_correct": false, "explanation": "mài（第四声）与 ài（第四声）声母不同，意思是出卖国家，与爱国相反。"}, {"text": "爱过", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，意思是曾经爱。"}], "explanations": {"爱国": "正确答案，意思是很爱自己的国家。", "外国": "wài 与 ài 相比多了声母 w，意思是外国，不是爱国。", "卖国": "mài（第四声）与 ài（第四声）声母不同，意思是出卖国家，与爱国相反。", "爱过": "guò（第四声）与 guó（第二声）声调不同，意思是曾经爱。"}, "sentence_index": null, "correct_answer": "爱国"}, "level_3": {"options": [{"text": "爱国", "is_correct": true, "explanation": "正确答案，“爱国”表示很爱自己的国家，填入后符合“那位军人”的形象。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”指认输屈服，与“军人特别……”的形象矛盾。"}, {"text": "叛变", "is_correct": false, "explanation": "语义：“叛变”指背叛所属的阵营，与军人的形象矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”指躲开责任或困难，与“那位军人特别……”的正面形象矛盾。"}], "explanations": {"爱国": "正确答案，“爱国”表示很爱自己的国家，填入后符合“那位军人”的形象。", "投降": "语义：“投降”指认输屈服，与“军人特别……”的形象矛盾。", "叛变": "语义：“叛变”指背叛所属的阵营，与军人的形象矛盾。", "逃避": "语义：“逃避”指躲开责任或困难，与“那位军人特别……”的正面形象矛盾。"}, "sentence_index": 0, "correct_answer": "爱国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消防员要爱国居民，帮他们脱险。", "explanation": "这里应该用〈保护〉。“爱国”不能带“居民”作宾语；〈保护〉可以带人作宾语。"}, {"text": "妈妈爱国孩子，每天都送他上学。", "explanation": "这里应该用〈照顾〉。“爱国”不能带“孩子”作宾语；〈照顾〉可以带人作宾语。"}, {"text": "我们要爱国老师，认真听课。", "explanation": "这里应该用〈尊重〉。“爱国”不能带“老师”作宾语；〈尊重〉可以用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱国", "is_correct": true, "explanation": "正确答案，“爱国”是小明想当兵的原因，填入后句意通顺。"}, {"text": "近视", "is_correct": false, "explanation": "语义：“近视”是不能参军的原因，与“长大后要当兵”的动机相反。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”不能作为当兵的原因，句中逻辑不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与“长大后要当兵”的理由没有关系，句意不通。"}], "explanations": {"爱国": "正确答案，“爱国”是小明想当兵的原因，填入后句意通顺。", "近视": "语义：“近视”是不能参军的原因，与“长大后要当兵”的动机相反。", "生病": "语义：“生病”不能作为当兵的原因，句中逻辑不通。", "结婚": "语义：“结婚”与“长大后要当兵”的理由没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "爱国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的表哥是班里最有名的爱国。", "explanation": "这里应该用〈爱国者〉。“爱国”是动词性词语，不能直接充当名词指“爱国的人”。"}, {"text": "这位老师是一个优秀的爱国。", "explanation": "这里应该用〈爱国者〉。“爱国”不能直接跟在数量词后面当名词用。"}, {"text": "我们在一个爱国的花园里散步。", "explanation": "这里应该用〈美丽〉。“爱国”只指人对国家的感情，不能用来形容景物；〈美丽〉可以形容花园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都应该爱国了，为国家出力。", "corrected_sentence": "我们都应该爱国，为国家出力。", "error_description": "「应该」表示尚未发生的意愿，后面的“爱国”不能再加“了”。错误形式是「爱国了」，正确形式是「爱国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该了爱国，也应该努力学习。", "corrected_sentence": "我们应该爱国，也应该努力学习。", "error_description": "错误：「应该」与动词之间不能插入「了」。错误形式是「我们应该了爱国」，正确形式是「我们应该爱国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88504, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卖国", "is_correct": true, "explanation": "与“爱国”构成反义：卖国指出卖国家的利益，与爱国相反。"}, {"text": "散步", "is_correct": false, "explanation": "与“爱国”没有反义关系，散步指慢慢走路。"}, {"text": "读书", "is_correct": false, "explanation": "与“爱国”没有反义关系，读书指阅读书籍。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“爱国”没有反义关系，唱歌指发声演唱。"}], "correct_answer": "卖国", "explanations": {"卖国": "与“爱国”构成反义：卖国指出卖国家的利益，与爱国相反。", "散步": "与“爱国”没有反义关系，散步指慢慢走路。", "读书": "与“爱国”没有反义关系，读书指阅读书籍。", "唱歌": "与“爱国”没有反义关系，唱歌指发声演唱。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
