INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "热爱自己的国家。", "primary_collocate": null, "pronunciation": "ài guó", "ipa": "ai̯˥˩ kuo̯˧˥", "syllable_count": 2, "sentences": [{"text": "他从小就很爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国的人都希望国家越来越好。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常教我们要爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生都爱国，从没离开过中国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家有难的时候，大家都应该爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷爱国，每天早上都看升国旗。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外工作多年，但是心里一直爱国。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱国不只是说话，更要为国家做事。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要爱国，也要爱自己的家乡。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱国，所以决定回国工作。", "target_word": "爱国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "愛國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "热爱自己的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f560e3a-3bd5-4867-b642-b1a189f978f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88504, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱国", "is_correct": true, "explanation": "正确答案，意思是热爱自己的国家。"}, {"text": "外国", "is_correct": false, "explanation": "wài 与 ài 相比多了声母 w，意思是外国，不是爱国。"}, {"text": "卖国", "is_correct": false, "explanation": "mài（第四声）与 ài（第四声）声母不同，意思是出卖国家，与爱国相反。"}, {"text": "爱过", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，意思是曾经爱。"}], "explanations": {"爱国": "正确答案，意思是热爱自己的国家。", "外国": "wài 与 ài 相比多了声母 w，意思是外国，不是爱国。", "卖国": "mài（第四声）与 ài（第四声）声母不同，意思是出卖国家，与爱国相反。", "爱过": "guò（第四声）与 guó（第二声）声调不同，意思是曾经爱。"}, "sentence_index": null, "correct_answer": "爱国"}, "level_3": {"options": [{"text": "爱国", "is_correct": true, "explanation": "正确答案，“爱国”表示热爱自己的国家，填入后符合句意。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：“后悔”指事后懊悔，与“从小”的品质描述不符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”指持相反意见，与“他从小就很……”所描述的热爱国家相反。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”指认输屈服，与句子描述的个人品质矛盾。"}], "explanations": {"爱国": "正确答案，“爱国”表示热爱自己的国家，填入后符合句意。", "后悔": "语义：“后悔”指事后懊悔，与“从小”的品质描述不符。", "反对": "语义：“反对”指持相反意见，与“他从小就很……”所描述的热爱国家相反。", "投降": "语义：“投降”指认输屈服，与句子描述的个人品质矛盾。"}, "sentence_index": 0, "correct_answer": "爱国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要爱国花草，不随便摘它们。", "explanation": "这里应该用〈爱护〉。爱国是不及物动词，不能带“花草”作宾语；〈爱护〉可以用于人或物。"}, {"text": "她爱国音乐，每天都练琴。", "explanation": "这里应该用〈热爱〉。“爱国”只表示对国家的感情，不能带“音乐”作宾语；〈热爱〉可以带事物。"}, {"text": "老师很爱国学生，每天都帮他们补课。", "explanation": "这里应该用〈关心〉。“爱国”只用于对国家的感情，不能带“学生”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCL