INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱国", "is_correct": true, "explanation": "正确答案，“爱国”表示热爱自己的国家，与“在国外工作但心里一直……”的转折相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”指不再记得，与“心里一直……”的情感描述相矛盾。"}, {"text": "背叛", "is_correct": false, "explanation": "语义：“背叛”指背弃，与“心里一直”的忠诚描述相矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”指躲开责任或困难，与“心里一直……”的忠诚描述不符。"}], "explanations": {"爱国": "正确答案，“爱国”表示热爱自己的国家，与“在国外工作但心里一直……”的转折相符。", "忘记": "语义：“忘记”指不再记得，与“心里一直……”的情感描述相矛盾。", "背叛": "语义：“背叛”指背弃，与“心里一直”的忠诚描述相矛盾。", "逃避": "语义：“逃避”指躲开责任或困难，与“心里一直……”的忠诚描述不符。"}, "sentence_index": 6, "correct_answer": "爱国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是班里很有名的爱国。", "explanation": "这里应该用〈爱国者〉。“爱国”是动词性词语，不能直接充当名词指“爱国的人”。"}, {"text": "她是一位优秀的爱国，经常帮助邻居。", "explanation": "这里应该用〈爱国者〉。“爱国”不能直接跟在数量词后面当名词用。"}, {"text": "这个孩子很爱国，每天都帮妈妈做家务。", "explanation": "这里应该用〈孝顺〉。“爱国”只指对国家的感情，不能用来形容子女对父母；〈孝顺〉可以形容子女对父母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都应该爱国了，为国家做事。", "corrected_sentence": "每个人都应该爱国，为国家做事。", "error_description": "「应该」表示尚未发生的意愿，后面的“爱国”不能再加“了”。错误形式是「爱国了」，正确形式是「爱国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很爱国很，希望为国家做贡献。", "corrected_sentence": "他很爱国，希望为国家做贡献。", "error_description": "“很”修饰“爱国”，只能用一次，放在前面；不能在“爱国”之后再加“很”。错误形式是「爱国很」，正确形式是「很爱国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c79bd9a-7046-4fd1-a184-9a6f3af12be8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
