INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88505, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "行走是用脚一步一步地走路。", "primary_collocate": null, "pronunciation": "xíng zǒu", "ipa": "ɕiŋ˧˥ tsoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "婴儿一岁左右就开始学习行走了。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用双脚在沙漠里行走了三天。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗用四条腿行走，人用两条腿行走。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她赤着脚在沙滩上慢慢行走。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位僧人拄着拐杖，在山间行走。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有车，每天靠双脚行走。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企鹅在冰上摇摇摆摆地行走。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，他在黑暗的小路上缓慢行走。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的泥地很软，行走时一步一个脚印。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩刚学会行走，一步一步很可爱。", "target_word": "行走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行走了", "label": "完成体"}, {"form": "行走着", "label": "持续体"}, {"form": "行走过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用脚一步一步地走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc8880f4-5902-4e22-8050-4cf2eac25d3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88505, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写字", "is_correct": false, "explanation": "语义：一岁左右的婴儿还不会写字，与句中的年龄不符。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：一岁左右的婴儿还不会讲解，与句中年龄不符。"}, {"text": "行走", "is_correct": true, "explanation": "行走：婴儿学会用脚走路，与“一岁左右”的年龄相符。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：一岁左右的婴儿不能驾驶任何车辆，与年龄不符。"}], "explanations": {"写字": "语义：一岁左右的婴儿还不会写字，与句中的年龄不符。", "讲解": "语义：一岁左右的婴儿还不会讲解，与句中年龄不符。", "行走": "行走：婴儿学会用脚走路，与“一岁左右”的年龄相符。", "驾驶": "语义：一岁左右的婴儿不能驾驶任何车辆，与年龄不符。"}, "sentence_index": 0, "correct_answer": "行走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皮球在草地上行走，一直滚到了门口。", "explanation": "这里表示圆球在地面上转着移动。“行走”只指人或动物用脚步行，皮球不会行走，不能这样用。"}, {"text": "小船在湖面上行走，慢慢向岸边靠近。", "explanation": "这里应该用〈航行〉。船在水上移动用“航行”，“行走”只指人或动物步行。"}, {"text": "小鱼在水里行走，游得很快。", "explanation": "这里表示鱼靠鳍摆动、在水中向前移动。“行走”只指人或动物用脚步行，鱼没有脚，不能用于水中移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88505, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游", "is_correct": false, "explanation": "语义：游是在水中移动，企鹅在冰面上，与句中场景不合。"}, {"text": "行走", "is_correct": true, "explanation": "行走：企鹅用脚一步步挪动，与“摇摇摆摆”相合。"}, {"text": "飞", "is_correct": false, "explanation": "语义：企鹅不会飞，“摇摇摆摆地飞”与其习性不符。"}, {"text": "踢", "is_correct": false, "explanation": "配价：踢需要宾语（踢什么），“摇摇摆摆地踢”没有宾语，句子不完整。"}], "explanations": {"游": "语义：游是在水中移动，企鹅在冰面上，与句中场景不合。", "行走": "行走：企鹅用脚一步步挪动，与“摇摇摆摆”相合。", "飞": "语义：企鹅不会飞，“摇摇摆摆地飞”与其习性不符。", "踢": "配价：踢需要宾语（踢什么），“摇摇摆摆地踢”没有宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "行走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机在天空中行走，飞得很高。", "explanation": "这里应该用〈飞行〉。飞机在空中用“飞行”，“行走”只指用脚步行。"}, {"text": "木头在河面上行走，慢慢漂向下游。", "explanation": "这里表示物体随着水流缓缓向前浮动。“行走”只指人或动物用脚步行，木头在水上不能用“行走”。"}, {"text": "蛇在草丛里行走，很快就不见了。", "explanation": "这里应该用〈爬〉。蛇没有脚，在地上移动用“爬”，不用“行走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子行走地很稳。", "corrected_sentence": "孩子行走得很稳。", "error_description": "错误：动词后的状态补语要用“得”，不能用“地”（“地”用在动词之前）。正确说法是“行走得很稳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人在花园里慢慢地行走走。", "corrected_sentence": "老人在花园里慢慢地行走。", "error_description": "错误：句末多出一个“走”。“行走”本身已是完整动词，后面不能再加“走”。正确说法是“慢慢地行走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdcbbccf-0815-4b23-ae2e-3edd83394703') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "反义：“批评”指指出做得不对的地方，“表扬”指肯定做得好的地方，二者相对。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”是出外游览，与“批评”不构成相对的关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无反义关系：“打扫”是清除脏东西，与“批评”不构成相对的关系。"}, {"text": "陪伴", "is_correct": false, "explanation": "无反义关系：“陪伴”是跟随在旁边，与“批评”不构成相对的关系。"}], "correct_answer": "表扬", "explanations": {"表扬": "反义：“批评”指指出做得不对的地方，“表扬”指肯定做得好的地方，二者相对。", "旅行": "无反义关系：“旅行”是出外游览，与“批评”不构成相对的关系。", "打扫": "无反义关系：“打扫”是清除脏东西，与“批评”不构成相对的关系。", "陪伴": "无反义关系：“陪伴”是跟随在旁边，与“批评”不构成相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "反义：“批评”指指出做得不对的地方，“表扬”指肯定做得好的地方，二者相对。"}, {"text": "帮助", "is_correct": false, "explanation": "无反义关系：“帮助”是给予支持，与“批评”不构成相对的关系。"}, {"text": "信任", "is_correct": false, "explanation": "无反义关系：“信任”是相信对方，与“批评”不构成相对的关系。"}, {"text": "尊重", "is_correct": false, "explanation": "无反义关系：“尊重”是重视对方，与“批评”不构成相对的关系。"}], "correct_answer": "表扬", "explanations": {"表扬": "反义：“批评”指指出做得不对的地方，“表扬”指肯定做得好的地方，二者相对。", "帮助": "无反义关系：“帮助”是给予支持，与“批评”不构成相对的关系。", "信任": "无反义关系：“信任”是相信对方，与“批评”不构成相对的关系。", "尊重": "无反义关系：“尊重”是重视对方，与“批评”不构成相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "批评是说别人做得不对的地方。", "primary_collocate": null, "pronunciation": "pī píng", "ipa": "pʰi˥ pʰɪŋ˧˥", "syllable_count": 2, "sentences": [{"text": "爸爸批评我说谎。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上批评了小明。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了事，老师批评了他。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈生气地批评了弟弟。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要在大家面前批评她。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从来不批评我们，只是笑着说话。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常批评同事的工作态度。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理批评了几个迟到的人。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做错了，家长应该批评他。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们批评他不守规矩。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批评了", "label": "体标"}, {"form": "批评过", "label": "体标"}, {"form": "批评批评", "label": "重叠"}, {"form": "批评家", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，说别人做得不对的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批评", "is_correct": true, "explanation": "批评：指出孩子做错的事，与“说谎”的语境相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是肯定做得好的事，与“说谎”相矛盾。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是支持好的行为，与“说谎”相矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地方，不能用于人和“说谎”。"}], "explanations": {"批评": "批评：指出孩子做错的事，与“说谎”的语境相符。", "表扬": "语义：“表扬”是肯定做得好的事，与“说谎”相矛盾。", "鼓励": "语义：“鼓励”是支持好的行为，与“说谎”相矛盾。", "打扫": "搭配：“打扫”的对象是房间、地方，不能用于人和“说谎”。"}, "sentence_index": 0, "correct_answer": "批评"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他帮我们解决了大问题，我们都在批评他。", "explanation": "这里应该用〈感谢〉。批评针对做得不对的地方，别人帮了大忙应该感谢，不能说“批评”。"}, {"text": "弟弟这次考了第一名，妈妈因此批评了他。", "explanation": "这里应该用〈表扬〉。批评针对做得不对的地方，对成绩好的弟弟应该表扬。"}, {"text": "她画的画很漂亮，老师批评了她。", "explanation": "这里应该用〈夸奖〉。批评针对做得不对的地方，画得漂亮应该夸奖，不能说“批评”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": true, "explanation": "批评：指出工作态度上的问题，与“同事的工作态度”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“工作态度”搭配作宾语。"}, {"text": "复印", "is_correct": false, "explanation": "搭配：“复印”的对象是文件，不能用于“工作态度”。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是毁坏实物，与抽象的“工作态度”不合。"}], "explanations": {"批评": "批评：指出工作态度上的问题，与“同事的工作态度”搭配。", "吃": "搭配：“吃”不能与“工作态度”搭配作宾语。", "复印": "搭配：“复印”的对象是文件，不能用于“工作态度”。", "烧": "语义：“烧”是毁坏实物，与抽象的“工作态度”不合。"}, "sentence_index": 6, "correct_answer": "批评"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿了第一名，全班同学都批评他。", "explanation": "这里应该用〈赞赏〉。批评针对做得不对的地方，拿了第一名应该赞赏。"}, {"text": "他第一次主动发言，老师批评了他的勇气。", "explanation": "这里应该用〈鼓励〉。批评针对缺点，对勇敢的表现应该鼓励。"}, {"text": "这场演讲非常精彩，大家都批评了演讲者。", "explanation": "这里应该用〈称赞〉。批评针对做得不对的地方，演讲精彩应该称赞演讲者，不能说“批评”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈批评我了粗心。", "corrected_sentence": "妈妈批评了我的粗心。", "error_description": "错误：动态助词“了”位置错误，应紧跟动词“批评”。正确：“批评了我的粗心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被老师批评了一个。", "corrected_sentence": "他被老师批评了一顿。", "error_description": "错误：表示批评次数的量词用“顿”，不用“个”。正确：“批评了一顿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "反义：“批评”指指出缺点，“表扬”指肯定优点，二者意思相对。"}, {"text": "解释", "is_correct": false, "explanation": "无反义关系：“解释”是说明道理，与“批评”不构成相对的关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”是交换意见，与“批评”不构成相对的关系。"}, {"text": "修改", "is_correct": false, "explanation": "无反义关系：“修改”是改正文字或计划，与“批评”不构成相对的关系。"}], "correct_answer": "表扬", "explanations": {"表扬": "反义：“批评”指指出缺点，“表扬”指肯定优点，二者意思相对。", "解释": "无反义关系：“解释”是说明道理，与“批评”不构成相对的关系。", "讨论": "无反义关系：“讨论”是交换意见，与“批评”不构成相对的关系。", "修改": "无反义关系：“修改”是改正文字或计划，与“批评”不构成相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表扬", "is_correct": true, "explanation": "反义：“批评”指指出缺点，“表扬”指肯定优点，二者意思相对。"}, {"text": "保护", "is_correct": false, "explanation": "无反义关系：“保护”是照顾、防止受害，与“批评”不构成相对的关系。"}, {"text": "建议", "is_correct": false, "explanation": "无反义关系：“建议”是提出看法供对方参考，与“批评”不构成相对的关系。"}, {"text": "整理", "is_correct": false, "explanation": "无反义关系：“整理”是使东西有条理，与“批评”不构成相对的关系。"}], "correct_answer": "表扬", "explanations": {"表扬": "反义：“批评”指指出缺点，“表扬”指肯定优点，二者意思相对。", "保护": "无反义关系：“保护”是照顾、防止受害，与“批评”不构成相对的关系。", "建议": "无反义关系：“建议”是提出看法供对方参考，与“批评”不构成相对的关系。", "整理": "无反义关系：“整理”是使东西有条理，与“批评”不构成相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对缺点和错误提出意见。", "primary_collocate": null, "pronunciation": "pī píng", "ipa": "pʰi˥ pʰɪŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师批评了他迟到的问题。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理批评我的报告写得太简单。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家批评这个计划有很多缺点。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少批评别人，总是先听听。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板当面批评了他的错误。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读者批评这本书的结尾不好。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你认真批评我的作文。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈批评我不应该乱花钱。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他批评过这家公司的服务。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家批评这个方案不安全。", "target_word": "批评", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批评了", "label": "体标"}, {"form": "批评过", "label": "体标"}, {"form": "批评批评", "label": "重叠"}, {"form": "批评家", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，对缺点和错误提出意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4849f8-6cfb-4526-a2df-117af276fd76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批评", "is_correct": true, "explanation": "批评：指出迟到这一缺点并提出意见，与“问题”搭配，符合句意。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”是肯定优点，不能用于“迟到的问题”。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示喜爱，与“迟到”这类缺点相矛盾。"}, {"text": "鼓励", "is_correct": false, "explanation": "搭配：“鼓励”的对象是人或积极行为，不能用于“迟到的问题”。"}], "explanations": {"批评": "批评：指出迟到这一缺点并提出意见，与“问题”搭配，符合句意。", "表扬": "搭配：“表扬”是肯定优点，不能用于“迟到的问题”。", "喜欢": "语义：“喜欢”表示喜爱，与“迟到”这类缺点相矛盾。", "鼓励": "搭配：“鼓励”的对象是人或积极行为，不能用于“迟到的问题”。"}, "sentence_index": 0, "correct_answer": "批评"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他写的这首诗意境很美，老师批评了他。", "explanation": "这里应该用〈赞美〉。批评针对缺点和错误，对意境优美的作品应该赞美，不能说“批评”。"}, {"text": "他这次考试进步很大，老师因此批评了他。", "explanation": "这里应该用〈表扬〉。批评针对缺点和错误，对进步应该表扬，说“批评”则逻辑不通。"}, {"text": "她很努力地帮助同学，老师因此批评了她。", "explanation": "这里应该用〈表扬〉。批评针对缺点和错误，对乐于助人的行为应该表扬，不能说“批评”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批评", "is_correct": true, "explanation": "批评：指对作文的缺点提出意见，与“请你认真”的请求相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是毁坏纸张，与“请你认真”的请求相矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与“请你认真”的请求相反。"}, {"text": "抽", "is_correct": false, "explanation": "搭配：“抽”一般不与“作文”搭配作宾语。"}], "explanations": {"批评": "批评：指对作文的缺点提出意见，与“请你认真”的请求相符。", "撕": "语义：“撕”是毁坏纸张，与“请你认真”的请求相矛盾。", "放弃": "语义：“放弃”表示不再坚持，与“请你认真”的请求相反。", "抽": "搭配：“抽”一般不与“作文”搭配作宾语。"}, "sentence_index": 6, "correct_answer": "批评"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演出非常精彩，观众们纷纷批评演员。", "explanation": "这里应该用〈称赞〉。批评针对缺点和错误，演出精彩时应该称赞演员，不能说“批评”。"}, {"text": "他的字写得非常漂亮，老师批评了他。", "explanation": "这里应该用〈夸奖〉。批评针对缺点和错误，字写得漂亮应该夸奖，不能说“批评”。"}, {"text": "孩子第一次主动发言，家长批评了他的勇气。", "explanation": "这里应该用〈鼓励〉。批评是指出缺点，对孩子的勇气应该鼓励。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师批评他批评很严厉。", "corrected_sentence": "老师批评他批评得很严厉。", "error_description": "错误：动词“批评”后带程度补语时缺少“得”。正确：“批评得很严厉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把他批评。", "corrected_sentence": "老师把他批评了一顿。", "error_description": "错误：“把”字句中动词“批评”后缺少补语。正确：“把他批评了一顿”，补语说明批评的次数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1367877e-67b8-4107-88b0-a65cad39fdd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
