INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "多年来是好多年以来，一直到现在。", "primary_collocate": null, "pronunciation": "duō nián lái", "ipa": "tu̯ɔ⁵⁵ njɛn³⁵ laɪ̯³⁵", "syllable_count": 3, "sentences": [{"text": "多年来，他每天早上都跑步。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，我一直住在这个小城。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，这家店的菜都很好吃。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我多年来都在同一家公司工作。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，她一直在帮助山区的孩子。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，爷爷的习惯一点儿也没变。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，我们每个春节都在一起过。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，那条河的水越来越干净。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，他写了很多信给老朋友。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，这里的天气一直很好。", "target_word": "多年来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间词：好多年以来一直到现在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b62440a-1174-47c4-b8b4-81f0b0821142') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多年来", "is_correct": true, "explanation": "“多年来”表示从过去延续到现在的长时间，与“每天早上都跑步”的长期习惯相符。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久前发生的一次，与“每天早上都”表示的习惯相冲突。"}, {"text": "一会儿", "is_correct": false, "explanation": "语义：“一会儿”指很短的时间，不能与“每天早上都”表示的长期习惯相合。"}, {"text": "这一刻", "is_correct": false, "explanation": "搭配：“这一刻”指眼下的一个瞬间，不与表示习惯的“每天……都”搭配。"}], "explanations": {"多年来": "“多年来”表示从过去延续到现在的长时间，与“每天早上都跑步”的长期习惯相符。", "刚才": "语义：“刚才”指不久前发生的一次，与“每天早上都”表示的习惯相冲突。", "一会儿": "语义：“一会儿”指很短的时间，不能与“每天早上都”表示的长期习惯相合。", "这一刻": "搭配：“这一刻”指眼下的一个瞬间，不与表示习惯的“每天……都”搭配。"}, "sentence_index": 0, "correct_answer": "多年来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我多年来会去北京工作。", "explanation": "这里应该用〈将来〉。多年来指从过去延续到现在的一段时间，不能用于尚未发生的打算。"}, {"text": "他多年来明天到公司。", "explanation": "这里应该用〈明天〉。多年来指很长一段时间，不能与“明天到公司”这种将来的单次动作搭配。"}, {"text": "我们多年来开始上课。", "explanation": "这里应该用〈现在〉。多年来指一段时间，不能用来描述一次性的开始动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多年来", "is_correct": true, "explanation": "“多年来”表示长时间的延续，与“每个春节都在一起过”这种长期重复的情况相符。"}, {"text": "眼下", "is_correct": false, "explanation": "语义：“眼下”指当前时刻，与一年一度的“每个春节都”不相配。"}, {"text": "上个月", "is_correct": false, "explanation": "搭配：“上个月”是一个月的范围，不能与一年一次的“每个春节都”搭配。"}, {"text": "一瞬间", "is_correct": false, "explanation": "语义：“一瞬间”极其短暂，与“每个春节都”这种周期性的重复冲突。"}], "explanations": {"多年来": "“多年来”表示长时间的延续，与“每个春节都在一起过”这种长期重复的情况相符。", "眼下": "语义：“眼下”指当前时刻，与一年一度的“每个春节都”不相配。", "上个月": "搭配：“上个月”是一个月的范围，不能与一年一次的“每个春节都”搭配。", "一瞬间": "语义：“一瞬间”极其短暂，与“每个春节都”这种周期性的重复冲突。"}, "sentence_index": 6, "correct_answer": "多年来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我多年来早上吃了一碗面。", "explanation": "这里应该用〈今天〉。多年来指从过去延续到现在的很长一段时间，不能与“吃了一碗面”这种一次性的动作搭配。"}, {"text": "我多年来昨天到北京。", "explanation": "这里应该用〈昨天〉。多年来指很长的时间，不能与“昨天到北京”这种具体某日的单次动作搭配。"}, {"text": "这件事多年来一眨眼就解决了。", "explanation": "这里应该用〈刚才〉。多年来指很长的时间，不能与“一眨眼就解决了”这种瞬间完成的结果搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多年来了，他的父母一直支持他。", "corrected_sentence": "多年来，他的父母一直支持他。", "error_description": "“多年来”后面不能加“了”，写成“多年来了”是错误的。“多年来”本身已表示从过去延续到现在，应写作“多年来，他的父母一直支持他。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多年来，我一直在这个城市多年来教书。", "corrected_sentence": "多年来，我一直在这个城市教书。", "error_description": "“多年来”重复出现：句首已有“多年来，”，句中“城市”和“教书”之间又出现一次，多余。应只保留句首的“多年来”，写作“多年来，我一直在这个城市教书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ba71728-9a0b-4532-b708-bea18447d19f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
