INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "深受主将喜爱和信任的部下将领。", "primary_collocate": null, "pronunciation": "ài jiàng", "ipa": "aɪ˥˩ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他是将军最信任的爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关羽是刘备的爱将。", "target_word": "爱将", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位爱将跟了将军二十年。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军派爱将去守城门。", "target_word": "爱将", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打仗时，他总带着自己的爱将。", "target_word": "爱将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军很舍不得他的爱将离开。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位爱将立了大功，将军很高兴。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是曹操手下的一员爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱将受伤了，将军十分难过。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老将军把重要的任务交给爱将。", "target_word": "爱将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "员", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "愛將", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：深受主将喜爱和信任的部下将领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d06d0e-067c-4c11-97ae-a74e588d261c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱将", "is_correct": true, "explanation": "爱将：深受主将喜爱和信任的部下将领，与“将军最信任的”相符。"}, {"text": "敌将", "is_correct": false, "explanation": "语义：“敌将”是敌方的将领，与“将军最信任的”相矛盾。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”是与将军为敌的人，不可能是将军最信任的人。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“信任”的对象要是人，不能说信任“书本”。"}], "explanations": {"爱将": "爱将：深受主将喜爱和信任的部下将领，与“将军最信任的”相符。", "敌将": "语义：“敌将”是敌方的将领，与“将军最信任的”相矛盾。", "仇人": "语义：“仇人”是与将军为敌的人，不可能是将军最信任的人。", "书本": "搭配：“信任”的对象要是人，不能说信任“书本”。"}, "sentence_index": 0, "correct_answer": "爱将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是三军的爱将，负责统率全军。", "explanation": "这里应该用〈主帅〉。“爱将”指主将的部下，不能用来指统率全军的人，统率全军的应是主帅。"}, {"text": "这只小狗是我的爱将，每天陪我散步。", "explanation": "这里应该用〈爱犬〉。“爱将”指将军身边受信任的部下将领，是人，不能指宠物。"}, {"text": "我的爱将下班后陪我去超市买菜。", "explanation": "这里应该用〈爱人〉。“爱将”指将军身边的部下将领，不能指配偶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱将", "is_correct": true, "explanation": "爱将：深受主将喜爱和信任的部下将领，与“立了大功，将军很高兴”相符。"}, {"text": "逃兵", "is_correct": false, "explanation": "语义：“逃兵”是临阵脱逃的人，与“立了大功”相矛盾。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“立功”要求有行动能力的人作主语，“花瓶”不能立功，量词“位”也不适用于物品。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：敌人立了大功，将军不会高兴，与“将军很高兴”相矛盾。"}], "explanations": {"爱将": "爱将：深受主将喜爱和信任的部下将领，与“立了大功，将军很高兴”相符。", "逃兵": "语义：“逃兵”是临阵脱逃的人，与“立了大功”相矛盾。", "花瓶": "搭配：“立功”要求有行动能力的人作主语，“花瓶”不能立功，量词“位”也不适用于物品。", "敌人": "语义：敌人立了大功，将军不会高兴，与“将军很高兴”相矛盾。"}, "sentence_index": 6, "correct_answer": "爱将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这位医生的爱将，负责整理病历。", "explanation": "这里应该用〈助手〉。“爱将”指将军最信任的部下将领，不能指医生的助手。"}, {"text": "这辆汽车是老将军的爱将，跑得很快。", "explanation": "这里应该用〈爱车〉。“爱将”指部下将领，是人，不能指汽车。"}, {"text": "他是村里的种菜爱将，每年都得奖。", "explanation": "这里应该用〈能手〉。“爱将”指将军信任的部下将领，不能指种菜技术好的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "将军手下有一只爱将，作战很勇敢。", "corrected_sentence": "将军手下有一员爱将，作战很勇敢。", "error_description": "错误形式：“一只爱将”中的量词“只”。正确形式：“一员爱将”。“只”多用于动物或成对物中的一个，指将领应用“员”或“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老将军最信任地爱将前不久受了伤。", "corrected_sentence": "老将军最信任的爱将前不久受了伤。", "error_description": "错误形式：“最信任地爱将”中的“地”。正确形式：“最信任的爱将”。“地”用于修饰动词，修饰名词“爱将”要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9027252-a8d3-480a-935e-6a91e3e74f16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
