INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88513, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表态是说出自己同意还是不同意。", "primary_collocate": null, "pronunciation": "biǎo tài", "ipa": "pjɑʊ˨˩˦ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "老师问大家去不去，小王还没表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意还是不同意，请快点表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让他表态，他笑了笑，没说话。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都等着你表态，你到底去不去？", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问我想不想搬家，我不愿意表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你同意吗？请你先表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，李明第一个表态支持。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想得罪人，所以一直不表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都说好，只有小张没表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板问谁愿意加班，大家都不敢表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表了态", "label": "体标（了，离合）"}, {"form": "表过态", "label": "体标（过，离合）"}], "register": "中性", "sense_fingerprint": "被问到同意或不同意时，说出自己的立场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表态", "is_correct": true, "explanation": "正确：表态指说出自己同意还是不同意，与“问大家去不去”的应答语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与被问“去不去”后的应答无关，句子意思不通。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差是外出办公，不能回应“去不去”的问题。"}, {"text": "吹牛", "is_correct": false, "explanation": "语域：“吹牛”是口语且含贬义，不是回应问题时表明立场的说法。"}], "explanations": {"表态": "正确：表态指说出自己同意还是不同意，与“问大家去不去”的应答语境相符。", "睡觉": "语义：睡觉与被问“去不去”后的应答无关，句子意思不通。", "出差": "语义：出差是外出办公，不能回应“去不去”的问题。", "吹牛": "语域：“吹牛”是口语且含贬义，不是回应问题时表明立场的说法。"}, "sentence_index": 0, "correct_answer": "表态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师当众表态了小王的努力。", "explanation": "这里应该用〈表扬〉。表态是表明立场，不能带“努力”作对象；称赞他人的努力要用表扬。"}, {"text": "市里表态了一位优秀教师。", "explanation": "这里应该用〈表彰〉。表态是表明立场，不能用来奖励人；公开奖励先进要用表彰。"}, {"text": "他终于向她表态了自己的心意。", "explanation": "这里应该用〈表白〉。表态指表明对事情的立场，说出爱意或心意要用表白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表态", "is_correct": true, "explanation": "正确：表态指表明同意或反对的立场，与“第一个……支持”相符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与后面的“支持”意思相反，句子自相矛盾。"}, {"text": "退缩", "is_correct": false, "explanation": "语义：“退缩”是畏缩后退，与“第一个……支持”的积极立场不符。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“沉默”后不能直接接“支持”构成动作，搭配不通。"}], "explanations": {"表态": "正确：表态指表明同意或反对的立场，与“第一个……支持”相符。", "反对": "语义：“反对”与后面的“支持”意思相反，句子自相矛盾。", "退缩": "语义：“退缩”是畏缩后退，与“第一个……支持”的积极立场不符。", "沉默": "搭配：“沉默”后不能直接接“支持”构成动作，搭配不通。"}, "sentence_index": 6, "correct_answer": "表态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在台上表态魔术。", "explanation": "这里应该用〈表演〉。表态指表明立场，不能带“魔术”作宾语；在台上表演节目要用表演。"}, {"text": "他脸上的表态很紧张。", "explanation": "这里应该用〈表情〉。表态指表明立场，不能用来形容脸上的神情。"}, {"text": "他在比赛中表态很好。", "explanation": "这里应该用〈表现〉。表态指表明立场，不能用来评价比赛中的表现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这件事了表态。", "corrected_sentence": "他对这件事表了态。", "error_description": "错误形式：“他对这件事了表态”。离合词“表态”的“了”应放在“表”和“态”之间，正确形式为“他对这件事表了态”，“了”位置放错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很表态了。", "corrected_sentence": "他很快表态了。", "error_description": "错误形式：“他很表态了”。“很”不能直接修饰表示动作的动词，应加上表示速度的“快”，正确形式为“他很快表态了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
