INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88514, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表明对某事的态度或看法。", "primary_collocate": null, "pronunciation": "biǎo tài", "ipa": "pjɑʊ˨˩˦ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "对这个新规定，公司还没有公开表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府已经对这件事表态了。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问他对比赛结果怎么看，他拒绝表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长在会上明确表态，反对考试作弊。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对网上的批评，那位歌手终于表态了。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家希望老师对这个问题表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有对这件事表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷都想知道教练会怎么表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对网上的传言已经公开表态。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们对新政策纷纷表态，意见不一。", "target_word": "表态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表了态", "label": "体标（了，离合）"}, {"form": "表过态", "label": "体标（过，离合）"}], "register": "中性", "sense_fingerprint": "对某件事或某个问题公开说明自己的态度和看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7295f940-47c1-4dfb-aff3-6ed17b335cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表态", "is_correct": true, "explanation": "正确：表态指公开说明对某事的态度或看法，与“对这个新规定”的语境相符。"}, {"text": "演出", "is_correct": false, "explanation": "语义：演出是表演节目，与“新规定”的语境无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“公开”不能修饰“睡觉”，搭配不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是娱乐活动，与公司对新规定的态度无关。"}], "explanations": {"表态": "正确：表态指公开说明对某事的态度或看法，与“对这个新规定”的语境相符。", "演出": "语义：演出是表演节目，与“新规定”的语境无关。", "睡觉": "搭配：“公开”不能修饰“睡觉”，搭配不通。", "跳舞": "语义：跳舞是娱乐活动，与公司对新规定的态度无关。"}, "sentence_index": 0, "correct_answer": "表态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市里表态了一位优秀教师。", "explanation": "这里应该用〈表彰〉。表态指公开说明态度或看法，不能用来奖励人；公开奖励先进要用表彰。"}, {"text": "他终于向她表态了自己的心意。", "explanation": "这里应该用〈表白〉。表态指公开说明对事情的态度，说出爱意或心意要用表白。"}, {"text": "演员在台上表态节目。", "explanation": "这里应该用〈表演〉。表态不能用来指在台上演出节目；表演节目要用表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表态", "is_correct": true, "explanation": "正确：表态指说明对某事的态度，与“对这件事”的语境相符。"}, {"text": "报销", "is_correct": false, "explanation": "语义：报销是报账，不能“对这件事”报销。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：旅行是外出游览，不能用“对这件事”来修饰。"}, {"text": "理发", "is_correct": false, "explanation": "语义：理发是剪头发，不能“对这件事”理发，意思不通。"}], "explanations": {"表态": "正确：表态指说明对某事的态度，与“对这件事”的语境相符。", "报销": "语义：报销是报账，不能“对这件事”报销。", "旅行": "语义：旅行是外出游览，不能用“对这件事”来修饰。", "理发": "语义：理发是剪头发，不能“对这件事”理发，意思不通。"}, "sentence_index": 6, "correct_answer": "表态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师当众表态了小王的进步。", "explanation": "这里应该用〈表扬〉。表态指公开说明态度或看法，不能用来称赞人的进步；称赞他人要用表扬。"}, {"text": "她脸上的表态很平静。", "explanation": "这里应该用〈表情〉。表态指表明态度，不能指脸上的神情，应说“表情”。"}, {"text": "湖面的表态很平静。", "explanation": "这里应该用〈表面〉。表态指表明态度，不能指物体的表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司还没有这个新规定表态。", "corrected_sentence": "公司还没有对这个新规定表态。", "error_description": "错误形式：“这个新规定表态”。表态的对象要用介词“对”引出，正确形式为“对这个新规定表态”，缺少“对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有对这件事表过态过。", "corrected_sentence": "他从来没有对这件事表过态。", "error_description": "错误形式：“表过态过”。动态助词“过”重复，只需一个，正确形式为“表过态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd99c8030-2e95-43f0-958d-9a6824ad9182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
